/**
 * The `client-hints` profile's runtime (specs/veml/profiles/client-hints.md):
 * a world's preferences for the shell's visitor-facing features.
 *
 * The shell supports these features, but a world controls them through VEML
 * and the script API rather than the shell hard-coding them. So the shell's
 * people, chat, touch controls, menu and VR controls read what is in force
 * here, and never a constant of their own: the shell's default when the
 * world says nothing, the world's `hints:*` otherwise, and whatever a world
 * script sets through `ClientHints.Set` at run time.
 *
 * One validator (`validateHint`) serves the VEML attributes and the script's
 * `Set` alike, as the spec requires: "validated exactly as the attribute is".
 * Values are held as strings — the script surface's type — with typed
 * readers for the features that consume them.
 */

import { HINT_DEFAULTS, HINT_SPECS, isHintName, validateHint, type HintName } from '../veml/clientHintsVocabulary';

export { HINT_DEFAULTS, HINT_SPECS, isHintName, validateHint };
export type { HintCheck, HintName, HintReason } from '../veml/clientHintsVocabulary';

export type TouchButton = 'jump' | 'chat' | 'fly';

export interface ClientHints {
  /** The value in force for `name` (the world's, or the shell default); null for a name not implemented. */
  get(name: string): string | null;
  /** Set the world's preference at run time. False, and nothing changes, when the value is refused. */
  set(name: string, value: string): boolean;
  /**
   * A new world: replace the world's layer (and a script's changes to it)
   * with this world's hints, and tell every subscriber about every name.
   */
  load(world: Partial<Record<string, string>> | undefined, baseUrl?: string): void;
  /** Called with the name after every accepted `set`, and for every name on `load`. Returns the unsubscribe. */
  subscribe(fn: (name: HintName) => void): () => void;
  /** The world's avatar, resolved against its document; undefined → the shell's own. */
  avatarUrl(): string | undefined;
  /** The touch buttons the world wants, with chat dropped when chat is off. Fly still needs `modes` (the caller's). */
  touchButtons(): TouchButton[];
  /** Plain readers for the features. */
  flag(name: HintName): boolean;
  shown(name: HintName): boolean;
}

export interface ClientHintsOptions {
  /** The world's hints, already validated (the parser's output). */
  world?: Partial<Record<string, string>>;
  /** The world document's URL, for `people.avatar`. */
  baseUrl?: string;
}

export function createClientHints(options: ClientHintsOptions = {}): ClientHints {
  const world = new Map<HintName, string>();
  let baseUrl = options.baseUrl;
  const fill = (from: Partial<Record<string, string>> | undefined): void => {
    world.clear();
    for (const [name, value] of Object.entries(from ?? {})) {
      if (isHintName(name) && typeof value === 'string') world.set(name, value);
    }
  };
  fill(options.world);
  const listeners = new Set<(name: HintName) => void>();
  const read = (name: HintName): string => world.get(name) ?? HINT_DEFAULTS[name];

  return {
    get: (name) => (isHintName(name) ? read(name) : null),
    set(name, value) {
      const check = validateHint(name, String(value));
      if (!check.ok || !isHintName(name)) return false;
      world.set(name, check.value);
      for (const fn of [...listeners]) fn(name);
      return true;
    },
    load(next, nextBaseUrl) {
      fill(next);
      baseUrl = nextBaseUrl;
      for (const name of Object.keys(HINT_SPECS) as HintName[]) for (const fn of [...listeners]) fn(name);
    },
    subscribe(fn) {
      listeners.add(fn);
      return () => listeners.delete(fn);
    },
    avatarUrl() {
      const raw = read('people.avatar');
      if (raw === '') return undefined;
      try {
        return new URL(raw, baseUrl).href;
      } catch {
        return undefined;
      }
    },
    touchButtons() {
      const list = read('controls.touch-buttons');
      if (list === 'none') return [];
      const chatOn = read('chat.enabled') === 'true';
      return list.split(/\s+/).filter((t): t is TouchButton => (t === 'jump' || t === 'fly' || (t === 'chat' && chatOn)));
    },
    flag: (name) => read(name) === 'true',
    shown: (name) => read(name) !== 'hide',
  };
}
