/**
 * The settings menu: a button and a panel over the settings layer
 * every page already has.
 *
 * It reuses the shell's shared settings infrastructure, so nothing here
 * keeps a store of its own. What it changes goes through the settings
 * controller's `saveUserSettings` (the persisted user layer,
 * `webverse:settings:v1`, under an embedder's overrides), and the name is
 * the visitor name the people messages already keep, chosen through
 * `chooseVisitorName`. The published-world boot and the full app mount this
 * same module.
 *
 * The button sits top-LEFT: top-right belongs to the Enter VR button, which
 * the menu button would otherwise cover. A top-left chat panel moves down
 * below it.
 *
 * Rows today: your name, where chat sits, look speed, quality and
 * anti-aliasing. Adding a row is adding a
 * field that reads `controller.get()` and writes `saveUserSettings`. The
 * panel is capped to the viewport and scrolls inside itself, so a row
 * added at the bottom never pushes Close off a small screen.
 */
import { DEFAULT_MESSAGES_SETTINGS, type MessagesCorner, type PartialShellSettings, type ShellSettings } from './shellSettings';
import { chooseVisitorName, visitorName, type NameStore } from '../net/visitorIdentity';
import type { ClientHints } from '../hints/clientHints';
import { QUALITY_TIERS, TEMPORAL_CHOICES, type QualityTier } from './quality';
import type { StyleOffer } from '../scene/placements/placementsView';

export interface SettingsMenuDeps {
  controller: { get(): ShellSettings; saveUserSettings(partial: PartialShellSettings): void };
  /** Where the visitor name is kept (the page's localStorage). */
  nameStore?: NameStore;
  /** A setting changed: redraw what reads it (the messages panel). */
  onChanged?: () => void;
  /** Forget what the visitor allowed or blocked for the current world's site (§9); the next visit asks again. */
  onForgetConsent?: () => void;
  /**
   * The world's `controls.menu` hint (profiles/client-hints.md): hide
   * takes the button off the page, live. The visitor's settings are not
   * hidden from them: the shell keeps them, and a later world may show it.
   */
  hints?: ClientHints;
  /** The tier auto picks on this device, shown beside it. */
  autoQuality?: QualityTier;
  /** The styles the current world's items come in and the visitor's choice among them, read each time the menu opens; none hides the Style row. */
  styles?: () => StyleOffer | undefined;
}

export interface SettingsMenu {
  open(): void;
  close(): void;
  isOpen(): boolean;
  dispose(): void;
}

/** Where chat may sit, and each place's name, in the same order. */
const CORNERS: readonly MessagesCorner[] = ['bottom-left', 'bottom-right', 'top-left', 'top-right'];
const CORNER_NAMES = ['Bottom left', 'Bottom right', 'Top left', 'Top right'];

const CSS = `[data-webverse-menu-button]{position:fixed;top:12px;left:12px;z-index:30;width:40px;height:40px;border-radius:50%;display:flex;align-items:center;justify-content:center;cursor:pointer;user-select:none;-webkit-user-select:none;font:20px/1 system-ui,sans-serif;color:#fff;background:rgba(0,0,0,.45);border:1px solid rgba(255,255,255,.4);-webkit-tap-highlight-color:transparent;touch-action:manipulation}[data-webverse-menu]{position:fixed;z-index:31;top:50%;left:50%;transform:translate(-50%,-50%);width:min(340px,92vw);box-sizing:border-box;padding:16px 18px;border-radius:10px;max-height:calc(100vh - 24px);max-height:calc(100dvh - 24px);overflow-y:auto;background:rgba(20,20,24,.92);color:#fff;font:15px/1.4 system-ui,sans-serif;box-shadow:0 8px 30px rgba(0,0,0,.5)}[data-webverse-menu][hidden]{display:none}[data-webverse-menu] h2{margin:0 0 12px;font-size:17px;font-weight:600}[data-webverse-menu] label:not([hidden]){display:block;margin:10px 0 4px;opacity:.85;font-size:13px}[data-webverse-menu] input[type=range]{padding:0;accent-color:#7aa2ff}[data-webverse-menu] input[type=checkbox]{width:auto;margin:0 6px 0 0;vertical-align:middle;accent-color:#7aa2ff}[data-webverse-menu] input,[data-webverse-menu] select{width:100%;box-sizing:border-box;padding:7px 9px;font:inherit;color:#fff;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.3);border-radius:6px}[data-webverse-menu] select option{color:#000}[data-webverse-menu-note]{min-height:1.2em;margin:4px 0 0;font-size:12px;opacity:.75}[data-webverse-menu-close]{margin-top:16px;width:100%;padding:8px;font:inherit;color:#fff;cursor:pointer;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.35);border-radius:6px}body #webverse-messages[data-webverse-messages-corner="top-left"]{top:60px}`;

export function mountSettingsMenu(doc: Document, deps: SettingsMenuDeps): SettingsMenu {
  // A select's options, each value with its name, in place of any it had.
  const fill = (select: HTMLSelectElement, values: readonly string[], names: readonly string[]): void =>
    select.replaceChildren(
      ...values.map((value, i) => {
        const option = doc.createElement('option');
        option.value = value;
        option.textContent = names[i]!;
        return option;
      }),
    );
  const style = doc.createElement('style');
  style.textContent = CSS;
  doc.head.appendChild(style);

  const button = doc.createElement('div');
  button.setAttribute('data-webverse-menu-button', '');
  button.setAttribute('role', 'button');
  button.setAttribute('tabindex', '0');
  button.setAttribute('aria-label', 'Settings');
  button.textContent = '☰';

  const panel = doc.createElement('div');
  panel.setAttribute('data-webverse-menu', '');
  panel.setAttribute('role', 'dialog');
  panel.setAttribute('aria-label', 'Settings');
  panel.hidden = true;

  const title = doc.createElement('h2');
  title.textContent = 'Settings';

  const nameLabel = doc.createElement('label');
  nameLabel.textContent = 'Your name';
  const name = doc.createElement('input');
  name.type = 'text';
  name.maxLength = 40;
  name.autocomplete = 'off';
  name.setAttribute('data-webverse-menu-field', 'name');
  nameLabel.htmlFor = name.id = 'webverse-menu-name';
  const note = doc.createElement('p');
  note.setAttribute('data-webverse-menu-note', '');

  const cornerLabel = doc.createElement('label');
  cornerLabel.textContent = 'Chat position';
  const corner = doc.createElement('select');
  corner.setAttribute('data-webverse-menu-field', 'corner');
  cornerLabel.htmlFor = corner.id = 'webverse-menu-corner';
  fill(corner, CORNERS, CORNER_NAMES);

  // Keep messages on screen: lines never fade (messages.fadeMs 0).
  const keepLabel = doc.createElement('label');
  const keep = doc.createElement('input');
  keep.type = 'checkbox';
  keep.setAttribute('data-webverse-menu-field', 'keep-messages');
  keep.id = 'webverse-menu-keep-messages';
  keepLabel.htmlFor = keep.id;
  keepLabel.append(keep, doc.createTextNode(' Keep messages on screen'));

  // Look speed: how fast the mouse or the look stick turns you.
  const speedLabel = doc.createElement('label');
  speedLabel.textContent = 'Look speed';
  const speed = doc.createElement('input');
  speed.type = 'range';
  speed.min = '0.25';
  speed.max = '3';
  speed.step = '0.25';
  speed.setAttribute('data-webverse-menu-field', 'look-speed');
  speedLabel.htmlFor = speed.id = 'webverse-menu-look-speed';

  // Quality: how much this device draws; auto starts from what the browser says about it.
  const qualityLabel = doc.createElement('label');
  qualityLabel.textContent = 'Quality';
  const quality = doc.createElement('select');
  quality.setAttribute('data-webverse-menu-field', 'quality');
  qualityLabel.htmlFor = quality.id = 'webverse-menu-quality';
  fill(quality, ['auto', ...QUALITY_TIERS], [deps.autoQuality ? `Auto (${deps.autoQuality})` : 'Auto', ...QUALITY_TIERS.map((value) => value[0]!.toUpperCase() + value.slice(1))]);

  // A graphics choice: a labelled select, saved to the visitor's settings as it changes. Style is the exception: the
  // world holds it while the visitor is there, and it is never saved with their settings.
  const choice = (text: string, key: 'temporal' | 'motionBlur' | 'focus' | 'terrainStyle' | 'relief' | 'things' | 'style', values: readonly string[], names: readonly string[]) => {
    const label = doc.createElement('label');
    label.textContent = text;
    const select = doc.createElement('select');
    select.setAttribute('data-webverse-menu-field', key);
    label.htmlFor = select.id = `webverse-menu-${key}`;
    fill(select, values, names);
    select.addEventListener('change', () => {
      if (key === 'style') return deps.styles?.()?.choose(select.value);
      deps.controller.saveUserSettings({ graphics: { [key]: select.value } as Partial<ShellSettings['graphics']> });
      deps.onChanged?.();
    });
    return [label, select] as const;
  };
  // Anti-aliasing: edges smoothed over frames on a planet, and the scene drawn smaller and rebuilt from them.
  const [temporalLabel, temporal] = choice('Anti-aliasing', 'temporal', TEMPORAL_CHOICES, ['Auto', 'Off', 'Temporal', 'Temporal, upscaled']);
  // Motion blur: a little on a planet's fast turns and flight; off unless the visitor turns it on.
  const [blurLabel, blur] = choice('Motion blur', 'motionBlur', ['off', 'on'], ['Off', 'On']);
  // Depth of field: the far ground softened from high up; the world's choice unless the visitor picks.
  const [focusLabel, focus] = choice('Depth of field', 'focus', ['auto', 'off', 'on'], ['World\u2019s choice', 'Off', 'On']);
  // Terrain: a planet's ground smoothed or as whole blocks; the world's choice unless the visitor picks.
  const [terrainLabel, terrain] = choice('Terrain', 'terrainStyle', ['auto', 'smooth', 'blocks'], ['World\u2019s choice', 'Smooth', 'Blocks']);
  // Block relief: the near blocks' faces raised by their own pictures; the world's choice unless the visitor picks.
  const [reliefLabel, relief] = choice('Block relief', 'relief', ['auto', 'off', 'on'], ['World\u2019s choice', 'Off', 'On']);
  // Moving things: what moves on a planet's surface, such as trains; the world's choice unless the visitor picks.
  const [thingsLabel, things] = choice('Moving things', 'things', ['auto', 'shown', 'hidden'], ['World\u2019s choice', 'Shown', 'Hidden']);
  // Style: the look placed items are drawn in, among the styles the world's items name; its options are set as the menu opens.
  const [styleLabel, styleChoice] = choice('Style', 'style', [], []);

  const close = doc.createElement('button');
  close.type = 'button';
  close.setAttribute('data-webverse-menu-close', '');
  close.textContent = 'Close';

  // What the visitor allowed or blocked for this site (§9), forgettable here.
  const forget = doc.createElement('button');
  forget.type = 'button';
  forget.setAttribute('data-webverse-menu-forget-consent', '');
  forget.textContent = "Forget this site's permissions";
  forget.style.cssText =
    'margin-top:12px;width:100%;padding:8px;font:inherit;color:#fff;cursor:pointer;' +
    'background:transparent;border:1px solid rgba(255,255,255,.35);border-radius:6px';
  forget.hidden = deps.onForgetConsent === undefined;

  panel.append(title, nameLabel, name, note, cornerLabel, corner, keepLabel, speedLabel, speed, qualityLabel, quality, temporalLabel, temporal, blurLabel, blur, focusLabel, focus, terrainLabel, terrain, reliefLabel, relief, thingsLabel, things, styleLabel, styleChoice, forget, close);
  doc.body.append(button, panel);

  const saveName = (): void => {
    const chosen = chooseVisitorName(deps.nameStore, name.value);
    if (chosen === null) {
      name.value = visitorName(deps.nameStore);
      note.textContent = 'A name cannot be blank.';
      return;
    }
    name.value = chosen;
    // The name travels with the hello, so the room sees it from the next join.
    note.textContent = `Saved. Others see "${chosen}" from your next visit.`;
  };

  // While open, Escape shuts it from anywhere on the page: after a pick from
  // the select, focus is not always inside the panel (found in e2e). While
  // shut, nothing is listened to.
  const onDocKey = (ev: KeyboardEvent): void => {
    if (ev.key !== 'Escape') return;
    ev.preventDefault();
    shut();
  };
  const open = (): void => {
    name.value = visitorName(deps.nameStore);
    note.textContent = '';
    corner.value = deps.controller.get().messages.corner;
    speed.value = String(deps.controller.get().locomotion.lookSpeed);
    keep.checked = deps.controller.get().messages.fadeMs <= 0;
    quality.value = deps.controller.get().graphics.quality;
    temporal.value = deps.controller.get().graphics.temporal;
    blur.value = deps.controller.get().graphics.motionBlur ?? 'off';
    focus.value = deps.controller.get().graphics.focus ?? 'auto';
    terrain.value = deps.controller.get().graphics.terrainStyle ?? 'auto';
    relief.value = deps.controller.get().graphics.relief ?? 'auto';
    things.value = deps.controller.get().graphics.things ?? 'auto';
    // The world's styles as they are now, after the world's own choice; the row only where there are some.
    const offer = deps.styles?.();
    const styles = offer?.names ?? [];
    fill(styleChoice, ['auto', ...styles], ['World’s choice', ...styles]);
    const chosen = offer?.current();
    styleChoice.value = chosen && styles.includes(chosen) ? chosen : 'auto';
    styleLabel.hidden = styleChoice.hidden = !styles.length;
    panel.hidden = false;
    button.setAttribute('aria-expanded', 'true');
    doc.addEventListener('keydown', onDocKey);
  };
  function shut(): void {
    panel.hidden = true;
    button.setAttribute('aria-expanded', 'false');
    doc.removeEventListener('keydown', onDocKey);
  }

  const onButton = (ev: Event): void => {
    ev.preventDefault();
    if (panel.hidden) open();
    else shut();
  };
  const onButtonKey = (ev: KeyboardEvent): void => {
    if (ev.key === 'Enter' || ev.key === ' ') onButton(ev);
  };
  // Everything typed in the menu is the menu's: the world never sees a key
  // from it. Escape shuts it.
  const onPanelKey = (ev: KeyboardEvent): void => {
    ev.stopPropagation();
    if (ev.key === 'Escape') {
      ev.preventDefault();
      shut();
    } else if (ev.key === 'Enter' && ev.target === name) {
      ev.preventDefault();
      saveName();
    }
  };
  const stopKey = (ev: Event): void => ev.stopPropagation();
  const onCorner = (): void => {
    deps.controller.saveUserSettings({ messages: { corner: corner.value as MessagesCorner } });
    deps.onChanged?.();
  };

  const onKeep = (): void => {
    deps.controller.saveUserSettings({ messages: { fadeMs: keep.checked ? 0 : DEFAULT_MESSAGES_SETTINGS.fadeMs } });
    deps.onChanged?.();
  };
  const onSpeed = (): void => {
    const v = Number(speed.value);
    if (!Number.isFinite(v) || v <= 0) return;
    deps.controller.saveUserSettings({ locomotion: { lookSpeed: v } });
    deps.onChanged?.();
  };

  const onQuality = (): void => {
    deps.controller.saveUserSettings({ graphics: { quality: quality.value as QualityTier | 'auto' } });
    deps.onChanged?.();
  };
  quality.addEventListener('change', onQuality);

  button.addEventListener('click', onButton);
  button.addEventListener('keydown', onButtonKey);
  panel.addEventListener('keydown', onPanelKey);
  panel.addEventListener('keyup', stopKey);
  name.addEventListener('change', saveName);
  corner.addEventListener('change', onCorner);
  speed.addEventListener('input', onSpeed);
  keep.addEventListener('change', onKeep);
  forget.addEventListener('click', () => {
    deps.onForgetConsent?.();
    note.textContent = 'Forgotten. This site will ask again next time.';
  });
  close.addEventListener('click', shut);

  // The button follows the world's hint, live.
  const followHint = (): void => {
    const want = deps.hints?.shown('controls.menu') ?? true;
    if (want && !button.isConnected) doc.body.insertBefore(button, panel);
    if (!want && button.isConnected) {
      shut();
      button.remove();
    }
  };
  followHint();
  const unsubscribe = deps.hints?.subscribe((name) => {
    if (name === 'controls.menu') followHint();
  });

  let disposed = false;
  return {
    open,
    close: shut,
    isOpen: () => !panel.hidden,
    dispose() {
      if (disposed) return;
      disposed = true;
      unsubscribe?.();
      doc.removeEventListener('keydown', onDocKey);
      button.removeEventListener('click', onButton);
      button.removeEventListener('keydown', onButtonKey);
      panel.removeEventListener('keydown', onPanelKey);
      panel.removeEventListener('keyup', stopKey);
      name.removeEventListener('change', saveName);
      corner.removeEventListener('change', onCorner);
      speed.removeEventListener('input', onSpeed);
      keep.removeEventListener('change', onKeep);
      close.removeEventListener('click', shut);
      button.remove();
      panel.remove();
      style.remove();
    },
  };
}
