/**
 * Light entity builder.
 *
 * Builds a declared `light` ENTITY (distinct from the world-owned default
 * lighting profile) into a Babylon light.
 *
 * Schema truth: the XSD `light` type is EMPTY, which means a DEFAULT
 * directional white intensity-1 light. The shell additionally reads the
 * WorldKit Blender plugin's forward-extension child elements
 * (light-type/color/intensity/range/spot-angle) so a world can declare
 * point, directional and spot lights; absent fields fall back to those
 * defaults, which conform to the schema.
 *
 * Field mapping:
 * - light-type → Babylon class: point→PointLight, directional→DirectionalLight,
 *   spot→SpotLight. Absent → directional (the schema default). Unknown
 *   or `area` → degraded to point + warn (no area light is built).
 * - color → light.diffuse (default WHITE), scaled per channel by the
 *   temperature's tint (lightColor.ts): the colour is what the light would be
 *   in daylight, the temperature warms or cools it.
 * - intensity → light.intensity (default 1).
 * - range → PointLight/SpotLight .range (directional ignores range).
 * - spot-angle (DEGREES) → SpotLight .angle (RADIANS — converted).
 * - cast-shadows → the caller hands the light to the world's shadow rig
 *   (shadows.ts), which decides and reports; this builder only builds.
 *
 * SCALE IS IGNORED, per the XSD light note "Scale is ignored". This
 * builder applies POSITION and ROTATION only — a transform's scale changes
 * nothing observable (asserted in tests). Deep per-module imports only, to
 * keep the first-paint bundle small.
 */
import { Vector3 } from '@babylonjs/core/Maths/math.vector';
import { Color3 } from '@babylonjs/core/Maths/math.color';
import { PointLight } from '@babylonjs/core/Lights/pointLight';
import { DirectionalLight } from '@babylonjs/core/Lights/directionalLight';
import { SpotLight } from '@babylonjs/core/Lights/spotLight';
import type { Light } from '@babylonjs/core/Lights/light';
import type { Node } from '@babylonjs/core/node';
import type { Scene } from '@babylonjs/core/scene';
import type { VemlLightEntity } from '../veml/documentModel';
import { vemlPositionToBabylon, vemlRotationToBabylon } from './vemlTransform';
import { parseVemlColor } from './primitives';
import { composeLightColor, type Rgb } from './lightColor';
import { log } from '../logging/runtimeLog';

/** Canonical light-type ids the shell builds. Absent → directional (default). */
export type ResolvedLightType = 'point' | 'directional' | 'spot';

/** Default intensity when none is authored. */
export const DEFAULT_LIGHT_INTENSITY = 1;
/**
 * Default cone angle (FULL angle, degrees) when no spot-angle is authored.
 * Babylon `SpotLight.angle` and the authored spot-angle are both the FULL cone
 * angle, so the authored value maps degrees→radians directly (no halving).
 */
export const DEFAULT_SPOT_ANGLE_DEG = 45;

const DEG_TO_RAD = Math.PI / 180;

/** A light's local forward (+Z), rotated by the entity rotation → direction. */
const LIGHT_FORWARD = new Vector3(0, 0, 1);

/**
 * What the light's diffuse was composed from, kept on the light so a later
 * change to one part (a script setting only the temperature) recomposes
 * from the authored colour instead of tinting a tint.
 */
export interface LightColorSource {
  base: Rgb;
  temperature?: number;
}

const COLOR_SOURCE_KEY = 'webverseLightColor';

/** The colour the light was last composed from; white with no temperature when nothing was recorded. */
export function lightColorSourceOf(light: Light): LightColorSource {
  const meta = light.metadata as Record<string, unknown> | null | undefined;
  const source = meta?.[COLOR_SOURCE_KEY] as LightColorSource | undefined;
  return source ? { base: { ...source.base }, temperature: source.temperature } : { base: { r: 1, g: 1, b: 1 } };
}

/** Set the light's diffuse to `base × tint(temperature)` and remember both parts. */
export function applyLightColor(light: Light, source: LightColorSource): void {
  const { r, g, b } = composeLightColor(source.base, source.temperature);
  light.diffuse = new Color3(r, g, b);
  const meta = (light.metadata as Record<string, unknown> | null | undefined) ?? {};
  meta[COLOR_SOURCE_KEY] = { base: { ...source.base }, temperature: source.temperature };
  light.metadata = meta;
}

/**
 * Resolve the authored light-type to a class the shell builds. Absent →
 * directional (the schema default). `area`/unknown → point (degrade) with a
 * warning.
 */
export function resolveLightType(raw: string | undefined, tag: string): ResolvedLightType {
  if (raw === undefined) return 'directional';
  const t = raw.trim().toLowerCase();
  if (t === 'point' || t === 'directional' || t === 'spot') return t;
  log.warn(
    `[webverse] light '${tag}': unsupported light-type '${raw}' — using point (area lights are not supported; degraded)`,
  );
  return 'point';
}

/** Position/rotation from the (scale-ignored) transform; identity when absent. */
function lightPose(entity: VemlLightEntity): { position: Vector3; direction: Vector3 } {
  const transform = entity.transform;
  if (transform !== undefined && transform.kind === 'scaletransform') {
    const rotation = vemlRotationToBabylon(transform.rotation);
    const direction = LIGHT_FORWARD.clone();
    direction.rotateByQuaternionToRef(rotation, direction);
    return { position: vemlPositionToBabylon(transform.position), direction };
  }
  // Absent transform (or a rejected non-scale kind the caller already skipped):
  // identity — position at origin, direction = forward.
  return { position: new Vector3(0, 0, 0), direction: LIGHT_FORWARD.clone() };
}

/**
 * Build the Babylon light for a `light` entity. Returns the light (the caller
 * registers it under the entity for disposal — a Light rides the registry
 * entry's `disposers`, not meshes/materials/textures). Never applies scale.
 */
export function createLightEntity(
  entity: VemlLightEntity,
  scene: Scene,
  parentNode: Node | null,
): Light {
  const tag = entity.tag ?? 'light';
  const kind = resolveLightType(entity.lightType, tag);
  const { position, direction } = lightPose(entity);
  const intensity = entity.intensity ?? DEFAULT_LIGHT_INTENSITY;
  // Default WHITE when no color authored.
  const { color } = parseVemlColor(entity.color ?? '#ffffff');

  let light: Light;
  switch (kind) {
    case 'point': {
      const p = new PointLight(`light:${tag}`, position, scene);
      if (entity.range !== undefined) p.range = entity.range;
      light = p;
      break;
    }
    case 'directional': {
      // Directional has no position; the frustum position is set for parity
      // but only the direction lights the scene. Range is ignored.
      const d = new DirectionalLight(`light:${tag}`, direction, scene);
      d.position = position;
      light = d;
      break;
    }
    case 'spot': {
      const angleRad = (entity.spotAngle ?? DEFAULT_SPOT_ANGLE_DEG) * DEG_TO_RAD;
      const s = new SpotLight(`light:${tag}`, position, direction, angleRad, 1, scene);
      if (entity.range !== undefined) s.range = entity.range;
      light = s;
      break;
    }
  }

  applyLightColor(light, {
    base: { r: color.r, g: color.g, b: color.b },
    ...(entity.temperature !== undefined && Number.isFinite(entity.temperature) ? { temperature: entity.temperature } : {}),
  });
  light.intensity = intensity;
  if (parentNode) light.parent = parentNode;

  return light;
}
