/**
 * Autoplay gesture gate.
 *
 * Browsers suspend the WebAudio AudioContext until a genuine user gesture
 * (autoplay policy), so `auto-play` cannot start sound at load: autoplay is
 * deferred to the first user gesture.
 *
 * This module is a DOM-free state machine so it is fully unit-testable without
 * a browser: `notifyGesture()` flips the latch and flushes queued callbacks
 * once; `onGesture(cb)` runs immediately if already gestured, else queues (and
 * returns an unregister so an entity that disposes before the gesture removes
 * its callback — no resurrecting a disposed Sound). Gesture state is PERSISTENT
 * across worlds: once the user has interacted, later worlds' autoplay may start
 * immediately (correct browser behavior).
 *
 * DOM wiring is a SEPARATE helper (`armDomGestureListeners`) so tests never
 * need a DOM; main.ts arms it on the live canvas + window in the browser.
 */
import { log } from '../logging/runtimeLog';

export interface AudioGestureGate {
  /** Has a user gesture occurred this session? */
  hasGestured(): boolean;
  /**
   * Run `cb` when a user gesture occurs. If one already occurred, `cb` runs
   * synchronously now. Returns an unregister that removes a still-pending `cb`.
   */
  onGesture(cb: () => void): () => void;
  /** Latch the gesture and flush every pending callback exactly once. */
  notifyGesture(): void;
  /** Callbacks still waiting for the first gesture (observability/tests). */
  pendingCount(): number;
  /** Drop all pending callbacks (they will never fire). */
  dispose(): void;
}

export function createAudioGestureGate(): AudioGestureGate {
  let gestured = false;
  let disposed = false;
  const pending = new Set<() => void>();

  return {
    hasGestured(): boolean {
      return gestured;
    },
    onGesture(cb: () => void): () => void {
      if (disposed) return () => {};
      if (gestured) {
        cb();
        return () => {};
      }
      pending.add(cb);
      return () => {
        pending.delete(cb);
      };
    },
    notifyGesture(): void {
      if (disposed || gestured) return;
      gestured = true;
      // Snapshot: a callback may (indirectly) register another; the new one
      // sees `gestured === true` and runs immediately, never re-queued here.
      const callbacks = [...pending];
      pending.clear();
      for (const cb of callbacks) {
        // A callback could dispose the gate mid-flush; honor that immediately
        // and stop running the rest of the snapshot.
        if (disposed) break;
        try {
          cb();
        } catch (err) {
          log.warn('[webverse] audio gesture callback threw:', err);
        }
      }
    },
    pendingCount(): number {
      return pending.size;
    },
    dispose(): void {
      disposed = true;
      pending.clear();
    },
  };
}

/** Event types that count as an activating user gesture. */
const GESTURE_EVENTS = ['pointerdown', 'keydown', 'touchstart'] as const;

/**
 * Attach real-DOM gesture listeners that latch the gate on the first genuine
 * user interaction. Returns a disposer that removes every listener. Kept out
 * of the state machine so unit tests stay DOM-free.
 */
export function armDomGestureListeners(
  gate: AudioGestureGate,
  target: {
    addEventListener(type: string, listener: () => void, options?: unknown): void;
    removeEventListener(type: string, listener: () => void, options?: unknown): void;
  },
): () => void {
  const handler = (): void => gate.notifyGesture();
  for (const type of GESTURE_EVENTS) {
    target.addEventListener(type, handler);
  }
  return () => {
    for (const type of GESTURE_EVENTS) {
      target.removeEventListener(type, handler);
    }
  };
}
