/**
 * Water in the scene (`specs/veml/profiles/water.md`).
 *
 * A body is a box whose top face is the surface; this module draws that face
 * as one mesh per body, answers the one question the visitor controller asks
 * (are these feet in water, and where is the surface and the bed), and tints
 * the view when the eye is under a surface.
 *
 * What a body is not: an entity. Its surface is never registered, so it is
 * never walkable and never picked, and a script cannot reach it. A blocker is
 * a box in which water does not apply; it has no mesh at all.
 *
 * The material comes from a code-split chunk (waterChunk.ts) and arrives
 * after the surface exists. Until then, and when the chunk cannot load, the
 * surface is a flat plane in the body's shallow colour: being wet never
 * depends on the shader (profile, Degradation 2).
 */
import { CreateGround } from '@babylonjs/core/Meshes/Builders/groundBuilder';
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import type { Mesh } from '@babylonjs/core/Meshes/mesh';
import { Color3 } from '@babylonjs/core/Maths/math.color';
import { Matrix, Quaternion, Vector3 } from '@babylonjs/core/Maths/math.vector';
import { VertexBuffer } from '@babylonjs/core/Buffers/buffer';
import { Scene } from '@babylonjs/core/scene';
import { StandardMaterial } from '../../engine/shaderImports';
import { probeWalkableSurfaceY, type WalkableSource } from '../../controller/groundProbe';
import { log } from '../../logging/runtimeLog';
import type { VemlWater, VemlWaterBlocker, VemlWaterBody } from '../../veml/documentModel';
import type { WaterBlockerBox, WaterChunkModule, WaterMaterialHandle } from './waterChunk';

export type { WaterChunkModule } from './waterChunk';
export type WaterChunkLoader = () => Promise<WaterChunkModule>;

/** What the controller learns about a point in the water. */
export interface WaterSample {
  /** The surface's height. */
  surfaceY: number;
  /** The walkable ground under this column, or null for a bottomless body. */
  bedY: number | null;
}

export interface WaterReport {
  bodies: number;
  blockers: number;
  surfaces: number;
  /** Which material the surfaces wear: the chunk's shader, the flat fallback, or not yet decided. */
  material: 'pending' | 'shader' | 'flat';
  /** The eye was under a surface on the last tick. */
  underwater: boolean;
}

export interface WaterHandle {
  /** The water at these feet, or null: above every surface, outside every box, or inside a blocker. */
  query(feet: Vector3): WaterSample | null;
  surfaces(): readonly AbstractMesh[];
  report(): WaterReport;
  /** Per frame: the waves move, the bed is re-read if the walkable set changed, the eye's tint follows. */
  tick(dtS: number, eye?: Vector3): void;
  /** Re-read the bed under every surface vertex (the depth the shader shades by). */
  refreshDepths(): void;
  /** Resolves once the material decision is made (shader or flat). Never rejects. */
  ready(): Promise<void>;
  dispose(): void;
}

export interface CreateWaterOptions {
  /** The chunk loader seam; defaults to the dynamic import. Unit tests inject a fake. */
  loader?: WaterChunkLoader;
  /** The walkable set, for the bed under a body. */
  walkables: WalkableSource;
  engineKind?: string;
}

export function emptyWaterReport(): WaterReport {
  return { bodies: 0, blockers: 0, surfaces: 0, material: 'flat', underwater: false };
}

/** How far the deep colour reaches when nothing lies under a body: deep, by definition. */
const BOTTOMLESS_DEPTH_FACTOR = 2;
/** Exponential fog density under water: the deep colour, with the world still visible (~30 m). */
const UNDERWATER_FOG_DENSITY = 0.08;
/** The surface mesh's finest division, in metres; a small body gets at least one quad. */
const SURFACE_QUAD_M = 2;
const SURFACE_MAX_SUBDIVISIONS = 64;

const defaultLoader: WaterChunkLoader = () => import('./waterChunk');

interface Body {
  spec: VemlWaterBody;
  mesh: Mesh;
  flat: StandardMaterial;
  shader: WaterMaterialHandle | null;
}

interface BlockerBox {
  inverse: Matrix;
  half: Vector3;
}

function blockerBox(b: VemlWaterBlocker): BlockerBox {
  const rotation = new Quaternion(b.rotation.x, b.rotation.y, b.rotation.z, b.rotation.w);
  if (rotation.length() === 0) rotation.set(0, 0, 0, 1);
  rotation.normalize();
  const world = Matrix.Compose(Vector3.One(), rotation, new Vector3(b.position.x, b.position.y, b.position.z));
  return { inverse: world.invert(), half: new Vector3(b.extent.x / 2, b.extent.y / 2, b.extent.z / 2) };
}

function insideBlocker(point: Vector3, box: BlockerBox): boolean {
  const local = Vector3.TransformCoordinates(point, box.inverse);
  return Math.abs(local.x) <= box.half.x && Math.abs(local.y) <= box.half.y && Math.abs(local.z) <= box.half.z;
}

function insideBody(point: Vector3, b: VemlWaterBody): boolean {
  return (
    Math.abs(point.x - b.position.x) <= b.extent.x / 2 &&
    Math.abs(point.z - b.position.z) <= b.extent.z / 2 &&
    point.y < b.position.y &&
    point.y >= b.position.y - b.extent.y
  );
}

export function createWater(scene: Scene, water: VemlWater, options: CreateWaterOptions): WaterHandle {
  const loader = options.loader ?? defaultLoader;
  const blockers = water.blockers.map(blockerBox);
  const shaderBoxes: WaterBlockerBox[] = blockers.map((b) => ({ inverse: b.inverse, half: { x: b.half.x, y: b.half.y, z: b.half.z } }));
  const bodies: Body[] = [];
  let material: WaterReport['material'] = water.bodies.length === 0 ? 'flat' : 'pending';
  let disposed = false;
  let time = 0;
  let lastWalkables: readonly AbstractMesh[] | null = null;
  let underwater = false;
  let savedFog: { mode: number; color: Color3; density: number } | null = null;

  water.bodies.forEach((spec, i) => {
    const subdivisionsX = Math.min(SURFACE_MAX_SUBDIVISIONS, Math.max(1, Math.ceil(spec.extent.x / SURFACE_QUAD_M)));
    const subdivisionsY = Math.min(SURFACE_MAX_SUBDIVISIONS, Math.max(1, Math.ceil(spec.extent.z / SURFACE_QUAD_M)));
    const mesh = CreateGround(
      `water:surface:${i}`,
      { width: spec.extent.x, height: spec.extent.z, subdivisionsX, subdivisionsY, updatable: true },
      scene,
    );
    mesh.position.set(spec.position.x, spec.position.y, spec.position.z);
    mesh.isPickable = false;
    mesh.checkCollisions = false;
    mesh.receiveShadows = false;
    mesh.computeWorldMatrix(true);
    const flat = new StandardMaterial(`water:flat:${i}`, scene);
    flat.diffuseColor = new Color3(spec.color.r, spec.color.g, spec.color.b);
    flat.specularColor = Color3.Black();
    flat.alpha = spec.color.a;
    flat.backFaceCulling = false;
    mesh.material = flat;
    bodies.push({ spec, mesh, flat, shader: null });
  });

  const depthOf = (spec: VemlWaterBody, x: number, z: number): number => {
    const ground = probeWalkableSurfaceY(options.walkables, x, z, spec.position.y);
    if (ground === null) return spec.clarity * BOTTOMLESS_DEPTH_FACTOR + 1;
    return Math.max(0, spec.position.y - ground);
  };

  const refreshDepths = (): void => {
    for (const b of bodies) {
      const positions = b.mesh.getVerticesData(VertexBuffer.PositionKind);
      if (!positions) continue;
      const count = positions.length / 3;
      const depths = new Float32Array(count);
      for (let v = 0; v < count; v += 1) {
        const x = positions[v * 3]! + b.spec.position.x;
        const z = positions[v * 3 + 2]! + b.spec.position.z;
        depths[v] = depthOf(b.spec, x, z);
      }
      b.mesh.setVerticesData('depth', depths, true, 1);
    }
  };

  const bedUnder = (spec: VemlWaterBody, x: number, z: number): number | null =>
    probeWalkableSurfaceY(options.walkables, x, z, spec.position.y);

  const sampleAt = (point: Vector3): { body: VemlWaterBody; sample: WaterSample } | null => {
    for (const b of bodies) {
      if (!insideBody(point, b.spec)) continue;
      if (blockers.some((box) => insideBlocker(point, box))) return null;
      return { body: b.spec, sample: { surfaceY: b.spec.position.y, bedY: bedUnder(b.spec, point.x, point.z) } };
    }
    return null;
  };

  const setUnderwater = (body: VemlWaterBody | null): void => {
    const now = body !== null;
    if (now && !underwater) {
      savedFog = { mode: scene.fogMode, color: scene.fogColor.clone(), density: scene.fogDensity };
      scene.fogMode = Scene.FOGMODE_EXP;
      scene.fogDensity = UNDERWATER_FOG_DENSITY;
    }
    if (now && body) scene.fogColor = new Color3(body.deepColor.r, body.deepColor.g, body.deepColor.b);
    if (!now && underwater && savedFog) {
      scene.fogMode = savedFog.mode;
      scene.fogColor = savedFog.color;
      scene.fogDensity = savedFog.density;
      savedFog = null;
    }
    underwater = now;
  };

  // The chunk: one material per body (each has its own colours), swapped in
  // when it lands. A failure leaves the flat surface and says so once.
  const ready: Promise<void> =
    bodies.length === 0
      ? Promise.resolve()
      : loader()
          .then((chunk) => {
            if (disposed) return;
            for (const b of bodies) {
              const handle = chunk.createWaterMaterial(
                {
                  color: b.spec.color,
                  deepColor: b.spec.deepColor,
                  clarity: b.spec.clarity,
                  waves: b.spec.waves,
                  blockers: shaderBoxes,
                },
                scene,
                options.engineKind,
              );
              b.shader = handle;
              b.mesh.material = handle.material;
            }
            material = 'shader';
          })
          .catch((err: unknown) => {
            if (disposed) return;
            material = 'flat';
            log.warn(`[webverse] water: the surface material could not load; drawing flat colour — ${String(err)}`);
          });

  refreshDepths();

  return {
    query(feet: Vector3): WaterSample | null {
      return sampleAt(feet)?.sample ?? null;
    },
    surfaces(): readonly AbstractMesh[] {
      return bodies.map((b) => b.mesh);
    },
    report(): WaterReport {
      return { bodies: bodies.length, blockers: blockers.length, surfaces: bodies.length, material, underwater };
    },
    tick(dtS: number, eye?: Vector3): void {
      if (disposed) return;
      time += Number.isFinite(dtS) && dtS > 0 ? dtS : 0;
      for (const b of bodies) b.shader?.setTime(time);
      const walkables = options.walkables();
      if (walkables !== lastWalkables) {
        lastWalkables = walkables;
        refreshDepths();
      }
      if (eye) setUnderwater(sampleAt(eye)?.body ?? null);
    },
    refreshDepths,
    ready(): Promise<void> {
      return ready;
    },
    dispose(): void {
      if (disposed) return;
      disposed = true;
      setUnderwater(null);
      for (const b of bodies) {
        b.shader?.dispose();
        b.flat.dispose();
        b.mesh.dispose(false, false);
      }
      bodies.length = 0;
    },
  };
}
