import { CSS_NAMED_COLORS } from "./colors-data.js";
export const ZERO_VEC3 = { x: 0, y: 0, z: 0 };
export const ONE_VEC3 = { x: 1, y: 1, z: 1 };
export const IDENTITY_QUAT = { x: 0, y: 0, z: 0, w: 1 };
/** Element-form vec3: `<position x="0" y="1.5" z="-2"/>` — each component
 *  an attribute on a child element, omitted components take `def`. */
export function parseVec3Element(attrs, def) {
    return {
        x: attrs?.["x"] !== undefined ? Number(attrs["x"]) : def.x,
        y: attrs?.["y"] !== undefined ? Number(attrs["y"]) : def.y,
        z: attrs?.["z"] !== undefined ? Number(attrs["z"]) : def.z,
    };
}
/** Element-form quaternion: `<rotation x="0" y="0" z="0" w="1"/>`. */
export function parseQuatElement(attrs, def) {
    return {
        x: attrs?.["x"] !== undefined ? Number(attrs["x"]) : def.x,
        y: attrs?.["y"] !== undefined ? Number(attrs["y"]) : def.y,
        z: attrs?.["z"] !== undefined ? Number(attrs["z"]) : def.z,
        w: attrs?.["w"] !== undefined ? Number(attrs["w"]) : def.w,
    };
}
/** Attribute-form vec3: `center="0 1.5 -2"` — three space-separated
 *  doubles on a single attribute. */
export function parseVec3Attr(raw, def) {
    if (raw === undefined)
        return def;
    const parts = raw.trim().split(/\s+/).map(Number);
    return {
        x: parts[0] ?? def.x,
        y: parts[1] ?? def.y,
        z: parts[2] ?? def.z,
    };
}
/** Attribute-form quaternion: four space-separated doubles. */
export function parseQuatAttr(raw, def) {
    if (raw === undefined)
        return def;
    const parts = raw.trim().split(/\s+/).map(Number);
    return {
        x: parts[0] ?? def.x,
        y: parts[1] ?? def.y,
        z: parts[2] ?? def.z,
        w: parts[3] ?? def.w,
    };
}
const HEX_RE = /^#([0-9a-fA-F]{3}|[0-9a-fA-F]{4}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})$/;
const RGBA_RE = /^color\(\s*([^)]*)\)$/i;
function hexComponent(h) {
    return h.length === 1 ? parseInt(h + h, 16) : parseInt(h, 16);
}
function hexToColor(digits, raw) {
    if (digits.length === 3 || digits.length === 4) {
        const r = hexComponent(digits[0]);
        const g = hexComponent(digits[1]);
        const b = hexComponent(digits[2]);
        const a = digits.length === 4 ? hexComponent(digits[3]) : 255;
        return { form: "hex", r: r / 255, g: g / 255, b: b / 255, a: a / 255, raw };
    }
    const r = parseInt(digits.slice(0, 2), 16);
    const g = parseInt(digits.slice(2, 4), 16);
    const b = parseInt(digits.slice(4, 6), 16);
    const a = digits.length === 8 ? parseInt(digits.slice(6, 8), 16) : 255;
    return { form: "hex", r: r / 255, g: g / 255, b: b / 255, a: a / 255, raw };
}
const NEUTRAL = { form: "neutral" };
/** §4.5 color: hex (#rgb/#rrggbb/#rrggbbaa), `color(r g b a)` with
 *  components as doubles in 0-1, or an ASCII-case-insensitive CSS named
 *  color. Absent input is the neutral default (no diagnostic); a
 *  recognized-but-unparseable value resolves to the same neutral default
 *  with `veml:4.5:bad-color`. */
export function parseColor(raw) {
    if (raw === undefined)
        return { color: NEUTRAL };
    if (raw.startsWith("#")) {
        const m = HEX_RE.exec(raw);
        if (!m)
            return { color: { form: "neutral", raw }, diagnostic: { id: "veml:4.5:bad-color", detail: raw } };
        return { color: hexToColor(m[1], raw) };
    }
    const rgba = RGBA_RE.exec(raw);
    if (rgba) {
        const parts = rgba[1].trim().split(/\s+/).filter((s) => s.length > 0).map(Number);
        const valid = (parts.length === 3 || parts.length === 4) &&
            parts.every((p) => Number.isFinite(p) && p >= 0 && p <= 1);
        if (!valid)
            return { color: { form: "neutral", raw }, diagnostic: { id: "veml:4.5:bad-color", detail: raw } };
        return { color: { form: "rgba", r: parts[0], g: parts[1], b: parts[2], a: parts[3] ?? 1, raw } };
    }
    const named = CSS_NAMED_COLORS[raw.toLowerCase()];
    if (named) {
        const a = raw.toLowerCase() === "transparent" ? 0 : 1;
        return { color: { form: "named", r: named[0] / 255, g: named[1] / 255, b: named[2] / 255, a, raw } };
    }
    return { color: { form: "neutral", raw }, diagnostic: { id: "veml:4.5:bad-color", detail: raw } };
}
