/**
 * Engine bootstrap: WebGPU where available, WebGL2 otherwise.
 *
 * The WebGPU engine + its WGSL shaders (~90 KB gzip) are CODE-SPLIT behind the
 * capability probe. The adapter is probed BEFORE the engine chunk downloads
 * (`WebGPUEngine.IsSupportedAsync` is exactly `requestAdapter() !== null`, so
 * probing first is behavior-identical): browsers that expose `navigator.gpu`
 * without a usable adapter — headless CI, blocklisted GPUs — take the WebGL2
 * path without paying the WebGPU download. The WebGL2 engine is the static
 * floor; its GLSL shaders are in the main bundle, so a WebGPU session does
 * also carry the (already-budgeted) GLSL payload.
 *
 * Device limits are queried HERE, once, at engine init —
 * WebGPU from `engine.supportedLimits` (the adapter's GPUSupportedLimits;
 * Babylon requests the device with the full adapter limits, so adapter
 * limits = device limits), WebGL2 from `engine.getCaps()` (only
 * maxTextureSize maps onto the key set; the buffer-size keys are
 * architecturally absent there and resolve to the portable floor with "n/a"
 * display). `forceLowLimits` (the `?limits=low` reserved param, read by
 * main.ts) substitutes the synthetic
 * sub-floor LOW_LIMITS_OVERRIDE on BOTH
 * paths — a simulated constrained device, engine-path-independent so
 * the headless WebGL2 e2e exercises the clamp.
 */
import './shaderImports';
import { loadWebGPUShaders } from './shaderImports';
import type { AbstractEngine } from '@babylonjs/core/Engines/abstractEngine';
import { Engine } from '@babylonjs/core/Engines/engine';
import { engineBootLogLine, webgpuEngineOptions, type EngineKind } from './engineChoice';
import { log } from '../logging/runtimeLog';
import {
  LOW_LIMITS_OVERRIDE,
  resolveDeviceCaps,
  type DeviceLimitValues,
  type ResolvedDeviceCaps,
} from './deviceCaps';

export interface CreateEngineOptions {
  /**
   * Test override (`?limits=low`): replace the device-reported
   * limits with the synthetic sub-floor set so every key clamps to the
   * portable floor.
   */
  forceLowLimits?: boolean;
  /** The GPU profile (`?gpu-profile`): the WebGPU device asks for the timestamp feature it times passes with. */
  gpuTiming?: boolean;
  /** Start in WebGL2 without trying WebGPU: a page loaded again to enter VR (xr/vrReload.ts). */
  webgl2?: boolean;
}

export interface BootedEngine {
  engine: AbstractEngine;
  kind: EngineKind;
  /** Device limits resolved against ceilings/floor — computed once, at init. */
  caps: ResolvedDeviceCaps;
  /**
   * Display-only extras for the debug HUD (WebGL2 caps with no configured
   * ceiling — informational, never clamped). Empty on the WebGPU path.
   */
  extraDisplayLimits: Readonly<Record<string, number>>;
}

/**
 * Apply the low-limits override (if requested) and resolve the caps — the single
 * place limits resolution happens.
 */
function finishCaps(
  actual: DeviceLimitValues,
  opts: CreateEngineOptions,
): ResolvedDeviceCaps {
  if (opts.forceLowLimits) {
    log.info('[webverse] limits override active (limits=low)');
    return resolveDeviceCaps({ ...LOW_LIMITS_OVERRIDE });
  }
  return resolveDeviceCaps(actual);
}

/** Minimal WebGPU surface for the pre-import capability probe. */
interface NavigatorGPULike {
  requestAdapter(): Promise<unknown | null>;
}

/**
 * Replace `canvas` with a pristine clone of itself. A canvas is permanently
 * bound to the first context type it hands out; if a WebGPU init fails AFTER
 * `getContext('webgpu')` was called, WebGL2 can never be created on that
 * element — the fallback needs a fresh one.
 */
function replaceWithFreshCanvas(canvas: HTMLCanvasElement): HTMLCanvasElement {
  const fresh = canvas.cloneNode(false) as HTMLCanvasElement;
  canvas.replaceWith(fresh);
  fresh.focus(); // keep the keyboard-focus invariant from index.html/main.ts
  return fresh;
}

/**
 * Create the render engine on `canvas`, trying WebGPU first and falling back
 * to WebGL2 on missing support OR on any WebGPU init failure. Logs which path
 * was taken (contract: `engineBootLogLine`, asserted by the e2e smoke test).
 */
export async function createEngine(
  canvas: HTMLCanvasElement,
  opts: CreateEngineOptions = {},
): Promise<BootedEngine> {
  let webgpuAttempt: { dispose(): void } | undefined;
  try {
    const nav = navigator as Navigator & { gpu?: NavigatorGPULike };
    // Adapter probe FIRST — only a browser with a live adapter downloads the
    // code-split WebGPU engine chunk.
    if (!opts.webgl2 && nav.gpu && (await nav.gpu.requestAdapter().catch(() => null)) !== null) {
      const { WebGPUEngine } = await import('@babylonjs/core/Engines/webgpuEngine');
      if (await WebGPUEngine.IsSupportedAsync) {
        await loadWebGPUShaders();
        const engine = new WebGPUEngine(canvas, webgpuEngineOptions(opts.gpuTiming === true));
        webgpuAttempt = engine;
        await engine.initAsync();
        // Streamed meshes (planet tiles and chunks) have their pipelines built in the background, not mid-frame.
        // Loaded here, on the WebGPU path, so it is no part of the first paint's bundle.
        const { installCompileAhead } = await import('./compileAhead');
        installCompileAhead(engine);
        // Read the key set off GPUSupportedLimits explicitly — its
        // properties are getters on the prototype, NOT enumerable own
        // properties, so a spread/Object.assign would silently produce {}.
        // Read BEFORE the boot log line: everything fallible must precede
        // the log, or a throw here would discard a working WebGPU engine
        // AND print both engine boot lines (the log-line contract is one
        // line per session).
        const gpuLimits = engine.supportedLimits;
        const caps = finishCaps(
          {
            maxTextureDimension2D: gpuLimits.maxTextureDimension2D,
            maxBufferSize: gpuLimits.maxBufferSize,
            maxUniformBufferBindingSize: gpuLimits.maxUniformBufferBindingSize,
            maxStorageBufferBindingSize: gpuLimits.maxStorageBufferBindingSize,
          },
          opts,
        );
        // Contract line — deliberately outside the runtime logger's level
        // gate: a stable machine-readable string the e2e asserts
        // (see engineChoice.ts) that must print by default, while the
        // logger's default level hides `info`.
        console.info(engineBootLogLine('webgpu'));
        return { engine, kind: 'webgpu', caps, extraDisplayLimits: {} };
      }
    }
  } catch (err) {
    log.warn('[webverse] WebGPU init failed, falling back to WebGL2:', err);
    if (webgpuAttempt) {
      try {
        webgpuAttempt.dispose(); // release the half-initialized GPU device
      } catch {
        /* a partially-constructed engine may throw on dispose — nothing to free */
      }
      // An engine was constructed, so initAsync may have already claimed the
      // canvas's one-and-only context.
      canvas = replaceWithFreshCanvas(canvas);
    }
  }

  const engine = new Engine(canvas, true);
  if (engine.webGLVersion < 2) {
    // Babylon silently downgrades to WebGL1; that is below the supported floor and
    // the shaders in the main bundle assume GLSL 3.0 — fail loudly, don't lie.
    engine.dispose();
    throw new Error('[webverse] WebGL2 is not available in this browser (WebGL2 is the minimum)');
  }
  // Contract line — deliberately outside the runtime logger's level gate
  // (see the webgpu twin above + engineChoice.ts).
  console.info(engineBootLogLine('webgl2'));
  // WebGL2: only the texture dimension maps onto the key set (Babylon's caps
  // expose no buffer-size limits and WebGL2 has no storage buffers — those
  // keys stay absent → floor sizing + "n/a" display, per deviceCaps.ts). The
  // render/cubemap sizes are HUD display extras with no ceilings.
  const glCaps = engine.getCaps();
  return {
    engine,
    kind: 'webgl2',
    caps: finishCaps({ maxTextureDimension2D: glCaps.maxTextureSize }, opts),
    extraDisplayLimits: {
      maxRenderTextureSize: glCaps.maxRenderTextureSize,
      maxCubemapTextureSize: glCaps.maxCubemapTextureSize,
    },
  };
}
