/**
 * §6.4 expansion: an `instance` becomes the prototype's entity subtree with
 * its parameters substituted.
 *
 * Substitution happens on the template's source infoset, one attribute value
 * at a time, and the result is typed by the same entity parser every authored
 * entity goes through. A parameter value therefore lands inside one attribute
 * and can never add an element, an attribute, or any markup — the observable
 * the draft uses to rule out splice-and-reparse. Templates are a closed
 * allowlist; `id` and `on-load` never survive one. A definition fetched by
 * `href` is a document whose root is `prototype`.
 */
import { DOMImplementation, DOMParser, onErrorStopParsing } from "@xmldom/xmldom";
import { VEML_4_0_NAMESPACE } from "./classify.js";
import { parseEntityElement, parsePrototypeElement } from "./parse.js";
/** §6.4: a placeholder and a `param` name are `[a-z][a-z0-9-]*`. */
const PARAM_NAME = /^[a-z][a-z0-9-]*$/;
/** Reserved on `instance`; a `param` so named is ignored. */
const RESERVED_PARAMS = new Set(["prototype", "tag", "id", "on-load"]);
/** What a template root may be: an entity or an entity subtype, never `html`. */
const TEMPLATE_ROOTS = new Set(["entity", "container", "asset", "primitive", "lod"]);
/** What a template may contain, besides the roots above: the structural children of an entity. */
const TEMPLATE_STRUCTURE = new Set([
    "level",
    "link",
    "transform",
    "position",
    "rotation",
    "scale",
    "size",
    "bounds",
    "meta",
    "placement-socket",
]);
/** Never in a template: these are stripped with a warning wherever they appear. */
const STRIPPED_ATTRS = new Set(["id", "on-load"]);
/**
 * One left-to-right pass over `value`: `{name}` becomes what `lookup` gives
 * for it (the empty string, with a warning, when nothing does); `{{` is a
 * literal brace; `}` is always literal; a `{` that begins no well-formed
 * placeholder is literal, with a warning. A substituted value is never
 * re-scanned.
 */
export function substitutePlaceholders(value, lookup, diagnostics, where) {
    let out = "";
    let i = 0;
    while (i < value.length) {
        const ch = value[i];
        if (ch !== "{") {
            out += ch;
            i += 1;
            continue;
        }
        if (value[i + 1] === "{") {
            out += "{";
            i += 2;
            continue;
        }
        const close = value.indexOf("}", i + 1);
        const name = close === -1 ? undefined : value.slice(i + 1, close);
        if (name !== undefined && PARAM_NAME.test(name)) {
            const bound = lookup(name);
            if (bound === undefined) {
                diagnostics.push({ id: "veml:6.4:unbound-param", detail: `{${name}} in ${where}; substituted empty` });
            }
            else {
                out += bound;
            }
            i = close + 1;
            continue;
        }
        diagnostics.push({ id: "veml:6.4:malformed-placeholder", detail: `'{' at ${i} in ${where}; literal` });
        out += "{";
        i += 1;
    }
    return out;
}
/**
 * Expand one `instance` of `decl` with its attribute `bindings`. Bindings win
 * over `param` defaults. The declaration's `templateSource` is required; an
 * `href`-only declaration is expanded through the definition the caller
 * fetched (`parsePrototypeDocument`), never here.
 */
export function expandInstance(decl, bindings) {
    const diagnostics = [];
    const source = decl.templateSource;
    if (source === undefined) {
        diagnostics.push({ id: "veml:6.4:no-template", detail: `prototype ${decl.name ?? "(unnamed)"} has no template` });
        return { node: undefined, diagnostics };
    }
    if (!TEMPLATE_ROOTS.has(source.tag)) {
        diagnostics.push({ id: "veml:6.4:template-root", detail: `<${source.tag}> cannot be a template root; prototype undeclared` });
        return { node: undefined, diagnostics };
    }
    const defaults = new Map();
    for (const p of decl.params) {
        if (RESERVED_PARAMS.has(p.name) || !PARAM_NAME.test(p.name)) {
            diagnostics.push({ id: "veml:6.4:reserved-param", detail: `param ${p.name} ignored` });
            continue;
        }
        defaults.set(p.name, p.default);
    }
    const lookup = (name) => bindings[name] ?? defaults.get(name);
    const dom = new DOMImplementation().createDocument(VEML_4_0_NAMESPACE, "template", null);
    const build = (node, path) => {
        const el = dom.createElementNS(VEML_4_0_NAMESPACE, node.tag);
        for (const [name, raw] of Object.entries(node.attributes)) {
            if (STRIPPED_ATTRS.has(name)) {
                diagnostics.push({ id: "veml:6.4:reserved-in-template", detail: `${path}@${name} stripped` });
                continue;
            }
            // Through the DOM, never through text: the value is one attribute value whatever it holds.
            el.setAttribute(name, substitutePlaceholders(raw, lookup, diagnostics, `${path}@${name}`));
        }
        if (node.text !== undefined)
            el.appendChild(dom.createTextNode(node.text));
        for (const child of node.children) {
            if (!TEMPLATE_ROOTS.has(child.tag) && !TEMPLATE_STRUCTURE.has(child.tag)) {
                diagnostics.push({ id: "veml:6.4:template-disallowed", detail: `<${child.tag}> in ${path} omitted` });
                continue;
            }
            el.appendChild(build(child, `${path}/${child.tag}`));
        }
        return el;
    };
    const root = build(source, source.tag);
    const state = { diagnostics: [], subsidiaryReferences: [] };
    const node = parseEntityElement(root, state) ?? undefined;
    diagnostics.push(...state.diagnostics);
    return { node, diagnostics };
}
/**
 * Parse a definition fetched by `href`: a document whose root is
 * `prototype` in the VEML namespace, with an inline `template` and no `href`
 * of its own (definitions never chain). A `name` on the root is ignored; the
 * referencing declaration's name is authoritative.
 */
export function parsePrototypeDocument(source) {
    if (/<!DOCTYPE/i.test(source)) {
        return {
            ok: false,
            diagnostics: [{ id: "veml:1.4:doctype", detail: "document type declaration rejected at the parse layer" }],
            errors: [],
        };
    }
    let dom;
    try {
        dom = new DOMParser({ onError: onErrorStopParsing }).parseFromString(source, "text/xml");
    }
    catch (e) {
        return { ok: false, diagnostics: [], errors: [`malformed-xml: ${e instanceof Error ? e.message : String(e)}`] };
    }
    const root = dom.documentElement;
    if (root === null || root.localName !== "prototype" || root.namespaceURI !== VEML_4_0_NAMESPACE) {
        return {
            ok: false,
            diagnostics: [{ id: "veml:6.4:fetched-root", detail: root ? `<${root.localName}> in ${root.namespaceURI ?? "no namespace"}` : "no root element" }],
            errors: [],
        };
    }
    if (root.hasAttribute("href")) {
        return { ok: false, diagnostics: [{ id: "veml:6.4:fetched-root-href", detail: "a fetched definition never chains" }], errors: [] };
    }
    const state = { diagnostics: [], subsidiaryReferences: [] };
    const decl = parsePrototypeElement(root, state);
    if (decl.templateSource === undefined) {
        state.diagnostics.push({ id: "veml:6.4:no-template", detail: "a fetched definition must carry an inline template" });
        return { ok: false, diagnostics: state.diagnostics, errors: [] };
    }
    return { ok: true, prototype: { ...decl, name: undefined }, diagnostics: state.diagnostics };
}
