/**
 * Engine-path vocabulary and the boot log-line contract. The capability probe
 * and the actual decision live in `bootstrap.ts` (they are inherently async
 * and failure-driven); this module owns the strings both tiers assert on.
 */

export type EngineKind = 'webgpu' | 'webgl2';

/**
 * The boot log line contract: the e2e tier asserts this exact shape, so keep
 * it stable ("[webverse] engine: webgpu" | "[webverse] engine: webgl2").
 */
export function engineBootLogLine(kind: EngineKind): string {
  return `[webverse] engine: ${kind}`;
}

/**
 * The WebGPU engine's options. Under the GPU profile the device also asks for
 * `timestamp-query`, the feature that lets the profiler time each render pass
 * on the graphics card (Babylon drops it again if the adapter lacks it);
 * otherwise the device asks for no optional feature, as always.
 */
export function webgpuEngineOptions(gpuTiming: boolean): { antialias: true; deviceDescriptor?: { requiredFeatures: ['timestamp-query'] } } {
  return gpuTiming ? { antialias: true, deviceDescriptor: { requiredFeatures: ['timestamp-query'] } } : { antialias: true };
}
