/**
 * Join a room by opening its link, through a rendezvous (WorldSync
 * protocol §4.2.1, Annex B).
 *
 * The worldsync session asks for a socket to the world's sync address and
 * speaks the protocol over it; it never knows what is behind it. This file
 * is that socket, and it finds out what is behind the address from the
 * answer to the session's own hello:
 *
 * - `session/welcome`: the address is an authority (an instance or an
 *   endpoint). Everything passes straight through, as a plain socket.
 * - `rendezvous/hold`: nobody holds the room. THIS TAB becomes its
 *   authority: the instance host runs here, in memory, and the session is
 *   connected to it through an in-memory pair. The tab stays attached to
 *   the rendezvous so the next visitor can find it, and answers their
 *   offers.
 * - `rendezvous/join`: someone holds it. A WebRTC data channel is opened to
 *   them, with offer, answer and candidates relayed by the rendezvous; once
 *   it is up the rendezvous is left, and the session speaks over the
 *   channel.
 *
 * The session's hello is sent again over whichever pipe won, so from the
 * session's side there was one socket, one hello and one welcome. A pipe
 * that never forms closes this socket, and the session's reconnect ladder
 * takes over; a world whose room cannot form stays a walkable static world
 * (service absent, §4.6), which is what the ladder already guarantees.
 */
import type { NetLog } from './mirrorBridge';
import type { WebSocketLike } from './worldsyncSession';
import { DEFAULT_ICE_SERVERS, type IceServer } from './iceServers';

/** The parts of an `RTCDataChannel` this file uses. */
export interface DataChannelLike {
  readonly readyState: string;
  send(text: string): void;
  close(): void;
  onopen: (() => void) | null;
  onmessage: ((event: { data: unknown }) => void) | null;
  onclose: (() => void) | null;
}

/** The parts of an `RTCPeerConnection` this file uses. */
export interface PeerConnectionLike {
  createDataChannel(label: string, init?: { ordered?: boolean }): DataChannelLike;
  createOffer(): Promise<{ type: 'offer'; sdp?: string }>;
  createAnswer(): Promise<{ type: 'answer'; sdp?: string }>;
  setLocalDescription(description: { type: string; sdp?: string }): Promise<void>;
  setRemoteDescription(description: { type: string; sdp?: string }): Promise<void>;
  addIceCandidate(candidate: unknown): Promise<void>;
  close(): void;
  onicecandidate: ((event: { candidate: unknown }) => void) | null;
  ondatachannel: ((event: { channel: DataChannelLike }) => void) | null;
  /** The connection's own liveness: a dead peer's channel may never say it closed. */
  readonly connectionState?: string;
  onconnectionstatechange?: (() => void) | null;
}

/** What the tab authority needs: `createInstanceHost`, loaded only when this tab holds a room. */
export type HostModule = typeof import('@fivesqd/worldsync/hosts/instance');

export interface RendezvousAwareDeps {
  /** The room: the declaration's `session`, which a rendezvous needs in the hello. */
  session: string;
  /** The world document's URL: what a joiner fetches as the room's snapshot when this tab holds it. */
  worldUrl: string;
  /** The real socket to the sync address. Default: the browser's WebSocket. */
  openSocket?: (url: string) => WebSocketLike;
  /** Default: `new rtcPeerConnection({ iceServers })`. */
  createPeerConnection?: () => PeerConnectionLike;
  /** The peer connection class the default factory builds with. Default: the browser's `RTCPeerConnection`. */
  rtcPeerConnection?: new (config: { iceServers: IceServer[] }) => PeerConnectionLike;
  /** STUN/TURN servers for the default peer connection. Default: `DEFAULT_ICE_SERVERS`. */
  iceServers?: ReadonlyArray<IceServer>;
  /**
   * This visitor's connection to the room failed, or never formed within
   * its wait: their network cannot reach the others. Said once per socket;
   * the session's reconnects open fresh sockets, so the caller decides how
   * often the visitor hears it.
   */
  onUnreachable?: () => void;
  /** Default: a dynamic import, so a world that never holds a room never loads the host. */
  loadHost?: () => Promise<HostModule>;
  /** How long a joiner waits for its channel before giving up this attempt. */
  channelTimeoutMs?: number;
  /** A holder's first wait before re-attaching to a rendezvous it lost; doubles to 30 s. */
  reattachMs?: number;
  /** How long a peer connection may stay `disconnected` before it counts as gone. */
  disconnectGraceMs?: number;
  /**
   * A private room's credential, fetched afresh when a holder re-attaches: the
   * one it joined on may have lapsed by then. Null or absent: the first hello
   * is sent again as it was.
   */
  credential?: () => Promise<string | null>;
  /**
   * The page's lifecycle (the Window). When this tab holds the room and the page goes (`pagehide`), the room is
   * handed on first: a closed tab never says so on its channels, and the others would wait on their connections'
   * own verdict to notice. Absent: the room is handed on only when the shell closes it.
   */
  pageLifecycle?: {
    addEventListener(type: 'pagehide', fn: () => void): void;
    removeEventListener(type: 'pagehide', fn: () => void): void;
  };
  log: NetLog;
}

/** How long a holder that handed its room on keeps its channels open, so the handoff reaches everyone. */
export const HANDOFF_LINGER_MS = 1_000;

export { DEFAULT_ICE_SERVERS };
export const DEFAULT_CHANNEL_TIMEOUT_MS = 15_000;
export const DEFAULT_REATTACH_MS = 1_000;
/**
 * ICE marks a connection `disconnected` within seconds of losing the
 * peer and `failed` only much later; a closed tab never delivers its data
 * channel's close. A short grace rides out a network blip, not a gone host.
 */
export const DEFAULT_DISCONNECT_GRACE_MS = 5_000;
const MAX_REATTACH_MS = 30_000;
const CHANNEL_LABEL = 'worldsync-ops';

type Listener = (event: { data?: unknown; code?: number }) => void;
type Mode = 'probing' | 'direct' | 'host' | 'joining' | 'joined' | 'closed';

interface Frame {
  type?: string;
  body?: Record<string, unknown>;
}

function parse(text: string): Frame {
  try {
    const f = JSON.parse(text) as Frame;
    return typeof f === 'object' && f !== null ? f : {};
  } catch {
    return {};
  }
}

const frame = (type: string, body: Record<string, unknown>): string => JSON.stringify({ v: 3, type, body });

function openNative(url: string): WebSocketLike {
  return new WebSocket(url) as unknown as WebSocketLike;
}

/** A channel end the instance host can hold as one of its sockets (its `SocketLike`). */
interface HostSocket {
  send(text: string): void;
  close(code?: number, reason?: string): void;
  on(event: 'message' | 'close', handler: (data?: unknown) => void): void;
}

/** A channel socket the host can also declare dead, when its peer is gone without a word. */
interface ChannelSocket extends HostSocket {
  gone(): void;
}

function channelSocket(channel: DataChannelLike): ChannelSocket {
  const handlers: { message: Array<(d?: unknown) => void>; close: Array<() => void> } = { message: [], close: [] };
  let ended = false;
  const end = (): void => {
    if (ended) return;
    ended = true;
    for (const h of handlers.close) h();
  };
  channel.onmessage = (e) => {
    for (const h of handlers.message) h(e.data);
  };
  channel.onclose = end;
  return {
    gone: () => {
      end();
      try {
        channel.close();
      } catch {
        /* already gone */
      }
    },
    send: (text) => {
      if (channel.readyState === 'open') channel.send(text);
    },
    close: () => channel.close(),
    on: (event, handler) => {
      if (event === 'message') handlers.message.push(handler);
      else handlers.close.push(handler as () => void);
    },
  };
}

export function openRendezvousAware(url: string, deps: RendezvousAwareDeps): WebSocketLike {
  const log = deps.log;
  const listeners = new Map<string, Listener[]>();
  const emit = (type: 'open' | 'message' | 'close' | 'error', event: { data?: unknown; code?: number }): void => {
    for (const l of listeners.get(type) ?? []) l(event);
  };

  let mode: Mode = 'probing';
  let helloText: string | null = null;
  /** Anything the session sends before a pipe is chosen. */
  const pending: string[] = [];
  /** Where the session's frames go once a pipe is chosen. */
  let outbound: ((text: string) => void) | null = null;

  // The browser's class is looked up when a peer is first needed, not at
  // open: a socket that passes straight through to an instance never needs one.
  // Servers the rendezvous handed over with its hold or join (protocol
  // §4.2.1): a relay's short-lived credentials, added to the resolved list
  // for every peer connection of this session.
  let handedServers: IceServer[] = [];
  const newPeer =
    deps.createPeerConnection ??
    (() => {
      const PeerConnection =
        deps.rtcPeerConnection ?? (RTCPeerConnection as unknown as NonNullable<RendezvousAwareDeps['rtcPeerConnection']>);
      return new PeerConnection({ iceServers: [...(deps.iceServers ?? DEFAULT_ICE_SERVERS), ...handedServers] });
    });
  let unreachableSaid = false;
  const unreachable = (): void => {
    if (unreachableSaid) return;
    unreachableSaid = true;
    deps.onUnreachable?.();
  };
  const loadHost = deps.loadHost ?? (() => import('@fivesqd/worldsync/hosts/instance'));

  // Host-side state.
  let host: ReturnType<HostModule['createInstanceHost']> | null = null;
  /** This tab's own connection to the room it holds, so the room is never handed to it. */
  let ownEnd: HostSocket | null = null;
  /** The room was handed on: it is not this tab's to keep findable any more. */
  let handedOn = false;
  const peers = new Map<string, PeerConnectionLike>();
  /** Each joiner's removal from the room this tab holds, by its handle at the rendezvous. */
  const dropJoiner = new Map<string, () => void>();
  // A private room (one entered on a credential) keeps every member attached to the rendezvous while it is in the
  // room, joiners included (§4.2.1, Staying admitted): that attachment is how a member taken off the list is removed.
  const staysAttached = deps.credential !== undefined;
  // Joiner-side state.
  let joinPeer: PeerConnectionLike | null = null;
  let authority: string | null = null;
  let joinTimer: ReturnType<typeof setTimeout> | null = null;
  const early: unknown[] = [];

  const openRendezvous = (): WebSocketLike => (deps.openSocket ?? openNative)(url);
  let ws = openRendezvous();
  /** The hello as the rendezvous saw it, room name included: what a holder re-attaches with. */
  let rendezvousHello: string | null = null;
  // A proxy in front of the rendezvous may cut an idle holder's connection
  // (CloudFront does so at 600 s), and the rendezvous then forgets the room, so
  // the next visitor would open a second one. A holder that loses its
  // rendezvous connection re-attaches.
  let reattaching = false;
  let reattachTimer: ReturnType<typeof setTimeout> | null = null;
  let reattachDelay = deps.reattachMs ?? DEFAULT_REATTACH_MS;

  const closeVirtual = (code: number): void => {
    if (mode === 'closed') return;
    mode = 'closed';
    deps.pageLifecycle?.removeEventListener('pagehide', onPageHide);
    if (joinTimer !== null) clearTimeout(joinTimer);
    if (reattachTimer !== null) clearTimeout(reattachTimer);
    for (const p of peers.values()) p.close();
    peers.clear();
    joinPeer?.close();
    host?.close();
    try {
      ws.close();
    } catch {
      /* already gone */
    }
    emit('close', { code });
  };

  const choose = (send: (text: string) => void, resendHello: boolean): void => {
    outbound = send;
    if (resendHello && helloText !== null) send(helloText);
    for (const t of pending.splice(0)) send(t);
  };

  // --- this tab holds the room ------------------------------------------------
  const becomeHost = async (): Promise<void> => {
    mode = 'host';
    const mod = await loadHost();
    if (mode !== 'host') return;
    let accept: ((socket: HostSocket) => void) | null = null;
    const server = { on: (_e: 'connection', h: (s: HostSocket) => void) => void (accept = h) };
    host = mod.createInstanceHost({
      server: server as never,
      session: deps.session,
      snapshotFrom: deps.worldUrl,
      log: (line) => log.info(`[webverse] worldsync room (this tab): ${line}`),
    });
    // The session's own connection to the room it now holds: an in-memory pair.
    const toSession = new Set<(d?: unknown) => void>();
    const closeHandlers = new Set<() => void>();
    const serverEnd: HostSocket = {
      send: (text) => queueMicrotask(() => emit('message', { data: text })),
      close: () => closeVirtual(1001),
      on: (event, handler) => {
        if (event === 'message') toSession.add(handler);
        else closeHandlers.add(handler as () => void);
      },
    };
    ownEnd = serverEnd;
    accept!(serverEnd);
    log.info('[webverse] worldsync: this tab holds the room; others join it through the rendezvous');
    choose((text) => queueMicrotask(() => toSession.forEach((h) => h(text))), true);

    // Admit each joiner that opens a channel to us.
    const admit = (channel: DataChannelLike, admitted: (sock: ChannelSocket) => void): void => {
      const open = (): void => {
        const sock = channelSocket(channel);
        admitted(sock);
        accept?.(sock);
      };
      if (channel.readyState === 'open') open();
      else channel.onopen = open;
    };
    hostAdmit = admit;
  };
  let hostAdmit: ((c: DataChannelLike, admitted: (sock: ChannelSocket) => void) => void) | null = null;

  /**
   * Call `onGone` when a peer connection is gone: `failed` or `closed`
   * at once, `disconnected` after a grace that a recovery cancels.
   */
  const watchConnection = (pc: PeerConnectionLike, onGone: () => void): void => {
    let grace: ReturnType<typeof setTimeout> | null = null;
    pc.onconnectionstatechange = () => {
      const state = pc.connectionState;
      if (state === 'failed' || state === 'closed') {
        if (grace !== null) clearTimeout(grace);
        grace = null;
        onGone();
      } else if (state === 'disconnected') {
        if (grace === null) {
          grace = setTimeout(() => {
            grace = null;
            if (pc.connectionState === 'disconnected') onGone();
          }, deps.disconnectGraceMs ?? DEFAULT_DISCONNECT_GRACE_MS);
        }
      } else if (grace !== null) {
        clearTimeout(grace);
        grace = null;
      }
    };
  };

  const answerOffer = async (from: string, sdp: string): Promise<void> => {
    const pc = newPeer();
    peers.set(from, pc);
    pc.onicecandidate = (e) => {
      if (e.candidate) ws.send(frame('signal/candidate', { to: from, candidate: toJSON(e.candidate) }));
    };
    let sock: ChannelSocket | null = null;
    pc.ondatachannel = (e) => hostAdmit?.(e.channel, (s) => (sock = s));
    const drop = (): void => {
      sock?.gone();
      pc.close();
      peers.delete(from);
      dropJoiner.delete(from);
    };
    dropJoiner.set(from, drop);
    // A joiner whose tab died never says so on its channel: drop it from the
    // room when its connection is gone, so no ghost stays in the roster.
    watchConnection(pc, () => {
      log.info('[webverse] worldsync: a visitor connection is gone — removing them from the room');
      drop();
    });
    await pc.setRemoteDescription({ type: 'offer', sdp });
    const answer = await pc.createAnswer();
    await pc.setLocalDescription(answer);
    ws.send(frame('signal/answer', { to: from, sdp: answer.sdp ?? '' }));
  };

  // --- someone else holds it --------------------------------------------------
  const join = async (to: string): Promise<void> => {
    mode = 'joining';
    authority = to;
    const pc = newPeer();
    joinPeer = pc;
    const channel = pc.createDataChannel(CHANNEL_LABEL, { ordered: true });
    // A host whose tab closed never closes this channel: watch the
    // connection, and when it is gone close this socket, so the session
    // reconnects and, the room now empty, re-forms it here.
    watchConnection(pc, () => {
      if (mode === 'joining' || mode === 'joined') {
        // `failed` is ICE giving up: no path between this network and the
        // host's. `closed` and a long `disconnected` are the host going away.
        if (pc.connectionState === 'failed') unreachable();
        log.warn('[webverse] worldsync: the host of this room is gone — reconnecting');
        closeVirtual(1006);
      }
    });
    pc.onicecandidate = (e) => {
      if (e.candidate) ws.send(frame('signal/candidate', { to, candidate: toJSON(e.candidate) }));
    };
    channel.onopen = () => {
      if (mode !== 'joining') return;
      mode = 'joined';
      if (joinTimer !== null) clearTimeout(joinTimer);
      log.info('[webverse] worldsync: connected directly to the room');
      channel.onmessage = (e) => emit('message', { data: e.data });
      channel.onclose = () => closeVirtual(1001);
      choose((text) => channel.send(text), true);
      // The rendezvous is out of the path now (§4.2.1). In a private room this tab stays attached to it all the
      // same, carrying nothing of the room: leaving it would be leaving the room.
      if (staysAttached) return;
      try {
        ws.close();
      } catch {
        /* already gone */
      }
    };
    joinTimer = setTimeout(() => {
      if (mode === 'joining') {
        log.warn('[webverse] worldsync: could not connect to the room directly — the world stays walkable');
        unreachable();
        closeVirtual(1006);
      }
    }, deps.channelTimeoutMs ?? DEFAULT_CHANNEL_TIMEOUT_MS);
    const offer = await pc.createOffer();
    await pc.setLocalDescription(offer);
    ws.send(frame('signal/offer', { to, sdp: offer.sdp ?? '' }));
  };

  const fromRendezvous = (text: string): void => {
    const f = parse(text);
    const body = f.body ?? {};
    if (mode === 'probing') {
      if (f.type === 'rendezvous/hold' || f.type === 'rendezvous/join') handedServers = handedIceServers(body['ice_servers']);
      if (f.type === 'rendezvous/hold') {
        void becomeHost().catch((err) => {
          log.warn('[webverse] worldsync: could not start the room in this tab', err);
          closeVirtual(1011);
        });
        return;
      }
      if (f.type === 'rendezvous/join' && typeof body['authority'] === 'string') {
        void join(body['authority']).catch((err) => {
          log.warn('[webverse] worldsync: could not offer a connection to the room', err);
          closeVirtual(1011);
        });
        return;
      }
      // Anything else: an authority answered. Straight through, from now on.
      mode = 'direct';
      choose((t) => ws.send(t), false);
      emit('message', { data: text });
      return;
    }
    if (mode === 'direct') {
      emit('message', { data: text });
      return;
    }
    // Staying admitted (§4.2.1): the rendezvous asked about this visitor again and was told no. The session hears
    // the refusal as its own, so it says so and does not climb the reconnect ladder against a "no".
    if (f.type === 'session/deny') {
      emit('message', { data: text });
      closeVirtual(1008);
      return;
    }
    if (f.type === 'rendezvous/leave' && typeof body['member'] === 'string') {
      const member = body['member'];
      if (mode === 'host') {
        // A member of the room this tab holds has left it, or was refused: it goes, channels and all.
        dropJoiner.get(member)?.();
      } else if ((mode === 'joined' || mode === 'joining') && member === authority) {
        log.warn('[webverse] worldsync: the host of this room is gone — reconnecting');
        closeVirtual(1006);
      }
      return;
    }
    const from = typeof body['from'] === 'string' ? body['from'] : null;
    if (mode === 'host' && from !== null) {
      if (f.type === 'signal/offer' && typeof body['sdp'] === 'string') {
        void answerOffer(from, body['sdp']).catch((err) => log.warn('[webverse] worldsync: could not answer a joiner', err));
      } else if (f.type === 'signal/candidate') {
        void peers.get(from)?.addIceCandidate(body['candidate']).catch(() => undefined);
      }
      return;
    }
    if (mode === 'joining' && joinPeer !== null && from === authority) {
      if (f.type === 'signal/answer' && typeof body['sdp'] === 'string') {
        void joinPeer
          .setRemoteDescription({ type: 'answer', sdp: body['sdp'] })
          .then(async () => {
            for (const c of early.splice(0)) await joinPeer?.addIceCandidate(c).catch(() => undefined);
          })
          .catch((err) => log.warn('[webverse] worldsync: the room refused our connection', err));
      } else if (f.type === 'signal/candidate') {
        // Before the answer lands there is no remote description to add it to.
        early.push(body['candidate']);
      }
    }
  };

  const reattach = (): void => {
    if (mode !== 'host' || reattachTimer !== null) return;
    const wait = reattachDelay;
    reattachDelay = Math.min(reattachDelay * 2, MAX_REATTACH_MS);
    reattachTimer = setTimeout(() => {
      reattachTimer = null;
      if (mode !== 'host') return;
      reattaching = true;
      ws = openRendezvous();
      wire(ws);
    }, wait);
  };

  /** The answer to a holder's re-attach: its room back, or someone else's. */
  const onReattachAnswer = (text: string): void => {
    reattaching = false;
    const f = parse(text);
    if (f.type === 'rendezvous/hold') {
      reattachDelay = deps.reattachMs ?? DEFAULT_REATTACH_MS;
      log.info('[webverse] worldsync: this room is findable again through the rendezvous');
    } else if (f.type === 'rendezvous/join') {
      // Someone took the room while this tab was away: two rooms now, and
      // they cannot be merged. People here stay here; new visitors go there.
      log.warn('[webverse] worldsync: another tab holds this room now — new visitors join that one, not this one');
    }
  };

  const wire = (sock: WebSocketLike): void => {
    sock.addEventListener('open', () => {
      if (sock !== ws) return;
      if (reattaching) {
        // A private room's ticket may have lapsed since the first hello, so a
        // fresh one goes in. None to be had: the first hello, for the
        // rendezvous to judge, and a refusal climbs the re-attach ladder.
        const hello = rendezvousHello;
        void Promise.resolve(deps.credential?.())
          .catch(() => null)
          .then((credential) => {
            if (sock !== ws || hello === null) return;
            const f = parse(hello);
            sock.send(credential ? JSON.stringify({ ...f, body: { ...f.body, credential } }) : hello);
          });
        return;
      }
      if (mode === 'probing') emit('open', {});
    });
    sock.addEventListener('message', (event) => {
      if (sock !== ws || mode === 'closed') return;
      const text = typeof event.data === 'string' ? event.data : String(event.data);
      if (reattaching) {
        onReattachAnswer(text);
        return;
      }
      fromRendezvous(text);
    });
    sock.addEventListener('close', (event) => {
      if (sock !== ws) return;
      // A holder losing the rendezvous keeps its room for everyone already in
      // it and re-attaches so new visitors can find it. A joiner that is
      // connected no longer needs it. Everyone else's socket is this one.
      if (mode === 'host') {
        // Handed on: the room is someone else's to keep findable now.
        if (handedOn) return;
        reattaching = false;
        log.warn('[webverse] worldsync: lost the rendezvous — re-attaching so new visitors can find this room');
        reattach();
        return;
      }
      // In a private room a joiner without its attachment is out of the room (the host is told so): reconnect.
      if (mode === 'joined' && !staysAttached) return;
      closeVirtual(event.code ?? 1006);
    });
    sock.addEventListener('error', () => {
      if (sock !== ws) return;
      if (mode === 'probing' || mode === 'direct') emit('error', {});
    });
  };
  wire(ws);

  /**
   * This tab is letting go of the room it holds (design §3.3, graceful handoff): the room tells its members who
   * holds it next, and the rendezvous is let go of at once, so the one named finds the room free. Returns who was
   * named, or null when nobody else is here.
   */
  const handOn = (): number | null => {
    if (mode !== 'host' || host === null || handedOn) return null;
    handedOn = true;
    const to = host.handOff((ownEnd ?? undefined) as never);
    log.info(`[webverse] worldsync: room handed to ${to ?? 'nobody'}`);
    try {
      ws.close();
    } catch {
      /* already gone */
    }
    return to;
  };
  function onPageHide(): void {
    handOn();
  }
  deps.pageLifecycle?.addEventListener('pagehide', onPageHide);

  return {
    send(text: string): void {
      if (mode === 'closed') return;
      if (outbound !== null) {
        outbound(text);
        return;
      }
      if (helloText === null && parse(text).type === 'session/hello') {
        helloText = text;
        // A rendezvous needs the room's name; an authority ignores it (§4.2.1).
        const hello = parse(text);
        rendezvousHello = JSON.stringify({ ...hello, body: { ...(hello.body ?? {}), session: deps.session } });
        ws.send(rendezvousHello);
        return;
      }
      pending.push(text);
    },
    close(): void {
      // The shell is closing the room this tab holds (the world unloaded, another opened): hand it on, and keep
      // its channels open a moment so the word reaches everyone before they close.
      if (mode === 'host' && host !== null && !handedOn && handOn() !== null) {
        const lingering = [...peers.values()];
        const room = host;
        peers.clear();
        host = null;
        setTimeout(() => {
          for (const p of lingering) p.close();
          room.close();
        }, HANDOFF_LINGER_MS);
      }
      closeVirtual(1000);
    },
    addEventListener(type, listener): void {
      listeners.set(type, [...(listeners.get(type) ?? []), listener]);
    },
  };
}

/** An `RTCIceCandidate` serialises through its own `toJSON`; a plain object is already data. */
function toJSON(candidate: unknown): unknown {
  const c = candidate as { toJSON?: () => unknown };
  return typeof c?.toJSON === 'function' ? c.toJSON() : candidate;
}

/**
 * The `ice_servers` a rendezvous hands over, in the browser's own shape (a
 * list of urls per entry), flattened to one server per url for the resolved
 * list's type. Anything that is not an ICE server is dropped, never fatal:
 * the hand-off must not fail on a provider's odd answer.
 */
export function handedIceServers(raw: unknown): IceServer[] {
  if (!Array.isArray(raw)) return [];
  const out: IceServer[] = [];
  for (const e of raw) {
    if (typeof e !== 'object' || e === null) continue;
    const o = e as Record<string, unknown>;
    const urls = Array.isArray(o['urls']) ? o['urls'].filter((u): u is string => typeof u === 'string') : typeof o['urls'] === 'string' ? [o['urls']] : [];
    for (const u of urls) {
      if (!/^(stuns?|turns?):/i.test(u)) continue;
      const entry: IceServer = { urls: u };
      if (typeof o['username'] === 'string') entry.username = o['username'];
      if (typeof o['credential'] === 'string') entry.credential = o['credential'];
      out.push(entry);
    }
  }
  return out;
}
