/**
 * EntityRegistry.
 *
 * The memory-correctness centerpiece: a world that leaks entity resources
 * on unload runs the browser out of memory. Every VEML-built entity becomes
 * one registry entry (UUID + tag) OWNING its Babylon nodes, meshes,
 * materials, textures, and observers; `dispose()` releases them
 * deterministically and idempotently; `disposeAll()` returns `count` to zero.
 *
 * Semantics:
 * - Entities are keyed by id; a duplicate id warns and overwrites; findByTag
 *   returns the first match. A missing document `id` gets crypto.randomUUID().
 * - disposeAll() deletes every entity and clears the map. Disposal is
 *   explicit Babylon dispose (meshes → materials → textures → root node,
 *   after custom disposers/observers), so the terminal state is exact:
 *   registry empty, every entity resource gone.
 *
 * Walkability: `walkableMeshes()` is the registry-backed provider for
 * the `WalkableSource` seam — registry-owned meshes of LOADED,
 * non-disposed entities ONLY. All registry-owned meshes are collidable
 * (`checkCollisions = true`, set by the builder), upholding groundProbe.ts's
 * walkable ⊆ collidable contract. The set is cached and invalidated on
 * register/dispose, because the probe calls this every tick.
 */
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import type { TransformNode } from '@babylonjs/core/Meshes/transformNode';
// The VEML 3.1 `link` payload (portal data). TYPE-ONLY import:
// scene→veml is the allowed dependency direction, and a type is
// erased, so the veml-zero-Babylon guard is untouched.
import type { VemlLink } from '../veml/documentModel';
import { log } from '../logging/runtimeLog';

/** Anything with an idempotent-enough dispose (Babylon materials/textures). */
export interface DisposableResource {
  dispose(): void;
}

export type EntityStatus = 'loaded' | 'errored';

export interface RegisterEntitySpec {
  /** Document id when present; a UUID is generated when absent. */
  id?: string;
  /** Document tag (required by the builder for buildable types). */
  tag: string;
  /** The VEML `xsi:type` (e.g. 'container', 'mesh', 'cubemesh'). */
  type: string;
  /** The entity's root node (container node or mesh root). */
  rootNode?: TransformNode;
  /** Meshes owned (and disposed) by this entity. */
  meshes?: AbstractMesh[];
  /** Materials owned by this entity. */
  materials?: DisposableResource[];
  /** Textures owned by this entity. */
  textures?: DisposableResource[];
  /**
   * Observer removals / custom teardown, run FIRST on dispose (the LIFO
   * teardown discipline from main.ts, scoped to one entity).
   */
  disposers?: Array<() => void>;
  /**
   * The VEML 3.1 `link` when this entity is a portal. Pure DATA
   * (href/resolvedHref/label); adds NOTHING to disposal. An entity carrying a
   * link AND owning ≥1 mesh becomes a `portals()` candidate.
   */
  link?: VemlLink;
  /**
   * The asset a LOADED entity came from, so a mirror drawn as an avatar
   * says which file it is (the errored path records it too). Optional:
   * primitives and containers have none.
   */
  assetUrl?: string;
}

/**
 * A portal candidate: a loaded, link-carrying entity together with
 * its pickable meshes. The entity↔mesh↔link mapping the raycast picker consumes
 * (src/interaction/portalPicker.ts).
 */
export interface PortalEntry {
  readonly entity: RegisteredEntity;
  readonly link: VemlLink;
  readonly meshes: readonly AbstractMesh[];
}

export interface RegisteredEntity {
  readonly id: string;
  readonly tag: string;
  readonly type: string;
  readonly status: EntityStatus;
  /** The asset URL: the one that failed for an errored entity, the one loaded for a glb entity. */
  readonly assetUrl?: string;
  readonly errorMessage?: string;
  readonly rootNode?: TransformNode;
  /** The VEML 3.1 `link` when this entity is a portal (else undefined). */
  readonly link?: VemlLink;
  /** Meshes currently owned (empty after dispose). */
  ownedMeshes(): readonly AbstractMesh[];
  /** Deterministic + idempotent. Also removes the entry from the registry. */
  dispose(): void;
  isDisposed(): boolean;
  /**
   * Puts what another file brought in place of what this entity loaded: the
   * old meshes, materials, textures and teardown are released in the order
   * `dispose` uses, and the entity, its root node and whatever is parented
   * under that node stay. For a model whose file is replaced while the world
   * is open. Does nothing on a disposed entity.
   */
  replaceContent(content: EntityContent): void;
}

/** What a model's file brings to its entity. */
export interface EntityContent {
  meshes: AbstractMesh[];
  materials?: DisposableResource[];
  textures?: DisposableResource[];
  disposers?: Array<() => void>;
  assetUrl?: string;
}

export interface EntityRegistry {
  readonly count: number;
  /**
   * A monotonic STRUCTURAL-CHANGE counter, bumped on every
   * register / dispose / disposeAll (the same choke point that invalidates the
   * walkable/portal/node caches). Lets an observer (the `worldSession.state()`
   * snapshot) cheaply detect that the entity SET changed — including an entity
   * created ASYNCHRONOUSLY after load (a script callback, or a remote-avatar
   * MIRROR created by an inbound network message)
   * — and rebuild only then (allocation-free in steady state).
   */
  readonly version: number;
  register(spec: RegisterEntitySpec): RegisteredEntity;
  /** A failed asset still registers, as `errored`, with the asset URL. */
  registerErrored(spec: {
    id?: string;
    tag: string;
    type: string;
    assetUrl: string;
    message: string;
    /** The placeholder root node (still owned — disposed with the entity). */
    rootNode?: TransformNode;
  }): RegisteredEntity;
  get(id: string): RegisteredEntity | undefined;
  /** First registered entity with this tag. */
  findByTag(tag: string): RegisteredEntity | undefined;
  all(): readonly RegisteredEntity[];
  /**
   * The node→entity reverse lookup backing the ENTITY-TREE-ON-DEMAND
   * (`BaseEntity.GetParent`/`GetChildren`). Given a Babylon node, return the
   * registry entity that OWNS it as its `rootNode` (or `undefined`). Derived
   * from the flat registry + the one-way scene graph — NO synced second tree
   * to drift out of step. Cached like `walkableMeshes`.
   */
  findByRootNode(node: TransformNode | null | undefined): RegisteredEntity | undefined;
  /**
   * The children of an entity, DERIVED from the Babylon node
   * hierarchy: loaded, non-disposed entities whose `rootNode.parent` is this
   * entity's `rootNode`. First-class support for `BaseEntity.GetChildren` with
   * no authoritative second tree.
   */
  children(id: string): readonly RegisteredEntity[];
  /** The WalkableSource payload: loaded entities' meshes only. */
  walkableMeshes(): readonly AbstractMesh[];
  /**
   * The portal candidates: LOADED, non-disposed entities carrying a
   * VEML 3.1 `link` AND owning ≥1 mesh (primitives + glb mesh entities). Cached
   * like `walkableMeshes()`; invalidated on register/dispose. Containers/UI carry
   * no pickable mesh and are excluded (a link on them is inert).
   */
  portals(): readonly PortalEntry[];
  /**
   * Force the walkable/portal/node caches to rebuild on next read.
   * Called by the script Entity API after a `SetVisibility`/`SetParent` that
   * changes walkable membership WITHOUT a register/dispose (a hidden→shown mesh
   * must become walkable the next tick). No-op-cheap; deterministic.
   */
  invalidateCaches(): void;
  /** Dispose every entity; count returns to zero. */
  disposeAll(): void;
}

export function createEntityRegistry(): EntityRegistry {
  const entities = new Map<string, InternalEntity>();
  let walkableCache: AbstractMesh[] | null = null;
  let portalCache: PortalEntry[] | null = null;
  // The node→entity reverse index (entity-tree-on-demand). Built
  // lazily, invalidated with the walkable/portal caches (register/dispose).
  let nodeCache: Map<TransformNode, InternalEntity> | null = null;

  interface InternalEntity extends RegisteredEntity {
    _meshes: AbstractMesh[];
    _materials: DisposableResource[];
    _textures: DisposableResource[];
    _disposers: Array<() => void>;
  }

  // The structural-change counter (see EntityRegistry.version).
  // Bumped in invalidateWalkables, which is the single choke point every
  // add/dispose/disposeAll already funnels through.
  let structuralVersion = 0;

  const invalidateWalkables = (): void => {
    walkableCache = null;
    // Portals ride the same lifecycle (loaded, non-disposed, owns meshes) —
    // invalidate together so the picker never sees a disposed portal mesh.
    portalCache = null;
    // The node→entity index rides the same lifecycle.
    nodeCache = null;
    // Every entity add/remove passes here; signal the SET changed.
    structuralVersion += 1;
  };

  const makeEntity = (
    spec: RegisterEntitySpec,
    status: EntityStatus,
    assetUrl?: string,
    errorMessage?: string,
  ): InternalEntity => {
    const id = spec.id ?? crypto.randomUUID();
    let disposed = false;
    // Deterministic order: observers/custom teardown first (they may
    // reference the nodes), then meshes, materials, textures.
    const releaseContent = (): void => {
      while (entity._disposers.length > 0) {
        try {
          entity._disposers.pop()!();
        } catch (err) {
          log.warn(`[webverse] entity ${id} disposer threw:`, err);
        }
      }
      for (const mesh of entity._meshes) {
        // Materials/textures are disposed explicitly below — never let the
        // mesh cascade into a material another entity might share.
        if (!mesh.isDisposed()) mesh.dispose(false, false);
      }
      entity._meshes.length = 0;
      for (const material of entity._materials) material.dispose();
      entity._materials.length = 0;
      for (const texture of entity._textures) texture.dispose();
      entity._textures.length = 0;
    };
    const entity: InternalEntity = {
      id,
      tag: spec.tag,
      type: spec.type,
      status,
      assetUrl,
      errorMessage,
      rootNode: spec.rootNode,
      link: spec.link,
      _meshes: spec.meshes ? [...spec.meshes] : [],
      _materials: spec.materials ? [...spec.materials] : [],
      _textures: spec.textures ? [...spec.textures] : [],
      _disposers: spec.disposers ? [...spec.disposers] : [],
      ownedMeshes(): readonly AbstractMesh[] {
        return disposed ? [] : entity._meshes;
      },
      isDisposed(): boolean {
        return disposed;
      },
      replaceContent(content: EntityContent): void {
        if (disposed) return;
        releaseContent();
        entity._meshes.push(...content.meshes);
        entity._materials.push(...(content.materials ?? []));
        entity._textures.push(...(content.textures ?? []));
        entity._disposers.push(...(content.disposers ?? []));
        const held = entity as { assetUrl?: string; status: EntityStatus; errorMessage?: string };
        if (content.assetUrl !== undefined) held.assetUrl = content.assetUrl;
        held.status = 'loaded';
        delete held.errorMessage;
        invalidateWalkables();
      },
      dispose(): void {
        if (disposed) return; // idempotent
        disposed = true;
        releaseContent();
        if (entity.rootNode && !entity.rootNode.isDisposed()) {
          entity.rootNode.dispose();
        }
        entities.delete(id);
        invalidateWalkables();
      },
    };
    return entity;
  };

  const add = (entity: InternalEntity): void => {
    const existing = entities.get(entity.id);
    if (existing) {
      // A duplicate id warns and overwrites, and the displaced entry is
      // disposed — an unreachable registry entry would otherwise leak its
      // Babylon resources.
      log.warn(
        `[webverse] entity with id ${entity.id} already registered — overwriting (and disposing the previous entry)`,
      );
      existing.dispose();
    }
    entities.set(entity.id, entity);
    invalidateWalkables();
  };

  return {
    get count(): number {
      return entities.size;
    },
    get version(): number {
      return structuralVersion;
    },
    register(spec: RegisterEntitySpec): RegisteredEntity {
      const entity = makeEntity(spec, 'loaded', spec.assetUrl);
      add(entity);
      return entity;
    },
    registerErrored(spec): RegisteredEntity {
      const entity = makeEntity(
        { id: spec.id, tag: spec.tag, type: spec.type, rootNode: spec.rootNode },
        'errored',
        spec.assetUrl,
        spec.message,
      );
      add(entity);
      return entity;
    },
    get(id: string): RegisteredEntity | undefined {
      return entities.get(id);
    },
    findByTag(tag: string): RegisteredEntity | undefined {
      for (const entity of entities.values()) {
        if (entity.tag === tag) return entity;
      }
      return undefined;
    },
    all(): readonly RegisteredEntity[] {
      return [...entities.values()];
    },
    findByRootNode(node: TransformNode | null | undefined): RegisteredEntity | undefined {
      if (!node) return undefined;
      if (nodeCache === null) {
        nodeCache = new Map<TransformNode, InternalEntity>();
        for (const entity of entities.values()) {
          if (entity.isDisposed() || !entity.rootNode) continue;
          nodeCache.set(entity.rootNode, entity);
        }
      }
      const found = nodeCache.get(node);
      return found && !found.isDisposed() ? found : undefined;
    },
    children(id: string): readonly RegisteredEntity[] {
      const parent = entities.get(id);
      if (!parent || parent.isDisposed() || !parent.rootNode) return [];
      const out: RegisteredEntity[] = [];
      for (const entity of entities.values()) {
        if (entity.isDisposed() || entity.status !== 'loaded') continue;
        if (entity.rootNode && entity.rootNode.parent === parent.rootNode) out.push(entity);
      }
      return out;
    },
    walkableMeshes(): readonly AbstractMesh[] {
      if (walkableCache === null) {
        walkableCache = [];
        for (const entity of entities.values()) {
          if (entity.status !== 'loaded' || entity.isDisposed()) continue;
          for (const mesh of entity.ownedMeshes()) {
            // A script-created entity spawns HIDDEN
            // (`setEnabled(false)`); a disabled mesh is not walkable/pickable
            // until `SetVisibility(true)` enables it (spawn-hidden contract).
            if (!mesh.isDisposed() && mesh.isEnabled()) walkableCache.push(mesh);
          }
        }
      }
      return walkableCache;
    },
    portals(): readonly PortalEntry[] {
      if (portalCache === null) {
        portalCache = [];
        for (const entity of entities.values()) {
          if (entity.status !== 'loaded' || entity.isDisposed()) continue;
          if (!entity.link) continue;
          const meshes = entity.ownedMeshes().filter((m) => !m.isDisposed());
          if (meshes.length === 0) continue; // no pickable mesh → not a portal
          portalCache.push({ entity, link: entity.link, meshes });
        }
      }
      return portalCache;
    },
    invalidateCaches(): void {
      invalidateWalkables();
    },
    disposeAll(): void {
      // Copy first: dispose() mutates the map.
      for (const entity of [...entities.values()]) entity.dispose();
      entities.clear();
      invalidateWalkables();
    },
  };
}
