/**
 * Lite-procedural-sky config resolution. PURE (no Babylon,
 * no DOM) so it unit-tests under plain node WITHOUT loading the code-split sky
 * chunk.
 *
 * Turns the parser's 57-attribute camelCase `VemlLiteProceduralSky` bag (every
 * XSD default already applied — src/veml/parser.ts) into the small render
 * struct the sky chunk consumes: colors resolved via the
 * `parseVemlColorValue` grammar (REUSED — no third color parser), and the
 * range-gated numeric attributes validated.
 *
 * Out-of-range values never abort the sky: when ground-height / ground-fade /
 * horizon-sky-blend / horizon-saturation-* / sun-diameter /
 * sky-lighting-falloff fall outside their ranges, the shell WARNS +
 * substitutes the XSD default (clamps to the valid model) and KEEPS
 * RENDERING — a malformed attribute never fails the load.
 *
 * The bag is wire-derived, so every attribute read goes through `readOwn` — an
 * own-property guard against prototype pollution: a wire `__proto__` /
 * `constructor` must never resolve to an Object.prototype member.
 */
import type { VemlLiteProceduralSky } from '../../veml/documentModel';
import { parseVemlColorValue } from './vemlColorValue';
import { log } from '../../logging/runtimeLog';

/** An RGB color for a sky uniform (VEML sky colors carry alpha, but the sky is
 * opaque — the gradient uses rgb only; the alpha is deliberately dropped).
 * HDR components (> 1) are preserved. */
export interface SkyColorRgb {
  r: number;
  g: number;
  b: number;
}

/** The render-ready procedural-sky config the chunk consumes. */
export interface ProceduralSkyConfig {
  groundEnabled: boolean;
  groundColor: SkyColorRgb;
  /** −1..1 (range gate). */
  groundHeight: number;
  /** 0..1 (range gate). */
  groundFadeAmount: number;
  /** 0.1..2 (range gate). */
  horizonSkyBlend: number;
  /** = day-horizon-color. */
  horizonColor: SkyColorRgb;
  /** = day-sky-color (zenith). */
  skyColor: SkyColorRgb;
  sunEnabled: boolean;
  /** Angular diameter in DEGREES, ≥ 0 (range gate). */
  sunDiameter: number;
  /** = sun-zenith-color. */
  sunColor: SkyColorRgb;
  dayNightCycleEnabled: boolean;
  /** The tag of the `light` entity the sun binds to (deferred until after
   * buildWorld). Absent → the sky renders with a default sun direction. */
  sunEntityTag?: string;
}

/** XSD defaults for the attributes the shell renders (the VEML schema). */
const DEF = {
  groundColor: '#07070700',
  groundHeight: -0.02,
  groundFadeAmount: 0.02,
  horizonSkyBlend: 0.579,
  dayHorizonColor: '#448bc5ff',
  daySkyColor: '#08124100',
  sunDiameter: 2,
  sunZenithColor: 'color(158 129 58 0)',
} as const;

/** Own-property guard (prototype pollution). */
function readOwn(bag: VemlLiteProceduralSky, key: string): unknown {
  return Object.prototype.hasOwnProperty.call(bag, key) ? bag[key] : undefined;
}

function readBool(bag: VemlLiteProceduralSky, key: string, fallback: boolean): boolean {
  const v = readOwn(bag, key);
  return typeof v === 'boolean' ? v : fallback;
}

function readColor(bag: VemlLiteProceduralSky, key: string, fallbackRaw: string): SkyColorRgb {
  const v = readOwn(bag, key);
  const raw = typeof v === 'string' ? v : fallbackRaw;
  const c = parseVemlColorValue(raw); // VEML color grammar (HDR-capable, guarded)
  return { r: c.r, g: c.g, b: c.b };
}

function readString(bag: VemlLiteProceduralSky, key: string): string | undefined {
  const v = readOwn(bag, key);
  return typeof v === 'string' && v.length > 0 ? v : undefined;
}

/**
 * A numeric attribute validated against its range gate. In-range → the
 * authored value; out-of-range → the XSD default + a warning (never fail).
 * `min`/`max` may be ±Infinity for a one-sided gate (e.g. sun-diameter ≥ 0).
 */
function readRanged(
  bag: VemlLiteProceduralSky,
  key: string,
  fallback: number,
  min: number,
  max: number,
  warn: (msg: string) => void,
): number {
  const v = readOwn(bag, key);
  const n = typeof v === 'number' && Number.isFinite(v) ? v : fallback;
  if (n < min || n > max) {
    warn(
      `[webverse] lite-procedural-sky: ${key}=${String(n)} out of range [${min}, ${max}] — using default ${fallback}`,
    );
    return fallback;
  }
  return n;
}

/**
 * Resolve the parsed sky bag into the render config. Never throws; out-of-range
 * numerics degrade to the XSD default with a warning.
 */
export function resolveSkyConfig(
  sky: VemlLiteProceduralSky,
  // Injectable seam kept for tests; defaults to the leveled runtime logger
  // (warn-level, prints by default).
  warn: (msg: string) => void = log.warn,
): ProceduralSkyConfig {
  return {
    groundEnabled: readBool(sky, 'groundEnabled', true),
    groundColor: readColor(sky, 'groundColor', DEF.groundColor),
    groundHeight: readRanged(sky, 'groundHeight', DEF.groundHeight, -1, 1, warn),
    groundFadeAmount: readRanged(sky, 'groundFadeAmount', DEF.groundFadeAmount, 0, 1, warn),
    horizonSkyBlend: readRanged(sky, 'horizonSkyBlend', DEF.horizonSkyBlend, 0.1, 2, warn),
    horizonColor: readColor(sky, 'dayHorizonColor', DEF.dayHorizonColor),
    skyColor: readColor(sky, 'daySkyColor', DEF.daySkyColor),
    sunEnabled: readBool(sky, 'sunEnabled', true),
    sunDiameter: readRanged(sky, 'sunDiameter', DEF.sunDiameter, 0, Infinity, warn),
    sunColor: readColor(sky, 'sunZenithColor', DEF.sunZenithColor),
    dayNightCycleEnabled: readBool(sky, 'dayNightCycleEnabled', true),
    sunEntityTag: readString(sky, 'sunEntityTag'),
  };
}
