/** §4.4: the quality levels, ascending. */
export const QUALITY_LEVELS = ["low", "medium", "high", "ultra"];
/** §4.4 choosing: at `level`, the alternative with the lowest quality not
 *  below it; with none, the asset's own file. */
export function chooseAssetSource(asset, level) {
    const at = QUALITY_LEVELS.indexOf(level);
    const fit = asset.sources.find((s) => QUALITY_LEVELS.indexOf(s.quality) >= at);
    const file = fit ?? asset;
    return {
        ...(file.src !== undefined ? { src: file.src } : {}),
        ...(file.assetType !== undefined ? { assetType: file.assetType } : {}),
        ...(file.integrity !== undefined ? { integrity: file.integrity } : {}),
    };
}
