/** Minimal shared input shape (desktop or touch — one per session). */
type BootInput = LocomotionInputSource & {
  isPointerLocked(): boolean;
  /** Raw held-key state for `Input.GetKeyValue` (touch → always false). */
  isKeyDown(key: string): boolean;
  dispose(): void;
};

/** The world a self-boot page carries. */
export type WorldSource =
  | { kind: 'inline'; html: string }
  | { kind: 'referenced'; url: string }
  | { kind: 'none' };

/**
 * The name the page gives this visitor, when the host that served it knows
 * who they are: `visitor-name` on a `<veml-world src="…">` pointer. Only the
 * pointer form carries it: an inline `<veml-world>` is the world document
 * itself, serialized unchanged, and this is a fact about the page, not the
 * world. The client never asks any service who the visitor is; the page says
 * it or it does not. Bounded like a name chosen in the menu. Absent or
 * blank: undefined, and the browser's kept or invented name serves as before.
 */
export function visitorNameFromPage(doc: Document): string | undefined {
  const worldEl = doc.getElementsByTagName('veml-world')[0];
  if (!worldEl?.getAttribute('src')?.trim()) return undefined;
  const name = worldEl.getAttribute('visitor-name')?.trim().slice(0, 40);
  return name ? name : undefined;
}

/** The longest avatar URL the room keeps (WorldSync protocol §4.6). */
const AVATAR_URL_MAX = 2048;

/**
 * The avatar the page says this visitor wears, when the host that served it
 * knows: `visitor-avatar` on a `<veml-world src="…">` pointer, an absolute
 * https URL of at most 2048 characters (the roster's own rule, so a value
 * the room would drop is not sent). Only the pointer form carries it, as for
 * `visitor-name`. Absent, blank or malformed: undefined, and the visitor
 * brings no avatar.
 */
export function visitorAvatarFromPage(doc: Document): string | undefined {
  const worldEl = doc.getElementsByTagName('veml-world')[0];
  if (!worldEl?.getAttribute('src')?.trim()) return undefined;
  const raw = worldEl.getAttribute('visitor-avatar')?.trim() ?? '';
  if (!raw || raw.length > AVATAR_URL_MAX || !raw.startsWith('https://')) return undefined;
  try {
    return new URL(raw).protocol === 'https:' ? raw : undefined;
  } catch {
    return undefined;
  }
}

/**
 * Where the host that served the page takes a sign-in the visitor makes in the world, to name them by it:
 * `visitor-session` on a `<veml-world src="…">` pointer, a path on the page's own origin and nothing else, so the
 * sign-in is only ever handed to the host that served the page. Absent or anything else: undefined, and a sign-in
 * made in the world names nobody.
 */
export function visitorSessionFromPage(doc: Document): string | undefined {
  return ownPathFromPage(doc, 'visitor-session');
}

/**
 * Where the host that served the page gives a ticket to its private world's room: `room-ticket` on the pointer
 * form, a path on the page's own origin and nothing else, as `visitor-session` is. Absent: the room is public.
 */
export function roomTicketFromPage(doc: Document): string | undefined {
  return ownPathFromPage(doc, 'room-ticket');
}

function ownPathFromPage(doc: Document, attribute: string): string | undefined {
  const worldEl = doc.getElementsByTagName('veml-world')[0];
  if (!worldEl?.getAttribute('src')?.trim()) return undefined;
  const path = worldEl.getAttribute(attribute)?.trim() ?? '';
  return path.startsWith('/') && !path.startsWith('//') ? path : undefined;
}


/**
 * Serialize the running document to an HTML STRING (its OWN source) — the input
 * to the inert self-parse (THE CRUX). Reading `outerHTML` never executes a
 * script and never couples the live DOM to a scene graph.
 */
export function serializeDocument(doc: Document): string {
  return doc.documentElement.outerHTML;
}

/**
 * Decide the world a self-boot page describes. Precedence:
 *   1. REFERENCED — a `<veml-world src="…">` or any `[data-world]` element
 *      (an explicit pointer wins over inline markup);
 *   2. INLINE — else, ≥1 `veml-*` element → the page's own serialized source;
 *   3. NONE — neither (the boot script was pulled in on a world-less page).
 */
export function resolveWorldSource(doc: Document): WorldSource {
  // A <veml-world src="…"> pointer, else any element's data-world: the one
  // rule in htmlRouting, shared with a load of this page's address from
  // another world.
  const pointer = worldPointerOf(doc);
  if (pointer) return { kind: 'referenced', url: pointer };
  if (containsVemlElement(doc)) return { kind: 'inline', html: serializeDocument(doc) };
  return { kind: 'none' };
}

/** The splash's critical CSS (mirrors index.html; injected only when absent). */
const SCAFFOLD_CSS = `html,body{margin:0;padding:0;width:100%;height:100%;overflow:hidden;background:#101014;}
#renderCanvas{width:100%;height:100%;display:block;touch-action:none;outline:none;}
#webverse-feedback{position:fixed;inset:0;z-index:10;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;background:var(--webverse-feedback-bg,#101014);color:var(--webverse-feedback-fg,#dfe3ea);font:14px/1.5 system-ui,sans-serif;text-align:center;pointer-events:none;}
#webverse-feedback[data-webverse-feedback-state='hidden']{display:none;}
#webverse-feedback .webverse-feedback-spinner{width:24px;height:24px;border:3px solid rgba(223,227,234,0.25);border-top-color:var(--webverse-feedback-accent,#7aa2ff);border-radius:50%;animation:webverse-feedback-spin 0.9s linear infinite;}
@keyframes webverse-feedback-spin{to{transform:rotate(360deg);}}
#webverse-feedback button{pointer-events:auto;font:inherit;color:inherit;background:transparent;border:1px solid var(--webverse-feedback-fg,#dfe3ea);border-radius:4px;padding:6px 16px;cursor:pointer;}`;

/**
 * Inject the runtime's DOM scaffold — a full-screen `#renderCanvas` + the
 * inline splash (`#webverse-feedback`) + the critical CSS — when the
 * author's page doesn't already carry them. Idempotent: an author
 * who inlined the splash markup for a truly-instant pre-chunk paint keeps it.
 * Returns the live canvas element. `#renderCanvas`/`#webverse-feedback` are
 * private implementation identifiers, exempt from the public naming scheme.
 */
export function ensureScaffold(doc: Document): HTMLCanvasElement {
  const body = doc.body;
  // The world is the whole page: without a viewport tag a phone lays
  // it out at 980 px and every control comes out tiny. An author's own tag
  // stands.
  if (doc.head && !doc.head.querySelector('meta[name="viewport"]')) {
    const meta = doc.createElement('meta');
    meta.name = 'viewport';
    meta.content = 'width=device-width, initial-scale=1';
    doc.head.appendChild(meta);
  }
  if (!doc.getElementById('webverse-feedback-styles')) {
    const style = doc.createElement('style');
    style.id = 'webverse-feedback-styles';
    style.textContent = SCAFFOLD_CSS;
    (doc.head ?? body).appendChild(style);
  }
  let canvas = doc.getElementById('renderCanvas') as HTMLCanvasElement | null;
  if (!canvas) {
    canvas = doc.createElement('canvas');
    canvas.id = 'renderCanvas';
    canvas.setAttribute('tabindex', '0');
    body.appendChild(canvas);
  }
  if (!doc.getElementById('webverse-feedback')) {
    const splash = doc.createElement('div');
    splash.id = 'webverse-feedback';
    splash.setAttribute('data-webverse-feedback-state', 'splash');
    splash.setAttribute('role', 'status');
    splash.setAttribute('aria-live', 'polite');
    const spinner = doc.createElement('div');
    spinner.className = 'webverse-feedback-spinner';
    spinner.setAttribute('aria-hidden', 'true');
    const p = doc.createElement('p');
    p.textContent = 'Loading…';
    splash.append(spinner, p);
    body.appendChild(splash);
  }
  return canvas;
}

/** The parse-outcome snapshot (mirrors main.ts's observability hook). */
function parseSnapshot(): NonNullable<Window['__webverse']>['lastParse'] {
  const result = lastParseResult();
  if (!result) return undefined;
  return {
    url: result.report.url,
    ok: result.ok,
    declaredVersion: result.report.declaredVersion,
    title: result.ok ? (result.document.metadata.title ?? null) : null,
    entityCount: result.ok ? result.document.environment.entities.length : 0,
    errorCount: result.report.errors.length,
    warningCount: result.report.warnings.length,
    errors: result.report.errors.map((e) => e.message),
    warnings: result.report.warnings.map((w) => ({ kind: w.kind, name: w.name, path: w.path })),
  };
}

/** The debug-level per-asset load trace (mirrors main.ts). */
function logProgressDebug(event: WorldLoadProgressEvent): void {
  switch (event.kind) {
    case 'asset-started':
      log.debug(`[webverse] load: asset started ${event.url}`);
      break;
    case 'asset-progress':
      log.debug(
        `[webverse] load: asset progress ${event.url} ${event.loadedBytes}/${event.totalBytes ?? '?'}`,
      );
      break;
    case 'asset-completed':
      log.debug(`[webverse] load: asset completed ${event.url}`);
      break;
    case 'asset-failed':
      log.debug(`[webverse] load: asset failed ${event.url} — ${event.message}`);
      break;
  }
}

/**
 * Self-boot the runtime against the live document. Mirrors `main.ts`'s boot
 * (LIFO teardown, the `window.__webverse` observability hook, a loud boot
 * `.catch` → the fatal error card) but LEANER — no debug HUD, no grounding
 * fixtures, no `limits`/`test-grounding` params. Loads the page's own world per
 * `resolveWorldSource` (inline serialize-and-inert-parse, or the referenced
 * form via the navigation controller).
 */
export async function runSelfBoot(
  doc: Document,
  win: Window,
  /** Where this viewer's own files are served from (the boot script's folder). */
  viewerBase?: string,
): Promise<void> {
  // Read the author's document BEFORE injecting the scaffold, so the inline
  // serialization + the referenced-URL read see the pristine page.
  const worldSource = resolveWorldSource(doc);
  const pageVisitorName = visitorNameFromPage(doc);
  const pageVisitorAvatar = visitorAvatarFromPage(doc);
  const pageVisitorSession = visitorSessionFromPage(doc);
  const pageRoomTicket = roomTicketFromPage(doc);

  const { search, hash } = win.location;
  initLogLevel(readReservedParam('log', search, hash));
  const spawnOverride =
    parseSpawnVector(readReservedParam('spawn', search, hash)) ?? undefined;

  // Inject canvas + splash + critical CSS before engine init so the splash
  // paints during the (slow) WebGPU probe + world fetch.
  const canvas = ensureScaffold(doc);

  let sessionRef: WorldSession | undefined;
  let controllerRef: NavigationController | undefined;
  const surface = createFeedbackSurface(doc, {
    onReload: (failedUrl) => {
      if (failedUrl !== null && controllerRef) {
        void controllerRef.navigate(failedUrl, { force: true }).catch(() => {});
      } else {
        win.location.reload();
      }
    },
  });

  const teardown: Array<() => void> = [];
  teardown.push(() => surface.dispose());

  const lifecycleLog: Array<{ kind: string; url?: string; at?: number }> = [];

  try {
    canvas.focus();
    // Loaded again to enter VR (src/xr/vrReload.ts): WebGL2 for this load, where VR presents.
    const vrAgain = new URLSearchParams(search).get('vr') === 'again';
    const { engine, kind } = await createEngine(canvas, { webgl2: vrAgain });
    teardown.push(() => engine.dispose());

    const touchPrimary = detectTouchPrimary(win);
    let touchModule: typeof import('../input/touchInput') | undefined;
    if (touchPrimary) {
      try {
        touchModule = await import('../input/touchInput');
      } catch (err) {
        engine.dispose();
        throw err;
      }
    }

    const testScene = createTestScene(engine);
    const { scene, camera, spawnFeet, walkables } = testScene;
    teardown.push(() => testScene.dispose());

    // The WebGPU→WebGL2 fallback may have replaced the canvas element.
    const liveCanvas = (engine.getRenderingCanvas() ?? canvas) as HTMLCanvasElement;
    // See main.ts: the same layered settings controller (default <
    // persisted < embedder), a fresh instance per boot so it re-reads `win.
    // localStorage` on every self-boot the same way main.ts's does per page load.
    const settingsController = createSettingsController({
      localStorage: win.localStorage ? win.localStorage : undefined,
      // On a phone, chat starts at the top, clear of the sticks.
      ...(touchPrimary ? { deviceDefaults: TOUCH_DEVICE_DEFAULTS } : {}),
    });
    // The controls hint: this loader is what a world's own address
    // serves, so the first person to open a shared link is told the keys here.
    const controlsHint = createControlsHint(doc, {
      settings: () => settingsController.get(),
      storage: win.localStorage ? win.localStorage : undefined,
      touch: touchPrimary,
    });
    teardown.push(() => controlsHint.dispose());
    // See main.ts: the script input dispatcher taps desktop keys
    // (observe-only) via this forwarder (dispatcher created after the session).
    let inputDispatcherRef: ScriptInputDispatcher | undefined;
    const input: BootInput = touchModule
      ? touchModule.createTouchInput<HTMLDivElement>(doc, {
          // The buttons the world asks for, and flight on touch (what F does).
          buttons: () => sessionRef?.hints().touchButtons() ?? ['jump', 'fly'],
          flyAllowed: () =>
            sessionRef?.flyAllowed({ forceFlyToggle: settingsController.get().locomotion.forceFlyToggle }) ?? false,
          flying: () => sessionRef?.isFlying() ?? false,
          onFlyToggle: () => {
            sessionRef?.attemptFlyToggle({ forceFlyToggle: settingsController.get().locomotion.forceFlyToggle });
          },
        })
      : createDesktopInput(
          liveCanvas,
          doc,
          (kind, key, code) => {
            // The fly toggle, exactly as main.ts wires it: the bound
            // key flips the active view's controller (no gravity, no
            // collision), gated by the world's <navigation modes> with the
            // user's forceFlyToggle override. Every world opened at its own
            // address (`/w/<id>`) boots through here.
            if (kind === 'down' && settingsController.get().bindings.flyToggle.includes(code)) {
              sessionRef?.attemptFlyToggle({
                forceFlyToggle: settingsController.get().locomotion.forceFlyToggle,
              });
            }
            inputDispatcherRef?.onKey(kind, key, code);
          },
          () => settingsController.get().bindings,
          // The tab-close path, same as main.ts: `pagehide` on the
          // Window releases the pointer lock the input took. Both boots
          // must pass the Window, or this one keeps a stale lock.
          win,
        );
    teardown.push(() => input.dispose());

    const controller = createFirstPersonController(scene, camera, input, spawnFeet, walkables);
    teardown.push(() => controller.dispose());

    // The people messages (chat, joins, leaves) on a published world.
    // The full app mounts its own; this boot mounts this one.
    const people = createPeopleMessages(doc, () => settingsController.get(), win.localStorage ?? undefined);
    // VR, as the full app has it (src/xr/vrEntry.ts, shared): a
    // published world is what someone opens in a headset browser. Its
    // callbacks read the session lazily; none runs before a button press.
    const vr = mountVrEntry({
      doc,
      engineKind: kind,
      session: {
        state: () => sessionRef!.state(),
        active: () => sessionRef!.active(),
        worldControlFlags: () => sessionRef!.worldControlFlags(),
        portals: () => sessionRef!.portals(),
        walkableMeshes: () => sessionRef!.walkableMeshes(),
        pickEntityAlongRay: (ray) => sessionRef!.pickEntityAlongRay(ray as Ray),
        dispatchEntityClick: (id) => sessionRef!.dispatchEntityClick(id),
      },
      feet: () => {
        const f = sessionRef!.active().controller.feetPosition();
        return { x: f.x, y: f.y, z: f.z };
      },
      teleportFeet: (x, y, z) => sessionRef!.active().controller.teleportFeet(new Vector3(x, y, z)),
      stepFeet: (dx, dz, dt) => {
        const f = sessionRef!.active().controller.moveFeetWithCollisions(dx, dz, dt);
        return { x: f.x, y: f.y, z: f.z };
      },
      navigate: (href) => void controllerRef?.navigate(href).catch(() => {}),
      onXrInput: (frame) => inputDispatcherRef?.onXrInput(frame),
      createPointerAffordance: (scene) => createVrPointerAffordance(scene as Scene),
      // The messages in the headset: the people panel's lines.
      messagesHud: { lines: () => people.shownLines(), create: (scene) => createVrMessagesHud(scene as Scene) },
      // On WebGPU the press loads this page again in WebGL2 (src/xr/vrReload.ts), loaded only then.
      reloadForVr: () => void import('../xr/vrReload').then((m) => m.reloadForVr(win)),
      log,
    });
    teardown.push(() => vr.dispose());
    if (vrAgain) void import('../xr/vrReload').then((m) => m.armed(win));
    // The quality tier: the visitor's, or the one this device starts on.
    const device = readDeviceFacts(win, (engine as { getGlInfo?: () => { renderer?: string } }).getGlInfo?.()?.renderer);
    const quality = () => qualityProfile(resolveTier(settingsController.get().graphics.quality, device));
    const applyRenderScale = () => engine.setHardwareScalingLevel(1 / quality().renderScale);
    applyRenderScale();
    // The styles the current world's items come in and the visitor's choice among them, for the menu's Style row.
    let worldStyles: StyleOffer | undefined;
    const session = createWorldSession({
      ...(viewerBase === undefined ? {} : { viewerBase }),
      // Which worlds this page opens: its own origin's, the list in its markup, and the world it points at itself.
      ...pageWorldRules(win.location, doc, worldSource.kind === 'referenced' ? worldSource.url : undefined),
      // A host that knows who the visitor is names them; else the browser's name.
      ...(pageVisitorName === undefined ? {} : { visitorName: pageVisitorName }),
      // And what they wear, when the host says.
      ...(pageVisitorAvatar === undefined ? {} : { visitorAvatar: pageVisitorAvatar }),
      // A private world's room admits on a ticket its host gives, asked for afresh at each join.
      ...(pageRoomTicket === undefined
        ? {}
        : { roomTicket: () => import('./roomTicket').then(({ roomTicket }) => roomTicket(pageRoomTicket, (u, init) => win.fetch(u, init))) }),
      // The DOM that hosts an `html` entity's embedded page (§4.6).
      htmlHost: { document },
      headPose: () => vr.headPose(), // what the others see of a VR visitor
      onMessage: people.onMessage,
      lookSpeed: () => settingsController.get().locomotion.lookSpeed, // the visitor's menu
      iceServers: () => settingsController.get().network.iceServers,
      // The visitor's shadows, no sharper than the tier allows.
      shadowMapSize: () => Math.min(settingsController.get().graphics.shadowMapSize, quality().shadowMapSize),
      assetQuality: () => quality().tier,
      planetQuality: () => ({ ...quality().planet, temporal: temporalOf(settingsController.get().graphics.temporal, quality().temporal), motionBlur: () => settingsController.get().graphics.motionBlur === 'on', focus: () => settingsController.get().graphics.focus ?? 'auto', terrainStyle: () => settingsController.get().graphics.terrainStyle ?? 'auto', things: () => settingsController.get().graphics.things ?? 'auto' }),
      onPlacementStyles: (offer) => {
        worldStyles = offer;
      },
      // A sign-in made in the world names the visitor there and then, when the page's host takes it: the others see
      // them by the name and avatar it answers. The room is told, never the page reloaded.
      ...(pageVisitorSession === undefined
        ? {}
        : {
            onSignedIn: (upstream: string) =>
              void import('./namedBySignIn')
                .then(({ namedBySignIn }) => namedBySignIn(pageVisitorSession, upstream, (u, init) => win.fetch(u, init)))
                .then((who) => {
                  if (who?.name) session.present(who.name, who.avatar);
                }),
          }),
      engine,
      input,
      noWorld: { scene, camera, controller },
      engineKind: kind,
      spawnOverride,
      // Browser localStorage backend for world scripts'
      // LocalStorage.* (persistent, kept per source; host-mediated, namespaced).
      localStorage:
        typeof window !== 'undefined' && window.localStorage ? window.localStorage : undefined,
      // §9: the surface asks the visitor; answers are remembered per site.
      consent: { request: (req) => surface.requestConsent(req) },
      consentStore: win.localStorage ? win.localStorage : undefined,
      // The World.LoadWorld/LoadWebPage seam (script nav == portal
      // nav == hash nav). controllerRef is set below, before any script runs.
      navigate: (url: string) => {
        void controllerRef?.navigate(url).catch(() => {});
      },
      // The Input polling source (isVR is the headset's presenting state).
      // move from the non-destructive axes, look from the active
      // controller's last-applied per-tick delta, key from the raw held-key set.
      scriptInput: {
        getMoveValue: () => {
          const axes = input.moveAxes();
          return { x: axes.strafe, y: axes.forward };
        },
        getLookValue: () => sessionRef?.active().controller.lastLookDelta() ?? { x: 0, y: 0 },
        isKeyDown: (key: string) => input.isKeyDown(key),
        isVR: () => vr.isPresenting(),
      },
      // Camera-attach is suspended while presenting (both boots can present).
      isPresenting: () => vr.isPresenting(),
      onProgress: (event) => {
        surface.onProgress(event);
        logProgressDebug(event);
      },
      onLifecycle: (event) => {
        lifecycleLog.push(
          'url' in event
            ? { kind: event.kind, url: event.url, at: performance.now() }
            : { kind: event.kind, at: performance.now() },
        );
        surface.onLifecycle(event);
        if (event.kind === 'world-entered' && sessionRef) {
          surface.notifyCapabilities(sessionRef.state().capabilities);
          controlsHint.onWorldEntered();
          vr.worldLoaded(true);
        }
        // Exit-on-nav: a session is bound to the scene it entered.
        if (event.kind === 'load-started' || event.kind === 'unloaded') vr.worldLoaded(false);
      },
    });
    sessionRef = session;
    teardown.push(() => session.dispose());
    teardown.push(people.mount(session, liveCanvas, { touch: touchPrimary, hints: session.hints() }));
    // The settings menu, over the same settings controller.
    const menu = mountSettingsMenu(doc, {
      controller: settingsController,
      nameStore: win.localStorage ?? undefined,
      // The render scale follows a new tier at once; the rest at the next world.
      onChanged: () => {
        people.refresh();
        applyRenderScale();
      },
      hints: session.hints(), // controls.menu
      onForgetConsent: () => session.forgetConsent(),
      autoQuality: autoTier(device),
      styles: () => worldStyles,
    });
    teardown.push(() => menu.dispose());

    const navigation = createHashNavigationController(win, session, worldSource.kind === 'referenced' ? { home: worldSource.url } : {});
    controllerRef = navigation;
    teardown.push(() => navigation.dispose());

    const portal = createPortalInteraction({
      getActive: () => session.active(),
      getPortals: () => session.portals(),
      navigation,
      input,
      doc,
      canvas: liveCanvas,
    });
    teardown.push(() => portal.dispose());

    // The script input dispatcher (host-pumped input → inputevents),
    // mirroring main.ts. Re-targets the live world; drained before tickScripts.
    const inputDispatcher = createScriptInputDispatcher({
      getWorldInputEvents: () => session.worldInputEvents(),
      getWorldToken: () => session.worldToken(),
      dispatch: (expr) => session.dispatchScriptEvent(expr),
      isPointerLocked: () => input.isPointerLocked(),
      pickEntityAt: (x, y, locked) => session.pickScriptEntityAt(x, y, locked),
      dispatchEntityClick: (id) => session.dispatchEntityClick(id),
      // The 4.0 core inputs → the active world's input bindings → the bus.
      onCoreInput: (input, data) => session.coreInput(input, data),
      canvas: liveCanvas,
    });
    inputDispatcherRef = inputDispatcher;
    teardown.push(() => inputDispatcher.dispose());

    const disarmGesture = armDomGestureListeners(session.audioGate(), win);
    teardown.push(() => disarmGesture());

    const onResize = (): void => engine.resize();
    win.addEventListener('resize', onResize);
    teardown.push(() => win.removeEventListener('resize', onResize));

    startRenderLoop(engine, session, navigation, portal, inputDispatcher, lifecycleLog, input, kind,
      touchPrimary ? 'touch' : 'desktop', win, settingsController, vr, pageVisitorName);

    // Load the page's own world. The inline path serializes the
    // running document and inert-parses it (THE CRUX); the referenced path is
    // the navigation controller's home, opened from the address as it stands,
    // so the page's own world adds no history entry and Back from a portal
    // returns to it; a world-less page just dismisses the splash to the
    // no-world scene.
    switch (worldSource.kind) {
      case 'inline':
        void session.loadInlineWorld(worldSource.html, win.location.href).catch(() => {});
        break;
      case 'referenced':
        void navigation.syncFromHash().catch(() => {});
        break;
      case 'none':
        surface.bootCompleted();
        break;
    }
  } catch (err) {
    while (teardown.length > 0) teardown.pop()!();
    throw err;
  }
}

function startRenderLoop(
  engine: Awaited<ReturnType<typeof createEngine>>['engine'],
  session: WorldSession,
  navigation: NavigationController,
  portal: PortalInteraction,
  inputDispatcher: ScriptInputDispatcher,
  lifecycleLog: Array<{ kind: string; url?: string; at?: number }>,
  input: BootInput,
  kind: string,
  inputMode: 'touch' | 'desktop',
  win: Window,
  settingsController: ReturnType<typeof createSettingsController>,
  vr: { tick(dtMs: number): boolean },
  pageVisitorName: string | undefined,
): void {
  // Monotonic frame counter (matches main.ts; the sandbox isolation
  // proof surface). A self-booted scripted world ticks its sandbox
  // here exactly like the app path.
  let frameCount = 0;
  engine.runRenderLoop(() => {
    const { scene, camera, controller } = session.active();
    // While presenting, the VR tick runs INSTEAD of the desktop one
    // (as main.ts does); move/look then come from the XR input, not the pump.
    if (!vr.tick(engine.getDeltaTime())) {
      controller.tick(engine.getDeltaTime() / 1000);
      // Feed the DESKTOP continuous move/look into the script input dispatcher.
      const axes = input.moveAxes();
      inputDispatcher.pumpDesktopMotion(
        { x: axes.strafe, y: axes.forward },
        controller.lastLookDelta(),
      );
    }
    // Drain host-pumped input into the sandbox BEFORE tickScripts.
    inputDispatcher.drain();
    // Drive host-driven sandbox time; no-op for a scriptless world,
    // deadline-guarded internally.
    session.tickScripts(engine.getDeltaTime());
    // The KINEMATIC character motion integrator (Jump arc + SURFACE
    // gravity), AFTER tickScripts, BEFORE updateFollowers, mirroring main.ts.
    session.updateCharacters(engine.getDeltaTime());
    // Water: the waves move, the bed is re-read, the eye's tint follows.
    session.updateWater(engine.getDeltaTime());
    // Physics: the visitor's capsule follows the feet; the engine steps in the render.
    session.updatePhysics(engine.getDeltaTime());
    // The sync session's tick (pose out, mirrors walked), mirroring main.ts.
    session.updateSync(engine.getDeltaTime());
    // Lod levels for the camera's distance, mirroring main.ts.
    session.updateLod();
    // A planet world's floating origin, zoom and terrain tiles; no-op otherwise.
    session.updatePlanet(engine.getDeltaTime());
    session.updateDeferred();
    // The CAMERA & RIG FOLLOWER loop (after scripts + controller tick,
    // before render), mirroring main.ts.
    session.updateFollowers();
    // The html surfaces follow their quads with this frame's camera.
    session.updateHtmlSurfaces(input.isPointerLocked());
    scene.render();
    frameCount += 1;
    portal.update();
    const feet = controller.feetPosition();
    win.__webverse = {
      engineKind: kind,
      ready: true,
      frame: frameCount,
      meshCount: scene.meshes.length,
      labelCount: scene.meshes.filter((m) => m.name.startsWith('label:')).length,
      pointerLocked: input.isPointerLocked(),
      inputMode,
      cameraPosition: { x: camera.position.x, y: camera.position.y, z: camera.position.z },
      yaw: controller.yaw,
      pitch: controller.pitch,
      feetPosition: { x: feet.x, y: feet.y, z: feet.z },
      everGrounded: controller.hasEverGrounded(),
      holding: controller.isHolding(),
      // The name the room will see: what the session was given, resolved the
      // way the session resolves it, so a test can see the page's name win.
      visitorName: pageVisitorName ?? browserVisitorName(win.localStorage ? win.localStorage : undefined),
      teleportFeet: (x: number, y: number, z: number) =>
        controller.teleportFeet(new Vector3(x, y, z)),
      setLook: (yawRad: number, pitchRad: number) =>
        controller.setOrientation(yawRad, pitchRad),
      // See main.ts: fan the ONE embedder call out to both
      // settings owners (the bindings controller + the session).
      applySettings: (partial: PartialShellSettings): void => {
        settingsController.applySettings(partial);
        session.applySettings(partial);
      },
      loadWorld: (url: string) => navigation.navigate(url, { force: true }),
      unloadWorld: () => navigation.clear(),
      dropSync: () => session.dropSync(), // the reconnect seam
      portalFocus: () => portal.focusedPortal(),
      activatePortal: () => portal.activateFocused(),
      dispatchEntityClick: (id: string) => session.dispatchEntityClick(id),
      lifecycleLog,
      activeMeshInfo: () =>
        session.active().scene.meshes.map((m) => {
          const p = m.getAbsolutePosition();
          return { name: m.name, isPickable: m.isPickable, position: { x: p.x, y: p.y, z: p.z } };
        }),
      sceneLightInfo: () =>
        session.active().scene.lights.map((l) => ({ name: l.name, type: l.getClassName() })),
      sceneMaterialInfo: () =>
        session.active().scene.materials.map((m) => ({ name: m.name, type: m.getClassName() })),
      sceneReflectionProbeInfo: () =>
        (session.active().scene.reflectionProbes ?? []).map((p) => ({ name: p.name })),
      worldState: session.state(),
      lastParse: parseSnapshot(),
      forgetConsent: (origin?: string) => session.forgetConsent(origin ?? win.location.origin),
    };
  });
}
