/**
 * `manifest` (VEML 4.0 §6.3): logical-name indirection.
 *
 * A document may name its content by logical names — `manifest:hero` — and
 * point at one small JSON file that maps each name to an absolute http(s)
 * address. Content stays immutable and cacheable under hashed names; the
 * manifest is the one mutable file that says where it is today. Resolution is
 * single-step and limited to `src` and `href`; a name the map lacks, or a map
 * that cannot be read, leaves each use unresolved and warned, and the
 * referencing element degrades as a failed reference.
 */
import type { VemlDocument, VemlEntity } from './documentModel';

const SCHEME = 'manifest:';
/** §6.3 names share §6.4's placeholder grammar. */
const NAME_RE = /^[a-z][a-z0-9-]*$/;

/** The logical name a `manifest:` URI carries, when it is one and the name is well formed. */
export function manifestNameOf(uri: string): string | undefined {
  if (!uri.startsWith(SCHEME)) return undefined;
  const name = uri.slice(SCHEME.length);
  return NAME_RE.test(name) ? name : undefined;
}

/** Every `manifest:` URI the document's `src`/`href` references carry, as written. */
export function manifestUsesOf(document: VemlDocument): string[] {
  const uses: string[] = [];
  const consider = (uri: string | undefined): void => {
    if (uri !== undefined && uri.startsWith(SCHEME)) uses.push(uri);
  };
  for (const s of document.metadata.scripts) consider(s.resolved);
  for (const p of document.metadata.prototypes ?? []) consider(p.url);
  // A `manifest:` name handed to a prototype as a parameter is the host's
  // use too (§6.4: "the host authored the value"), so it counts here.
  const considerBindings = (pending: Array<{ bindings: Record<string, string> }> | undefined): void => {
    for (const p of pending ?? []) for (const v of Object.values(p.bindings)) consider(v);
  };
  const walk = (entities: readonly VemlEntity[]): void => {
    for (const e of entities) {
      if ('meshResources' in e) for (const r of e.meshResources) consider(r.resolved);
      if ('meshAlternatives' in e) for (const a of e.meshAlternatives ?? []) consider(a.resource.resolved);
      consider(e.include?.resolved);
      considerBindings(e.pendingInstances);
      walk(e.children);
      for (const level of e.lodLevels ?? []) {
        considerBindings(level.pendingInstances);
        walk(level.entities);
      }
    }
  };
  walk(document.environment.entities);
  return uses;
}

export function documentUsesManifest(document: VemlDocument): boolean {
  return manifestUsesOf(document).length > 0;
}

/**
 * The map from a parsed manifest body. Only an object counts as a manifest at
 * all; within it, only a well-formed name mapping to a string that is an
 * absolute http(s) URL counts as an entry. Everything else is warned about
 * and left out: a non-string value, a value that is itself a `manifest:` name
 * (resolution is single-step), a relative or non-http(s) address.
 */
export function parseManifest(body: unknown, warn: (message: string) => void): Map<string, string> | undefined {
  if (body === null || typeof body !== 'object' || Array.isArray(body)) {
    warn('[webverse] manifest: the document is not a JSON object of names to addresses (§6.3); no names resolve');
    return undefined;
  }
  const map = new Map<string, string>();
  for (const [name, value] of Object.entries(body as Record<string, unknown>)) {
    if (!NAME_RE.test(name)) {
      warn(`[webverse] manifest: entry "${name}" is not a valid name ([a-z][a-z0-9-]*); ignored`);
      continue;
    }
    if (typeof value !== 'string') {
      warn(`[webverse] manifest: entry "${name}" is not a string; ignored`);
      continue;
    }
    if (value.startsWith(SCHEME)) {
      warn(`[webverse] manifest: entry "${name}" points at another manifest: name; resolution is single-step (§6.3), ignored`);
      continue;
    }
    if (!/^https?:\/\//.test(value) || !isAbsoluteUrl(value)) {
      warn(`[webverse] manifest: entry "${name}" is not an absolute http(s) address; ignored`);
      continue;
    }
    map.set(name, value);
  }
  return map;
}

function isAbsoluteUrl(value: string): boolean {
  try {
    const u = new URL(value);
    return u.protocol === 'http:' || u.protocol === 'https:';
  } catch {
    return false;
  }
}

/**
 * Replace every `manifest:` reference the document's `src`/`href` carry with
 * the address the map gives it, in place. A use the map cannot answer — or
 * every use, when there is no map — is left as written, warned once, and
 * returned, so the caller can report it; the element then degrades as a
 * failed reference when it is fetched.
 */
export function rewriteManifestReferences(
  document: VemlDocument,
  map: Map<string, string> | undefined,
  warn: (message: string) => void,
): string[] {
  const unresolved: string[] = [];
  const resolve = (uri: string, where: string): string => {
    if (!uri.startsWith(SCHEME)) return uri;
    const name = manifestNameOf(uri);
    const target = name !== undefined ? map?.get(name) : undefined;
    if (target !== undefined) return target;
    unresolved.push(uri);
    const why =
      map === undefined
        ? 'the document has no readable manifest'
        : name === undefined
          ? 'not a valid manifest name'
          : 'not in the manifest';
    warn(`[webverse] manifest: ${where} "${uri}" is unresolved — ${why} (§6.3); the reference fails`);
    return uri;
  };
  for (const s of document.metadata.scripts) s.resolved = resolve(s.resolved, 'script');
  for (const p of document.metadata.prototypes ?? []) p.url = resolve(p.url, `prototype ${p.name}`);
  if (document.metadata.subsidiaryRefs !== undefined) {
    // The eligibility list must name what the sites now name, quietly: the
    // use itself was already warned above or will be below.
    document.metadata.subsidiaryRefs = document.metadata.subsidiaryRefs.map((r) => {
      const name = manifestNameOf(r);
      return (name !== undefined ? map?.get(name) : undefined) ?? r;
    });
  }
  const walk = (entities: readonly VemlEntity[]): void => {
    for (const e of entities) {
      const tag = e.tag ?? e.id ?? '(untagged)';
      if ('meshResources' in e) for (const r of e.meshResources) r.resolved = resolve(r.resolved, `asset '${tag}'`);
      if ('meshAlternatives' in e) for (const a of e.meshAlternatives ?? []) a.resource.resolved = resolve(a.resource.resolved, `source of asset '${tag}'`);
      if (e.include !== undefined) e.include.resolved = resolve(e.include.resolved, `include on '${tag}'`);
      walk(e.children);
      for (const level of e.lodLevels ?? []) walk(level.entities);
    }
  };
  walk(document.environment.entities);
  return unresolved;
}
