/**
 * The round touch buttons beside the sticks: jump (the touch input
 * module) and chat (the messages module). Their shared look lives here, with
 * no imports, so the messages module can draw a chat button without pulling
 * the touch chunk into a desktop page's first paint (the touch input is
 * code-split).
 */

/** The sticks' size and inset (touchInput.ts re-exports them); the buttons sit clear of them. */
export const STICK_BASE_PX = 120;
export const STICK_INSET_PX = 24;

/** The round touch buttons (jump, and chat from the messages module) beside the sticks. */
export const TOUCH_BUTTON_PX = 64;
/** Above the sticks, clear of them: the stick's inset + base + a gap. */
export const TOUCH_BUTTON_BOTTOM_PX = STICK_INSET_PX + STICK_BASE_PX + 16;

/**
 * One round touch button's CSS, on `side`, `offsetPx` in from that edge and
 * `bottomPx` up from the bottom (default: just above the stick). Shared with
 * the chat button.
 */
export function touchButtonCss(
  side: 'left' | 'right',
  offsetPx: number = STICK_INSET_PX + (STICK_BASE_PX - TOUCH_BUTTON_PX) / 2,
  bottomPx: number = TOUCH_BUTTON_BOTTOM_PX,
): string {
  return (
    `position:fixed;bottom:${bottomPx}px;${side}:${offsetPx}px;` +
    `width:${TOUCH_BUTTON_PX}px;height:${TOUCH_BUTTON_PX}px;border-radius:50%;` +
    'display:flex;align-items:center;justify-content:center;' +
    'font:600 13px system-ui,sans-serif;color:#fff;letter-spacing:.02em;' +
    'background:rgba(0,0,0,0.35);border:2px solid rgba(255,255,255,0.45);' +
    'box-sizing:border-box;touch-action:none;user-select:none;' +
    '-webkit-user-select:none;-webkit-tap-highlight-color:transparent;z-index:12;'
  );
}
