/** What a world may do right now (§9): read live, so a grant takes effect on the next call. */
interface ConsentGate {
  granted(capability: string): boolean;
}

/**
 * `LocalStorage` behind the `persistent-storage` gate: nothing is read or
 * written until the visitor allows it, and the client says so once.
 */
function gatedStorage(
  backend: LocalStorageBackend | undefined,
  gate: ConsentGate,
  warn: (message: string) => void,
): LocalStorageBackend {
  let warned = false;
  const allowed = (): boolean => {
    if (gate.granted('persistent-storage')) return true;
    if (!warned) {
      warned = true;
      warn('[webverse] script: LocalStorage is empty until the visitor allows persistent-storage (§9)');
    }
    return false;
  };
  return {
    getItem: (key) => (allowed() ? (backend?.getItem(key) ?? null) : null),
    setItem: (key, value) => {
      if (allowed()) backend?.setItem(key, value);
    },
    removeItem: (key) => {
      if (allowed()) backend?.removeItem(key);
    },
  };
}

/** The script host behind the `position-reporting` gate: where the visitor stands is null until allowed. */
function gatedPosition(host: EntityApiHost | undefined, gate: ConsentGate, warn: (message: string) => void): EntityApiHost | undefined {
  if (!host) return host;
  let warned = false;
  return {
    ...host,
    cameraGetPosition: (local) => {
      if (gate.granted('position-reporting')) return host.cameraGetPosition(local);
      if (!warned) {
        warned = true;
        warn('[webverse] script: Camera.GetPosition is null until the visitor allows position-reporting (§9)');
      }
      return null;
    },
  };
}
