/**
 * Camera near plane (m). Babylon's default is 1 m — far too deep for a
 * first-person walker whose capsule can rest CAPSULE_RADIUS_M (0.3 m) from a
 * wall: everything within arm's reach gets clipped away (a window frame
 * stood at is cut open). MUST stay below the capsule radius; 5 cm keeps a 6× margin.
 */
export const CAMERA_NEAR_PLANE_M = 0.05;

/**
 * Build the `NetEntityBridge` the sync session uses to read a LOCAL entity's
 * type/transform and to create/move/delete the other visitors' MIRRORS via the
 * SAME entity factory. Pure delegation to the live `entityApi` (the entity
 * registry) — all plain-data (handle-as-id: an entity id + a `{x,y,z}`/
 * `{x,y,z,w}` cross, NEVER a Babylon node). Only the avatar set
 * (character/mesh/container) is a valid mirror type; any other → `describe`
 * returns null.
 */
export function createNetEntityBridge(entityApi: EntityApiHost): NetEntityBridge {
  const asType = (t: string | null): NetEntityType | null =>
    t === 'character' || t === 'mesh' || t === 'container' ? t : null;
  const vec3 = (v: { x: number; y: number; z: number } | null): NetVec3 =>
    v ? { x: v.x, y: v.y, z: v.z } : { x: 0, y: 0, z: 0 };
  const quat = (v: { x: number; y: number; z: number; w: number } | null): NetQuat =>
    v ? { x: v.x, y: v.y, z: v.z, w: v.w } : { x: 0, y: 0, z: 0, w: 1 };
  return {
    describe(entityId) {
      const type = asType(entityApi.getType(entityId));
      if (!type) return null;
      return {
        type,
        tag: entityApi.getTag(entityId) ?? entityId,
        // Registration announces the LOCAL transform (relative to the parent).
        position: vec3(entityApi.getPosition(entityId, true) as NetVec3 | null),
        rotation: quat(entityApi.getRotation(entityId, true) as NetQuat | null),
      };
    },
    readTransform(entityId) {
      if (!entityApi.get(entityId)) return null;
      // The periodic broadcast uses the LIVE WORLD transform; the corpus avatar
      // is unparented, so world == local.
      return {
        position: vec3(entityApi.getPosition(entityId, false) as NetVec3 | null),
        rotation: quat(entityApi.getRotation(entityId, false) as NetQuat | null),
      };
    },
    createMirror(spec) {
      return entityApi.createMirror(spec);
    },
    moveMirror(entityId, position) {
      // The ISOLATION-GUARDED mirror mutator: refuses a non-mirror id
      // (a local authored entity, incl. one that overwrote a pre-claimed mirror).
      return entityApi.moveMirror(entityId, position);
    },
    rotateMirror(entityId, rotation) {
      return entityApi.rotateMirror(entityId, rotation);
    },
    deleteMirror(entityId) {
      return entityApi.deleteMirror(entityId);
    },
    animateMirror(entityId, clip) {
      return entityApi.animateMirror(entityId, clip);
    },
    entityExists(entityId) {
      return entityApi.get(entityId) != null;
    },
  };
}

/**
 * World lifecycle events. The seam the default
 * feedback surface (and any embedder-driven replacement — this plus
 * `onProgress` IS the opt-out API) reacts to. Whoever initiates a load
 * (`__webverse.loadWorld`, a future NavigationController, an embedder), the
 * same events fire — the surface never wraps or intercepts the load path.
 *
 * Order per load: `load-started` → (`document-parsed` → `world-entered`) on
 * success | `load-failed` on a parse/fetch report failure or an unexpected
 * build throw. `unloaded` fires whenever an ACTIVE world is torn down
 * (explicit unload or the implicit unload at the top of the next load), AND
 * when an explicit unload/dispose CANCELS an in-flight load (the session
 * ends world-less either way — a surface must never keep a loading overlay
 * for an abandoned load). A superseded/disposed mid-flight
 * load emits nothing further (generation guard) — only the winning load ever
 * reaches `world-entered`.
 */
/**
 * What a `load-failed` event carries: the parse report's errors (fetch /
 * malformed-xml / not-veml / unsupported-namespace, incl. the additive
 * `phase` on fetch errors), or a synthesized `fatal` entry for an unexpected
 * build throw (the world document was fine; construction failed).
 */
export type WorldLoadFailure = VemlParseError | { kind: 'fatal'; message: string };

export type WorldLifecycleEvent =
  | { kind: 'load-started'; url: string }
  | { kind: 'document-parsed'; url: string; title: string | null }
  | { kind: 'load-failed'; url: string; errors: WorldLoadFailure[] }
  | { kind: 'world-entered'; url: string; title: string | null }
  | { kind: 'unloaded' };

export type WorldLifecycleListener = (event: WorldLifecycleEvent) => void;

