/** Plain-JSON world snapshot for observability (window.__webverse). */
export interface WorldSessionState {
  loaded: boolean;
  url: string | null;
  registryCount: number;
  entities: Array<{
    id: string;
    tag: string;
    type: string;
    status: 'loaded' | 'errored';
    assetUrl?: string;
    errorMessage?: string;
  }>;
  progressLog: WorldLoadProgressEvent[];
  /**
   * The last load that FAILED, or null. Set on `load-failed`, cleared
   * on the next `load-started`. This is what makes "failed" distinguishable
   * from "loaded, empty": a bare model URL whose fetch 404s builds an empty
   * world with `loaded: true`, and without this nothing downstream — not the
   * UI, not a test, not the user — could tell that from success.
   */
  lastFailure: { url: string; kind: string; message: string } | null;
  /**
   * The declared worldsync session's live state, or null when
   * the world declares nothing this shell can use. Refreshed on every read:
   * attachment, membership and mirrors change without a lifecycle event.
   */
  sync: WorldsyncSessionState | null;
  /** Has a user gesture unlocked audio autoplay this session? */
  audioGestured: boolean;
  /** Declared audio entities (gesture-gate + spatial state). */
  audio: Array<{
    tag: string;
    autoPlay: boolean;
    playing: boolean;
    pending: boolean;
    spatial: boolean;
    position: { x: number; y: number; z: number };
    /** World direction a directional sound's cone faces; absent when it plays in every direction. */
    direction?: { x: number; y: number; z: number };
  }>;
  /**
   * Capability degradation report: every degraded (known-but-web-
   * unsupported) and genuinely-unknown entity type this world declared, with
   * counts + tags. The programmatic report surface (the feedback surface reads
   * it here); mirrored to window.__webverse.worldState.capabilities.
   */
  capabilities: CapabilityReport;
  /**
   * The resolved entry pose (spawn chain + auto-frame). `feet` is the
   * standing point (camera = feet + eye height), `yawRad` the camera heading,
   * `source` which resolution step won. `contentCenter`/`contentRadius` describe
   * the entity-mesh extents (null when the world has no entity meshes);
   * `contentInView` is a LIVE per-read check (camera.isInFrustum over those
   * extents) — the "off-origin worlds are never blank" assertion surface.
   */
  spawn: {
    source: SpawnSource;
    feet: { x: number; y: number; z: number };
    yawRad: number;
    contentCenter: { x: number; y: number; z: number } | null;
    contentRadius: number | null;
    contentInView: boolean;
  };
  /**
   * The applied world-owned environment (background). `kind` is
   * which path ran (color | panorama | neutral fallback), `clearColor` the
   * scene clear color RGBA (matches the parsed color), `hasEnvironmentTexture`
   * whether a neutral/skybox IBL is present, `panorama` whether the
   * code-split PhotoDome path ran (the e2e both-directions chunk-fetch check).
   */
  background: EnvironmentInfo;
  /**
   * The QuickJS sandbox script report. `chunkLoaded` whether the
   * code-split QuickJS-WASM chunk was fetched (true only for a world with
   * `<script>` entries — the e2e both-directions check); `scriptCount` the
   * declared scripts; `errors` any script fetch/throw/deadline-interrupt
   * captured WITHOUT killing the world; `testLog` the minimal test
   * bridge's `__sandboxLog` output.
   */
  scriptReport: ScriptReport;
  /**
   * The action bus's observation surface (VEML 4.0 §8): every fire on the
   * active world's bus — name, source, and `handled`: a handler ran, or the
   * client consumed a built-in (`veml.interact` from a defaulted press is the
   * client's whether or not a portal was under the cursor). Newest last,
   * capped. Cleared per world. How the e2e sees a binding reach a script
   * without pixels.
   */
  actionLog: Array<{ name: string; source: ActionSource; handled: boolean }>;
  /**
   * `include` composition (VEML 4.0 §6.2). The world is entered before any
   * included document arrives; `settled` flips once every one of them has
   * landed or been omitted, and `entries` says which, where, and why not.
   */
  includes: { settled: boolean; entries: IncludeOutcome[] };
  /**
   * `prototype` definitions fetched by `href` (VEML 4.0 §6.4), one entry per
   * name some `instance` used. `settled` flips once every one has expanded
   * under its hosts or been omitted; inline prototypes expand at parse time
   * and are not listed.
   */
  prototypes: { settled: boolean; entries: PrototypeOutcome[] };
  /**
   * Each `lod` (VEML 4.0 §4.10): the level showing for the viewer's distance,
   * and the levels built so far, ascending. A level is built the first time
   * it is needed and kept.
   */
  lods: Array<{ entityId: string; active: number; built: number[] }>;
  /**
   * Capabilities and consent (VEML 4.0 §9) for the active 4.0 world: its
   * origin and one entry per declared name — granted, denied, pending the
   * visitor's answer, unsupported (the client has no feature for it) or
   * unknown (not in the vocabulary). Empty for a 3.x world.
   */
  consent: { origin: string | null; entries: ConsentPlanEntry[] };
  /**
   * What waits behind declared bounds (VEML 4.0 §4.8): a glb, an include or a
   * lod the author boxed, which loads once the visitor is near the box and
   * looking at it. `entityId` is the declared id, else the tag.
   */
  deferred: Array<{ entityId: string; tag: string; kind: 'asset' | 'include' | 'lod'; status: 'waiting' | 'loading' | 'loaded' }>;
  /**
   * The active document's `manifest` (VEML 4.0 §6.3): where it was fetched
   * from, whether it was needed (`unused`), read (`resolved`), unreadable
   * (`failed`) or missing while names used it (`undeclared`), and every
   * `manifest:` reference that stayed unresolved.
   */
  manifest: { url: string | null; status: 'unused' | 'resolved' | 'failed' | 'undeclared'; unresolved: string[] };
  /**
   * Shadows in the active world: the map size in use, one entry per light
   * that got a generator (its kind and how many meshes cast into it), and
   * the lights that asked and were declined, with why.
   */
  shadows: ShadowReport;
  /**
   * Water in the active world (the `water` profile): how many bodies and
   * blockers, how many surfaces drawn and with which material, whether the
   * eye is under a surface, and whether the visitor is swimming now.
   */
  water: WaterReport & { swimming: boolean };
  /**
   * Physics in the active world: whether the engine was asked for, loaded or
   * failed, and how many dynamic, static and kinematic bodies it holds.
   */
  physics: PhysicsReport;
}

/** What became of one fetched prototype: expanded under its hosts, or omitted and why. */
export interface PrototypeOutcome {
  name: string;
  url: string;
  status: 'composed' | 'omitted';
  reason?: 'ineligible' | 'cap' | 'fetch' | 'parse' | 'integrity' | 'cancelled';
  message?: string;
  /** How many instances expanded. */
  instances: number;
}

/** The action log keeps this many entries; older ones fall off the front. */
const ACTION_LOG_CAP = 200;
/** Messages an html page posts before its world commits are held, up to this many. */
const HELD_HTML_MESSAGES_CAP = 32;

/** Each include with its place in the include tree (IncludeSite.order): `prefix`, then its index; unchanged where the parent's place is unknown. */
function ordered(sites: IncludeSite[], prefix: readonly number[] | undefined): IncludeSite[] {
  return prefix === undefined ? sites : sites.map((s, i) => ({ ...s, order: [...prefix, i] }));
}

/** The gravity a document's own `locomotion` gives, if any. */
function gravityOf(doc: VemlDocument): { gravity?: number } {
  const g = doc.environment.locomotion?.gravity;
  return g !== undefined ? { gravity: g } : {};
}

/** The same, as the gravity in the space of a root world that is not a planet. */
function spaceGravityOf(doc: VemlDocument): { spaceGravity?: number } {
  const g = doc.environment.locomotion?.gravity;
  return g !== undefined ? { spaceGravity: g } : {};
}

/** The empty spawn block used when no world is loaded. */
function emptySpawnState(): WorldSessionState['spawn'] {
  return {
    source: 'origin',
    feet: { x: 0, y: 0, z: 0 },
    yawRad: 0,
    contentCenter: null,
    contentRadius: null,
    contentInView: false,
  };
}

/** The empty background block used when no world is loaded. */
function emptyBackgroundState(): EnvironmentInfo {
  return {
    kind: 'neutral',
    clearColor: { r: 0, g: 0, b: 0, a: 1 },
    hasEnvironmentTexture: false,
    panorama: false,
    fog: { enabled: false, mode: 'none', color: { r: 0, g: 0, b: 0 }, density: 0 },
    defaultLightingProfileApplied: false,
  };
}

