/**
 * Messages: the panel. Shell chrome: a small list of what happened,
 * who is here, and one line to say something.
 *
 * Chrome belongs to the user, not the world (VEML §5.1's rule for the exit
 * is the general one). So this is wired only by the default page (`main.ts`),
 * like the feedback surface: an embedder that drives `createWorldSession`
 * gets the stream and no default UI. Everything a person sees is a setting —
 * shown, which channels, which corner, how many lines, how long they stay,
 * the keys, the words — read live, applied on `applySettings()`.
 *
 * DOM only, no Babylon imports, main bundle. Naming: the
 * `data-webverse-messages-*` attributes are this runtime's private,
 * swappable identifiers, the same allowance as the feedback surface's.
 *
 * Input rule: the line is a real <input>. Closed, it has no
 * focus and eats nothing. Open, it has focus, and every key inside it stays
 * inside it — `stopPropagation` — so W is a letter, not a step. Enter sends
 * the trimmed line and closes; an empty line sends nothing; Escape closes and
 * forgets. A send the session refuses (nobody to hear) keeps the line open
 * with its text, so nothing typed is lost to a bad moment.
 */
import type { ShellMessagesSettings } from '../settings/shellSettings';
import type { MessageStream } from './messageStream';

export const MESSAGES_CONTAINER_ID = 'webverse-messages';

export interface MessagesMember {
  name: string;
  self: boolean;
}

export interface MessagesPanelOptions {
  stream: MessageStream;
  settings: () => ShellMessagesSettings;
  /** Who is here, by name, the viewer marked. Empty when there is no session. */
  members: () => readonly MessagesMember[];
  /** Send a line to the room. False when there is nobody to hear it. */
  send: (text: string) => boolean;
}

export interface MessagesPanel {
  /** Redraw lines and members from the stream and the members source. */
  refresh(): void;
  /** Settings changed: placement, visibility, channels. Redraws. */
  applySettings(): void;
  openInput(): void;
  closeInput(): void;
  inputOpen(): boolean;
  /** Show/hide the panel, this session (the setting is the default; this is the key). */
  toggle(): void;
  /**
   * The text the panel shows now (unfaded lines), or nothing while
   * it is hidden: what the headset panel draws.
   */
  shownLines(): string[];
  dispose(): void;
}

/** How many lines the open chat line reads back. */
export const HISTORY_SHOWN = 50;

const CSS = `
#${MESSAGES_CONTAINER_ID}{position:fixed;z-index:8;max-width:min(40vw,420px);pointer-events:none;
  font:13px/1.35 system-ui,sans-serif;color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.8);}
#${MESSAGES_CONTAINER_ID}[data-webverse-messages-corner^="bottom"]{bottom:12px}
#${MESSAGES_CONTAINER_ID}[data-webverse-messages-corner^="top"]{top:12px}
#${MESSAGES_CONTAINER_ID}[data-webverse-messages-corner$="left"]{left:12px}
#${MESSAGES_CONTAINER_ID}[data-webverse-messages-corner$="right"]{right:12px;text-align:right}
#${MESSAGES_CONTAINER_ID} [data-webverse-messages-members]{opacity:.85;margin-bottom:6px;display:flex;gap:8px;flex-wrap:wrap}
#${MESSAGES_CONTAINER_ID} [data-webverse-messages-member="self"]{text-decoration:underline}
#${MESSAGES_CONTAINER_ID} [data-webverse-messages-line]{margin:2px 0;word-break:break-word}
#${MESSAGES_CONTAINER_ID} [data-webverse-messages-lines][data-webverse-messages-history]{pointer-events:auto;max-height:40vh;overflow-y:auto;
  background:rgba(0,0,0,.35);border-radius:4px;padding:4px 6px}
#${MESSAGES_CONTAINER_ID} [data-webverse-messages-line="shell"]{opacity:.75;font-style:italic}
#${MESSAGES_CONTAINER_ID} [data-webverse-messages-line="world"]{opacity:.85}
#${MESSAGES_CONTAINER_ID} [data-webverse-messages-input]{pointer-events:auto;margin-top:6px;width:100%;box-sizing:border-box;
  background:rgba(0,0,0,.55);color:#fff;border:1px solid rgba(255,255,255,.35);border-radius:3px;padding:4px 6px;font:inherit;outline:none}
@media (max-width:600px){#${MESSAGES_CONTAINER_ID}{max-width:calc(100vw - 88px)}
  #${MESSAGES_CONTAINER_ID} [data-webverse-messages-input]{min-width:calc(100vw - 88px);font-size:16px}}
`;

export function createMessagesPanel(doc: Document, options: MessagesPanelOptions): MessagesPanel {
  const style = doc.createElement('style');
  style.textContent = CSS;
  doc.head.appendChild(style);

  const root = doc.createElement('div');
  root.id = MESSAGES_CONTAINER_ID;
  root.setAttribute('role', 'log');
  root.setAttribute('aria-live', 'polite');

  const membersNode = doc.createElement('div');
  membersNode.setAttribute('data-webverse-messages-members', '');
  const linesNode = doc.createElement('div');
  linesNode.setAttribute('data-webverse-messages-lines', '');
  const input = doc.createElement('input');
  input.type = 'text';
  input.setAttribute('data-webverse-messages-input', '');
  input.setAttribute('autocomplete', 'off');
  input.hidden = true;
  root.append(membersNode, linesNode, input);
  doc.body.appendChild(root);

  /** The key toggle: null = the setting decides; a boolean = this session's choice. */
  let toggled: boolean | null = null;
  let disposed = false;

  const shown = (): boolean => (toggled === null ? options.settings().visible : toggled);

  const drawMembers = (): void => {
    membersNode.replaceChildren();
    for (const m of options.members()) {
      const span = doc.createElement('span');
      span.setAttribute('data-webverse-messages-member', m.self ? 'self' : 'other');
      span.textContent = m.name;
      membersNode.appendChild(span);
    }
  };

  const drawLines = (): void => {
    linesNode.replaceChildren();
    // `visible()` is the one filter: it already drops hidden channels and
    // faded lines against the SAME settings and clock. The panel draws what
    // it is handed — a second filter here only drifts from that one. With
    // the chat line open, it draws the recent history instead, faded
    // lines included, scrollable, scrolled to the newest.
    const history = !input.hidden;
    if (history) linesNode.setAttribute('data-webverse-messages-history', 'true');
    else linesNode.removeAttribute('data-webverse-messages-history');
    for (const m of history ? options.stream.history(HISTORY_SHOWN) : options.stream.visible()) {
      const line = doc.createElement('div');
      line.setAttribute('data-webverse-messages-line', m.channel);
      line.textContent = m.text; // textContent: a field is text, never markup
      linesNode.appendChild(line);
    }
    if (history) linesNode.scrollTop = linesNode.scrollHeight;
  };

  const refresh = (): void => {
    if (disposed) return;
    root.hidden = !shown();
    root.setAttribute('data-webverse-messages-corner', options.settings().corner);
    // Zero cost at rest: main.ts calls refresh() every render tick.
    // A hidden panel does no DOM work; the first refresh after it is shown
    // draws everything that arrived meanwhile.
    if (!shown()) return;
    drawMembers();
    drawLines();
  };

  const closeInput = (): void => {
    input.value = '';
    input.hidden = true;
    if (doc.activeElement === input) input.blur();
    refresh(); // back from the history to the unfaded view
  };

  const onInputKey = (ev: KeyboardEvent): void => {
    // Everything typed here is ours: the world never sees a key from the line.
    ev.stopPropagation();
    if (ev.key === 'Enter') {
      ev.preventDefault();
      const text = input.value.trim();
      if (text.length === 0) {
        closeInput();
        return;
      }
      if (options.send(text)) closeInput();
      return;
    }
    if (ev.key === 'Escape') {
      ev.preventDefault();
      closeInput();
    }
  };
  input.addEventListener('keydown', onInputKey);
  input.addEventListener('keyup', (ev) => ev.stopPropagation());

  const unsubscribe = options.stream.subscribe(() => refresh());
  refresh();

  return {
    refresh,
    applySettings: refresh,
    openInput() {
      if (disposed) return;
      if (!shown()) {
        toggled = true;
        refresh();
      }
      input.hidden = false;
      refresh(); // the history, while the line is open
      input.focus();
    },
    closeInput,
    shownLines: () => (shown() ? options.stream.visible().map((m) => m.text) : []),
    inputOpen: () => !input.hidden,
    toggle() {
      toggled = !shown();
      if (!toggled) closeInput();
      refresh();
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      unsubscribe();
      input.removeEventListener('keydown', onInputKey);
      root.remove();
      style.remove();
    },
  };
}
