/** Percent-decodes the URL fragment as UTF-8, then compares by exact
 *  codepoint equality (case-sensitive) against entry-point `id`s — non-ASCII
 *  entry point names are first-class. An unknown fragment falls back to the
 *  entry point named `default` with `veml:5:unknown-fragment`. No fragment
 *  at all resolves straight to `default`, no diagnostic. */
export function resolveArrival(entryPoints, fragment) {
    const find = (id) => entryPoints.find((e) => e.id === id);
    if (fragment === undefined)
        return { entryPoint: find("default") };
    let decoded;
    try {
        decoded = decodeURIComponent(fragment);
    }
    catch {
        decoded = fragment; // malformed percent-sequence: compare the raw fragment, it simply won't match
    }
    const match = find(decoded);
    if (match)
        return { entryPoint: match };
    return { entryPoint: find("default"), diagnostic: { id: "veml:5:unknown-fragment", detail: fragment } };
}
