/**
 * Deferral by declared bounds (VEML 4.0 §4.8).
 *
 * A declared box is a promise about extent, consumed before content exists:
 * nothing has to be downloaded to know where a thing is and how big it is.
 * The client trusts it to defer: content behind a declared box loads once
 * the visitor is near the box and looking at it. Distance is to the box's
 * nearest point, so a large thing whose edge is close loads even when its
 * centre is far. Declared bounds govern deferral only, never visibility:
 * once loaded, the geometry is what renders.
 */
import { Vector3, Matrix, Quaternion } from '@babylonjs/core/Maths/math.vector';
import { Frustum } from '@babylonjs/core/Maths/math.frustum';
import type { Plane } from '@babylonjs/core/Maths/math.plane';
import { BoundingInfo } from '@babylonjs/core/Culling/boundingInfo';
import type { Camera } from '@babylonjs/core/Cameras/camera';
import type { VemlTransform, VemlVec3 } from '../veml/documentModel';

/** Beyond this, a declared box is "far" and its content waits, whatever the view. */
export const DEFER_DISTANCE_M = 150;

/** An axis-aligned box in world space. */
export interface WorldBox {
  min: Vector3;
  max: Vector3;
}

export interface DeclaredBounds {
  center: VemlVec3;
  size: VemlVec3;
}

/**
 * The declared box under the entity's own transform and `parentWorld`, as an
 * axis-aligned box: the eight corners transformed, then their extremes. A
 * `size` transform is resolved against the declared size — §4.2's "declared
 * bounds satisfy this without loading". A canvas transform is screen-space
 * and gives the box no world placement; the parent's frame is used as is.
 */
export function declaredWorldBox(
  bounds: DeclaredBounds,
  transform: VemlTransform | undefined,
  parentWorld: Matrix,
): WorldBox {
  let local = Matrix.Identity();
  if (transform !== undefined && transform.kind !== 'canvastransform') {
    const scale =
      transform.kind === 'scaletransform'
        ? new Vector3(transform.scale.x, transform.scale.y, transform.scale.z)
        : new Vector3(
            ratio(transform.size.x, bounds.size.x),
            ratio(transform.size.y, bounds.size.y),
            ratio(transform.size.z, bounds.size.z),
          );
    const q = transform.rotation;
    local = Matrix.Compose(
      scale,
      new Quaternion(q.x, q.y, q.z, q.w),
      new Vector3(transform.position.x, transform.position.y, transform.position.z),
    );
  }
  const world = local.multiply(parentWorld);
  const half = new Vector3(bounds.size.x / 2, bounds.size.y / 2, bounds.size.z / 2);
  const c = bounds.center;
  let min = new Vector3(Infinity, Infinity, Infinity);
  let max = new Vector3(-Infinity, -Infinity, -Infinity);
  for (const sx of [-1, 1]) {
    for (const sy of [-1, 1]) {
      for (const sz of [-1, 1]) {
        const corner = Vector3.TransformCoordinates(
          new Vector3(c.x + sx * half.x, c.y + sy * half.y, c.z + sz * half.z),
          world,
        );
        min = Vector3.Minimize(min, corner);
        max = Vector3.Maximize(max, corner);
      }
    }
  }
  return { min, max };
}

function ratio(target: number, declared: number): number {
  return declared > 0 ? target / declared : 1;
}

/** Distance from `point` to the nearest point of `box`; zero inside. */
export function nearestDistance(box: WorldBox, point: Vector3): number {
  const dx = Math.max(box.min.x - point.x, 0, point.x - box.max.x);
  const dy = Math.max(box.min.y - point.y, 0, point.y - box.max.y);
  const dz = Math.max(box.min.z - point.z, 0, point.z - box.max.z);
  return Math.sqrt(dx * dx + dy * dy + dz * dz);
}

/** The camera's frustum planes, from fresh view and projection matrices. */
export function frustumPlanesOf(camera: Camera): Plane[] {
  const view = camera.getViewMatrix(true);
  const projection = camera.getProjectionMatrix(true);
  return Frustum.GetPlanes(view.multiply(projection));
}

/** Near enough and in view: the content behind this box should load now. */
export function shouldLoad(box: WorldBox, eye: Vector3, planes: Plane[]): boolean {
  if (nearestDistance(box, eye) > DEFER_DISTANCE_M) return false;
  return new BoundingInfo(box.min, box.max).isInFrustum(planes);
}
