/**
 * Shell input bindings — the SINGLE SOURCE of physical key-code literals for
 * locomotion + the debug HUD toggle. `desktopInput.ts` and
 * `main.ts` read every key code through this table; nothing outside this
 * file may spell a `KeyboardEvent.code` literal (guard test:
 * tests/unit/shellSettings.test.ts).
 *
 * `descend` defaults to BOTH shift codes so it stays side-agnostic, the way
 * `KeyboardEvent.key === 'Shift'` is: ShiftLeft and ShiftRight both read as
 * `key: 'Shift'`, and binding both codes keeps either one working under
 * code-based tracking.
 */
export type BindableAction =
  | 'forward'
  | 'back'
  | 'left'
  | 'right'
  | 'jump'
  | 'descend'
  /** Held while walking: run. Shares Shift with descend, which only flying reads. */
  | 'run'
  | 'flyToggle'
  | 'debugHud'
  /** Open the Messages line to type into. */
  | 'chat'
  /** Show or hide the Messages panel. */
  | 'messagesToggle'
  /** Show or hide the controls hint. */
  | 'help';

export type KeyBindings = Readonly<Record<BindableAction, readonly string[]>>;

export const DEFAULT_BINDINGS: KeyBindings = {
  forward: ['KeyW'],
  back: ['KeyS'],
  left: ['KeyA'],
  right: ['KeyD'],
  jump: ['Space'],
  descend: ['ShiftLeft', 'ShiftRight'],
  run: ['ShiftLeft', 'ShiftRight'],
  flyToggle: ['KeyF'],
  debugHud: ['Backquote'],
  chat: ['Enter'],
  messagesToggle: ['KeyM'],
  help: ['KeyH'],
};

/**
 * How a key reads to a person, for the controls hint. Lives here because
 * this is the one file allowed to spell key codes. Letters and digits lose
 * their prefix; the rest are named; anything unknown shows its code.
 */
const KEY_LABELS: Readonly<Record<string, string>> = {
  Space: 'Space',
  ShiftLeft: 'Shift',
  ShiftRight: 'Shift',
  ControlLeft: 'Ctrl',
  ControlRight: 'Ctrl',
  AltLeft: 'Alt',
  AltRight: 'Alt',
  Backquote: '`',
  Enter: 'Enter',
  Escape: 'Esc',
  Slash: '/',
  ArrowUp: '↑',
  ArrowDown: '↓',
  ArrowLeft: '←',
  ArrowRight: '→',
};

export function keyLabel(code: string): string {
  const named = KEY_LABELS[code];
  if (named !== undefined) return named;
  return /^(?:Key|Digit|Numpad)(.+)$/.exec(code)?.[1] ?? code;
}

/** Every code a movement/jump/descend/run action binds — the `held` tracking set. */
export function trackedCodes(bindings: KeyBindings): Set<string> {
  return new Set([
    ...bindings.forward,
    ...bindings.back,
    ...bindings.left,
    ...bindings.right,
    ...bindings.jump,
    ...bindings.descend,
    ...bindings.run,
  ]);
}
