/**
 * The action bus — VEML 4.0 §8.1, per world.
 *
 * An action is a named event. Names are free: any non-empty string without
 * whitespace, no registration. Sources are input bindings (§8.2), an entity's
 * `on-load`, an html entity's `on-message`, a button's click, and scripts.
 * Firing an action nobody handles is legal and warns, once per name, so a
 * misspelt binding is visible without flooding the log.
 *
 * The one rule with teeth: `veml.*` is reserved for the client's built-ins,
 * and only an INPUT BINDING may fire one. From every other source a `veml.*`
 * action is ignored with a warning. That is how content — a world's script,
 * an embedded page, an `on-load` — never steers the visitor or triggers an
 * interaction on their behalf.
 *
 * Handlers run synchronously, in registration order; a handler that throws is
 * reported and the rest still run. The bus knows nothing about the sandbox:
 * the session registers a host handler that forwards into it.
 */

export type ActionSource = 'input-binding' | 'on-load' | 'on-message' | 'on-click' | 'script' | 'shell';

export type ActionHandler = (data: unknown) => void;

/** The initial built-ins (§8.1); every other `veml.*` name is reserved too. */
export const BUILT_IN_ACTIONS: ReadonlyArray<string> = Object.freeze([
  'veml.character.move',
  'veml.character.look',
  'veml.interact',
]);

export interface ActionBus {
  /** Fire `name` with `data` from `source`. True when at least one handler ran. */
  fire(name: string, data: unknown, source: ActionSource): boolean;
  /** Register a handler; returns the unsubscribe. Throws on an invalid name. */
  on(name: string, handler: ActionHandler): () => void;
  hasHandler(name: string): boolean;
  dispose(): void;
}

export interface ActionBusOptions {
  /** Where the bus says what it ignored. Default: the console. */
  warn?: (message: string) => void;
}

/** §8.1: non-empty, no whitespace. */
export function isValidActionName(name: unknown): name is string {
  return typeof name === 'string' && name.length > 0 && !/\s/.test(name);
}

export function isReservedAction(name: string): boolean {
  return name.startsWith('veml.');
}

export function createActionBus(options: ActionBusOptions = {}): ActionBus {
  const warn = options.warn ?? ((m: string) => console.warn(m));
  // A Map keyed by name is prototype-pollution-immune: `__proto__` is a name.
  let handlers = new Map<string, ActionHandler[]>();
  const warnedUnhandled = new Set<string>();
  let disposed = false;

  return {
    fire(name, data, source) {
      if (disposed) return false;
      if (!isValidActionName(name)) {
        warn(`[webverse] actions: invalid action name ${JSON.stringify(name)} from ${source} — ignored`);
        return false;
      }
      if (isReservedAction(name) && source !== 'input-binding') {
        warn(
          `[webverse] actions: '${name}' is a reserved built-in; only an input binding may fire it, not ${source} — ignored`,
        );
        return false;
      }
      const list = handlers.get(name);
      if (!list || list.length === 0) {
        if (!warnedUnhandled.has(name)) {
          warnedUnhandled.add(name);
          warn(`[webverse] actions: '${name}' fired (${source}) with no handler — a legal no-op`);
        }
        return false;
      }
      // Snapshot: a handler may unsubscribe itself or another mid-fire.
      for (const handler of [...list]) {
        try {
          handler(data);
        } catch (err) {
          warn(`[webverse] actions: handler for '${name}' threw: ${(err as Error)?.message ?? String(err)}`);
        }
      }
      return true;
    },
    on(name, handler) {
      if (!isValidActionName(name)) throw new Error(`invalid action name ${JSON.stringify(name)}`);
      if (disposed) return () => {};
      const list = handlers.get(name) ?? [];
      list.push(handler);
      handlers.set(name, list);
      return () => {
        const current = handlers.get(name);
        if (!current) return;
        const i = current.indexOf(handler);
        if (i !== -1) current.splice(i, 1);
        if (current.length === 0) handlers.delete(name);
      };
    },
    hasHandler(name) {
      return (handlers.get(name)?.length ?? 0) > 0;
    },
    dispose() {
      disposed = true;
      handlers = new Map();
      warnedUnhandled.clear();
    },
  };
}
