/**
 * Lite fog. Exponential scene fog from `effects/lite-fog`.
 *
 * Fog is applied ONLY when `effects/lite-fog` is present AND `fog-enabled` is
 * true; the baseline is fog OFF.
 *
 * Mapping: exponential fog (f = exp(-density·dist)) → Babylon
 * `Scene.FOGMODE_EXP` (1), NOT FOGMODE_EXP2 (exponential-squared). The fog
 * `color` reuses `parseVemlColorValue` (the XSD default "gray" resolves
 * there); NO second color parser.
 *
 * An out-of-range density is clamped to [0,1] with a warning and EXP fog still
 * renders, rather than dropping the whole fog: a malformed value degrades the
 * world, never fails it.
 *
 * `Scene` is imported as a VALUE for its static FOGMODE_* constants; it is
 * already in the main bundle (worldSession). `Color3` is a Maths class.
 */
import { Scene } from '@babylonjs/core/scene';
import { Color3 } from '@babylonjs/core/Maths/math.color';
import type { VemlLiteFog } from '../../veml/documentModel';
import { parseVemlColorValue } from './vemlColorValue';
import { log } from '../../logging/runtimeLog';

export interface FogHandle {
  /** Reset the scene to the no-fog baseline (FOGMODE_NONE) — churn-critical for
   * a reused scene (a fresh per-world scene is disposed anyway). */
  reset(): void;
}

/** Clamp a density to the [0,1] range; warn on a violation (fog is kept). */
function clampDensity(density: number): number {
  if (!Number.isFinite(density) || density < 0 || density > 1) {
    const clamped = !Number.isFinite(density) ? 0.5 : Math.min(1, Math.max(0, density));
    log.warn(
      `[webverse] lite-fog: density '${density}' out of [0,1] — clamped to ${clamped}`,
    );
    return clamped;
  }
  return density;
}

/**
 * Apply `effects/lite-fog` as exponential scene fog. Absent `liteFog` or
 * `fog-enabled=false` → no fog (FOGMODE_NONE). Never throws.
 */
export function applyLiteFog(liteFog: VemlLiteFog | undefined, scene: Scene): FogHandle {
  const reset = (): void => {
    scene.fogMode = Scene.FOGMODE_NONE;
  };

  if (liteFog === undefined || liteFog.fogEnabled !== true) {
    reset();
    return { reset };
  }

  const { r, g, b } = parseVemlColorValue(liteFog.color);
  scene.fogMode = Scene.FOGMODE_EXP; // exponential, not exponential-squared
  scene.fogColor = new Color3(r, g, b);
  scene.fogDensity = clampDensity(liteFog.density);
  return { reset };
}
