/**
 * Self-boot entry. Built to `dist/webverse-boot.js` (a
 * STABLE filename — the swappable one-liner an author includes). A world HTML
 * self-initializes the runtime with ONE line:
 *
 *   <script type="module" src="…/webverse-boot.js"></script>
 *
 * All logic lives in `./selfBootCore` (unit-testable, never auto-runs); this
 * entry only invokes it against the live document once the DOM is parsed, and
 * converts a boot failure to the fatal error card (never an eternal
 * splash).
 *
 */
import { log } from '../logging/runtimeLog';
import { createFeedbackSurface } from '../feedback/feedbackSurface';
import { runSelfBoot } from './selfBootCore';
// The app loads the HTML dialect's parser on demand, since its typical world
// is XML. A self-boot page's world is usually its own inline HTML, so this
// entry imports the parser statically: it ships in the boot's first paint
// and the parse never waits on a second fetch.
import '../veml/htmlDialect';

/**
 * The folder this script was loaded from, which is where the viewer's own
 * files are: a world page at /w/<id> loads it from /webverse/. Held
 * in a variable so the bundler does not treat it as an asset reference.
 */
const entryUrl = import.meta.url;
const viewerBase = new URL('.', entryUrl).href;

function start(): void {
  runSelfBoot(document, window, viewerBase).catch((err: unknown) => {
    // Fail loudly: the splash converts to the fatal error card,
    // full detail to the console — never a silent blank page.
    log.error('[webverse] self-boot failed:', err);
    try {
      createFeedbackSurface(document).showFatal(err);
    } catch {
      /* the DOM itself is unavailable — the console error above is all we can do */
    }
  });
}

if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start, { once: true });
  } else {
    start();
  }
}
