/**
 * The planet profile's values (`specs/veml/profiles/planet.md`, Numbers and
 * positions): decimal numbers with no exponent, infinity or NaN; lists
 * comma-separated with no spaces; geographic positions with latitude in
 * [−90, 90] and longitude taken modulo 360 into (−180, 180]. Shared by the
 * document's parser and the planet description's reader, so both read a
 * position the same way.
 */

import type { VemlPlanetSite } from './documentModel';
import { resolveWorldUri } from './uriResolve';

const NUMBER = /^-?[0-9]+(\.[0-9]+)?$/;

/** A profile number, or undefined. */
export function planetNumber(raw: string | number | undefined): number | undefined {
  if (typeof raw === 'number') return Number.isFinite(raw) ? raw : undefined;
  if (raw === undefined || !NUMBER.test(raw)) return undefined;
  return Number(raw);
}

/** A longitude into (−180, 180]. */
export function wrapLongitude(lon: number): number {
  // In range already: untouched, so a written value is read back exactly.
  if (lon > -180 && lon <= 180) return lon;
  const w = ((((lon + 180) % 360) + 360) % 360) - 180;
  return w === -180 ? 180 : w;
}

/** `count` comma-separated numbers, or undefined. */
export function planetList(raw: string | undefined, count: number): number[] | undefined {
  if (raw === undefined) return undefined;
  const parts = raw.split(',');
  if (parts.length !== count) return undefined;
  const out = parts.map((p) => planetNumber(p));
  return out.every((v) => v !== undefined) ? (out as number[]) : undefined;
}

/** A geographic position, `lat,lon` or (with `allowAlt`) `lat,lon,alt`, or undefined. */
export function geographic(raw: string | undefined, allowAlt: boolean): number[] | undefined {
  if (raw === undefined) return undefined;
  const n = raw.split(',').length;
  if (n !== 2 && !(allowAlt && n === 3)) return undefined;
  const v = planetList(raw, n);
  if (!v || v[0]! < -90 || v[0]! > 90) return undefined;
  v[1] = wrapLongitude(v[1]!);
  return v;
}

export type PlanetSite = VemlPlanetSite;

/** A site from `planet:site` attributes or a description's `sites` entry; undefined if it is invalid. */
export function readSite(fields: Record<string, unknown>, baseUrl: string): PlanetSite | undefined {
  const str = (k: string) => (typeof fields[k] === 'string' ? (fields[k] as string) : typeof fields[k] === 'number' ? String(fields[k]) : undefined);
  const href = str('href');
  const at = geographic(str('at'), true);
  const radius = planetNumber(fields.radius as string | number | undefined);
  const heading = fields.heading === undefined ? 0 : planetNumber(fields.heading as string | number | undefined);
  if (!href || !at || radius === undefined || radius <= 0 || heading === undefined) return undefined;
  const site: PlanetSite = { href: { raw: href, resolved: resolveWorldUri(href, baseUrl) }, at, heading, radius };
  const integrity = str('integrity');
  if (integrity !== undefined) site.integrity = integrity;
  return site;
}
