/**
 * Who a visitor is to the others in a room: a name, and the colour of
 * their default avatar.
 *
 * A visitor who has not set a name gets a random one, and the default avatar
 * a random-looking colour. The name is made once per browser and kept, so a person is
 * the same "Anonymous Otter" every visit until they choose a name. The colour
 * comes from the NAME, so it looks random and is still the same on every
 * screen: nothing extra needs to cross the wire.
 */

/** Where the name is kept, in the browser's own storage. */
export const VISITOR_NAME_KEY = 'webverse.visitorName';

const ANIMALS = [
  'Otter', 'Heron', 'Badger', 'Lynx', 'Falcon', 'Walrus', 'Panda', 'Koala', 'Gecko', 'Moose',
  'Beaver', 'Raven', 'Dolphin', 'Tiger', 'Llama', 'Penguin', 'Fox', 'Owl', 'Hedgehog', 'Bison',
  'Squirrel', 'Kangaroo', 'Octopus', 'Turtle', 'Wombat', 'Ibis', 'Jaguar', 'Narwhal', 'Quokka', 'Yak',
] as const;

/** The parts of `Storage` used here; absent in a private window or a test. */
export interface NameStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

const read = (store: NameStore | undefined): string | null => {
  try {
    const v = store?.getItem(VISITOR_NAME_KEY);
    return typeof v === 'string' && v.trim().length > 0 ? v.trim() : null;
  } catch {
    return null;
  }
};

const write = (store: NameStore | undefined, name: string): void => {
  try {
    store?.setItem(VISITOR_NAME_KEY, name);
  } catch {
    /* storage refused (private mode, quota): the name holds for this visit */
  }
};

/** This browser's name: the one chosen or kept, else a new "Anonymous <Animal>", kept from now on. */
export function visitorName(store: NameStore | undefined, random: () => number = Math.random): string {
  const kept = read(store);
  if (kept !== null) return kept;
  const animal = ANIMALS[Math.min(ANIMALS.length - 1, Math.floor(random() * ANIMALS.length))]!;
  const made = `Anonymous ${animal}`;
  write(store, made);
  return made;
}

/** A person's own choice of name. Blank is refused (null) and the old name stays. */
export function chooseVisitorName(store: NameStore | undefined, name: string): string | null {
  const chosen = name.trim().slice(0, 40);
  if (chosen.length === 0) return null;
  write(store, chosen);
  return chosen;
}

/**
 * The colour a person's default avatar is drawn in: a hue from the name's
 * hash, at a fixed saturation and lightness, so every colour is clear and
 * none is grey or dark. The same name gives the same colour on every screen.
 */
export function avatarColor(name: string): { r: number; g: number; b: number } {
  let h = 2166136261;
  for (let i = 0; i < name.length; i++) {
    h ^= name.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  const hue = ((h >>> 0) % 360) / 360;
  return hslToRgb(hue, 0.6, 0.55);
}

function hslToRgb(h: number, s: number, l: number): { r: number; g: number; b: number } {
  const q = l < 0.5 ? l * (1 + s) : l + s - l * s;
  const p = 2 * l - q;
  const channel = (t: number): number => {
    let x = t;
    if (x < 0) x += 1;
    if (x > 1) x -= 1;
    if (x < 1 / 6) return p + (q - p) * 6 * x;
    if (x < 1 / 2) return q;
    if (x < 2 / 3) return p + (q - p) * (2 / 3 - x) * 6;
    return p;
  };
  return { r: channel(h + 1 / 3), g: channel(h), b: channel(h - 1 / 3) };
}
