/**
 * Desktop input source: pointer lock + WASD + mouse-look deltas.
 *
 * Design notes:
 * - Key listeners live on the CANVAS, not `window` — window listeners lose to
 *   DevTools focus after console use. The canvas has `tabindex="0"` +
 *   focus-on-load (index.html / main.ts); the click that requests pointer lock
 *   also re-focuses it.
 * - Mouse deltas (`movementX/Y`) are consumed only while pointer-locked; the
 *   first mousemove after acquiring the lock is dropped (some platforms
 *   deliver a large bogus initial delta).
 * - Movement intent is gated on the pointer lock: losing the lock (Esc)
 *   clears held keys and pending deltas so the player never "runs away"
 *   while the browser owns the pointer.
 * - This module is one INPUT SOURCE behind `LocomotionInputSource`; the
 *   mobile virtual sticks plug into the same controller core through the
 *   same interface.
 * - Everything registered here is removed by `dispose()` — wired into
 *   main.ts's HMR cleanup closure so no listener leaks.
 * - Which physical keys drive forward/back/left/right/jump/
 *   descend is read live from `getBindings()` (default `DEFAULT_BINDINGS`,
 *   src/input/bindings.ts) — this module holds no key-code literals itself.
 */
import { DEFAULT_BINDINGS, trackedCodes, type KeyBindings } from './bindings';

/** Movement intent, each axis in [-1, 1]. forward = +W/-S, strafe = +D/-A. */
export interface MoveAxes {
  forward: number;
  strafe: number;
}

/** Accumulated look delta in PIXELS since the last consume (raw movementX/Y). */
export interface LookDelta {
  yawPx: number;
  pitchPx: number;
}

/** The contract the controller core consumes — device-agnostic. */
export interface LocomotionInputSource {
  moveAxes(): MoveAxes;
  /** Returns the accumulated look delta and resets the accumulator. */
  consumeLookDelta(): LookDelta;
  /**
   * Edge-triggered jump request: true exactly once per physical press since
   * the last consume. OPTIONAL — a source without a jump affordance (touch
   * sticks, test doubles) simply omits it and the controller never jumps.
   */
  consumeJump?(): boolean;
  /**
   * LEVEL-triggered jump intent: true while the jump control is currently
   * held (non-destructive read). Backs the controller's hold-to-keep-jumping
   * option — landing while this is true re-jumps immediately. OPTIONAL, like
   * `consumeJump`. In FLY MODE the controller reads it as ASCEND.
   */
  jumpHeld?(): boolean;
  /**
   * LEVEL-triggered descend intent (fly mode: Shift). OPTIONAL — a source
   * without it simply never descends in flight.
   */
  descendHeld?(): boolean;
  /**
   * LEVEL-triggered run intent (walking: Shift). OPTIONAL — a source without
   * it simply never runs.
   */
  runHeld?(): boolean;
}

type Listener = (ev: Event) => void;

/** Minimal event surface so unit tests can use plain-object doubles. */
export interface MinimalEventTarget {
  addEventListener(type: string, listener: Listener): void;
  removeEventListener(type: string, listener: Listener): void;
}

export interface PointerLockCanvas extends MinimalEventTarget {
  focus(): void;
  requestPointerLock(): void | Promise<void>;
}

export interface PointerLockDocument extends MinimalEventTarget {
  readonly pointerLockElement: unknown;
  /**
   * The browser's release call. Optional so older engines and plain
   * test doubles still satisfy the surface; when absent nothing is released
   * (and nothing throws).
   */
  exitPointerLock?(): void;
}

export interface DesktopInput extends LocomotionInputSource {
  isPointerLocked(): boolean;
  /**
   * Is `key` (a `KeyboardEvent.key` string, e.g. the letter w, a
   * bare space, or Shift) currently held? The RAW key state (NOT lock-gated
   * — a script polls raw key state), backing the `Input.GetKeyValue(key)`
   * polling API. Own-property-safe (a `Set` — a `__proto__` key is a normal
   * member, never prototype pollution).
   */
  isKeyDown(key: string): boolean;
  /** Jump queue consume — ALWAYS present on the desktop source (bound key). */
  consumeJump(): boolean;
  /** True while the bound jump key is held and the pointer is locked (hold-to-keep-jumping). */
  jumpHeld(): boolean;
  /** True while the bound descend key is held and the pointer is locked (fly-mode descend). */
  descendHeld(): boolean;
  /** True while the bound run key is held and the pointer is locked (walking runs). */
  runHeld(): boolean;
  dispose(): void;
}

/**
 * An OBSERVE-ONLY key tap. The script `inputevent` dispatcher
 * subscribes here so NO second `keydown`/`keyup` is attached (the controller's
 * existing canvas listeners already receive EVERY key — they only FILTER to
 * the bound movement keys). The observer fires BEFORE that filter and NEVER
 * mutates the controller's held-keys / lock state, so locomotion is
 * untouched. `key` = `KeyboardEvent.key` (web-standard, e.g. the letter a
 * or Shift), `code` = `KeyboardEvent.code` (e.g. the codes for A or Space).
 */
export type RawKeyObserver = (kind: 'down' | 'up', key: string, code: string) => void;

/**
 * The live key-bindings source. A GETTER (not a snapshot): every
 * event handler + accessor below reads through it, so `applySettings`
 * rebinding a key takes effect on the very next event with no re-creation.
 * Defaults to `DEFAULT_BINDINGS`, so behaviour is unchanged when nothing
 * overrides it.
 */
export type BindingsSource = () => KeyBindings;

/**
 * Where `pagehide` fires: the Window. Passed in rather than reached
 * for (like `doc`), so the unit tests drive it with a plain double and the
 * module stays free of globals.
 */
export type PageLifecycleTarget = MinimalEventTarget;

export function createDesktopInput(
  canvas: PointerLockCanvas,
  doc: PointerLockDocument,
  onRawKey?: RawKeyObserver,
  getBindings: BindingsSource = () => DEFAULT_BINDINGS,
  pageLifecycle?: PageLifecycleTarget,
): DesktopInput {
  // The bound movement/jump/descend codes feed `held`. All share the held
  // set's lifecycle (cleared on unlock/blur/dispose — a stale hold never
  // persists).
  const held = new Set<string>();
  // Jump: a queued edge-triggered press (the bound jump key while
  // pointer-locked), consumed by the controller once per tick. Lock-gated
  // like `held` (movement intent), repeat-filtered (one queued jump per
  // physical press — holding the key must not auto-bounce on every OS key
  // repeat), cleared wherever `held` is cleared (unlock/blur/dispose) so a
  // stale press never fires later.
  let jumpQueued = false;
  // The GENERAL held-key set (by `KeyboardEvent.key`), the source
  // for `Input.GetKeyValue`. Distinct from `held` (which tracks ONLY WASD codes
  // for locomotion): this is EVERY key, raw (NOT lock-gated — a script polls raw
  // key state). A `Set` is prototype-pollution-
  // immune (a `__proto__` key is a normal member). Cleared on blur (a keyup that
  // never arrives after focus leaves the canvas), like `held`.
  const pressedKeys = new Set<string>();
  // The lock may ALREADY be held on this canvas when the input is created —
  // a lock taken before this module ran. `pointerlockchange` never re-fires
  // for a lock that didn't change, so reading the real state here is what
  // keeps a fresh instance from being permanently dead to clicks.
  let locked = doc.pointerLockElement === canvas;
  let skipNextMouseMove = locked;
  let yawPx = 0;
  let pitchPx = 0;

  const onClick: Listener = () => {
    // Keyboard focus + pointer lock on the same user gesture.
    canvas.focus();
    if (!locked) {
      try {
        // May return a promise (newer lib.dom); rejection (user denied / not
        // allowed yet) is non-fatal — the next click retries. Older engines
        // throw SYNCHRONOUSLY instead of firing pointerlockerror — equally
        // non-fatal.
        void Promise.resolve(canvas.requestPointerLock()).catch(() => undefined);
      } catch {
        /* denied — the next click retries */
      }
    }
  };

  const onKeyDown: Listener = (ev) => {
    const k = ev as KeyboardEvent;
    // Observe-only tap FIRST (before the movement filter); it never touches
    // `held`/lock, so movement is unaffected. Skip OS key-repeat (`ev.repeat`):
    // a script `key` handler fires ONCE per physical press, so a held key
    // dispatches it once — not once per auto-repeat. (The controller's
    // `held` Set is repeat-idempotent, so this does not affect locomotion.)
    if (onRawKey && !k.repeat) onRawKey('down', k.key, k.code);
    const bindings = getBindings();
    if (trackedCodes(bindings).has(k.code)) held.add(k.code);
    if (bindings.jump.includes(k.code) && !k.repeat && locked) {
      jumpQueued = true;
      // The jump key scrolls the page on a focused element (Space) — never
      // while it means jump.
      k.preventDefault?.();
    }
    // Raw held-key state for Input.GetKeyValue (Set.add is repeat-
    // idempotent, so an OS auto-repeat does not disturb it).
    pressedKeys.add(k.key);
  };

  const onKeyUp: Listener = (ev) => {
    const k = ev as KeyboardEvent;
    if (onRawKey) onRawKey('up', k.key, k.code);
    held.delete(k.code);
    pressedKeys.delete(k.key);
  };

  const onMouseMove: Listener = (ev) => {
    if (!locked) return;
    if (skipNextMouseMove) {
      skipNextMouseMove = false;
      return;
    }
    const m = ev as MouseEvent;
    yawPx += m.movementX ?? 0;
    pitchPx += m.movementY ?? 0;
  };

  const onPointerLockChange: Listener = () => {
    const nowLocked = doc.pointerLockElement === canvas;
    if (nowLocked && !locked) skipNextMouseMove = true;
    if (!nowLocked) {
      // Esc exits are browser-owned: stop moving and drop stale deltas.
      held.clear();
      jumpQueued = false;
      yawPx = 0;
      pitchPx = 0;
    }
    locked = nowLocked;
  };

  const onBlur: Listener = () => {
    // If keyboard focus leaves the canvas, its `keyup` will never arrive —
    // drop held keys rather than walk forever on a stale set. (Browsers exit
    // the pointer lock on window blur, but a focus shift WITHIN the page can
    // leave the lock held.)
    held.clear();
    jumpQueued = false;
    pressedKeys.clear(); // a keyup will never arrive; drop raw keys too
  };

  // Give back the lock we took, and ONLY the lock we took. Releasing
  // a lock held by another element would be the same bug in the other
  // direction. `exitPointerLock` is optional on the surface (older engines,
  // plain doubles) and may throw in odd states; neither is fatal here.
  const releaseOurLock = (): void => {
    if (doc.pointerLockElement !== canvas) return;
    try {
      doc.exitPointerLock?.();
    } catch {
      /* the browser refused — nothing more we can do on the way out */
    }
  };

  // The tab-close path. `pagehide` (not `beforeunload`, which is
  // unreliable, nor `unload`, deprecated). NOT `visibilitychange`: that also
  // fires on a tab switch, where dropping the lock on someone alt-tabbing
  // mid-walk would be the wrong behaviour. Held keys are dropped for the
  // same reason `onBlur` drops them: their keyup will never arrive.
  const onPageHide: Listener = () => {
    releaseOurLock();
    held.clear();
    jumpQueued = false;
    pressedKeys.clear();
    yawPx = 0;
    pitchPx = 0;
    locked = false;
  };

  canvas.addEventListener('click', onClick);
  canvas.addEventListener('keydown', onKeyDown);
  canvas.addEventListener('keyup', onKeyUp);
  canvas.addEventListener('blur', onBlur);
  doc.addEventListener('mousemove', onMouseMove);
  doc.addEventListener('pointerlockchange', onPointerLockChange);
  pageLifecycle?.addEventListener('pagehide', onPageHide);

  return {
    isPointerLocked: () => locked,
    isKeyDown: (key: string): boolean => pressedKeys.has(key),
    moveAxes(): MoveAxes {
      if (!locked) return { forward: 0, strafe: 0 };
      const b = getBindings();
      const anyHeld = (codes: readonly string[]): boolean => codes.some((c) => held.has(c));
      return {
        forward: (anyHeld(b.forward) ? 1 : 0) - (anyHeld(b.back) ? 1 : 0),
        strafe: (anyHeld(b.right) ? 1 : 0) - (anyHeld(b.left) ? 1 : 0),
      };
    },
    consumeLookDelta(): LookDelta {
      const delta = { yawPx, pitchPx };
      yawPx = 0;
      pitchPx = 0;
      return delta;
    },
    consumeJump(): boolean {
      const queued = jumpQueued;
      jumpQueued = false;
      return queued;
    },
    jumpHeld(): boolean {
      // Lock-gated at READ time like moveAxes — movement intent never leaks
      // while the browser owns the pointer.
      return locked && getBindings().jump.some((c) => held.has(c));
    },
    descendHeld(): boolean {
      // Fly-mode descend: the bound descend key(s) held, tracked by CODE (not
      // raw `key`) so it flows through the SAME live-bindings seam as
      // movement/jump — lock-gated at read like the rest of movement intent.
      return locked && getBindings().descend.some((c) => held.has(c));
    },
    runHeld(): boolean {
      // Walking run: the bound run key(s) held, through the same live bindings, lock-gated at read.
      return locked && getBindings().run.some((c) => held.has(c));
    },
    dispose(): void {
      // Release BEFORE the pointerlockchange listener goes, so the browser's
      // state and ours agree at the end: `locked = false` below must not be
      // our flag alone while the browser still holds the pointer.
      releaseOurLock();
      canvas.removeEventListener('click', onClick);
      canvas.removeEventListener('keydown', onKeyDown);
      canvas.removeEventListener('keyup', onKeyUp);
      canvas.removeEventListener('blur', onBlur);
      doc.removeEventListener('mousemove', onMouseMove);
      doc.removeEventListener('pointerlockchange', onPointerLockChange);
      pageLifecycle?.removeEventListener('pagehide', onPageHide);
      held.clear();
      jumpQueued = false;
      pressedKeys.clear();
      yawPx = 0;
      pitchPx = 0;
      locked = false;
    },
  };
}
