/**
 * VEML primitive mesh builders.
 *
 * All 11 primitive types (documentModel.VEML_PRIMITIVE_TYPES) built from
 * DEEP MeshBuilder imports (never the @babylonjs/core barrel, which would
 * bloat the main bundle) at UNIT dimensions (~1 m bounds) so
 * scaletransform/sizetransform math is sane.
 *
 * GEOMETRY IS SHELL POLICY: exact tessellation is not an observable
 * contract — no conformance clause exists for vertex layouts; only
 * transform/bounds behavior conforms (see vemlTransform.ts). rectangularpyramid/prism/arch have no Babylon
 * builder and are hand-rolled VertexData (kept small; main-bundle code).
 *
 * `planemesh` lies in the XZ plane (floor-capable): the VEML corpus uses
 * planemesh floors with scale (x, 1, z) — e.g. the sample worlds — which
 * only makes sense for an XZ-lying quad. Babylon's CreatePlane is XY-facing;
 * CreateGround is the XZ quad (and is already in the main bundle via the
 * test scene).
 *
 * The `color` element maps to StandardMaterial diffuse (+ alpha) — material
 * class imported ONLY from src/engine/shaderImports.ts (the manifest
 * invariant). The material is entity-owned: the caller registers it for
 * disposal.
 */
import { CreateBox } from '@babylonjs/core/Meshes/Builders/boxBuilder';
import { CreateSphere } from '@babylonjs/core/Meshes/Builders/sphereBuilder';
import { CreateGround } from '@babylonjs/core/Meshes/Builders/groundBuilder';
import { Mesh } from '@babylonjs/core/Meshes/mesh';
import { VertexData } from '@babylonjs/core/Meshes/mesh.vertexData';
import { Color3 } from '@babylonjs/core/Maths/math.color';
import type { Scene } from '@babylonjs/core/scene';
import type { VemlPrimitiveType } from '../veml/documentModel';
import { StandardMaterial } from '../engine/shaderImports';
import { log } from '../logging/runtimeLog';

// ---------------------------------------------------------------------------
// VEML color → Color3 + alpha.
// ---------------------------------------------------------------------------

/**
 * Named colors accepted in VEML color strings. Values are the HTML color
 * constants.
 */
const NAMED_COLORS: Record<string, [number, number, number]> = {
  red: [1, 0, 0],
  green: [0, 0.5, 0],
  blue: [0, 0, 1],
  white: [1, 1, 1],
  black: [0, 0, 0],
  yellow: [1, 0.92, 0.016],
  cyan: [0, 1, 1],
  aqua: [0, 1, 1],
  magenta: [1, 0, 1],
  fuchsia: [1, 0, 1],
  gray: [0.5, 0.5, 0.5],
  grey: [0.5, 0.5, 0.5],
  silver: [0.75, 0.75, 0.75],
  orange: [1, 0.647, 0],
  brown: [0.647, 0.165, 0.165],
  maroon: [0.5, 0, 0],
  lime: [0, 1, 0],
  olive: [0.5, 0.5, 0],
  navy: [0, 0, 0.5],
  teal: [0, 0.5, 0.5],
  purple: [0.5, 0, 0.5],
  darkblue: [0, 0, 0.545],
  lightblue: [0.678, 0.847, 0.902],
};

const FALLBACK_GRAY: [number, number, number] = [0.5, 0.5, 0.5];

export interface ParsedVemlColor {
  color: Color3;
  alpha: number;
}

/**
 * Parse a VEML `color` value: `#rgb`, `#rgba`, `#rrggbb`, `#rrggbbaa`, or a
 * named color. Unknown/absent → gray with a console warning (never a
 * failure). No DOM/canvas involved — must run under node/NullEngine.
 */
export function parseVemlColor(value: string | undefined): ParsedVemlColor {
  if (value !== undefined) {
    const raw = value.trim();
    const named = NAMED_COLORS[raw.toLowerCase()];
    if (named) {
      return { color: new Color3(...named), alpha: 1 };
    }
    const hexMatch = /^#([0-9a-fA-F]{3,8})$/.exec(raw);
    if (hexMatch) {
      const hex = hexMatch[1] ?? '';
      if (hex.length === 3 || hex.length === 4) {
        const digit = (i: number): number => parseInt(hex.charAt(i) + hex.charAt(i), 16) / 255;
        return {
          color: new Color3(digit(0), digit(1), digit(2)),
          alpha: hex.length === 4 ? digit(3) : 1,
        };
      }
      if (hex.length === 6 || hex.length === 8) {
        const byte = (i: number): number => parseInt(hex.slice(i, i + 2), 16) / 255;
        return {
          color: new Color3(byte(0), byte(2), byte(4)),
          alpha: hex.length === 8 ? byte(6) : 1,
        };
      }
    }
    log.warn(`[webverse] unknown VEML color '${value}' — using gray`);
  }
  return { color: new Color3(...FALLBACK_GRAY), alpha: 1 };
}

/** Build the entity-owned StandardMaterial for a primitive's `color`. */
export function createPrimitiveMaterial(
  name: string,
  colorValue: string | undefined,
  scene: Scene,
): StandardMaterial {
  const { color, alpha } = parseVemlColor(colorValue);
  const material = new StandardMaterial(name, scene);
  material.diffuseColor = color;
  if (alpha < 1) material.alpha = alpha;
  return material;
}

// ---------------------------------------------------------------------------
// Hand-rolled VertexData shapes (no Babylon builder exists).
// Positions are unit-bounded; normals computed; winding chosen for Babylon's
// default left-handed front faces.
// ---------------------------------------------------------------------------

function meshFromVertexData(
  name: string,
  scene: Scene,
  positions: number[],
  indices: number[],
): Mesh {
  const mesh = new Mesh(name, scene);
  const normals: number[] = [];
  VertexData.ComputeNormals(positions, indices, normals);
  const vertexData = new VertexData();
  vertexData.positions = positions;
  vertexData.indices = indices;
  vertexData.normals = normals;
  vertexData.applyToMesh(mesh);
  return mesh;
}

/**
 * Lathe: revolve a (radius, y) profile around the Y axis with `segments`
 * radial steps. A profile point with radius ~0 becomes a single pole vertex
 * (cone apex, cap center); consecutive points connect with quads (or fans at
 * poles). One helper serves cylinder, cone, and capsule — hand-rolled
 * because Babylon's cylinderBuilder + capsuleBuilder measured ~5.9 KB
 * minified in the main bundle for these three fixed unit shapes (geometry
 * is shell policy, so the smaller hand-rolled version wins).
 */
function createLathe(
  name: string,
  scene: Scene,
  profile: Array<{ r: number; y: number }>,
  segments: number,
): Mesh {
  const positions: number[] = [];
  const indices: number[] = [];
  // ringStart[i] = first vertex index of ring i; poles store a single vertex.
  const ringStart: number[] = [];
  const isPole: boolean[] = [];
  for (const point of profile) {
    ringStart.push(positions.length / 3);
    const pole = point.r < 1e-6;
    isPole.push(pole);
    if (pole) {
      positions.push(0, point.y, 0);
    } else {
      for (let j = 0; j < segments; j++) {
        const a = (2 * Math.PI * j) / segments;
        positions.push(point.r * Math.cos(a), point.y, point.r * Math.sin(a));
      }
    }
  }
  for (let i = 0; i < profile.length - 1; i++) {
    const s0 = ringStart[i]!;
    const s1 = ringStart[i + 1]!;
    for (let j = 0; j < segments; j++) {
      const jn = (j + 1) % segments;
      if (isPole[i] && isPole[i + 1]) continue;
      if (isPole[i]) {
        indices.push(s0, s1 + j, s1 + jn);
      } else if (isPole[i + 1]) {
        indices.push(s0 + j, s1, s0 + jn);
      } else {
        indices.push(s0 + j, s1 + j, s1 + jn, s0 + j, s1 + jn, s0 + jn);
      }
    }
  }
  return meshFromVertexData(name, scene, positions, indices);
}

/** Capsule profile: bottom hemisphere arc, straight side, top arc. */
function capsuleProfile(radius: number, height: number, arcSteps: number): Array<{ r: number; y: number }> {
  const profile: Array<{ r: number; y: number }> = [];
  const cylHalf = height / 2 - radius;
  for (let i = 0; i <= arcSteps; i++) {
    const a = -Math.PI / 2 + (Math.PI / 2) * (i / arcSteps);
    profile.push({ r: radius * Math.cos(a), y: -cylHalf + radius * Math.sin(a) });
  }
  for (let i = 1; i <= arcSteps; i++) {
    const a = (Math.PI / 2) * (i / arcSteps);
    profile.push({ r: radius * Math.cos(a), y: cylHalf + radius * Math.sin(a) });
  }
  return profile;
}

/**
 * Torus: ring radius 0.375, tube radius 0.125 → bounds (1, 0.25, 1).
 * Hand-rolled for the same budget reason as the lathe shapes.
 */
function createTorusMesh(name: string, scene: Scene): Mesh {
  const R = 0.375;
  const r = 0.125;
  const ringSteps = 24;
  const tubeSteps = 12;
  const positions: number[] = [];
  const indices: number[] = [];
  for (let i = 0; i < ringSteps; i++) {
    const u = (2 * Math.PI * i) / ringSteps;
    for (let j = 0; j < tubeSteps; j++) {
      const v = (2 * Math.PI * j) / tubeSteps;
      const c = R + r * Math.cos(v);
      positions.push(c * Math.cos(u), r * Math.sin(v), c * Math.sin(u));
    }
  }
  for (let i = 0; i < ringSteps; i++) {
    const inext = (i + 1) % ringSteps;
    for (let j = 0; j < tubeSteps; j++) {
      const jnext = (j + 1) % tubeSteps;
      const a = i * tubeSteps + j;
      const b = inext * tubeSteps + j;
      const c = inext * tubeSteps + jnext;
      const d = i * tubeSteps + jnext;
      indices.push(a, b, c, a, c, d);
    }
  }
  return meshFromVertexData(name, scene, positions, indices);
}

/**
 * Regular tetrahedron on the unit cube's alternating corners (~unit bounds).
 * Hand-rolled: Babylon's CreatePolyhedron ships a 15-shape data table
 * (~7.9 KB minified, measured) to produce these four vertices — the single
 * largest dead weight of the builder set in the main bundle.
 */
function createTetrahedron(name: string, scene: Scene): Mesh {
  const s = 0.5;
  const positions = [
    s, s, s, //
    s, -s, -s, //
    -s, s, -s, //
    -s, -s, s,
  ];
  const indices = [
    0, 2, 1, //
    0, 1, 3, //
    0, 3, 2, //
    1, 2, 3,
  ];
  return meshFromVertexData(name, scene, positions, indices);
}

/** Square-based pyramid: base 1×1 at y=−0.5, apex at y=+0.5. */
function createRectangularPyramid(name: string, scene: Scene): Mesh {
  const h = 0.5;
  const positions = [
    // base corners
    -0.5, -h, -0.5, //
    0.5, -h, -0.5, //
    0.5, -h, 0.5, //
    -0.5, -h, 0.5, //
    // apex
    0, h, 0,
  ];
  const indices = [
    // base (facing down)
    0, 1, 2, 0, 2, 3,
    // sides
    0, 4, 1, 1, 4, 2, 2, 4, 3, 3, 4, 0,
  ];
  return meshFromVertexData(name, scene, positions, indices);
}

/**
 * Triangular prism ("tent"): 1×1×1 bounds — rectangular base at y=−0.5,
 * ridge along z at y=+0.5.
 */
function createPrism(name: string, scene: Scene): Mesh {
  const positions = [
    // front triangle (z = −0.5): 0 base-left, 1 base-right, 2 ridge
    -0.5, -0.5, -0.5, //
    0.5, -0.5, -0.5, //
    0, 0.5, -0.5, //
    // back triangle (z = +0.5): 3 base-left, 4 base-right, 5 ridge
    -0.5, -0.5, 0.5, //
    0.5, -0.5, 0.5, //
    0, 0.5, 0.5,
  ];
  const indices = [
    // front cap
    0, 2, 1,
    // back cap
    3, 4, 5,
    // base
    0, 1, 4, 0, 4, 3,
    // left slope
    0, 3, 5, 0, 5, 2,
    // right slope
    1, 2, 5, 1, 5, 4,
  ];
  return meshFromVertexData(name, scene, positions, indices);
}

/**
 * Arch: a 1×1 face (x∈[−0.5,0.5], y∈[−0.5,0.5]) with a semicircular cutout
 * (radius 0.35, centered at the bottom edge), extruded 0.25 in z. Front/back
 * caps triangulated as left leg + right leg + arc band; inner arc surface and
 * outer walls close the solid.
 */
function createArch(name: string, scene: Scene): Mesh {
  const r = 0.35;
  const depth = 0.25;
  const zF = -depth / 2;
  const zB = depth / 2;
  const yBottom = -0.5;
  const yTop = 0.5;
  const segments = 8;

  const positions: number[] = [];
  const indices: number[] = [];
  const addVertex = (x: number, y: number, z: number): number => {
    positions.push(x, y, z);
    return positions.length / 3 - 1;
  };

  // Arc points from left (θ=π) to right (θ=0), on the bottom edge.
  const arc: Array<{ x: number; y: number }> = [];
  for (let i = 0; i <= segments; i++) {
    const theta = Math.PI - (Math.PI * i) / segments;
    arc.push({ x: r * Math.cos(theta), y: yBottom + r * Math.sin(theta) });
  }

  // One cap (z fixed). `flip` reverses winding for the back cap.
  const buildCap = (z: number, flip: boolean): void => {
    const quad = (a: number, b: number, c: number, d: number): void => {
      if (flip) indices.push(a, c, b, a, d, c);
      else indices.push(a, b, c, a, c, d);
    };
    // Left leg: x ∈ [−0.5, −r], y ∈ [bottom, top].
    const l0 = addVertex(-0.5, yBottom, z);
    const l1 = addVertex(-r, yBottom, z);
    const l2 = addVertex(-r, yTop, z);
    const l3 = addVertex(-0.5, yTop, z);
    quad(l0, l1, l2, l3);
    // Right leg: x ∈ [r, 0.5].
    const r0 = addVertex(r, yBottom, z);
    const r1 = addVertex(0.5, yBottom, z);
    const r2 = addVertex(0.5, yTop, z);
    const r3 = addVertex(r, yTop, z);
    quad(r0, r1, r2, r3);
    // Arc band: each arc point pairs with a point on the top edge above it.
    for (let i = 0; i < arc.length - 1; i++) {
      const p0 = arc[i]!;
      const p1 = arc[i + 1]!;
      const a0 = addVertex(p0.x, p0.y, z);
      const a1 = addVertex(p1.x, p1.y, z);
      const t1 = addVertex(p1.x, yTop, z);
      const t0 = addVertex(p0.x, yTop, z);
      quad(a0, a1, t1, t0);
    }
  };
  buildCap(zF, false);
  buildCap(zB, true);

  // Walls: quads between front (z=zF) and back (z=zB) along a boundary edge.
  const wall = (
    x0: number,
    y0: number,
    x1: number,
    y1: number,
    flip: boolean,
  ): void => {
    const f0 = addVertex(x0, y0, zF);
    const f1 = addVertex(x1, y1, zF);
    const b1 = addVertex(x1, y1, zB);
    const b0 = addVertex(x0, y0, zB);
    if (flip) indices.push(f0, b1, f1, f0, b0, b1);
    else indices.push(f0, f1, b1, f0, b1, b0);
  };
  wall(-0.5, yBottom, -0.5, yTop, false); // outer left (x=−0.5)
  wall(0.5, yTop, 0.5, yBottom, false); // outer right (x=+0.5)
  wall(-0.5, yTop, 0.5, yTop, false); // top (y=+0.5)
  wall(-0.5, yBottom, -r, yBottom, true); // left-leg underside
  wall(r, yBottom, 0.5, yBottom, true); // right-leg underside
  for (let i = 0; i < arc.length - 1; i++) {
    // Inner arc surface (faces into the opening).
    const p0 = arc[i]!;
    const p1 = arc[i + 1]!;
    wall(p0.x, p0.y, p1.x, p1.y, true);
  }

  return meshFromVertexData(name, scene, positions, indices);
}

// ---------------------------------------------------------------------------
// The 11-type dispatch.
// ---------------------------------------------------------------------------

export function createPrimitiveMesh(
  type: VemlPrimitiveType,
  name: string,
  scene: Scene,
): Mesh {
  switch (type) {
    case 'cubemesh':
      return CreateBox(name, { size: 1 }, scene);
    case 'spheremesh':
      return CreateSphere(name, { diameter: 1, segments: 16 }, scene);
    case 'capsulemesh':
      return createLathe(name, scene, capsuleProfile(0.25, 1, 6), 16);
    case 'cylindermesh':
      // Closed unit cylinder: pole → bottom rim → top rim → pole gives caps.
      return createLathe(
        name,
        scene,
        [
          { r: 0, y: -0.5 },
          { r: 0.5, y: -0.5 },
          { r: 0.5, y: 0.5 },
          { r: 0, y: 0.5 },
        ],
        24,
      );
    case 'planemesh':
      // XZ-lying floor-capable quad (see header note).
      return CreateGround(name, { width: 1, height: 1 }, scene);
    case 'torusmesh':
      return createTorusMesh(name, scene);
    case 'conemesh':
      // Closed unit cone: base cap (pole → rim), slope (rim → apex pole).
      return createLathe(
        name,
        scene,
        [
          { r: 0, y: -0.5 },
          { r: 0.5, y: -0.5 },
          { r: 0, y: 0.5 },
        ],
        24,
      );
    case 'tetrahedronmesh':
      return createTetrahedron(name, scene);
    case 'rectangularpyramidmesh':
      return createRectangularPyramid(name, scene);
    case 'prismmesh':
      return createPrism(name, scene);
    case 'archmesh':
      return createArch(name, scene);
  }
}
