/**
 * WebXR subsystem — the MAIN-BUNDLE FACE.
 *
 *
 * Pure TypeScript types + the injectable loader seam — ZERO Babylon/XR
 * imports (guard: `tests/unit/xrImportHygiene.test.ts`; this module lands in
 * the main bundle, so a WebXR import here would drag `@babylonjs/core/XR/*`
 * into first paint for every visitor). The active Babylon Scene crosses this face
 * as an OPAQUE `unknown` — the core face never names a Babylon type, exactly
 * like `sandboxTypes.ts`; the code-split `xrChunk.ts` casts it to `Scene`.
 *
 * Naming: neutral/veml — `xr`/`immersiveSession`, never a
 * `webverse`-branded construct an author or another runtime implementer would
 * touch. The user-facing button LABEL ("Enter VR") is fine; the private DOM
 * `data-webverse-xr-*` attributes reuse the swappable-implementation allowance
 * (the same as `feedbackSurface`'s `data-webverse-feedback-*`).
 *
 * Scope: get INTO and OUT OF an `immersive-vr` session cleanly — same scene,
 * same position, flat-screen never degraded — plus the seams the chunk needs
 * for VR locomotion (turn/joystick) and VR pointers (portals/teleport).
 */

import type { VrPointerAffordanceLike } from './vrPointer';

/** A plain feet/eye position crossing the core↔chunk seam (no Babylon type). */
export interface XrVec3 {
  x: number;
  y: number;
  z: number;
}

/**
 * A per-frame snapshot of the XR controllers' relevant inputs,
 * read from the raw WebXR gamepads in the chunk and crossed as PLAIN
 * DATA to (a) the VR locomotion tick and (b) the `onXrInput` dispatcher route.
 * `leftStick` = motion, `rightStick` = turn (the shell's convention). Buttons are
 * pressed-state booleans (trigger = select / button 0, grip = squeeze / button 1).
 */
export interface XrInputFrame {
  leftStick: { x: number; y: number };
  rightStick: { x: number; y: number };
  trigger: boolean;
  grip: boolean;
}

/**
 * Options handed to the code-split chunk's `createImmersiveSession`. `scene`
 * is OPAQUE here (the core face stays Babylon-free); the chunk casts it to a
 * Babylon `Scene`. The callbacks are the position-continuity seam:
 * `getFeetPosition` is read at entry to re-base the XR camera
 * at the visitor's CURRENT feet (not the eye — `local-floor` supplies the
 * head-above-floor offset); `onEntered`/`onExited` let `main.ts` suspend/resume
 * the desktop first-person controller and teleport its feet to the exit pose.
 */
export interface XrSessionOptions {
  /** The active Babylon Scene — opaque to the core face; the chunk casts it. */
  scene: unknown;
  /** Read at enter time: the visitor's current FEET position (the controller's feet). */
  getFeetPosition(): XrVec3;
  /** Fired once the immersive-vr session is live (main.ts suspends desktop tick). */
  onEntered(): void;
  /**
   * Fired on exit with the FEET position: horizontal (x,z) from the XR camera's
   * world position at exit (respects room-scale walking), vertical (y) pinned to
   * the ENTRY feet (the controller re-grounds via its probe next tick — no
   * eye-height double-count). main.ts teleports the controller there so
   * flat-screen resumes seamlessly where the headset was (no camera snap).
   */
  onExited(exitFeet: XrVec3): void;
  /**
   * The active world's parsed `controlflags`, read at enter to
   * resolve the VR locomotion config (`turn-locomotion`/`joystick-motion`,
   * comfort defaults in `resolveVrLocomotionConfig`) AND the per-hand VR pointer
   * modes (`left-vr-pointer`/`right-vr-pointer`, defaults in
   * `resolveVrPointerConfig`). `undefined` when the world declares no
   * `<controlflags>`.
   */
  getControlFlags?():
    | {
        turnLocomotion?: string;
        joystickMotion?: boolean;
        leftVrPointer?: string;
        rightVrPointer?: string;
      }
    | undefined;
  /**
   * The firstPersonController reuse seam: apply a
   * WORLD-space horizontal move (already speed·dt-scaled) THROUGH the SAME
   * `firstPersonController.moveFeetWithCollisions` grounding/collision path as
   * desktop, returning the collision-resolved FEET. VR translation feeds the rig
   * from this (identical collision/gravity/ledge/relocate rules, reusing
   * the single desktop physics path, never a second one).
   */
  stepLocomotion?(worldDx: number, worldDz: number, dtS: number): XrVec3;
  /**
   * Route the frame's XR controller inputs through the runtime's
   * EXISTING `inputevent` dispatcher names (thumbstick→`move`/`endmove`,
   * trigger→`left`/`endleft`, grip→`right`/`endright`) via the SAME
   * host-pump→tick-drain path (NO second dispatch path).
   */
  onXrInput?(frame: XrInputFrame): void;
  /**
   * The active world's portal candidates (`registry.portals()`
   * — link-carrying entities with pickable meshes), read each presenting frame
   * for the `ui`-pointer `pickPortal` raycast. OPAQUE (`unknown`) to keep the
   * core face Babylon-free; the chunk casts it to `readonly PortalEntry[]`.
   */
  getPortalCandidates?(): unknown;
  /**
   * The active world's WALKABLE-GROUND meshes ONLY
   * (`registry.walkableMeshes()` — the SAME set desktop grounding uses;
   * sky/backdrop/photodome/UI are excluded by construction), read each
   * presenting frame for the `teleport`-pointer ground raycast. OPAQUE
   * (`unknown`); the chunk casts it to `readonly AbstractMesh[]`.
   */
  getWalkableMeshes?(): unknown;
  /**
   * Navigate to a portal's resolved href via the SAME
   * `NavigationController.navigate` + the shared browser history stack the
   * desktop portals use (native Back returns). Plain-data seam (a string href).
   */
  navigateHref?(href: string): void;
  /** The entity a controller ray hits, by id, from the desktop click's candidate set; null for a miss. */
  pickEntityAlongRay?(ray: unknown): string | null;
  /** Run that entity's on-click, as a desktop click does. */
  clickEntity?(id: string): void;
  /**
   * Teleport the desktop controller/rig FEET to a ground point
   * (`firstPersonController.teleportFeet`). The chunk re-bases the XR camera
   * at the new feet afterward (the locomotion rig↔feetPosition feedback),
   * so the headset jumps to the target AND flat-screen exit continuity stays
   * correct. Plain-data seam (a world-space point).
   */
  teleportFeetTo?(x: number, y: number, z: number): void;
  /**
   * Build the IN-WORLD pointer affordance (highlight + label +
   * reticle + laser) for the active scene. Provided by `main.ts` from the
   * MAIN-bundle `createVrPointerAffordance` (which reuses the existing
   * `shaderImports` StandardMaterial/DynamicTexture — so it folds into main
   * WITHOUT reshaping first-paint chunking; a dynamic-chunk StandardMaterial
   * consumer perturbs the Rolldown shader split by ~7 KB). `scene` is OPAQUE here (the chunk passes the real
   * Babylon Scene). The pointer LOGIC (`vrPointer.ts`) stays code-split.
   */
  createPointerAffordance?(scene: unknown): VrPointerAffordanceLike;
}

/**
 * The controller the chunk produces — the ONLY XR handle `main.ts` holds. A
 * handle-as-behavior seam: no live Babylon XR object crosses back into the
 * main bundle.
 */
/**
 * Where the visitor's head is while presenting: the XR camera's world
 * position, and its yaw about +Y (0 = facing +Z, the shell's convention).
 * What the others in the room are shown of a VR visitor.
 */
export interface XrHeadPose {
  position: XrVec3;
  yaw: number;
}

export interface ImmersiveSessionController {
  /** True while an immersive-vr session is presenting (render loop suspends desktop tick). */
  isPresenting(): boolean;
  /**
   * The per-frame VR locomotion tick (turn + joystick translation +
   * XR-input routing). The render loop calls this while presenting IN PLACE OF
   * the suspended desktop `controller.tick`. No-op when not presenting.
   */
  tick(dtMs: number): void;
  /** Request + start the immersive-vr session (chunk already loaded by the caller). */
  enter(): Promise<void>;
  /** End the immersive-vr session and return to flat-screen. */
  exit(): Promise<void>;
  /** Subscribe to presenting-state transitions (button label flip). Returns an unsubscribe. */
  onStateChange(cb: (presenting: boolean) => void): () => void;
  /** The head's pose while presenting; null otherwise. */
  headPose(): XrHeadPose | null;
  /**
   * Teardown: end the session if presenting, then dispose the Babylon
   * WebXR helper (camera, session manager, managed output canvas, reference
   * space). Idempotent. Called on world-swap (exit-on-nav) and app teardown.
   */
  dispose(): void;
}

/** The shape of the code-split chunk (`xrChunk.ts`), reached via the loader seam. */
export interface XrSessionModule {
  createImmersiveSession(options: XrSessionOptions): Promise<ImmersiveSessionController>;
}

/**
 * The worldSession/main.ts seam — a `() => import('./xrChunk')` by default;
 * unit tests inject a fake module so no real Babylon WebXR runs in node.
 */
export type XrChunkLoader = () => Promise<XrSessionModule>;

/** The default loader: dynamic-import the chunk (the ONLY place it's referenced). */
export const defaultXrChunkLoader: XrChunkLoader = () => import('./xrChunk');
