/**
 * Whether a brought avatar is small enough to wear. The client-hints profile
 * lets a shell refuse one larger than a size it sets; this shell's is 8 MB.
 * The server is asked for the size first (HEAD). When it does not say, the
 * bytes are counted as they arrive and the download stops as soon as the
 * limit is passed. A check that cannot be made at all answers yes: the
 * avatar's own load then decides, and falls back if it fails.
 */

/** The largest brought avatar this shell wears. */
export const AVATAR_MAX_BYTES = 8 * 1024 * 1024;

/** A check for `url`: true when it fits under `maxBytes`, or when its size cannot be learned. */
export function avatarFitsUnder(maxBytes: number, fetchImpl: typeof fetch = fetch) {
  return async (url: string): Promise<boolean> => {
    try {
      const head = await fetchImpl(url, { method: 'HEAD' });
      const length = Number(head.headers.get('content-length'));
      if (head.ok && head.headers.has('content-length') && Number.isFinite(length)) return length <= maxBytes;
    } catch {
      // No answer to HEAD: count the bytes instead.
    }
    try {
      const res = await fetchImpl(url);
      if (!res.ok || !res.body) return true;
      const reader = res.body.getReader();
      let total = 0;
      for (;;) {
        const { done, value } = await reader.read();
        if (done) return true;
        total += value.byteLength;
        if (total > maxBytes) {
          await reader.cancel();
          return false;
        }
      }
    } catch {
      return true;
    }
  };
}
