/** VEML 4.0 §4.4: the quality levels, ascending. */
export const VEML_QUALITY_LEVELS = ['low', 'medium', 'high', 'ultra'] as const;
export type VemlQualityLevel = (typeof VEML_QUALITY_LEVELS)[number];

/** One alternative file of a model, and the highest quality level it is meant for. */
export interface VemlMeshAlternative {
  quality: VemlQualityLevel;
  resource: VemlResourceRef;
}

/**
 * A light entity.
 *
 * The XSD `light` type is an EMPTY extension of `entity`, which on its own
 * means a default directional white intensity-1 light. These fields are a
 * FORWARD EXTENSION matching what the VEML Blender plugin emits: child
 * elements light-type/color/intensity/range/spot-angle/cast-shadows, plus
 * temperature. When absent, the light falls back to that default
 * (directional, white, intensity 1). `scale` is ignored per the XSD note.
 */
export interface VemlLightEntity extends VemlEntityBase {
  type: 'light';
  /** point | directional | spot (absent → directional). */
  lightType?: string;
  /** VEML color string (absent → white). */
  color?: string;
  /** Absent → 1. */
  intensity?: number;
  /** Point/spot only; directional ignores it. */
  range?: number;
  /** Spot only, in DEGREES (converted to radians at build). */
  spotAngle?: number;
  /** A directional or spot light casts shadows onto the world's meshes; point lights cannot. */
  castShadows: boolean;
  /** Colour temperature in kelvin, composed with `color` (6500 leaves it as authored). */
  temperature?: number;
}

