// ---------------------------------------------------------------------------
// Metadata (XSD veml/metadata, lines 1205–1216).
// ---------------------------------------------------------------------------

export interface VemlInputEvent {
  input?: string;
  event?: string;
}

/** VEML 4.0 §8.2 `<input-binding input="…" action="…"/>`, verbatim. */
export interface VemlInputBinding {
  input: string;
  action: string;
}

/** 11 optional control-flag children (XSD `controlflags`, lines 228–242). */
export interface VemlControlFlags {
  leftVrPointer?: string;
  rightVrPointer?: string;
  leftVrPoker?: boolean;
  rightVrPoker?: boolean;
  leftHandInteraction?: boolean;
  rightHandInteraction?: boolean;
  turnLocomotion?: string;
  joystickMotion?: boolean;
  leftGrabMove?: boolean;
  rightGrabMove?: boolean;
  twoHandedGrabMove?: boolean;
}

export interface VemlSynchronizationService {
  type?: string;
  address?: string;
  id?: string;
  session?: string;
  /** VEML 4.0 §7 `ice-servers`: STUN/TURN URLs for the peer-authority mode, verbatim. */
  iceServers?: string;
}

export interface VemlMetadata {
  /** May be absent on the wire (A.7 leniency) despite XSD minOccurs=1. */
  title?: string;
  capabilities: string[];
  /**
   * VEML 4.0 §10 profile declarations — absent on the 3.x path.
   * The shell implements `lighting` (asset-layer KHR_lights_punctual honored,
   * default rig stands down — specs/veml/profiles/lighting.md); any other
   * declared profile degrades with a warning per §2/§10.
   */
  profiles?: string[];
  /** Ordered; each resolved against the world document URL. */
  scripts: VemlScriptRef[];
  inputEvents: VemlInputEvent[];
  /**
   * VEML 4.0 §8.2 `input-binding` declarations, verbatim and in order —
   * absent on the 3.x path. Resolved against the per-input defaults by the
   * session (`src/actions/inputBindings.ts`).
   */
  inputBindings?: VemlInputBinding[];
  controlFlags?: VemlControlFlags;
  synchronizationServices: VemlSynchronizationService[];
  /**
   * VEML 4.0 §6.2: every subsidiary reference (include or prototype) in
   * document order, resolved. Only the first sixteen are eligible for
   * composition, and the count is over all of them. Absent on the 3.x path.
   */
  subsidiaryRefs?: string[];
  /**
   * VEML 4.0 §6.4 prototypes declared by `href`, first declaration per name,
   * resolved against the document. Fetched by the session lazily — only a
   * name some `instance` uses — and only after entry. Inline prototypes are
   * expanded at parse time and are not listed. Absent on the 3.x path.
   */
  prototypes?: Array<{ name: string; url: string; integrity?: string }>;
  /**
   * VEML 4.0 §6.3 `manifest`: the JSON map from logical names to addresses
   * that this document's `manifest:` references resolve through. Fetched by
   * the session, once, only if a reference uses it. Absent on the 3.x path.
   */
  manifest?: { raw: string; resolved: string };
}

// ---------------------------------------------------------------------------
// Environment (XSD veml/environment, lines 1217–1226).
// ---------------------------------------------------------------------------

export interface VemlLiteFog {
  /** XSD attribute defaults: fog-enabled false, color "gray", density 0.5. */
  fogEnabled: boolean;
  color: string;
  density: number;
}

/**
 * Lite procedural sky — the XSD's ~57 defaulted attributes as a camelCase
 * bag. Values are string | number | boolean per each attribute's XSD type;
 * defaults from XSD lines 72–130 are pre-applied by the parser, so the sky
 * renderer never re-defaults.
 */
export interface VemlLiteProceduralSky {
  [key: string]: string | number | boolean | undefined;
  sunEntityTag?: string;
}

/**
 * Prototype of the `environment` profile's image-based-lighting
 * declaration. The `src` image supplies reflections and ambient light without
 * being drawn as the visible sky (a DCC viewport at World Opacity 0). The
 * OPTIONAL attributes carry the world's AUTHORED look as data: none of these
 * may be shell constants, and a
 * declaring world without them renders with neutral defaults (intensity 1,
 * diffuse 1, specular 1, no glazing coating, punctual lights kept).
 *
 * POSTURE — the §5.2 locomotion contract, verbatim: HINTS, never commands.
 * A shell SHOULD honor them and MAY clamp or REINTERPRET them as its
 * rendering evolves; invalid values are ignored, never fatal (§2).
 *
 * ATTRIBUTE TRIAGE (Principles 4/6 — a FROZEN set until the profile is
 * specified; add NOTHING here before then):
 * - WORLD SEMANTICS (defensible in any engine): `punctualLights`
 *   ("the environment is the sole light source"), `intensity` (exposure-like
 *   dominance of the environment).
 * - RENDERING HINTS (meaningful but engine-shaped): `diffuse`/`specular`
 *   encode a two-term irradiance/radiance split; `glazingF0` is physically
 *   definable (coated-glazing reflectance) but was tuned, not measured.
 * - SHELL-ERA COMPENSATION (candidate to NOT survive into the spec):
 *   `glazingBoost` — a fudge multiplier for this engine's missing
 *   transmission+coating; an independent implementation has no defensible
 *   mapping for it. A shell with real transmission SHOULD reinterpret or
 *   ignore it rather than double-apply.
 */
export interface VemlEnvironmentMap extends VemlResourceRef {
  /** scene-level environment intensity (default 1). */
  intensity?: number;
  /** Diffuse irradiance-fill strength (default 1). */
  diffuse?: number;
  /** Specular-only scale on the environment cube (default 1). */
  specular?: number;
  /** Extra environment term on declared glazing (default 1 = none). */
  glazingBoost?: number;
  /** Coated-glass reflectance floor for glazing (default 0 = authored F0). */
  glazingF0?: number;
  /**
   * 'exclude' = this world's authored look treats the environment as the ONLY
   * light source (a Material-Preview-referenced export) and its asset-carried
   * punctual lights must not render. Absent/'keep' = lights render normally —
   * the `lighting` profile's "world's declared lights are authoritative"
   * default. VEML-declared `light` entities are NEVER excluded.
   */
  punctualLights?: 'keep' | 'exclude';
}

export type VemlBackground =
  | {
      kind: 'color';
      color: string;
      /**
       * Prototype `environment` profile — an equirect image used as the ENVIRONMENT
       * (image-based lighting: reflections + ambient) WITHOUT being drawn as
       * the visible sky. Set only when a world declares
       * `<profile>environment</profile>`. Matches a DCC viewport whose World
       * Opacity is 0 (a plain backdrop while glass and metal reflect the
       * studio HDRI).
       */
      environmentMap?: VemlEnvironmentMap;
    }
  | { kind: 'panorama'; panorama: VemlResourceRef }
  | { kind: 'lite-procedural-sky'; sky: VemlLiteProceduralSky };

/**
 * VEML 4.0 §5.2 locomotion hints, read AHEAD of the 4.0 parser retarget:
 * hints, never commands — the controller SHOULD honor and MAY clamp them.
 * Only attributes in the valid form (finite, ≥ 0) land here; an invalid
 * value warns at parse and is treated as absent (§2 tolerance).
 */
export interface VemlLocomotion {
  /** m/s², positive magnitude acting downward. */
  gravity?: number;
  /** Meters — the apex a jump reaches above the feet. */
  jumpHeight?: number;
}

/**
 * VEML 4.0 §5.1 navigation — author preference, never command. `modes`
 * gates which locomotion modes a world ADVERTISES (e.g. whether the fly
 * toggle is offered); an empty array means no `modes` attribute was
 * declared — the shell treats that the SAME as no `<navigation>` element at
 * all (unrestricted). `speed` multiplies the walk (1.4 m/s) /
 * fly (5 m/s) baselines; absent = 1 (the XSD default).
 */
export interface VemlNavigation {
  modes: string[];
  speed?: number;
}

export interface VemlEnvironment {
  /** May be absent on the wire (A.7 leniency) despite XSD minOccurs=1. */
  background?: VemlBackground;
  liteFog?: VemlLiteFog;
  /** VEML 3.1 — parsed only; spawn RESOLUTION happens at scene build. */
  spawn?: VemlSpawn;
  /** VEML 4.0 §5.1 — present only when the document declares <navigation>. */
  navigation?: VemlNavigation;
  /** VEML 4.0 §5.2 — present only when the document declares <locomotion>. */
  locomotion?: VemlLocomotion;
  /**
   * The `client-hints` profile (profiles/client-hints.md): the world's
   * hints, validated, by their script names (`people.labels`, …). Present only
   * when the profile is declared and a `hints:hints` is carried.
   */
  clientHints?: Record<string, string>;
  /**
   * The `water` profile (profiles/water.md): the bodies a visitor can see
   * and enter, and the blockers that carve them. Present only when the
   * profile is declared and a body or blocker is carried, or when a 3.x
   * `water`/`waterblocker` entity mapped onto it at build.
   */
  water?: VemlWater;
  /**
   * The `planet` profile (profiles/planet.md): present only when the profile
   * is declared and a valid `planet:planet` is carried. The world is then a
   * planet, and its frame the planet's.
   */
  planet?: VemlPlanet;
  entities: VemlEntity[];
}

/** A colour with its components in 0..1, as the water profile's §4.5 colours resolve. */
export interface VemlWaterColor {
  r: number;
  g: number;
  b: number;
  a: number;
}

/**
 * `water:body`: a horizontal surface filling the top face of the box its
 * transform describes. `position.y` is the surface; the water fills
 * `extent.y` metres below it. Not an entity: nothing is parented to it and
 * no script sees it.
 */
export interface VemlWaterBody {
  position: VemlVec3;
  /** The box's extent in metres (the transform's scale). */
  extent: VemlVec3;
  color: VemlWaterColor;
  deepColor: VemlWaterColor;
  /** Metres of depth at which the colour has become `deepColor`; 0 is opaque. */
  clarity: number;
  /** 0..1: how much the surface moves. */
  waves: number;
}

/** `water:blocker`: a box in which water does not apply, in the world frame, rotation honoured. */
export interface VemlWaterBlocker {
  position: VemlVec3;
  rotation: VemlQuaternion;
  extent: VemlVec3;
}

export interface VemlWater {
  bodies: VemlWaterBody[];
  blockers: VemlWaterBlocker[];
}

/** A planet world (profiles/planet.md, `planet:planet`, `planet:entry`, `planet:site`). */
export interface VemlPlanet {
  /** The planet description. */
  src: VemlResourceRef;
  /** Metres, at altitude 0. */
  radius: number;
  /** Metres above altitude 0 within which the planet holds a visitor. */
  reach: number;
  /** lat, lon: the arrival of last resort. */
  spawn: [number, number];
  /**
   * The planet's day, each as declared and valid, absent otherwise (the
   * defaults are the day's, scene/planet/sun.ts): seconds a turn under the
   * sun takes (0 holds it still; absent, the planet declares no day), the
   * hour at longitude 0 at the epoch, the latitude the sun stands over at
   * noon, and the seconds from one high tide to the next.
   */
  dayLength?: number;
  time?: number;
  sunLatitude?: number;
  tidePeriod?: number;
  entries: VemlPlanetEntry[];
  sites: VemlPlanetSite[];
}

/** A site: an included world placed on the surface by geographic position. */
export interface VemlPlanetSite {
  href: VemlResourceRef;
  /** lat, lon, and optionally alt. */
  at: number[];
  /** Degrees clockwise from north. */
  heading: number;
  /** Metres: the site's declared bounds, for loading and culling. */
  radius: number;
  integrity?: string;
}

/** A named arrival on a planet's surface. */
export interface VemlPlanetEntry {
  id: string;
  /** lat, lon: the visitor's feet arrive on the ground here. */
  at: [number, number];
  /** heading (clockwise from north), pitch (above the horizon), in degrees. */
  look: [number, number];
}

// ---------------------------------------------------------------------------
// Document root.
// ---------------------------------------------------------------------------

export interface VemlDocument {
  /** What the wire declared: '3.0' | '3.1' | 'none' (clauses A.2/A.3). */
  declaredVersion: VemlDeclaredVersion;
  metadata: VemlMetadata;
  environment: VemlEnvironment;
}
