/**
 * Browser stand-in for `@xmldom/xmldom`, to keep the main bundle in budget.
 *
 * `@fivesqd/veml-parse` imports xmldom — correct in Node (the conformance
 * suite has no platform DOM), but in the browser it shipped a whole XML
 * parser the platform already provides (~44 KB gzip over the 350 KB main
 * bundle budget). Both Vite builds alias `@xmldom/xmldom` to this module,
 * which wraps the NATIVE DOMParser while reproducing the one xmldom
 * behavior veml-parse depends on: with `onError: onErrorStopParsing`,
 * malformed XML THROWS (the native parser instead returns a document
 * containing a `parsererror` element).
 *
 * TypeScript still typechecks veml-parse against the real xmldom types —
 * this substitution is bundle-time only, so the runtime surface here must
 * stay call-compatible with the subset veml-parse uses (constructor
 * options + parseFromString, and `DOMImplementation.createDocument` for
 * prototype expansion, which builds an element tree rather than parsing
 * text).
 */

/** Marker matching xmldom's export; the shim always stops on error. */
export const onErrorStopParsing = 'onErrorStopParsing';

export class DOMParser {
  // Options accepted for signature compatibility; error behavior is fixed.
  constructor(_options?: unknown) {}

  parseFromString(source: string, mimeType: string): Document {
    const doc = new globalThis.DOMParser().parseFromString(
      source,
      mimeType as DOMParserSupportedType,
    );
    // Native parsers signal failure in-band: Firefox replaces the root with
    // a parsererror document; Chromium nests a <parsererror> element. Either
    // way the element is present — convert to xmldom's throw.
    const errors = doc.getElementsByTagName('parsererror');
    if (errors.length > 0) {
      throw new Error(errors[0]?.textContent?.trim() || 'XML parse error');
    }
    return doc;
  }
}

/**
 * The platform's implementation object, behind xmldom's class shape. Only
 * `createDocument` is used: expansion (§6.4) creates elements and sets
 * attributes on them through the DOM, and the native one is the same API.
 */
export class DOMImplementation {
  createDocument(namespaceURI: string | null, qualifiedName: string, doctype: DocumentType | null = null): Document {
    return globalThis.document.implementation.createDocument(namespaceURI, qualifiedName, doctype);
  }
}
