/**
 * World-owned environment application.
 *
 * Lighting and environment come from the WORLD, never from imported glbs.
 * This dispatches `environment/background` into a live Babylon scene:
 *  - color → `scene.clearColor` (parsed via vemlColorValue) + a neutral IBL
 *    (createNeutralEnvironmentTexture) so PBR materials aren't black.
 *  - panorama → the CODE-SPLIT PhotoDome chunk (equirect visible sky) +
 *    skybox-derived IBL; a color-only world NEVER fetches that chunk, keeping
 *    it off the load fast path.
 *  - lite-procedural-sky → the CODE-SPLIT procedural sky dome + a neutral IBL.
 *  - absent → a neutral fallback (neutral clear + neutral IBL).
 * Fog and the default lighting profile are applied alongside the background.
 *
 * Returns an EnvironmentHandle the world session owns and disposes on unload
 * (BEFORE scene.dispose, so a reused scene returns to baseline — the panorama
 * churn guard). The environment is NOT an EntityRegistry entity, so its
 * disposal is explicit here (the dome/textures must return the scene to
 * baseline under repeated load/unload).
 *
 * `Color4` is a Maths class (not a material) — imported directly, not via the
 * shader manifest.
 */
import { Color3, Color4 } from '@babylonjs/core/Maths/math.color';
import { Vector3 } from '@babylonjs/core/Maths/math.vector';
import { HemisphericLight } from '@babylonjs/core/Lights/hemisphericLight';
import { Scene } from '@babylonjs/core/scene';
import type { VemlBackground, VemlLiteFog } from '../../veml/documentModel';
import type { EntityRegistry } from '../entityRegistry';
import { parseVemlColorValue } from './vemlColorValue';
import {
  createNeutralEnvironmentTexture,
  type NeutralEnvironmentHandle,
} from './neutralEnvironment';
import type { PanoramaDomeModule } from './photoDomeChunk';
import type { EquirectCubeModule } from './equirectCubeChunk';
import type { ProceduralSkyModule } from './skyChunk';
import type { RoomReflectionProbeHandle, RoomReflectionProbeModule } from './reflectionProbeChunk';
import { resolveSkyConfig } from './skyConfig';
import { sunDirectionOf } from '../../veml/parse40';
import { applyLiteFog } from './liteFog';
import { createDefaultLightingProfile, type DefaultLightingHandle } from './defaultLighting';
import { log } from '../../logging/runtimeLog';

/** The neutral clear color used behind a panorama and for the no-op/deferred
 * cases. */
const NEUTRAL_CLEAR = new Color4(0.05, 0.06, 0.09, 1);

/**
 * Asset-light count at which the irradiance fill is likely slot-starved
 * (Babylon's default per-material light cap is 4; measured on the reference
 * device: with 10 asset lights the fill never bound at ANY intensity). A
 * WARNING threshold, not rendering behavior.
 */
const STARVED_DIFFUSE_LIGHT_THRESHOLD = 4;

// NO tuned environment constants live here, deliberately: the shell is generic — it renders ANY world, so an
// environment-mapped world's look (intensity, diffuse, specular, glazing
// treatment, punctual-light policy) is carried by the WORLD's own
// `<environment-map>` attributes (documentModel.VemlEnvironmentMap) with
// neutral defaults, and the irradiance fill is tinted from the LOADED
// image's hemisphere means (EquirectCubeResult), never from constants.

export interface EnvironmentHandle {
  dispose(): void;
}

export interface ApplyEnvironmentOptions {
  /** 'webgpu' gates the WGSL background shader load inside the panorama chunk. */
  engineKind?: string;
  /** Code-split panorama chunk loader seam (dynamic import by default;
   * unit tests inject a fake so PhotoDome/texture decode never runs headless). */
  panoramaChunkLoader?: () => Promise<PanoramaDomeModule>;
  /**
   * Neutral IBL factory seam. Defaults to the real `RawCubeTexture`-based
   * neutral env; the unit tier injects a fake because Babylon `NullEngine`
   * cannot create a raw cube texture (the GL texture-type lookup is a WebGL-
   * only path — the e2e drives the REAL neutral env in a browser), mirroring
   * the gltfChunk/audio/panorama headless seams.
   */
  neutralEnvironmentFactory?: (scene: Scene) => NeutralEnvironmentHandle;
  /** Code-split procedural-sky chunk loader seam (unit tests inject
   * a fake so ShaderMaterial/GLSL never compiles headless). */
  skyChunkLoader?: () => Promise<ProceduralSkyModule>;
  /** `effects/lite-fog`, applied as exponential scene fog
   * orthogonally to the background branch (absent/disabled → no fog). */
  liteFog?: VemlLiteFog;
  /** Code-split equirect→cube loader seam (unit tests
   * inject a fake so no canvas/image decode runs headless). */
  equirectCubeLoader?: () => Promise<EquirectCubeModule>;
  /** Code-split room-reflection-probe chunk loader seam (unit
   * tests inject a fake/spy so the real ReflectionProbe/RTT never runs
   * headless, and a no-lights world can assert it is never even fetched). */
  roomReflectionProbeLoader?: () => Promise<RoomReflectionProbeModule>;
}

/** The fog observability (no pixel reads). */
export interface FogEnvironmentInfo {
  /** True when exponential fog is active (Scene.FOGMODE_EXP). */
  enabled: boolean;
  /** 'exp' (f = exp(-density·distance)) or 'none'. */
  mode: 'none' | 'exp';
  color: { r: number; g: number; b: number };
  density: number;
}

/** The lite-procedural-sky observability (no pixel reads). */
export interface SkyEnvironmentInfo {
  /** The `light` entity tag the sun binds to (absent → default sun direction). */
  sunEntityTag?: string;
  /** True once `bindSunAfterEntities` resolved the tag to a light entity. */
  sunBound: boolean;
  /** The sky-space direction toward the sun (updated live while a sun is bound). */
  sunDirection: { x: number; y: number; z: number };
  /** The ShaderMaterial's effect compiled — the GLSL-compile guard (live). */
  ready: boolean;
  dayNightCycleEnabled: boolean;
}

/** A plain-JSON description of what was applied (worldState observability). */
export interface EnvironmentInfo {
  kind: 'color' | 'panorama' | 'neutral' | 'lite-procedural-sky';
  clearColor: { r: number; g: number; b: number; a: number };
  hasEnvironmentTexture: boolean;
  panorama: boolean;
  /** Set only for the lite-procedural-sky path. */
  sky?: SkyEnvironmentInfo;
  /** Exponential fog state (mode 'none' when no fog). */
  fog: FogEnvironmentInfo;
  /**
   * True once the deferred default lighting profile (hemispheric +
   * directional key) was injected (color/neutral background + zero declared
   * `light` entities). Only meaningful after buildWorld; false otherwise.
   */
  defaultLightingProfileApplied: boolean;
}

const defaultPanoramaChunkLoader = (): Promise<PanoramaDomeModule> =>
  import('./photoDomeChunk').then((m) => ({ createPanoramaDome: m.createPanoramaDome }));

const defaultEquirectCubeLoader = (): Promise<EquirectCubeModule> =>
  import('./equirectCubeChunk').then((m) => ({ createEquirectCubeTexture: m.createEquirectCubeTexture }));

const defaultSkyChunkLoader = (): Promise<ProceduralSkyModule> =>
  import('./skyChunk').then((m) => ({ createProceduralSky: m.createProceduralSky }));

const defaultRoomReflectionProbeLoader = (): Promise<RoomReflectionProbeModule> =>
  import('./reflectionProbeChunk').then((m) => ({
    createRoomReflectionProbe: m.createRoomReflectionProbe,
  }));

/** The applied environment: the disposer + a plain-JSON snapshot of what ran. */
export interface AppliedEnvironment extends EnvironmentHandle {
  info: EnvironmentInfo;
  /**
   * Deferred sun binding (lite-procedural-sky only). Called by the
   * session AFTER buildWorld so the sun `light` entity exists (the sun binds
   * on load completion, once every entity is built). Absent/unresolved tag →
   * warn + keep the default sun direction (never throws).
   */
  bindSunAfterEntities?(registry: EntityRegistry, scene: Scene): void;
  /**
   * Deferred default-lighting decision (EVERY background kind).
   * Called by the session AFTER buildWorld so declared `light` entities can be
   * counted: zero lights → inject the hemispheric + directional key profile
   * (on top of the branch's own environment lighting — panorama IBL / procedural
   * sun + neutral IBL — so StandardMaterial primitives are not left black);
   * ≥1 light → the world's lights are authoritative, no injection.
   * `assetLightCount`: lights DELIVERED by glb assets under the VEML 4.0
   * `lighting` profile count the same as declared `light` entities — a
   * profile world whose assets carry lights stands the default rig down.
   */
  applyDefaultLightingAfterEntities?(
    registry: EntityRegistry,
    scene: Scene,
    assetLightCount?: number,
  ): void;
  /** Refresh live info fields (sky.ready, sun direction) on read. */
  refreshInfo?(): void;
  /**
   * The RUNTIME sky-swap seam (`Environment.SetSkyTexture`/
   * `SetSolidColorSky`). Re-invokes the SAME `dispatchBackground` a VEML
   * `<background>` uses, disposes the PREVIOUS background layer, adopts the new
   * one, and mutates `info`'s background fields IN PLACE (so the live
   * `worldState.background` reference reflects the swap). Fog + the default
   * lighting profile are PRESERVED (a sky swap is orthogonal to them). Never
   * throws. The two thin wrappers build the synthetic `VemlBackground`.
   */
  setBackground?(background: VemlBackground): Promise<void>;
  /** `Environment.SetSolidColorSky(color)` → the color background. */
  setSolidColorSky?(color: { r: number; g: number; b: number; a: number }): void;
  /** `Environment.SetSkyTexture(url)` → the panorama background. */
  setSkyTexture?(resolvedUrl: string): void;
}

/**
 * Copy ONLY the background fields (kind/clearColor/environment-
 * texture/panorama/sky) from a freshly-swapped layer's info into the STABLE
 * `info` object `worldState.background` references. Fog + `defaultLighting-
 * ProfileApplied` are DELIBERATELY preserved (orthogonal to a sky swap).
 */
function copyBackgroundInfo(target: EnvironmentInfo, source: EnvironmentInfo): void {
  target.kind = source.kind;
  target.clearColor = source.clearColor;
  target.hasEnvironmentTexture = source.hasEnvironmentTexture;
  target.panorama = source.panorama;
  if (source.sky) target.sky = source.sky;
  else delete target.sky;
}

/** Finite-guard a numeric color/URL component (a forged NaN → the default). */
function finite(n: number | undefined, dflt: number): number {
  return typeof n === 'number' && Number.isFinite(n) ? n : dflt;
}

function fogSnapshot(scene: Scene): FogEnvironmentInfo {
  const enabled = scene.fogMode === Scene.FOGMODE_EXP;
  const c = scene.fogColor;
  return {
    enabled,
    mode: enabled ? 'exp' : 'none',
    color: { r: c.r, g: c.g, b: c.b },
    density: scene.fogDensity,
  };
}

function snapshot(
  scene: Scene,
  kind: EnvironmentInfo['kind'],
  panorama: boolean,
  sky?: SkyEnvironmentInfo,
): EnvironmentInfo {
  const c = scene.clearColor;
  return {
    kind,
    clearColor: { r: c.r, g: c.g, b: c.b, a: c.a },
    hasEnvironmentTexture: scene.environmentTexture != null,
    panorama,
    ...(sky ? { sky } : {}),
    fog: fogSnapshot(scene),
    defaultLightingProfileApplied: false,
  };
}

/**
 * Apply the world's declared background to `scene`. Async: the panorama path
 * awaits the code-split chunk. Never throws for a malformed color (the parser
 * returns a gray fallback). Fog is applied orthogonally in the
 * public `applyEnvironment` wrapper below; this only dispatches the background.
 */
async function dispatchBackground(
  background: VemlBackground | undefined,
  scene: Scene,
  options: ApplyEnvironmentOptions = {},
  hooks?: {
    /** The declared environment image provably never arrived — the
     * caller may degrade (re-inject the default rig it stood down). */
    environmentMapFailed?: () => void;
  },
): Promise<AppliedEnvironment> {
  const neutralFactory = options.neutralEnvironmentFactory ?? createNeutralEnvironmentTexture;

  // ----- panorama (code-split) -----
  if (background?.kind === 'panorama') {
    const loader = options.panoramaChunkLoader ?? defaultPanoramaChunkLoader;
    const chunk = await loader();
    // A neutral clear sits behind the enclosing dome (the dome covers it).
    scene.clearColor = NEUTRAL_CLEAR.clone();
    const dome = await chunk.createPanoramaDome(
      background.panorama.resolved,
      scene,
      options.engineKind,
    );
    dome.setPickableFalse();
    // The dome could not install a sky-derived IBL on this device (float
    // linear filtering unsupported — see createPanoramaDome). Fall back to the
    // neutral IBL so PBR materials stay lit and reflective.
    const fallbackIbl = dome.iblApplied ? undefined : neutralFactory(scene);
    return {
      // A panorama always lights the world: by the neutral environment above,
      // or by its own picture, which arrives behind the world and is not in
      // the scene yet when this is read.
      info: { ...snapshot(scene, 'panorama', true), hasEnvironmentTexture: true },
      dispose(): void {
        fallbackIbl?.dispose();
        dome.dispose();
      },
    };
  }

  // ----- solid color (optionally with an IBL-only environment map) -----
  if (background?.kind === 'color') {
    const { r, g, b } = parseVemlColorValue(background.color);
    // Alpha forced to 1: a sky is opaque (an alpha < 1 clear color would show
    // the page through the canvas). HDR components (> 1) are PRESERVED here and
    // clamp only at LDR display. The parser's malformed-value fallback alpha
    // (0.5) is likewise opaquified for the clear color.
    scene.clearColor = new Color4(r, g, b, 1);
    // An IBL-ONLY environment map: the color stays the visible
    // backdrop while this image supplies reflections and ambient, matching a
    // DCC viewport at World Opacity 0. The neutral IBL is installed FIRST so
    // the world is never unlit while the image loads, and is replaced (and
    // released) if the cube builds; a failure keeps the neutral IBL (and the
    // caller's environmentMapFailed hook may re-inject the default rig).
    const neutral = neutralFactory(scene);
    let environmentMap: { dispose(): void } | undefined;
    let environmentFill: { dispose(): void } | undefined;
    // The PER-LAYER teardown guard (the same hazard as the environment-wide
    // guard in applyEnvironment, one level down): the load chain below is
    // fire-and-forget, and a runtime
    // background swap disposes THIS LAYER while the scene lives on. Without
    // this flag a late-resolving load would clobber the NEW layer's
    // environment, apply the OLD declaration's intensity, leak a fill light
    // nothing will ever dispose — and a late FAILURE would fire the shared
    // hook and poison the new background's rig decision.
    let layerDisposed = false;
    // Scene-GLOBAL state this layer mutates must return with it: the
    // install below sets scene.environmentIntensity from the declaration;
    // without a restore, the NEXT background inherits the multiplier (a
    // swap from an intensity-3 world would render the following neutral IBL
    // 3x hot).
    let prevSceneIntensity: number | undefined;
    const envMap = background.environmentMap;
    if (envMap) {
      const cubeLoader = options.equirectCubeLoader ?? defaultEquirectCubeLoader;
      const mapUrl = envMap.resolved;
      void cubeLoader()
        .then((chunk) => chunk.createEquirectCubeTexture(mapUrl, scene))
        .then((result) => {
          if (result === null) {
            log.warn(`[webverse] environment map could not be read: ${mapUrl}`);
            if (!layerDisposed) hooks?.environmentMapFailed?.();
            return;
          }
          if (scene.isDisposed || layerDisposed) {
            result.cube.dispose();
            return;
          }
          environmentMap = result.cube;
          scene.environmentTexture = result.cube;
          // Success is LOGGED, not silent: "no warning" must never be the only
          // evidence the environment installed.
          log.info(
            `[webverse] environment map installed: ${mapUrl} ` +
              `intensity=${envMap.intensity ?? 1} specular=${envMap.specular ?? 1} ` +
              `diffuse=${envMap.diffuse ?? 1} sky=[${result.skyAverage.join(',')}] ` +
              `ground=[${result.groundAverage.join(',')}]`,
          );
          // The world's DECLARED look, neutral when undeclared (no shell
          // constants):
          // scene.environmentIntensity scales every PBR material's
          // environment term; cube.level additionally scales SPECULAR
          // sampling only (both measured on the reference device).
          prevSceneIntensity = scene.environmentIntensity;
          scene.environmentIntensity = envMap.intensity ?? 1;
          result.cube.level = envMap.specular ?? 1;
          // Diffuse irradiance emulation, tinted from the LOADED image's own
          // hemisphere means. A hemispheric fill instead of spherical
          // harmonics: the SH path is inert on the reference WebGPU device
          // (a 20x coefficient scale changed zero pixels), and attaching SH
          // AND a fill would double-light devices where SH works — one
          // deterministic mechanism everywhere (see equirectCubeChunk).
          // Specular BLACK: sheen is the environment cube's job.
          const fill = new HemisphericLight(
            'environmentIrradianceFill',
            new Vector3(0, 1, 0),
            scene,
          );
          fill.diffuse = new Color3(...result.skyAverage);
          fill.groundColor = new Color3(...result.groundAverage);
          fill.specular = new Color3(0, 0, 0);
          fill.intensity = envMap.diffuse ?? 1;
          environmentFill = fill;
        })
        .catch((err: unknown) => {
          log.warn(`[webverse] environment map failed: ${String(err)}`);
          // A dead layer's failure is not the live layer's news.
          if (!layerDisposed) hooks?.environmentMapFailed?.();
        });
    }
    return {
      info: snapshot(scene, 'color', false),
      dispose(): void {
        layerDisposed = true; // seal BEFORE freeing — an in-flight load sees it
        if (prevSceneIntensity !== undefined && !scene.isDisposed) {
          scene.environmentIntensity = prevSceneIntensity;
        }
        environmentFill?.dispose();
        if (environmentMap !== undefined && scene.environmentTexture === environmentMap) {
          scene.environmentTexture = null;
        }
        environmentMap?.dispose();
        neutral.dispose();
      },
    };
  }

  // ----- lite-procedural-sky (code-split) -----
  if (background?.kind === 'lite-procedural-sky') {
    const loader = options.skyChunkLoader ?? defaultSkyChunkLoader;
    const chunk = await loader();
    const config = resolveSkyConfig(background.sky); // out-of-range → default + warn
    // A neutral clear sits behind the enclosing dome (the dome covers it).
    scene.clearColor = NEUTRAL_CLEAR.clone();
    // engineKind selects WGSL (WebGPU, native — no CDN transpiler) vs GLSL (WebGL2).
    const sky = chunk.createProceduralSky(config, scene, options.engineKind);
    sky.setPickableFalse();
    // The sky is a visible background; the PBR IBL is the in-core neutral cube
    // (a sky-derived IBL would be a refinement).
    const neutral = neutralFactory(scene);

    // The `sky` profile states the sun directly (elevation/azimuth)
    // because VEML 4.0 has no light vocabulary for a tag to name. When the
    // document said where the sun is, point it there NOW rather than waiting
    // for a `bindSunAfterEntities` that has no entity to bind to.
    const declared =
      background.sky['sunElevation'] !== undefined || background.sky['sunAzimuth'] !== undefined
        ? sunDirectionOf(background.sky)
        : undefined;
    if (declared) sky.setSunDirection(new Vector3(declared.x, declared.y, declared.z));

    // The default sun direction the dome starts with (upper sky) — surfaced so
    // the defaults-only / unbound path is observable before any bind.
    const info = snapshot(scene, 'lite-procedural-sky', false, {
      sunEntityTag: config.sunEntityTag,
      sunBound: declared !== undefined,
      sunDirection: declared ?? { x: 0.3, y: 0.6, z: 0.3 },
      ready: false,
      dayNightCycleEnabled: config.dayNightCycleEnabled,
    });

    return {
      info,
      bindSunAfterEntities(registry: EntityRegistry, boundScene: Scene): void {
        const tag = config.sunEntityTag;
        const warn = (why: string): void =>
          log.warn(`[webverse] lite-procedural-sky: ${why} — using default sun direction`);
        if (tag === undefined) {
          warn('no sun-entity-tag');
          return;
        }
        const entry = registry.findByTag(tag);
        if (entry === undefined) {
          warn(`sun-entity-tag '${tag}' not found`);
          return;
        }
        if (entry.type !== 'light') {
          warn(`sun-entity-tag '${tag}' is not a light entity`);
          return;
        }
        // Read the light's WORLD-space forward direction — parent-aware. A
        // DirectionalLight's local `.direction` ignores any parent-node
        // rotation, so bind from the transformed direction: computeWorldMatrix
        // refreshes the parent chain, computeTransformedInformation() populates
        // `transformedDirection`, and getShadowDirection() returns it (or the
        // local direction when unparented — already world-space).
        const light = boundScene.getLightByName(`light:${tag}`) as
          | {
              direction?: Vector3;
              computeWorldMatrix?: (force: boolean) => unknown;
              computeTransformedInformation?: () => boolean;
              getShadowDirection?: (faceIndex?: number) => Vector3;
            }
          | null;
        if (light === null || light === undefined) {
          warn(`sun light '${tag}' not found`);
          return;
        }
        light.computeWorldMatrix?.(true);
        light.computeTransformedInformation?.();
        const worldDir =
          typeof light.getShadowDirection === 'function'
            ? light.getShadowDirection()
            : light.direction;
        if (worldDir === undefined) {
          warn(`sun light '${tag}' has no direction`);
          return;
        }
        // Sky-space sun direction = OPPOSITE the light's travel direction (a
        // sun light shines DOWN-forward; the sun sits UP-back in the sky). Bound
        // ONCE at load: there is no runtime sun movement (the day/night cycle
        // and scripted light motion are not implemented). A live per-frame
        // follow would be honest only if it re-read the world-space direction
        // each frame; it belongs with a dynamic-sun feature, not shipped inert.
        const d = worldDir.scale(-1);
        sky.setSunDirection(d);
        info.sky!.sunBound = true;
        info.sky!.sunDirection = { x: d.x, y: d.y, z: d.z };
      },
      refreshInfo(): void {
        info.sky!.ready = sky.isReady();
      },
      dispose(): void {
        sky.dispose();
        neutral.dispose();
      },
    };
  }

  // ----- neutral fallback (absent background) -----
  scene.clearColor = NEUTRAL_CLEAR.clone();
  const neutral = neutralFactory(scene);
  return {
    info: snapshot(scene, 'neutral', false),
    dispose(): void {
      neutral.dispose();
    },
  };
}

/**
 * Apply the world's declared environment to `scene`: the background (color /
 * panorama / lite-procedural-sky / neutral) PLUS exponential `lite-fog`, and
 * attach the deferred default-lighting decision for EVERY background kind
 * ("no declared lights → still looks good" is background-agnostic). Fog is orthogonal to the background — it applies for every branch —
 * and is reset on dispose so a REUSED scene returns to baseline (churn). Never
 * throws for a malformed color/fog (the parser returns a gray fallback).
 */
export async function applyEnvironment(
  background: VemlBackground | undefined,
  scene: Scene,
  options: ApplyEnvironmentOptions = {},
): Promise<AppliedEnvironment> {
  // Fog first (orthogonal to the background), so each branch's snapshot() reads
  // the fog state into info.fog.
  const fog = applyLiteFog(options.liteFog, scene);

  // The CURRENT background layer (color/panorama/sky/neutral),
  // held in a MUTABLE ref so `Environment.SetSkyTexture`/`SetSolidColorSky` can
  // swap it live: a swap builds the next layer via the SAME dispatchBackground,
  // adopts it, and disposes the previous one. `applied.dispose` always disposes
  // the CURRENT layer (not the initial one).
  const envMapHooks = {
    environmentMapFailed: (): void => {
      envMapFailed = true;
      evaluateDefaultRig();
    },
  };
  let backgroundLayer = await dispatchBackground(background, scene, options, envMapHooks);

  // The STABLE info object worldState.background references (worldSession).
  // Runtime swaps MUTATE it IN PLACE (never re-assign) via copyBackgroundInfo.
  const info: EnvironmentInfo = backgroundLayer.info;

  // The default lighting profile is decided AFTER buildWorld (the
  // light count is only known then), so it is injected via a deferred method
  // and stored here for disposal with the environment.
  let defaultLighting: DefaultLightingHandle | undefined;
  // The one-shot room reflection probe, fired from the same
  // after-entities hook (fire-and-forget code-split chunk; see
  // loadRoomReflectionProbe below).
  let roomReflectionProbe: RoomReflectionProbeHandle | undefined;
  // The world's DECLARED environment-map look. Everything below keys off
  // this DATA, never shell constants — absent attributes mean neutral
  // defaults, and a declaring world without them behaves like any other.
  // MUTABLE: a runtime background swap (Environment.SetSkyTexture/
  // SetSolidColorSky) replaces it with the NEXT background's declaration and
  // the policy below is restored + re-applied, so a swap never strands
  // coated glazing or disabled lights.
  let envMap = background?.kind === 'color' ? background.environmentMap : undefined;
  // Glazing materials given the DECLARED boost — restored on dispose.
  const boostedGlazing: Array<{
    m: { environmentIntensity?: number; metallic?: number | null };
    prevMetallic: number | null | undefined;
    prevEnvironmentIntensity: number | undefined;
  }> = [];
  // A material the world marked as glazing: the exporter writes the glTF
  // extras key on a window pane's material, and the loader hands extras over
  // as `metadata.gltf.extras`. The mark is the whole decision; shape, alpha
  // and roughness are the author's.
  interface GlazingMaterial {
    name: string;
    getClassName(): string;
    metallic?: number | null;
    environmentIntensity?: number;
    metadata?: { gltf?: { extras?: Record<string, unknown> } } | null;
  }
  const isMarkedGlazing = (m: GlazingMaterial): boolean =>
    m.getClassName() === 'PBRMaterial' && !!m.metadata?.gltf?.extras?.['veml_glazing'];
  // Punctual lights stood down for HDRI-only lighting — re-enabled on dispose.
  const disabledPunctual: Array<{ setEnabled(v: boolean): void }> = [];
  // One-shot guard for the after-entities hook.
  let hookRan = false;
  // Set when the declared environment image provably failed to load —
  // the stand-down justification ("the environment terms light the world")
  // is gone, so the rig decision re-evaluates.
  let envMapFailed = false;
  // The hook's registry/light context, kept so a runtime background swap can
  // re-evaluate the environment-map policy with the new declaration.
  // NOTE: assetLightCount is the LOAD-TIME count — a script that creates
  // lights later is not re-counted at swap time (documented staleness).
  let policyContext: { registry: EntityRegistry; assetLightCount: number } | undefined;

  /**
   * The default-rig decision, re-evaluated whenever its inputs move
   * (the after-entities hook, a runtime background swap, an environment-map
   * load failure): zero world lights AND no LIVE environment declaration →
   * rig; otherwise no rig. Idempotent both ways.
   */
  const evaluateDefaultRig = (): void => {
    if (disposed || policyContext === undefined) return;
    const { registry, assetLightCount } = policyContext;
    const lightCount =
      registry.all().filter((e) => e.type === 'light').length + assetLightCount;
    const wantRig = lightCount === 0 && (envMap === undefined || envMapFailed);
    if (wantRig && defaultLighting === undefined) {
      defaultLighting = createDefaultLightingProfile(scene);
      applied.info.defaultLightingProfileApplied = true;
    } else if (!wantRig && defaultLighting !== undefined) {
      defaultLighting.dispose();
      defaultLighting = undefined;
      applied.info.defaultLightingProfileApplied = false;
    } else {
      applied.info.defaultLightingProfileApplied = defaultLighting !== undefined;
    }
  };

  /** Undo the CURRENT environment-map policy (glazing + punctual lights). */
  const restoreEnvMapPolicy = (): void => {
    for (const { m, prevMetallic, prevEnvironmentIntensity } of boostedGlazing) {
      m.environmentIntensity = prevEnvironmentIntensity;
      m.metallic = prevMetallic;
    }
    boostedGlazing.length = 0;
    for (const l of disabledPunctual) l.setEnabled(true);
    disabledPunctual.length = 0;
  };

  // The teardown guard. `Environment.SetSkyTexture` is FIRE-AND-
  // FORGET (an async panorama fetch): a swap can still be in flight when the
  // world navigates away and `dispose()` runs (worldSession.teardownWorld
  // disposes the environment BEFORE scene.dispose). Without this flag a
  // late-resolving swap would build a PhotoDome/textures on the DISPOSED scene —
  // orphan GPU resources scene.dispose() already ran past (a cross-world/post-
  // teardown leak + use-after-free). Once disposed, setBackground is inert.
  let disposed = false;

  const applied: AppliedEnvironment = {
    info,
    // Disposers-first order (mirrors the registry): the injected lights, then
    // the CURRENT background layer's resources (neutral IBL / dome), then reset
    // fog — all before worldSession.teardownWorld calls scene.dispose().
    dispose(): void {
      disposed = true; // seal BEFORE freeing, so an in-flight swap sees it on resume
      roomReflectionProbe?.dispose();
      restoreEnvMapPolicy();
      defaultLighting?.dispose();
      backgroundLayer.dispose();
      fog.reset();
    },
    // The lite-procedural-sky sun bind is fired ONCE after
    // buildWorld, so it operates on the INITIAL layer (delegated as-is).
    bindSunAfterEntities: backgroundLayer.bindSunAfterEntities?.bind(backgroundLayer),
    refreshInfo(): void {
      // The CURRENT layer's refreshInfo mutates ITS OWN info object; after a
      // runtime swap that is a DIFFERENT object than the stable `info`, so sync
      // the background fields back (fog/default-lighting preserved).
      backgroundLayer.refreshInfo?.();
      if (backgroundLayer.info !== info) copyBackgroundInfo(info, backgroundLayer.info);
    },
    async setBackground(next: VemlBackground): Promise<void> {
      if (disposed) return; // the world was torn down — do not touch a dead scene
      const nextLayer = await dispatchBackground(next, scene, options, envMapHooks);
      // The await may have straddled a teardown (a fire-and-forget panorama
      // resolving after navigation). Adopting now would leak the just-built dome
      // into the disposed scene — dispose it instead and stay inert.
      if (disposed) {
        nextLayer.dispose();
        return;
      }
      const previous = backgroundLayer;
      backgroundLayer = nextLayer; // adopt BEFORE disposing (env-texture guard)
      copyBackgroundInfo(info, nextLayer.info);
      previous.dispose();
      // The environment-map POLICY (glazing coating, punctual-light
      // exclusion) belongs to the background that declared it. Restore the
      // old declaration's effects and apply the new one's — the default-
      // material remap is every-world viewer policy and stays.
      envMap = next.kind === 'color' ? next.environmentMap : undefined;
      envMapFailed = false; // the NEW layer's own failure will re-set it
      if (policyContext !== undefined) {
        restoreEnvMapPolicy();
        applyEnvMapPolicy(policyContext.registry, policyContext.assetLightCount);
        evaluateDefaultRig(); // the rig decision follows the swap
      }
    },
    setSolidColorSky(color): void {
      const colorStr = `color(${finite(color.r, 0.5)} ${finite(color.g, 0.5)} ${finite(
        color.b,
        0.5,
      )} ${finite(color.a, 1)})`;
      void this.setBackground?.({ kind: 'color', color: colorStr });
    },
    setSkyTexture(resolvedUrl): void {
      void this.setBackground?.({
        kind: 'panorama',
        panorama: { raw: resolvedUrl, resolved: resolvedUrl },
      });
    },
  };

  // The default-profile decision applies to EVERY background kind: the SAME
  // count-gated rig serves color, neutral, panorama and lite-procedural-sky.
  // A StandardMaterial primitive receives NO
  // diffuse light from an IBL/skybox — so a zero-`light` world under a panorama
  // or procedural sky would otherwise render its primitives BLACK. Injecting the hemispheric + key rig
  // ON TOP OF the branch's own environment lighting (panorama IBL / procedural
  // sun disc + neutral IBL) keeps such worlds visible without washing the sky
  // (the sky dome is unlit — infiniteDistance/emissive, unaffected by lights).
  // ≥1 declared light → NO injection (the world's lights are authoritative)
  // for every kind, so a world that DOES declare a sun/light is untouched.
  applied.applyDefaultLightingAfterEntities = (
    registry: EntityRegistry,
    _scene: Scene,
    assetLightCount = 0,
  ): void => {
    // Idempotence guard — a second invocation would re-capture the
    // ALREADY-remapped default-material values as "previous" and corrupt the
    // dispose-time restore. The hook is one-shot per world by contract; a
    // repeat call is a no-op.
    if (hookRan) return;
    hookRan = true;
    // Asset-delivered lights (VEML 4.0 lighting profile) count alongside
    // declared `light` entities — either source of world light stands the
    // default rig down; zero of both injects it (never black). A declared
    // ENVIRONMENT MAP is likewise world-declared lighting: the fill +
    // environment terms light the world, and the default rig stacking on top
    // would double-light — same stand-down rule, third source. The decision
    // lives in evaluateDefaultRig and RE-EVALUATES on background swaps and
    // on environment-map load failure.
    policyContext = { registry, assetLightCount };
    evaluateDefaultRig();
    // NO authoring-tool remaps: a material-less primitive renders with the
    // glTF SPEC default — the shell never rewrites it. The fidelity fix
    // lives at EXPORT: the ingest .blend path assigns explicit materials, so
    // the FILE carries the authored look into every viewer. Authoring-tool
    // knowledge does not belong in the generic shell.
    // The declared environment-map policy (context stored above).
    applyEnvMapPolicy(registry, assetLightCount);
    // The lighting profile's DELIVERED punctual lights (with no declared
    // environment map: a declared map reflects the ENVIRONMENT, not the
    // room — see the note at the bottom of applyEnvMapPolicy) get a one-shot
    // room reflection probe on their glass/mirror/chrome materials.
    // Fire-and-forget + code-split: a world with zero asset lights never
    // even fetches the chunk.
    if (assetLightCount > 0 && envMap === undefined) {
      loadRoomReflectionProbe();
    }
  };

  /**
   * Dynamically import the reflection-probe chunk and attach it
   * to every renderable mesh currently in the scene. Guards `disposed` on
   * resume: a fire-and-forget load can straddle a teardown/
   * navigate-away, and attaching a probe to a disposed scene would leak GPU
   * resources nothing will ever release.
   */
  function loadRoomReflectionProbe(): void {
    const loader = options.roomReflectionProbeLoader ?? defaultRoomReflectionProbeLoader;
    void loader()
      .then((chunk) => {
        if (disposed) return;
        roomReflectionProbe = chunk.createRoomReflectionProbe(scene, scene.meshes);
      })
      .catch((err: unknown) => {
        log.warn(`[webverse] room reflection probe failed: ${String(err)}`);
      });
  }

  /**
   * Apply the CURRENT `envMap` declaration's policy: punctual-light
   * exclusion + glazing coating. Runs from the after-entities hook and again
   * after a runtime background swap (with `restoreEnvMapPolicy` first).
   */
  function applyEnvMapPolicy(registry: EntityRegistry, assetLightCount: number): void {
    // Punctual lights disable ONLY when the WORLD declares
    // `punctual-lights="exclude"` — an authored fact ("my baked look treats
    // the environment as the only light source"; ingest emits it for a
    // Material-Preview-referenced .blend, where scene lights are not
    // rendered). Without the declaration the `lighting` profile's rule holds
    // untouched: the world's declared lights are authoritative. VEML-declared
    // `light` ENTITIES are NEVER excluded — spared by REGISTRY lookup (the
    // `light:<tag>` names lightEntity.ts mints), never by a bare string
    // match a glb light could collide with.
    if (envMap?.punctualLights === 'exclude' && assetLightCount > 0) {
      const spared = new Set(
        registry
          .all()
          .filter((e) => e.type === 'light')
          .map((e) => `light:${e.tag}`),
      );
      for (const light of scene.lights) {
        const cls = light.getClassName();
        if ((cls === 'PointLight' || cls === 'SpotLight') && !spared.has(light.name)) {
          light.setEnabled(false);
          disabledPunctual.push(light);
        }
      }
    }
    // A measured limitation, surfaced honestly: with the asset's punctual
    // lights KEPT, they hold the per-material shader light slots and the
    // irradiance fill added after them never reaches the shader at ANY
    // intensity (verified up to 50,000 on the reference device) — the
    // world's declared `diffuse` term is silently absent. Warn instead of
    // silently under-lighting; `punctual-lights="exclude"` frees the slots.
    if (
      envMap !== undefined &&
      envMap.punctualLights !== 'exclude' &&
      assetLightCount >= STARVED_DIFFUSE_LIGHT_THRESHOLD
    ) {
      log.warn(
        `[webverse] environment-map diffuse term may be starved: ${assetLightCount} asset ` +
          'punctual lights hold the shader light slots and the irradiance fill added after ' +
          'them may never bind. Declare punctual-lights="exclude" on <environment-map> if ' +
          'the environment is meant to be the dominant light.',
      );
    }
    // Glazing coating — ONLY under the world's DECLARED glazing attributes
    // (neutral defaults do nothing). MUST run after buildWorld: the
    // environment-map install callback fires while the glb is still
    // streaming, so a material loop there sees none of the world's materials
    // (the same ordering trap bindSunAfterEntities exists for).
    const glazingBoost = envMap?.glazingBoost ?? 1;
    const glazingF0 = envMap?.glazingF0 ?? 0;
    if (envMap !== undefined && (glazingBoost !== 1 || glazingF0 > 0)) {
      // The world says which glass is a window: the exporter marks a pane's
      // material (and splits a material shared with a table top, so the slab
      // keeps the original). The client coats the marked materials and
      // nothing else: no shape rule, no alpha or roughness rule, no clone.
      // A glb from before the mark carries none, and renders its authored
      // dielectric glass under these attributes (see docs/ARCHITECTURE.md).
      for (const mt of scene.materials as unknown as GlazingMaterial[]) {
        if (!isMarkedGlazing(mt)) continue;
        const prevMetallic = mt.metallic;
        const prevEnvironmentIntensity = mt.environmentIntensity;
        mt.environmentIntensity = (mt.environmentIntensity ?? 1) * glazingBoost;
        // Coated-glass reflectance (measured): a dielectric's 4% F0 is
        // swamped by the 75% transmission — the "reflection" the pane
        // showed was exterior geometry THROUGH the glass, untouched by any
        // cube change. Metallic F0 makes the environment genuinely
        // compete, tinted by the near-white base color, with transmission
        // still owned by alpha.
        mt.metallic = Math.max(mt.metallic ?? 0, glazingF0);
        boostedGlazing.push({ m: mt, prevMetallic, prevEnvironmentIntensity });
      }
    }
    // No room reflection probe on this path (a declared environment map):
    // the probe attaches to every material under 0.3 roughness, turning
    // doors and trim into room mirrors, when the authored expectation for a
    // DECLARED environment map is the ENVIRONMENT in the reflections, not
    // the room. The probe is scoped to the OTHER case: a lighting-profile
    // world's delivered lights with NO declared environment map (see
    // loadRoomReflectionProbe's call site) — there the room is the only
    // environment there is, so it becomes the reflection.
  }

  return applied;
}
