/**
 * The controls hint. Shell chrome: on a world's first visit in this
 * browser it says how to look, move, jump and fly, then gets out of the way.
 *
 * Chrome belongs to the user, not the world (VEML §5.1; the Messages panel's
 * rule): the page wires it — `main.ts` and the self-boot loader, which is what
 * a world's own address serves — and a world cannot draw or suppress it. An
 * embedder turns it off with the `hints.controls` setting.
 *
 * Every word is a setting (`hints.words`, defaults in shellSettings) and every
 * key is read from the LIVE bindings through `keyLabel`, so a rebound key
 * reads as rebound and this module spells no key code (the key-binding
 * guard checks that no shell module hard-codes one).
 *
 * Input: it never eats an event. The first click, tap or key puts it away and
 * still reaches the world and its scripts; the `help` binding brings it back
 * and is the one key it answers to. Put away once is remembered in the
 * browser (`CONTROLS_HINT_SEEN_KEY`, namespaced like the other shell keys);
 * with no storage (a private window) it simply shows each visit.
 *
 * DOM only, no Babylon imports, main bundle. `data-webverse-hint-*` are this
 * runtime's private identifiers, like the feedback surface's.
 */
import { keyLabel, type KeyBindings } from '../input/bindings';
import { DEFAULT_HINT_WORDS, type ShellSettings } from '../settings/shellSettings';

export { keyLabel };

export const CONTROLS_HINT_ID = 'webverse-controls-hint';
export const CONTROLS_HINT_SEEN_KEY = 'webverse:hints:controls-seen:v1';

/** Storage the hint may use; `window.localStorage` in a page. */
type HintStorage = Pick<Storage, 'getItem' | 'setItem'>;

export interface ControlsHintOptions {
  settings: () => ShellSettings;
  storage: HintStorage | undefined;
  /** Touch-primary device: touch wording, no keys. */
  touch: boolean;
}

export interface ControlsHint {
  /** A world was entered: show it if the mode says so. */
  onWorldEntered(): void;
  /** The help binding: show or hide, whatever the seen mark says. */
  toggle(): void;
  /** Put it away and remember that it was seen. */
  dismiss(): void;
  dispose(): void;
}

const first = (codes: readonly string[]): string => {
  const code = codes[0];
  return code === undefined ? '?' : keyLabel(code);
};
const all = (codes: readonly string[]): string =>
  [...new Set(codes.map(keyLabel))].join(' / ') || '?';

/** The hint's lines, from the live bindings and the configured words. */
export function controlsHintLines(
  bindings: KeyBindings,
  touch: boolean,
  words = DEFAULT_HINT_WORDS,
): string[] {
  const fields: Record<string, string> = {
    move: [first(bindings.forward), first(bindings.left), first(bindings.back), first(bindings.right)].join(' '),
    jump: all(bindings.jump),
    run: all(bindings.run),
    descend: all(bindings.descend),
    fly: all(bindings.flyToggle),
    help: all(bindings.help),
  };
  const template = touch ? words.touch : words.desktop;
  return template.map((line) => line.replace(/\{(\w+)\}/g, (m, k: string) => fields[k] ?? m));
}

export function createControlsHint(doc: Document, options: ControlsHintOptions): ControlsHint {
  const el = doc.createElement('div');
  el.id = CONTROLS_HINT_ID;
  el.setAttribute('role', 'note');
  el.setAttribute('data-webverse-hint-state', 'hidden');
  Object.assign(el.style, {
    position: 'fixed',
    left: '50%',
    top: '16px',
    transform: 'translateX(-50%)',
    maxWidth: 'min(92vw, 520px)',
    padding: '10px 16px',
    borderRadius: '10px',
    background: 'var(--webverse-hint-bg, rgba(16, 16, 20, 0.78))',
    color: 'var(--webverse-hint-fg, #eef1f6)',
    font: '14px/1.55 system-ui, sans-serif',
    textAlign: 'center',
    pointerEvents: 'none',
    zIndex: '15',
    display: 'none',
  } satisfies Partial<CSSStyleDeclaration>);
  (doc.body ?? doc.documentElement).appendChild(el);

  const mode = () => options.settings().hints.controls;
  const isShown = () => el.getAttribute('data-webverse-hint-state') === 'shown';

  function render(): void {
    const s = options.settings();
    el.replaceChildren(
      ...controlsHintLines(s.bindings, options.touch, s.hints.words ?? DEFAULT_HINT_WORDS).map((line) => {
        const row = doc.createElement('div');
        row.textContent = line;
        return row;
      }),
    );
  }
  function show(): void {
    render();
    el.style.display = 'block';
    el.setAttribute('data-webverse-hint-state', 'shown');
  }
  function hide(): void {
    el.style.display = 'none';
    el.setAttribute('data-webverse-hint-state', 'hidden');
  }
  function seen(): boolean {
    try {
      return options.storage?.getItem(CONTROLS_HINT_SEEN_KEY) != null;
    } catch {
      return false;
    }
  }
  function markSeen(): void {
    try {
      options.storage?.setItem(CONTROLS_HINT_SEEN_KEY, '1');
    } catch {
      /* private window or a full quota: it just shows again next time */
    }
  }

  const dismiss = (): void => {
    if (!isShown()) return;
    hide();
    markSeen();
  };
  const toggle = (): void => {
    if (mode() === 'never') return;
    if (isShown()) dismiss();
    else show();
  };

  // Never eats an event: no preventDefault, no stopPropagation.
  const onKey = (ev: Event): void => {
    const code = (ev as KeyboardEvent).code;
    if (options.settings().bindings.help.includes(code)) toggle();
    else dismiss();
  };
  const onPointer = (): void => dismiss();
  doc.addEventListener('keydown', onKey);
  doc.addEventListener('pointerdown', onPointer);
  doc.addEventListener('mousedown', onPointer);
  doc.addEventListener('touchstart', onPointer);

  return {
    onWorldEntered(): void {
      const m = mode();
      if (m === 'always' || (m === 'first-visit' && !seen())) show();
    },
    toggle,
    dismiss,
    dispose(): void {
      doc.removeEventListener('keydown', onKey);
      doc.removeEventListener('pointerdown', onPointer);
      doc.removeEventListener('mousedown', onPointer);
      doc.removeEventListener('touchstart', onPointer);
      el.remove();
    },
  };
}
