/**
 * The VEML 4.0 path.
 *
 * `@fivesqd/veml-parse` is the ONLY 4.0 parser in the shell: this module
 * routes documents by the §1.4 discriminator and MAPS the parser's typed 4.0
 * model into the shell's existing `VemlDocument` once, so the whole scene
 * layer (buildWorld, spawnResolve, worldSession, portals, locomotion wiring)
 * is untouched downstream. No 4.0 grammar knowledge lives here — only the
 * semantic correspondence between the two models:
 *
 *   entry-point + URL fragment  → environment.spawn (resolveArrival, §5)
 *   primitive shape="cube"      → the shell's `cubemesh` family (§4.5)
 *   asset src                   → mesh entity with one resource (§4.4)
 *   entity / container          → container marker (children carried)
 *   html                        → html entity (§4.6)
 *   lod                         → container (its own children always render)
 *                                 + entity.lodLevels, chosen by distance and
 *                                 built on first need by the session (§4.10)
 *   link href/label attributes  → the shell's portal link (§6.1)
 *   locomotion / navigation / background / capabilities → passed through
 *
 *   input-binding               → metadata.inputBindings (§8.2; the session
 *                                 resolves defaults and routes to the bus)
 *   on-load                     → onLoadAction (§8.1 — an action, not code)
 *   include                     → entity.include + metadata.subsidiaryRefs
 *                                 (§6.2; the session composes after entry)
 *   prototype / instance        → an inline prototype expands here, under the
 *                                 host (§6.4); an href one → entity.pendingInstances
 *                                 + metadata.prototypes, for the session
 *
 * A surface the client does not implement is surfaced honestly as a
 * `diagnostic` warning with a shell-local `veml:4.0-port:*` id (an
 * unsupported profile, an unknown shape) — the world still loads (§2).
 *
 * The legacy prototype parser (parser.ts) remains the 3.0/3.1 path — the
 * ingest CLI emits 3.1 and the prototype demo worlds are 3.1 — loaded on
 * demand rather than with the app.
 */
import {
  expandInstance,
  IDENTITY_QUAT,
  ONE_VEC3,
  parseColor,
  parseQuatElement,
  parseVec3Element,
  parseVeml as parseVeml40,
  resolveArrival,
  VEML_4_0_NAMESPACE,
  ZERO_VEC3,
} from '@fivesqd/veml-parse';
import type {
  AssetEntity,
  Color,
  OpaqueNode,
  VemlDocument as Doc40,
  EntityNode,
  HtmlEntity,
  InstanceRef,
  LinkRef,
  LodEntity,
  PrimitiveEntity,
  PrototypeDeclaration,
  Transform as Transform40,
} from '@fivesqd/veml-parse';
import type { VemlParseResult, VemlParseWarning } from './parser';
import type { VemlControlFlags, VemlLiteProceduralSky, VemlWater, VemlWaterBlocker, VemlWaterBody, VemlWaterColor } from './documentModel';
import { readPlanetProfile } from './planetProfile';
import { validateHint } from './clientHintsVocabulary';
import type {
  VemlDocument,
  VemlEntity,
  VemlHtmlEntity,
  VemlInputBinding,
  VemlLink,
  VemlLodLevel,
  VemlMarkerEntity,
  VemlMeshEntity,
  VemlPrimitiveEntity,
  VemlPrimitiveType,
  VemlEnvironmentMap,
  VemlResourceRef,
  VemlScriptRef,
  VemlTransform,
} from './documentModel';
import { followableWorldUri, resolveWorldUri } from './uriResolve';

// ---------------------------------------------------------------------------
// §1.4 routing.
// ---------------------------------------------------------------------------

const VEML_NS_3_0 = 'http://www.fivesqd.com/schemas/veml/3.0';
const VEML_NS_3_1 = 'http://www.fivesqd.com/schemas/veml/3.1';

/**
 * Light root-tag sniff for routing ONLY (each path re-derives its own truth):
 * a `<veml>` root in the 4.0 namespace — or namespace-less but carrying
 * `version` — takes the 4.0 path; the 3.x namespaces and the namespace-less
 * prototype-era form take the legacy parser; anything else goes legacy so its
 * existing not-veml / unsupported-namespace error surface answers.
 */
export function is40Document(text: string): boolean {
  const src = text.replace(/<\?[\s\S]*?\?>/g, '').replace(/<!--[\s\S]*?-->/g, '');
  const m = /<([A-Za-z][\w:-]*)((?:\s+[\w:-]+="[^"]*")*)\s*\/?>/.exec(src);
  if (!m || m[1] !== 'veml') return false;
  const attrs: Record<string, string> = {};
  const attrRe = /([\w:-]+)="([^"]*)"/g;
  let a: RegExpExecArray | null;
  while ((a = attrRe.exec(m[2] ?? ''))) attrs[a[1]!] = a[2]!;
  const xmlns = attrs['xmlns'];
  if (xmlns === VEML_4_0_NAMESPACE) return true;
  if (xmlns === VEML_NS_3_0 || xmlns === VEML_NS_3_1) return false;
  if (xmlns === undefined) return attrs['version'] !== undefined;
  return false; // foreign namespace — legacy path reports it
}

/**
 * The router `loadWorld` (and tests) use for XML text. The legacy 3.x parser
 * is code-split, fetched the first time a world needs it, so a typical 4.0
 * world never downloads it. Never rejects.
 */
export async function parseWorldText(text: string, worldDocUrl: string): Promise<VemlParseResult> {
  if (is40Document(text)) return parseWorld40Xml(text, worldDocUrl);
  let parseLegacy: (xmlText: string, worldDocUrl: string) => VemlParseResult;
  try {
    parseLegacy = await loadLegacyParser();
  } catch (err) {
    return readerUnavailable('VEML 3', worldDocUrl, err);
  }
  return parseLegacy(text, worldDocUrl);
}

/**
 * The destructured import is what lets the bundler drop the chunk's other
 * exports; a whole-namespace import would ship all of them.
 */
async function loadLegacyParser(): Promise<(xmlText: string, worldDocUrl: string) => VemlParseResult> {
  const { parseVeml } = await import('./parser');
  return parseVeml;
}

/**
 * The failed load for a world whose code-split parser could not be fetched
 * (the viewer went offline mid-session): reported like any failed fetch.
 */
export function readerUnavailable(reader: string, worldDocUrl: string, err: unknown): VemlParseResult {
  return {
    ok: false,
    report: {
      url: worldDocUrl,
      declaredVersion: null,
      errors: [
        {
          kind: 'fetch',
          phase: 'network',
          message: `Could not load the viewer's ${reader} reader for ${worldDocUrl}: ${
            err instanceof Error ? err.message : String(err)
          }`,
          url: worldDocUrl,
        },
      ],
      warnings: [],
    },
  };
}

// ---------------------------------------------------------------------------
// The 4.0 parse + map.
// ---------------------------------------------------------------------------

function fragmentOf(worldDocUrl: string): string | undefined {
  const hash = worldDocUrl.indexOf('#');
  if (hash === -1) return undefined;
  const fragment = worldDocUrl.slice(hash + 1);
  return fragment.length > 0 ? fragment : undefined;
}

export function parseWorld40Xml(text: string, worldDocUrl: string): VemlParseResult {
  const parsed = parseVeml40(text);
  const warnings: VemlParseWarning[] = parsed.diagnostics.map((d) => ({
    kind: 'diagnostic',
    name: d.id,
    path: d.detail ?? '',
  }));

  if (!parsed.ok || !parsed.document) {
    return {
      ok: false,
      report: {
        url: worldDocUrl,
        declaredVersion: '4.0',
        errors: [
          {
            kind: 'malformed-xml',
            message:
              parsed.errors.join('; ') ||
              parsed.diagnostics.map((d) => d.id).join('; ') ||
              'unparseable VEML 4.0 document',
            url: worldDocUrl,
          },
        ],
        warnings,
      },
    };
  }

  const document = mapDocument(parsed.document, worldDocUrl, warnings, parsed.subsidiaryReferences);
  return {
    ok: true,
    document,
    report: { url: worldDocUrl, declaredVersion: '4.0', errors: [], warnings },
  };
}

function colorString(c: Color | undefined): string | undefined {
  if (!c || c.form === 'neutral') return undefined;
  return c.raw;
}

function mapLink(l: LinkRef | undefined, worldDocUrl: string): VemlLink | undefined {
  if (!l?.href) return undefined;
  // A link that does not resolve to http(s) is not a portal.
  const resolvedHref = followableWorldUri(l.href, worldDocUrl);
  if (resolvedHref === undefined) return undefined;
  return { href: l.href, resolvedHref, label: l.label ?? '' };
}

/**
 * §4.2 → shell transform. `size` wins when present (already resolved by the
 * parser per veml:4.2:scale-and-size) and maps onto the shell's
 * `sizetransform`; NOTE the semantic gap recorded for the freeze work: 4.0
 * `size` is a uniform-fit target extent, the shell's 3.1-era sizetransform
 * is per-axis — identical for the common uniform case, divergent otherwise
 * (§11 trap table territory, not this story's).
 */
function mapTransform(t: Transform40 | undefined): VemlTransform | undefined {
  if (!t) return undefined;
  if (t.size) {
    return { kind: 'sizetransform', position: t.position, rotation: t.rotation, size: t.size };
  }
  return { kind: 'scaletransform', position: t.position, rotation: t.rotation, scale: t.scale };
}

/** 4.0 §4.5 shape names → the shell's 11 primitive mesh types. */
const SHAPE_TO_TYPE: Record<string, VemlPrimitiveType> = {
  cube: 'cubemesh',
  sphere: 'spheremesh',
  capsule: 'capsulemesh',
  cylinder: 'cylindermesh',
  plane: 'planemesh',
  torus: 'torusmesh',
  cone: 'conemesh',
  'rectangular-pyramid': 'rectangularpyramidmesh',
  tetrahedron: 'tetrahedronmesh',
  prism: 'prismmesh',
  arch: 'archmesh',
};

/** §10 profiles this shell implements (specs/veml/profiles/). */
// `sky` is implemented below (the mapping onto the procedural-sky arm) and
// was missing from this set, so a declared sky profile was reported as
// unimplemented while it rendered. The set and the mappings must agree.
const SHELL_IMPLEMENTED_PROFILES: ReadonlySet<string> = new Set(['lighting', 'sky', 'environment', 'client-hints', 'water', 'planet']);

/**
 * The document's prototypes by name (§6.4 Resolution: first declaration
 * wins). An inline one carries its declaration and expands at parse time; an
 * `href` one carries where to fetch it and is the session's, after entry.
 */
type PrototypeTable = Map<
  string,
  { kind: 'inline'; decl: PrototypeDeclaration } | { kind: 'href'; url: string; integrity?: string }
>;

interface MapCtx {
  worldDocUrl: string;
  warnings: VemlParseWarning[];
  prototypes: PrototypeTable;
}

function warnPort(ctx: MapCtx, slug: string, detail: string): void {
  ctx.warnings.push({ kind: 'diagnostic', name: `veml:4.0-port:${slug}`, path: detail });
}

function warnDiagnostics(ctx: MapCtx, diagnostics: ReadonlyArray<{ id: string; detail?: string }>): void {
  for (const d of diagnostics) ctx.warnings.push({ kind: 'diagnostic', name: d.id, path: d.detail ?? '' });
}

function prototypeTable(doc: Doc40, ctx: MapCtx): PrototypeTable {
  const table: PrototypeTable = new Map();
  for (const decl of doc.metadata.prototypes) {
    if (decl.name === undefined || decl.name === '') {
      ctx.warnings.push({ kind: 'diagnostic', name: 'veml:6.4:unnamed-prototype', path: 'declaration without a name ignored' });
      continue;
    }
    if (table.has(decl.name)) {
      ctx.warnings.push({ kind: 'diagnostic', name: 'veml:6.4:duplicate-prototype', path: `${decl.name}: first declaration wins` });
      continue;
    }
    if (decl.templateSource !== undefined) {
      if (decl.href !== undefined) {
        ctx.warnings.push({
          kind: 'diagnostic',
          name: 'veml:6.4:both-href-and-template',
          path: `${decl.name}: inline template wins over href`,
        });
      }
      table.set(decl.name, { kind: 'inline', decl });
    } else if (decl.href !== undefined) {
      table.set(decl.name, {
        kind: 'href',
        url: resolveWorldUri(decl.href, ctx.worldDocUrl),
        ...(decl.integrity !== undefined ? { integrity: decl.integrity } : {}),
      });
    } else {
      ctx.warnings.push({ kind: 'diagnostic', name: 'veml:6.4:no-template', path: `${decl.name}: neither href nor template; undeclared` });
    }
  }
  return table;
}

/**
 * Map one expanded subtree (§6.4) for the session, which expands `href`
 * prototypes after entry. Relative references inside it resolve against the
 * definition's URL, never the host's.
 */
export function mapPrototypeInstance(
  node: EntityNode,
  definingUrl: string,
  warnings: VemlParseWarning[],
): VemlEntity | undefined {
  return mapEntity(node, { worldDocUrl: definingUrl, warnings, prototypes: new Map() });
}

function mapEntities(nodes: EntityNode[], ctx: MapCtx): VemlEntity[] {
  const out: VemlEntity[] = [];
  for (const n of nodes) {
    const mapped = mapEntity(n, ctx);
    if (mapped) out.push(mapped);
  }
  return out;
}

/**
 * §6.4: an inline prototype expands into `into`, after what is already
 * there; an href one is returned for the session, which fetches it after
 * entry. A name nobody declared is omitted (§2's ignore rule).
 */
function resolveInstances(
  instances: readonly InstanceRef[],
  into: VemlEntity[],
  ctx: MapCtx,
): NonNullable<VemlEntity['pendingInstances']> {
  const pending: NonNullable<VemlEntity['pendingInstances']> = [];
  for (const inst of instances) {
    const name = inst.prototype ?? '';
    const entry = name === '' ? undefined : ctx.prototypes.get(name);
    if (entry === undefined) {
      ctx.warnings.push({ kind: 'diagnostic', name: 'veml:6.4:undeclared-prototype', path: `instance of '${name}' omitted` });
      continue;
    }
    if (entry.kind === 'href') {
      pending.push({ prototype: name, bindings: inst.bindings });
      continue;
    }
    const expanded = expandInstance(entry.decl, inst.bindings);
    warnDiagnostics(ctx, expanded.diagnostics);
    if (expanded.node === undefined) continue;
    const child = mapEntity(expanded.node, ctx);
    if (child) into.push(child);
  }
  return pending;
}

function mapEntity(e: EntityNode, ctx: MapCtx): VemlEntity | undefined {
  const base = {
    tag: e.tag,
    id: e.id,
    // 4.0 `on-load` names an ACTION (§8.1), not a script function: it rides
    // the bus, never the 3.x `Handler("id")` dispatch.
    onLoadAction: e.onLoad,
    transform: mapTransform(e.transform),
    children: mapEntities(e.children, ctx),
    synchronizer: e.synchronizer,
    placementSockets: e.placementSockets.map((s) => ({
      position: s.position,
      rotation: s.rotation,
      connectingOffset: s.connectingOffset,
    })),
    link: mapLink(e.link, ctx.worldDocUrl),
    // §6.2: kept on the entity; the session composes it after entry.
    ...(e.include?.href !== undefined
      ? {
          include: {
            raw: e.include.href,
            resolved: resolveWorldUri(e.include.href, ctx.worldDocUrl),
            ...(e.include.integrity !== undefined ? { integrity: e.include.integrity } : {}),
          },
        }
      : {}),
    // §4.8: a declared box the session may defer behind.
    ...(e.bounds !== undefined ? { bounds: { center: e.bounds.center, size: e.bounds.size } } : {}),
  };

  const pendingInstances = resolveInstances(e.instances, base.children, ctx);
  if (pendingInstances.length > 0) Object.assign(base, { pendingInstances });

  switch (e.kind) {
    case 'primitive': {
      const p = e as PrimitiveEntity;
      const type = p.shape !== undefined ? SHAPE_TO_TYPE[p.shape] : 'cubemesh';
      if (type === undefined) {
        // Open-set tolerance: an unrecognized shape renders as the neutral box.
        warnPort(ctx, 'unknown-shape', `${p.shape}; neutral cube rendered`);
      }
      const entity: VemlPrimitiveEntity = {
        ...base,
        type: type ?? 'cubemesh',
        color: colorString(p.color),
      };
      return entity;
    }
    case 'asset': {
      const a = e as AssetEntity;
      const entity: VemlMeshEntity = {
        ...base,
        type: 'mesh',
        meshName: a.tag,
        meshResources: a.src
          ? [{ raw: a.src, resolved: resolveWorldUri(a.src, ctx.worldDocUrl) }]
          : [],
        // §4.4: lighter files for the same model, as the parser ordered them.
        ...(a.sources.length > 0
          ? { meshAlternatives: a.sources.map((s) => ({ quality: s.quality, resource: { raw: s.src, resolved: resolveWorldUri(s.src, ctx.worldDocUrl) } })) }
          : {}),
      };
      return entity;
    }
    case 'html': {
      const h = e as HtmlEntity;
      const entity: VemlHtmlEntity = {
        ...base,
        type: 'html',
        url: h.url ? { raw: h.url, resolved: resolveWorldUri(h.url, ctx.worldDocUrl) } : undefined,
        onMessage: h.onMessage,
      };
      return entity;
    }
    case 'lod': {
      // §4.10: a container whose own children always render, plus levels the
      // session chooses between by distance and builds on first need.
      const l = e as LodEntity;
      const lodLevels: VemlLodLevel[] = l.levels.map((level) => {
        const entities = mapEntities(level.children, ctx);
        const pending = resolveInstances(level.instances, entities, ctx);
        return { range: level.range, entities, ...(pending.length > 0 ? { pendingInstances: pending } : {}) };
      });
      const entity: VemlMarkerEntity = {
        ...base,
        type: 'container',
        ...(lodLevels.length > 0 ? { lodLevels } : {}),
      };
      return entity;
    }
    case 'entity':
    case 'container': {
      const entity: VemlMarkerEntity = { ...base, type: 'container' };
      return entity;
    }
  }
}

/**
 * The `client-hints` profile (specs/veml/profiles/client-hints.md):
 * `hints:hints` in `environment`, five children whose attributes become the
 * runtime's hint names (`people.labels`, …), each validated by the same
 * `validateHint` a script's `ClientHints.Set` uses. The profile's own
 * elements are never reported unknown (the spec's MUST NOT).
 */
function clientHints(doc: Doc40, ctx: MapCtx): Record<string, string> | undefined {
  if (!doc.metadata.profiles.includes('client-hints')) return undefined;
  const roots = doc.environment.unknown.filter((n) => n.tag === 'hints');
  if (roots.length === 0) return undefined;
  const implemented = new Set(['hints', 'people', 'chat', 'controls', 'vr', 'planet', 'placements', 'view']);
  for (let i = ctx.warnings.length - 1; i >= 0; i -= 1) {
    const w = ctx.warnings[i]!;
    if (w.name === 'veml:2:unknown-element' && typeof w.path === 'string' && implemented.has(w.path.replace(/^<|>$/g, ''))) {
      ctx.warnings.splice(i, 1);
    }
  }
  const warn = (slug: string, path: string): void => {
    ctx.warnings.push({ kind: 'diagnostic', name: `veml:client-hints:${slug}`, path });
  };
  if (roots.length > 1) warn('duplicate', `${roots.length - 1} further <hints:hints> ignored`);
  const out: Record<string, string> = {};
  for (const child of roots[0]!.children) {
    // An unknown child keeps §2's own unknown-element warning (not removed above).
    if (!implemented.has(child.tag) || child.tag === 'hints') continue;
    for (const [attr, raw] of Object.entries(child.attributes)) {
      const name = `${child.tag}.${attr}`;
      const check = validateHint(name, raw);
      if (!check.ok) {
        warn(check.reason, `${name}="${raw}"`);
        continue;
      }
      if (check.reason) warn(check.reason, `${name}="${raw}" read as "${check.value}"`);
      out[name] = check.value;
    }
  }
  return out;
}

/** `hints:vr` feeds the VR controls the shell already reads (3.0 controlflags' names). */
function controlFlagsFrom(hints: Record<string, string> | undefined): VemlControlFlags | undefined {
  if (!hints) return undefined;
  const flags: VemlControlFlags = {};
  if (hints['vr.turn'] !== undefined) flags.turnLocomotion = hints['vr.turn'];
  if (hints['vr.stick-motion'] !== undefined) flags.joystickMotion = hints['vr.stick-motion'] === 'true';
  if (hints['vr.left-pointer'] !== undefined) flags.leftVrPointer = hints['vr.left-pointer'];
  if (hints['vr.right-pointer'] !== undefined) flags.rightVrPointer = hints['vr.right-pointer'];
  return Object.keys(flags).length > 0 ? flags : undefined;
}

function mapDocument(
  doc: Doc40,
  worldDocUrl: string,
  warnings: VemlParseWarning[],
  subsidiaryReferences: ReadonlyArray<{ href: string }> = [],
): VemlDocument {
  const ctx: MapCtx = { worldDocUrl, warnings, prototypes: new Map() };
  ctx.prototypes = prototypeTable(doc, ctx);
  const env = doc.environment;
  const hints = clientHints(doc, ctx);
  const planet = readPlanetProfile(doc.metadata.profiles, doc.environment.unknown, ctx.warnings, worldDocUrl);
  const controlFlags = controlFlagsFrom(hints);
  const water = waterProfile(doc, ctx);

  // §8.3 — the sandboxed script tier: 4.0 `<script src>` refs feed
  // the SAME machinery as the 3.1 path (worldSession fetches + runs
  // metadata.scripts through the code-split sandbox). The draft leaves "the
  // full script API specified separately", so the shell's existing session
  // API is what scripts receive — core-conformant. The ACTION BUS half of
  // §8 (§8.1 actions, §8.2 input-binding, `world.actions.*`) remains
  // deferred, VISIBLY, behind its own diagnostic below.
  const scripts: VemlScriptRef[] = [];
  for (const s of doc.metadata.scripts) {
    if (typeof s.src !== 'string' || s.src.length === 0) continue;
    scripts.push({
      raw: s.src,
      resolved: resolveWorldUri(s.src, ctx.worldDocUrl),
      ...(s.integrity !== undefined ? { integrity: s.integrity } : {}),
    });
  }
  // §8.2 — carried verbatim; the session resolves them against the per-input
  // defaults and routes the core inputs through the bus.
  const inputBindings: VemlInputBinding[] = [];
  for (const b of doc.metadata.inputBindings ?? []) {
    if (typeof b.input !== 'string' || typeof b.action !== 'string') continue;
    inputBindings.push({ input: b.input, action: b.action });
  }
  // §6.4: the href prototypes, for the session to fetch after entry.
  const prototypes: NonNullable<VemlDocument['metadata']['prototypes']> = [];
  for (const [name, entry] of ctx.prototypes) {
    if (entry.kind === 'href') {
      prototypes.push({ name, url: entry.url, ...(entry.integrity !== undefined ? { integrity: entry.integrity } : {}) });
    }
  }
  // §10 profiles: those in SHELL_IMPLEMENTED_PROFILES are honoured; any other
  // declared profile warns and the world degrades to core behavior (§2/§10).
  for (const profile of doc.metadata.profiles) {
    if (!SHELL_IMPLEMENTED_PROFILES.has(profile)) {
      warnings.push({
        kind: 'diagnostic',
        name: 'veml:4.0-port:profile-unsupported',
        path: `profile '${profile}' not implemented — core behavior applies`,
      });
    }
  }

  // §5 arrival: the WORLD URL's fragment picks the entry point; unknown falls
  // back to `default` with the parser's own diagnostic id.
  const arrival = resolveArrival(env.entryPoints, fragmentOf(worldDocUrl));
  if (arrival.diagnostic) {
    warnings.push({
      kind: 'diagnostic',
      name: arrival.diagnostic.id,
      path: arrival.diagnostic.detail ?? '',
    });
  }

  return {
    declaredVersion: '4.0',
    metadata: {
      title: doc.metadata.title,
      capabilities: doc.metadata.capabilities,
      profiles: [...doc.metadata.profiles],
      scripts,
      ...(controlFlags === undefined ? {} : { controlFlags }),
      inputEvents: [],
      inputBindings,
      // `type` is not optional to carry: §7's entire selection rule is
      // "the first whose `type` it implements", so dropping it here made
      // the declaration unusable no matter what a shell did with it.
      synchronizationServices: doc.metadata.synchronizationServices.map((s) => ({
        type: s.type,
        address: s.address,
        id: s.id,
        session: s.session,
        iceServers: s.iceServers,
      })),
      // §6.2 eligibility counts includes and prototypes together, in order.
      subsidiaryRefs: subsidiaryReferences.map((r) => resolveWorldUri(r.href, ctx.worldDocUrl)),
      prototypes,
      // §6.3: the map the session resolves `manifest:` names through.
      ...(doc.metadata.manifest !== undefined
        ? { manifest: { raw: doc.metadata.manifest, resolved: resolveWorldUri(doc.metadata.manifest, ctx.worldDocUrl) } }
        : {}),
    },
    environment: {
      background: mapBackground(doc, ctx),
      spawn: arrival.entryPoint
        ? { position: arrival.entryPoint.position, rotation: arrival.entryPoint.rotation }
        : undefined,
      locomotion: env.locomotion
        ? {
            ...(env.locomotion.gravity !== undefined ? { gravity: env.locomotion.gravity } : {}),
            ...(env.locomotion.jumpHeight !== undefined
              ? { jumpHeight: env.locomotion.jumpHeight }
              : {}),
          }
        : undefined,
      // §5.1 navigation (modes/speed), passed through untouched;
      // the shell's fly-toggle gating + walk-speed multiplier read it (
      // src/scene/worldSession.ts / src/controller/firstPersonController.ts).
      navigation: env.navigation
        ? {
            modes: [...env.navigation.modes],
            ...(env.navigation.speed !== undefined ? { speed: env.navigation.speed } : {}),
          }
        : undefined,
      ...(hints === undefined ? {} : { clientHints: hints }),
      ...(water === undefined ? {} : { water }),
      ...(planet === undefined ? {} : { planet }),
      entities: mapEntities(env.entities, ctx),
    },
  };
}

/** The water profile's defaults (`specs/veml/profiles/water.md`, `water:body`). */
export const WATER_DEFAULTS = Object.freeze({
  color: '#2a6f97ff',
  deepColor: '#0b2a3aff',
  clarity: 4,
  waves: 0.1,
});

/**
 * The `water` profile (`specs/veml/profiles/water.md`): `water:body` and
 * `water:blocker` in `environment`, declarations rather than entities.
 *
 * The same pattern as `proceduralSky` below: read what the core parser
 * called unknown, gated on the profile declaration, and withdraw the
 * `veml:2:unknown-element` warnings for what this shell implements. The
 * profile's own diagnostics: `veml:water:out-of-range` (clamped, once per
 * attribute), `veml:water:rotated` (a body's rotation ignored),
 * `veml:water:invalid` (a transform that is not numbers; the element is
 * dropped). A bad colour keeps the core's `veml:4.5:bad-color` and the
 * default applies.
 */
function waterProfile(doc: Doc40, ctx: MapCtx): VemlWater | undefined {
  if (!doc.metadata.profiles.includes('water')) return undefined;
  const bodyNodes = doc.environment.unknown.filter((n) => n.tag === 'body');
  const blockerNodes = doc.environment.unknown.filter((n) => n.tag === 'blocker');
  if (bodyNodes.length === 0 && blockerNodes.length === 0) return undefined;

  const warn = (slug: string, path: string): void => {
    ctx.warnings.push({ kind: 'diagnostic', name: `veml:water:${slug}`, path });
  };
  const warnedRange = new Set<string>();

  const finite = (v: { x: number; y: number; z: number; w?: number }): boolean =>
    Number.isFinite(v.x) && Number.isFinite(v.y) && Number.isFinite(v.z) && (v.w === undefined || Number.isFinite(v.w));

  /** A box transform from the element's `transform` child, or null when it is not numbers. */
  const box = (
    node: OpaqueNode,
  ): { position: { x: number; y: number; z: number }; rotation: { x: number; y: number; z: number; w: number }; extent: { x: number; y: number; z: number } } | null => {
    const t = node.children.find((c) => c.tag === 'transform');
    const attrsOf = (tag: string): Record<string, string> | undefined => t?.children.find((c) => c.tag === tag)?.attributes;
    const position = parseVec3Element(attrsOf('position'), ZERO_VEC3);
    const rotation = parseQuatElement(attrsOf('rotation'), IDENTITY_QUAT);
    const extent = parseVec3Element(attrsOf('scale'), ONE_VEC3);
    if (!finite(position) || !finite(rotation) || !finite(extent)) return null;
    return { position, rotation, extent };
  };

  const num = (bag: Record<string, string>, attr: string, lo: number, hi: number, fallback: number): number => {
    const raw = bag[attr];
    if (raw === undefined) return fallback;
    const v = Number(raw);
    const clamped = Number.isFinite(v) ? Math.min(hi, Math.max(lo, v)) : fallback;
    if (clamped !== v && !warnedRange.has(attr)) {
      warnedRange.add(attr);
      warn('out-of-range', Number.isFinite(v) ? `${attr}=${v} clamped to ${clamped}` : `${attr}="${raw}"`);
    }
    return clamped;
  };

  const color = (bag: Record<string, string>, attr: string, fallback: string): VemlWaterColor => {
    const raw = bag[attr] ?? fallback;
    const parsed = parseColor(raw);
    if (parsed.diagnostic) {
      ctx.warnings.push({ kind: 'diagnostic', name: parsed.diagnostic.id, path: `body@${attr}` });
    }
    const c = parsed.color.form === 'neutral' ? parseColor(fallback).color : parsed.color;
    if (c.form === 'neutral') return { r: 0.5, g: 0.5, b: 0.5, a: 1 };
    return { r: c.r, g: c.g, b: c.b, a: c.a };
  };

  const isIdentity = (q: { x: number; y: number; z: number; w: number }): boolean =>
    q.x === 0 && q.y === 0 && q.z === 0 && Math.abs(q.w) === 1;

  const bodies: VemlWaterBody[] = [];
  for (const node of bodyNodes) {
    const b = box(node);
    if (b === null) {
      warn('invalid', '<body> transform is not numbers; the body is ignored');
      continue;
    }
    if (!isIdentity(b.rotation)) warn('rotated', '<body> rotation ignored: a body is horizontal');
    bodies.push({
      position: b.position,
      extent: b.extent,
      color: color(node.attributes, 'color', WATER_DEFAULTS.color),
      deepColor: color(node.attributes, 'deep-color', WATER_DEFAULTS.deepColor),
      clarity: num(node.attributes, 'clarity', 0, Number.MAX_VALUE, WATER_DEFAULTS.clarity),
      waves: num(node.attributes, 'waves', 0, 1, WATER_DEFAULTS.waves),
    });
  }
  const blockers: VemlWaterBlocker[] = [];
  for (const node of blockerNodes) {
    const b = box(node);
    if (b === null) {
      warn('invalid', '<blocker> transform is not numbers; the blocker is ignored');
      continue;
    }
    blockers.push({ position: b.position, rotation: b.rotation, extent: b.extent });
  }

  // The core parser flagged every body and blocker as unknown before this
  // ran; the profile makes emitting that a MUST NOT for implemented
  // elements. In place, for the reason proceduralSky gives.
  const implemented = new Set(['body', 'blocker']);
  for (let i = ctx.warnings.length - 1; i >= 0; i -= 1) {
    const w = ctx.warnings[i]!;
    if (w.name === 'veml:2:unknown-element' && typeof w.path === 'string' && implemented.has(w.path.replace(/^<|>$/g, ''))) {
      ctx.warnings.splice(i, 1);
    }
  }
  return { bodies, blockers };
}

/**
 * The `sky` profile (`specs/veml/profiles/sky.md`) — a procedural sky
 * declared in the document rather than a flat backdrop.
 *
 * No new renderer: the code-split sky chunk already draws a
 * ground→horizon→zenith gradient with a sun disc, reached through the
 * `lite-procedural-sky` arm of `VemlBackground`. This maps the profile's
 * grouped children onto the bag that arm carries.
 *
 * The pattern is `environmentMapRef`'s, immediately below: read what the core
 * parser calls unknown, gated on the profile declaration, and withdraw the
 * now-false warning. The profile makes that withdrawal normative.
 */
const SKY_DEFAULTS = {
  daySkyColor: '#08124100',
  dayHorizonColor: '#448bc5ff',
  horizonSkyBlend: 0.579,
  groundColor: '#07070700',
  groundHeight: -0.02,
  groundFadeAmount: 0.02,
  sunDiameter: 2,
  sunZenithColor: 'color(158 129 58 0)',
  sunElevation: 45,
  sunAzimuth: 180,
} as const;

/**
 * The sun's direction from the profile's `elevation`/`azimuth`, as the sky
 * chunk's `sunDirection` uniform wants it: unit length, Y up, azimuth
 * measured clockwise from -Z.
 */
export function sunDirectionOf(sky: VemlLiteProceduralSky): { x: number; y: number; z: number } {
  const elevation = typeof sky['sunElevation'] === 'number' ? sky['sunElevation'] : 45;
  const azimuth = typeof sky['sunAzimuth'] === 'number' ? sky['sunAzimuth'] : 180;
  const el = (elevation * Math.PI) / 180;
  const az = (azimuth * Math.PI) / 180;
  const cosEl = Math.cos(el);
  return { x: cosEl * Math.sin(az), y: Math.sin(el), z: -cosEl * Math.cos(az) };
}

function proceduralSky(doc: Doc40, ctx: MapCtx): VemlLiteProceduralSky | undefined {
  if (!doc.metadata.profiles.includes('sky')) return undefined;
  const root = doc.environment.unknown.find((n) => n.tag === 'sky');
  if (root === undefined) return undefined;

  const child = (tag: string): Record<string, string> =>
    root.children.find((c) => c.tag === tag)?.attributes ?? {};
  const atmosphere = child('atmosphere');
  const ground = child('ground');
  const sun = child('sun');

  /** A number in range, or the default — and say so, never refuse (§ Degradation). */
  const num = (
    bag: Record<string, string>,
    attr: string,
    lo: number,
    hi: number,
    fallback: number,
  ): number => {
    const raw = bag[attr];
    if (raw === undefined) return fallback;
    const v = Number(raw);
    if (!Number.isFinite(v)) {
      ctx.warnings.push({ kind: 'diagnostic', name: 'veml:sky:out-of-range', path: `${attr}="${raw}"` });
      return fallback;
    }
    if (v < lo || v > hi) {
      const clamped = Math.min(hi, Math.max(lo, v));
      ctx.warnings.push({
        kind: 'diagnostic',
        name: 'veml:sky:out-of-range',
        path: `${attr}=${v} clamped to ${clamped}`,
      });
      return clamped;
    }
    return v;
  };
  const bool = (bag: Record<string, string>, attr: string): boolean => bag[attr] !== 'false';
  const color = (bag: Record<string, string>, attr: string, fallback: string): string =>
    bag[attr] ?? fallback;

  // The sun is self-contained: 4.0 has no light vocabulary for a tag to name
  // (`profiles/lighting.md`), so elevation/azimuth become the direction the
  // chunk's `sunDirection` uniform already takes.
  const elevation = num(sun, 'elevation', -90, 90, SKY_DEFAULTS.sunElevation);
  const azimuth = num(sun, 'azimuth', 0, 360, SKY_DEFAULTS.sunAzimuth);
  const sky: VemlLiteProceduralSky = {
    daySkyColor: color(atmosphere, 'zenith', SKY_DEFAULTS.daySkyColor),
    dayHorizonColor: color(atmosphere, 'horizon', SKY_DEFAULTS.dayHorizonColor),
    horizonSkyBlend: num(atmosphere, 'blend', 0.1, 2, SKY_DEFAULTS.horizonSkyBlend),
    groundEnabled: bool(ground, 'enabled'),
    groundColor: color(ground, 'color', SKY_DEFAULTS.groundColor),
    groundHeight: num(ground, 'height', -1, 1, SKY_DEFAULTS.groundHeight),
    groundFadeAmount: num(ground, 'fade', 0, 1, SKY_DEFAULTS.groundFadeAmount),
    sunEnabled: bool(sun, 'enabled'),
    sunDiameter: num(sun, 'diameter', 0, Number.MAX_SAFE_INTEGER, SKY_DEFAULTS.sunDiameter),
    sunZenithColor: color(sun, 'color', SKY_DEFAULTS.sunZenithColor),
    // The DOCUMENT's data, in the document's terms. Turning it into a
    // direction vector is the renderer's job — `sunDirectionOf` below — and
    // the bag's type is `string | number | boolean` for exactly this reason.
    sunElevation: elevation,
    sunAzimuth: azimuth,
    dayNightCycleEnabled: false,
  };

  // HONEST REPORTING: the core parser flagged `sky` and every child as
  // unknown before this ran. Withdraw the warnings for what IS implemented —
  // the profile makes this a MUST NOT — and leave the rest standing, so a
  // `sky:weather` still reads as unhandled.
  const implemented = new Set(['sky', 'atmosphere', 'ground', 'sun']);
  // IN PLACE. `ctx.warnings = ctx.warnings.filter(...)` rebinds a local and
  // leaves the caller's array untouched; `environmentMapRef` below uses
  // splice for the same reason.
  for (let i = ctx.warnings.length - 1; i >= 0; i -= 1) {
    const w = ctx.warnings[i]!;
    if (
      w.name === 'veml:2:unknown-element' &&
      typeof w.path === 'string' &&
      implemented.has(w.path.replace(/^<|>$/g, ''))
    ) {
      ctx.warnings.splice(i, 1);
    }
  }
  return sky;
}

/**
 * The `environment` profile's image-based-lighting
 * declaration: `<environment-map src="…"/>` inside `<environment>`.
 *
 * It rides Principle 7 (unknown elements are ignored, never fatal), so it
 * parses today and warns honestly; a shell without the profile sees only the
 * warning and the world's plain color background. §3.2 could NOT carry this:
 * the 4.0 parser enforces "exactly one of color or panorama" and drops the
 * color when both are present, so an IBL-plus-visible-color world is
 * inexpressible through `background` alone, hence a profile element.
 */
function environmentMapRef(doc: Doc40, ctx: MapCtx): VemlEnvironmentMap | undefined {
  if (!doc.metadata.profiles.includes('environment')) return undefined;
  // Matched by LOCAL name: the reference parser records unrecognised elements
  // without their namespace (profiles/sky.md, Schema), so the namespaced
  // `env:environment-map` (profiles/environment.md) and the earlier
  // un-namespaced export both arrive as `environment-map` — the page lets a
  // shell keep reading the earlier form.
  const nodes = doc.environment.unknown.filter((n) => n.tag === 'environment-map');
  if (nodes.length === 0) return undefined;
  // HONEST REPORTING: the reference
  // parser rightly flags <environment-map> as unknown — but THIS shell reads
  // and honours it, so that warning would be false. Removed ONLY on this
  // consumed path, for every occurrence; a non-declaring document keeps the
  // honest §2 unknown-element warning.
  for (let i = ctx.warnings.length - 1; i >= 0; i--) {
    const w = ctx.warnings[i]!;
    if (w.name === 'veml:2:unknown-element' && w.path === '<environment-map>') ctx.warnings.splice(i, 1);
  }
  // profiles/environment.md: at most one is honoured.
  if (nodes.length > 1) {
    ctx.warnings.push({
      kind: 'diagnostic',
      name: 'veml:environment:duplicate',
      path: `${nodes.length - 1} further <environment-map> ignored`,
    });
  }
  const node = nodes[0]!;
  const src = node.attributes['src'];
  if (src === undefined || src.length === 0) {
    ctx.warnings.push({ kind: 'diagnostic', name: 'veml:environment:missing-src', path: '<environment-map>' });
    return undefined;
  }
  const map: VemlEnvironmentMap = { raw: src, resolved: resolveWorldUri(src, ctx.worldDocUrl) };
  // Optional look attributes — WORLD data, not shell constants.
  // Finite and ≥ 0, or ignored with a warning
  // (§2 tolerance; profiles/environment.md). `max` clamps, also with a warning.
  const num = (attr: string, max = Infinity): number | undefined => {
    const raw = node.attributes[attr];
    if (raw === undefined) return undefined;
    const v = Number(raw);
    if (!Number.isFinite(v) || v < 0) {
      ctx.warnings.push({ kind: 'diagnostic', name: 'veml:environment:out-of-range', path: `${attr}="${raw}"` });
      return undefined;
    }
    if (v > max) {
      ctx.warnings.push({
        kind: 'diagnostic',
        name: 'veml:environment:out-of-range',
        path: `${attr}=${v} clamped to ${max}`,
      });
      return max;
    }
    return v;
  };
  map.intensity = num('intensity');
  map.diffuse = num('diffuse');
  map.specular = num('specular');
  map.glazingBoost = num('glazing-boost');
  map.glazingF0 = num('glazing-f0', 1);
  const lights = node.attributes['punctual-lights'];
  if (lights === 'exclude' || lights === 'keep') map.punctualLights = lights;
  return map;
}

function mapBackground(doc: Doc40, ctx: MapCtx): VemlDocument['environment']['background'] {
  const bg = doc.environment.background;
  const environmentMap = environmentMapRef(doc, ctx);
  // The `sky` profile's backdrop wins over `background` (profiles/sky.md,
  // Degradation case 2): a computed sky and a flat colour are not rivals, and
  // the colour is what a shell WITHOUT the profile shows.
  const sky = proceduralSky(doc, ctx);
  if (sky) return { kind: 'lite-procedural-sky', sky };
  if (!bg) {
    return environmentMap ? { kind: 'color', color: '#000000ff', environmentMap } : undefined;
  }
  // The `environment` profile refines §3.2's
  // panorama-wins rule: with BOTH attributes present, the panorama becomes the
  // IBL and the color stays the visible backdrop. A shell without the profile
  // reads plain §3.2 (panorama wins, sky drawn) — degraded, never broken.
  if (bg.panorama) {
    return {
      kind: 'panorama',
      panorama: { raw: bg.panorama, resolved: resolveWorldUri(bg.panorama, ctx.worldDocUrl) },
    };
  }
  const color = colorString(bg.color);
  if (color === undefined) {
    return environmentMap ? { kind: 'color', color: '#000000ff', environmentMap } : undefined;
  }
  return environmentMap ? { kind: 'color', color, environmentMap } : { kind: 'color', color };
}
