/**
 * Shell settings — user-owned input bindings + locomotion
 * preferences, layered `bindings-default < persisted user settings <
 * embedder overrides`. Persisted settings live in the page consumer's
 * `localStorage` (mockable — the same `LocalStorageBackend` seam the
 * world-script LocalStorage API uses, under a DIFFERENT namespaced key so the two never
 * collide). Embedder overrides come from `createWorldSession({ settings })`
 * / `__webverse.applySettings(...)` (src/main.ts) and are SESSION-SCOPED —
 * never written back to storage.
 *
 * The persisted layer is written by the settings menu, through the
 * controller's `saveUserSettings`.
 */
import type { BindableAction, KeyBindings } from '../input/bindings';
import { DEFAULT_BINDINGS } from '../input/bindings';
import type { LocalStorageBackend } from '../sandbox/sandboxTypes';
import type { FocusChoice, MotionBlurChoice, QualityTier, ReliefChoice, TemporalChoice, TerrainStyleChoice, ThingsChoice } from './quality';

export interface ShellLocomotionSettings {
  /** Holding the jump control re-jumps on every landing. Default true. */
  autoJumpOnHold: boolean;
  /**
   * §5.1 user override: force the fly toggle available even when the loaded
   * world's `<navigation modes>` withholds it. The substitution latitude
   * runs one way — a user may always re-enable what a world withheld, never
   * the reverse. Default false.
   */
  forceFlyToggle: boolean;
  /**
   * How fast the mouse or the look stick turns you: a multiplier on
   * the shell's look sensitivity, the visitor's own (the menu's slider).
   * Default 1.
   */
  lookSpeed: number;
}

/** Where the Messages panel sits. A data attribute the theme reads; the default CSS places all four. */
export type MessagesCorner = 'bottom-left' | 'bottom-right' | 'top-left' | 'top-right';

/**
 * Messages: the panel that says what happened, who is here, and takes
 * a line to say something. EVERY default here is data (easy to start with,
 * always customizable): a user, an embedder, or a page
 * changes any of it without a rebuild, and the panel's code carries no
 * user-facing string of its own — the words come from `templates`.
 */
export interface ShellMessagesSettings {
  /** Shown at all. */
  visible: boolean;
  /** Which sources are drawn: the shell's notices, the people in the room, the world's own words. */
  channels: { shell: boolean; people: boolean; world: boolean };
  corner: MessagesCorner;
  /** Lines kept; the oldest go first. */
  maxLines: number;
  /** A line older than this is no longer drawn; 0 = never fades. */
  fadeMs: number;
  /**
   * kind → template, with `{field}` placeholders. A kind with no template
   * renders its `text` field, or nothing. Adding a kind is adding a line.
   */
  templates: Record<string, string>;
}

/**
 * The controls hint: when it shows, and what it says. The words are
 * data like the Messages templates: `{move}`, `{run}`, `{jump}`, `{descend}`, `{fly}`
 * and `{help}` are filled from the LIVE bindings, so a rebound key reads as
 * rebound. `first-visit` shows it once per browser; `always` on every world;
 * `never` turns it off (an embedder with its own help).
 */
export type ControlsHintMode = 'first-visit' | 'always' | 'never';

export interface ShellHintWords {
  desktop: readonly string[];
  touch: readonly string[];
}

export interface ShellHintsSettings {
  controls: ControlsHintMode;
  /** Absent → DEFAULT_HINT_WORDS. */
  words?: ShellHintWords;
}

export const DEFAULT_HINT_WORDS: ShellHintWords = {
  desktop: [
    'Click to look around · Esc gives the mouse back',
    '{move} to move · {run} to run · {jump} to jump',
    '{fly} to fly, where the world allows it — {jump} up, {descend} down',
    '{help} shows this again',
  ],
  // Looking is the right stick, not a drag; name the buttons too.
  touch: [
    'Left stick moves · right stick looks',
    'Jump · Chat · Fly buttons above',
    'Tap to dismiss',
  ],
};

/** How this client reaches other visitors. */
export interface ShellNetworkSettings {
  /**
   * ICE servers for the peer-authority mode, as `stun:`/`turn:`/`turns:`
   * URLs (a TURN entry as `turn:user:secret@host:port`). A deployment's
   * own relay for strict networks. Set, they replace what the world
   * declares and the default public STUN list. Default: none.
   */
  iceServers: readonly string[];
}

/** What the visitor's machine spends on the picture. */
export interface ShellGraphicsSettings {
  /**
   * The edge of a light's shadow map, in texels; the client caps it at 2048
   * and 0 turns shadows off. A world's lights ask for shadows, the visitor
   * decides how sharp they are. Default 1024.
   */
  shadowMapSize: number;
  /**
   * How much the device draws (settings/quality.ts): a tier, or `auto`,
   * which starts from what the browser says about the device. A tier's
   * shadows cap shadowMapSize. Default auto.
   */
  quality: QualityTier | 'auto';
  /**
   * Edges smoothed over frames on a planet, and the scene drawn smaller and
   * rebuilt from them (settings/quality.ts `temporalOf`): the tier's on
   * `auto`, `off`, `antialias` or `upscale`. Default auto.
   */
  temporal: TemporalChoice;
  /** Motion blur on a planet's fast turns and flight: `off` (the default, for comfort) or `on`. Never drawn in VR. */
  motionBlur?: MotionBlurChoice;
  /** Depth of field on a planet: `auto` (the default) follows the world, `off` never, `on` wherever the tier can. */
  focus?: FocusChoice;
  /** A planet's terrain style: `auto` (the default) follows the world, `smooth` or `blocks` where the host serves it. */
  terrainStyle?: TerrainStyleChoice;
  /** The blocks' relief on a planet: `auto` (the default) follows the world, `off` flat, `on` with relief where the tier draws it. */
  relief?: ReliefChoice;
  /** The things that move on a planet: `auto` (the default) follows the world, `shown` or `hidden` whatever it asks. */
  things?: ThingsChoice;
}

export interface ShellSettings {
  bindings: KeyBindings;
  locomotion: ShellLocomotionSettings;
  messages: ShellMessagesSettings;
  hints: ShellHintsSettings;
  network: ShellNetworkSettings;
  graphics: ShellGraphicsSettings;
}

export type PartialKeyBindings = Partial<Record<BindableAction, readonly string[]>>;

export interface PartialShellMessagesSettings {
  visible?: boolean;
  channels?: Partial<ShellMessagesSettings['channels']>;
  corner?: MessagesCorner;
  maxLines?: number;
  fadeMs?: number;
  templates?: Record<string, string>;
}

export interface PartialShellSettings {
  bindings?: PartialKeyBindings;
  locomotion?: Partial<ShellLocomotionSettings>;
  messages?: PartialShellMessagesSettings;
  hints?: Partial<ShellHintsSettings>;
  network?: Partial<ShellNetworkSettings>;
  graphics?: Partial<ShellGraphicsSettings>;
}

export const DEFAULT_MESSAGES_SETTINGS: ShellMessagesSettings = {
  visible: true,
  channels: { shell: true, people: true, world: true },
  corner: 'bottom-left',
  maxLines: 8,
  fadeMs: 15_000,
  templates: {
    entered: 'entered {title}',
    'load-failed': 'could not load {url}',
    capability: '{text}',
    joined: '{name} joined',
    left: '{name} left',
    chat: '{name}: {text}',
    reconnecting: 'connection lost — reconnecting ({attempt})',
    back: 'connection restored',
    refused: 'the room refused: {code}',
    ended: 'session ended ({reason})',
    unreachable: 'could not reach the other visitors from this network',
    world: '{text}',
  },
};

export const DEFAULT_SHELL_SETTINGS: ShellSettings = {
  bindings: DEFAULT_BINDINGS,
  locomotion: { autoJumpOnHold: true, forceFlyToggle: false, lookSpeed: 1 },
  messages: DEFAULT_MESSAGES_SETTINGS,
  hints: { controls: 'first-visit' },
  network: { iceServers: [] },
  graphics: { shadowMapSize: 1024, quality: 'auto', temporal: 'auto' },
};

/** Field-by-field for the two nested records, so one template or one channel can change alone. */
function mergeMessages(
  a: PartialShellMessagesSettings | undefined,
  b: PartialShellMessagesSettings | undefined,
): PartialShellMessagesSettings | undefined {
  if (!a) return b;
  if (!b) return a;
  return {
    ...a,
    ...b,
    channels: { ...a.channels, ...b.channels },
    templates: { ...a.templates, ...b.templates },
  };
}

/** Namespaced (like the world-script LocalStorage's `webverse:ls:`) — never collides with a
 * world script's LocalStorage keys or an embedder's own app keys. */
export const SETTINGS_STORAGE_KEY = 'webverse:settings:v1';

/** A phone's defaults, under a person's and an embedder's choices: chat at the top, clear of the sticks. */
export const TOUCH_DEVICE_DEFAULTS: PartialShellSettings = { messages: { corner: 'top-left' } };

function mergePartial(
  a: PartialShellSettings | undefined,
  b: PartialShellSettings | undefined,
): PartialShellSettings | undefined {
  if (!a) return b;
  if (!b) return a;
  const messages = mergeMessages(a.messages, b.messages);
  return {
    bindings: { ...a.bindings, ...b.bindings },
    locomotion: { ...a.locomotion, ...b.locomotion },
    ...(messages === undefined ? {} : { messages }),
    ...(a.hints || b.hints ? { hints: { ...a.hints, ...b.hints } } : {}),
    ...(a.network || b.network ? { network: { ...a.network, ...b.network } } : {}),
    ...(a.graphics || b.graphics ? { graphics: { ...a.graphics, ...b.graphics } } : {}),
  };
}

/** bindings-default < persisted user settings < embedder overrides. */
export function mergeShellSettings(
  ...layers: Array<PartialShellSettings | undefined>
): ShellSettings {
  let result = DEFAULT_SHELL_SETTINGS;
  for (const layer of layers) {
    if (!layer) continue;
    result = {
      bindings: { ...result.bindings, ...layer.bindings },
      locomotion: { ...result.locomotion, ...layer.locomotion },
      messages: {
        ...result.messages,
        ...layer.messages,
        channels: { ...result.messages.channels, ...layer.messages?.channels },
        templates: { ...result.messages.templates, ...layer.messages?.templates },
      },
      hints: { ...result.hints, ...layer.hints },
      network: { ...result.network, ...layer.network },
      graphics: { ...result.graphics, ...layer.graphics },
    };
  }
  return result;
}

/**
 * Never throws: a missing key, malformed JSON,
 * or a non-object payload all resolve to "no persisted settings" rather than
 * breaking boot.
 */
export function readPersistedSettings(
  backend: LocalStorageBackend | undefined,
): PartialShellSettings | undefined {
  if (!backend) return undefined;
  try {
    const raw = backend.getItem(SETTINGS_STORAGE_KEY);
    if (!raw) return undefined;
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed !== 'object' || parsed === null) return undefined;
    return parsed as PartialShellSettings;
  } catch {
    return undefined;
  }
}

/** The persisted layer's write path; the settings menu reaches it through `saveUserSettings`. */
export function writePersistedSettings(
  backend: LocalStorageBackend,
  settings: PartialShellSettings,
): void {
  backend.setItem(SETTINGS_STORAGE_KEY, JSON.stringify(settings));
}

export interface SettingsController {
  /** The resolved settings — default < persisted < embedder, recomputed on every apply. */
  get(): ShellSettings;
  /**
   * Merge into the EMBEDDER layer (session-scoped, never persisted, always
   * wins over the persisted user layer). Rebinding via this call takes
   * effect immediately — anything reading `get()` live (e.g. desktopInput's
   * bindings getter) sees it on the very next read.
   */
  applySettings(partial: PartialShellSettings): void;
  /**
   * Merge into the persisted USER layer and keep it: the settings
   * menu's write path. Applied at once (an embedder's override of the same
   * setting still wins, as the layering says), written to storage for the
   * next visit. No storage, or storage that refuses: it holds for this
   * visit, never throws.
   */
  saveUserSettings(partial: PartialShellSettings): void;
}

export function createSettingsController(
  options: {
    localStorage?: LocalStorageBackend;
    embedderSettings?: PartialShellSettings;
    /**
     * The device's defaults, UNDER everything a person or an embedder
     * chooses: on a phone, chat starts at the top, clear of the sticks.
     */
    deviceDefaults?: PartialShellSettings;
  } = {},
): SettingsController {
  const device = options.deviceDefaults;
  let persisted = readPersistedSettings(options.localStorage);
  let embedder = options.embedderSettings;
  let resolved = mergeShellSettings(device, persisted, embedder);
  return {
    get: () => resolved,
    applySettings(partial: PartialShellSettings): void {
      embedder = mergePartial(embedder, partial);
      resolved = mergeShellSettings(device, persisted, embedder);
    },
    saveUserSettings(partial: PartialShellSettings): void {
      persisted = mergePartial(persisted, partial);
      resolved = mergeShellSettings(device, persisted, embedder);
      if (!options.localStorage || !persisted) return;
      try {
        writePersistedSettings(options.localStorage, persisted);
      } catch {
        /* storage refused (private mode, quota): it holds for this visit */
      }
    },
  };
}
