/**
 * The messages, in the headset.
 *
 * The flat messages panel is page DOM, which a headset does not show, so a
 * visitor in VR would see nobody join and read no chat. While presenting, the same
 * lines the flat panel would show are drawn on a small plane held in view by
 * the active (XR) camera — below and to the left, about a metre out, readable
 * without being in the way. It shows nothing while the flat panel is hidden,
 * so it follows the world's `hints:chat` and the visitor's own toggle.
 *
 * Reading only: sending from a headset is not supported yet. Drawn like the name labels (a DynamicTexture
 * on a plane, a dark backing, white text); main bundle, like the VR pointer
 * affordance, and made only when a VR session begins.
 */
import { CreatePlane } from '@babylonjs/core/Meshes/Builders/planeBuilder';
import type { Mesh } from '@babylonjs/core/Meshes/mesh';
import type { Scene } from '@babylonjs/core/scene';
import { DynamicTexture, StandardMaterial } from '../engine/shaderImports';

export const VR_MESSAGES_MESH = 'vr-messages';

/** The plane, in metres, and where it sits relative to the eyes. */
const PLANE_W = 0.56;
const PLANE_H = 0.28;
const OFFSET = { x: -0.3, y: -0.24, z: 0.95 } as const;
const TEX_W = 1024;
const TEX_H = 512;
const FONT_PX = 46;
const MAX_LINES = 6;

export interface VrMessagesHud {
  /** Draw these lines (newest last); none hides the panel. Cheap when nothing changed. */
  show(lines: readonly string[]): void;
  dispose(): void;
}

/** The parts of a 2D context used here (a CanvasRenderingContext2D fits). */
interface HudContext {
  fillStyle: unknown;
  font: string;
  textBaseline: unknown;
  clearRect(x: number, y: number, w: number, h: number): void;
  fillRect(x: number, y: number, w: number, h: number): void;
  fillText(text: string, x: number, y: number): void;
  measureText(text: string): { width: number };
}

/** Clip `text` to `max` px, with an ellipsis. */
function fit(ctx: HudContext, text: string, max: number): string {
  if (ctx.measureText(text).width <= max) return text;
  let t = text;
  while (t.length > 1 && ctx.measureText(`${t}…`).width > max) t = t.slice(0, -1);
  return `${t}…`;
}

export function createVrMessagesHud(scene: Scene): VrMessagesHud {
  const mesh: Mesh = CreatePlane(VR_MESSAGES_MESH, { width: PLANE_W, height: PLANE_H }, scene);
  mesh.isPickable = false;
  mesh.isVisible = false;
  mesh.position.set(OFFSET.x, OFFSET.y, OFFSET.z);
  const texture = new DynamicTexture(`${VR_MESSAGES_MESH}:tex`, { width: TEX_W, height: TEX_H }, scene, true);
  texture.hasAlpha = true;
  // The plane's texture arrives flipped on v, as the name labels' does, so
  // it is flipped back in the texture (v' = 1 - v), as they are.
  texture.vScale = -1;
  texture.vOffset = 1;
  const material = new StandardMaterial(`${VR_MESSAGES_MESH}:mat`, scene);
  material.emissiveTexture = texture;
  material.diffuseTexture = texture;
  material.useAlphaFromDiffuseTexture = true;
  material.disableLighting = true;
  material.backFaceCulling = false;
  mesh.material = material;
  // Drawn over the world: a panel the visitor reads must not sink into a wall.
  mesh.renderingGroupId = 1;

  let drawn = '';
  const draw = (lines: readonly string[]): void => {
    const ctx = texture.getContext() as unknown as HudContext | null;
    if (ctx) {
      ctx.clearRect(0, 0, TEX_W, TEX_H);
      ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
      ctx.fillRect(0, 0, TEX_W, TEX_H);
      ctx.font = `600 ${FONT_PX}px system-ui, sans-serif`;
      ctx.textBaseline = 'top';
      ctx.fillStyle = '#ffffff';
      const shown = lines.slice(-MAX_LINES);
      const lineH = Math.floor((TEX_H - 32) / MAX_LINES);
      const top = TEX_H - 16 - shown.length * lineH; // newest at the bottom
      shown.forEach((line, i) => ctx.fillText(fit(ctx, line, TEX_W - 48), 24, top + i * lineH));
    }
    texture.update(false);
  };

  return {
    show(lines) {
      // Follow whichever camera is active: the XR camera replaces the flat one on Enter.
      const camera = scene.activeCamera;
      if (camera && mesh.parent !== camera) mesh.parent = camera;
      if (lines.length === 0) {
        mesh.isVisible = false;
        return;
      }
      mesh.isVisible = true;
      const key = lines.join('\n');
      if (key === drawn) return;
      drawn = key;
      draw(lines);
    },
    dispose() {
      mesh.dispose(false, true);
    },
  };
}
