/**
 * ICE servers for the serverless mode: how two browsers find a path to each
 * other, and who gets to say which servers help them.
 *
 * Three layers, the first with anything usable in it wins:
 * 1. the client setting `network.iceServers`, a deployment's choice (its
 *    own TURN relay, or no public server at all);
 * 2. the world document's `ice-servers` on its `synchronization-service`;
 * 3. the default list below.
 *
 * A list is space-separated `stun:`, `stuns:`, `turn:` or `turns:` URLs
 * (RFC 7064/7065). A TURN entry carries its credentials as userinfo,
 * `turn:user:secret@host:port`, which the URI RFCs do not allow and this
 * grammar does, because there is no other place for them in one attribute.
 * A credential in a public document is a published credential: a
 * deployment that needs TURN gives out short-lived ones through the
 * setting, or accepts that the document's are readable by everyone.
 */

export interface IceServer {
  urls: string;
  username?: string;
  credential?: string;
}

/**
 * Two public STUN servers, both free of credentials and both carrying no
 * traffic: a STUN server only tells a browser its own public address.
 * Google's (stun.l.google.com:19302, long documented in WebRTC samples)
 * and Cloudflare's (stun.cloudflare.com:3478, from Cloudflare's Calls
 * documentation). Two, from two operators, so one being down is not a
 * silent failure to connect.
 */
export const DEFAULT_ICE_SERVERS: readonly IceServer[] = [
  { urls: 'stun:stun.l.google.com:19302' },
  { urls: 'stun:stun.cloudflare.com:3478' },
];

const SCHEME = /^(stuns?|turns?):/i;

/** One entry of a list: an ICE URL, or undefined with a warning. */
function parseOne(item: string, warn?: (message: string) => void): IceServer | undefined {
  const match = SCHEME.exec(item);
  if (!match) {
    warn?.(`[webverse] ice-servers: '${item}' is not a stun:/stuns:/turn:/turns: URL — skipped`);
    return undefined;
  }
  const scheme = match[1]!.toLowerCase();
  const rest = item.slice(match[0].length);
  const at = rest.lastIndexOf('@');
  if (at === -1 || !scheme.startsWith('turn')) return { urls: `${scheme}:${rest}` };
  const userinfo = rest.slice(0, at);
  const colon = userinfo.indexOf(':');
  if (colon === -1) {
    warn?.(`[webverse] ice-servers: '${item}' has a user and no credential — skipped`);
    return undefined;
  }
  return {
    urls: `${scheme}:${rest.slice(at + 1)}`,
    username: decodeURIComponent(userinfo.slice(0, colon)),
    credential: decodeURIComponent(userinfo.slice(colon + 1)),
  };
}

/** The servers a list names, in order; what is not an ICE URL is skipped with a warning. */
export function parseIceServers(text: string, warn?: (message: string) => void): IceServer[] {
  const out: IceServer[] = [];
  for (const item of text.split(/\s+/)) {
    if (item.length === 0) continue;
    const server = parseOne(item, warn);
    if (server) out.push(server);
  }
  return out;
}

/**
 * The servers to use: the setting, else the document, else the default. A
 * layer that names only unusable entries is warned about and passed over,
 * so a typo never silently turns the public STUN servers off.
 */
export function resolveIceServers(input: {
  setting?: readonly string[];
  document?: string;
  warn?: (message: string) => void;
}): IceServer[] {
  const { warn } = input;
  const fromSetting = parseIceServers((input.setting ?? []).join(' '), warn);
  if (fromSetting.length > 0) return fromSetting;
  if ((input.setting ?? []).some((s) => s.trim().length > 0)) {
    warn?.('[webverse] ice-servers: the client setting names no usable server — using the document or the default');
  }
  const fromDocument = parseIceServers(input.document ?? '', warn);
  if (fromDocument.length > 0) return fromDocument;
  if ((input.document ?? '').trim().length > 0) {
    warn?.('[webverse] ice-servers: the document names no usable server — using the default STUN list');
  }
  return DEFAULT_ICE_SERVERS.map((s) => ({ ...s }));
}
