/**
 * §7 synchronization selection.
 *
 * A world declares where its session lives; this decides which declaration
 * the shell would use. It decides **only that**. No socket is opened here,
 * no transport is named, and nothing in this file knows what a sync message
 * looks like — which is the point, because §7 says VEML privileges no
 * protocol and `type` is an open identifier whose wire belongs to the named
 * protocol's own specification.
 *
 * So the whole input is: the declarations, and the list of types this shell
 * implements. When that list is empty the answer is "stay static", and the
 * world is not broken — a conforming world requires no server at all.
 *
 * Every rule here is quoted from the spec at its use site, because the
 * tempting mistakes are all *reasonable*: ranking by the shell's own
 * preference instead of document order, failing a document over one bad
 * address, dropping a group the shell cannot use so an entity naming it
 * looks like a typo.
 */
import type { VemlSynchronizationService } from './documentModel';

/**
 * The sync protocols this shell actually implements, in no particular
 * order — §7 selection is by DOCUMENT order, never by this list's order.
 *
 * The shell speaks `worldsync` through the `@fivesqd/worldsync` client
 * (`createClient`) over the WebSocket binding (protocol Annex A), in
 * `src/net/worldsyncSession.ts`. A type belongs here only once its
 * transport works: naming one the shell cannot speak would select a
 * declaration it then fails to join, which is worse than staying static.
 */
export const IMPLEMENTED_SYNC_TYPES: readonly string[] = ['worldsync'];

/**
 * Schemes that name a local resource rather than a network endpoint.
 *
 * §1.4: "an `address` names a **network endpoint**: a local-resource scheme
 * (`file:`, `data:`, …) — or any scheme the named protocol does not
 * sanction — is a document error with its own resolution: the *declaration*
 * is unusable (warn), and fallback proceeds within its group."
 *
 * A deny-list rather than an allow-list, deliberately: VEML privileges no
 * protocol, so a scheme this shell has never heard of must still be allowed
 * through to whichever transport claims it. `manifest:` is here because the
 * same section says a sync address "is never `manifest:`-resolvable".
 */
const LOCAL_RESOURCE_SCHEMES = new Set([
  'file',
  'data',
  'blob',
  'about',
  'javascript',
  'filesystem',
  'manifest',
]);

/** Why a declaration could not be used, in words an author can act on. */
export interface SyncSelectionWarning {
  /** Stable slug for the diagnostic id. */
  slug: string;
  /** The sentence. Carries the offending value wherever there is one. */
  detail: string;
}

/** One `id`'s fallback group, after §7 has been applied to it. */
export interface SyncGroup {
  /** The author-chosen name entities refer to via `<synchronizer service="…"/>`. */
  id: string;
  /**
   * The room, taken from the FIRST declaration in the group.
   *
   * §7: "Declarations in one group MUST name the same `session`
   * (differing sessions: the first declaration's wins, warn) — fallback
   * changes transport, never the room."
   */
  session: string;
  /** Every declaration naming this id, in document order, usable or not. */
  members: VemlSynchronizationService[];
  /**
   * The one this shell would use, or undefined when it can use none.
   *
   * Undefined is not the same as the group being absent: an entity naming
   * this id stays static *with a warning*, rather than being told it named
   * something that does not exist.
   */
  chosen?: VemlSynchronizationService;
}

export interface SyncSelection {
  /** Groups in the order their first declaration appears. */
  groups: SyncGroup[];
  warnings: SyncSelectionWarning[];
  /** The group an entity's `synchronizer` names, or undefined. */
  groupFor(id: string): SyncGroup | undefined;
}

/**
 * The ONE declaration this shell attaches to for presence: the first group
 * in document order that has a usable declaration.
 *
 * §7 lets a document declare several groups and lets entities name one
 * each; presence — where THIS shell's user is — is not an entity and names
 * none. So the first usable group is the room the user
 * walks into, and a document that wants a different room for presence puts
 * it first. Undefined when nothing is usable, which is the static world.
 */
export function chooseSession(
  selection: SyncSelection,
): { type: string; address: string; id: string; session: string; iceServers?: string } | undefined {
  for (const group of selection.groups) {
    const chosen = group.chosen;
    if (chosen === undefined) continue;
    // `chosen` passed the usability checks above, so these are present.
    return {
      type: chosen.type!.trim(),
      address: chosen.address!.trim(),
      id: group.id,
      session: group.session,
      ...(chosen.iceServers !== undefined ? { iceServers: chosen.iceServers } : {}),
    };
  }
  return undefined;
}

/** True when the address names something this shell may dereference at all. */
function isNetworkEndpoint(address: string): boolean {
  const match = /^([A-Za-z][A-Za-z0-9+.-]*):/.exec(address.trim());
  // No scheme at all is a relative reference, which cannot name an
  // endpoint on another host. §7 addresses are absolute.
  if (!match) return false;
  return !LOCAL_RESOURCE_SCHEMES.has(match[1]!.toLowerCase());
}

/**
 * Apply §7 to a document's declarations.
 *
 * `implementedTypes` is what this shell can actually speak. It is compared
 * case-sensitively: `type` is a protocol identifier, and two identifiers
 * differing only in case are two identifiers.
 */
export function selectSynchronization(
  declarations: readonly VemlSynchronizationService[],
  implementedTypes: readonly string[],
): SyncSelection {
  const warnings: SyncSelectionWarning[] = [];
  const speaks = new Set(implementedTypes);
  const byId = new Map<string, SyncGroup>();
  const order: string[] = [];

  for (const d of declarations) {
    const id = d.id?.trim();
    if (!id) {
      // A declaration with no id can join no group, and §7 gives no way to
      // refer to it. Nothing can opt into it, so it is simply dropped.
      warnings.push({
        slug: 'no-id',
        detail: `a synchronization-service declaration has no id, so nothing can name it${
          d.address ? ` (address ${d.address})` : ''
        }`,
      });
      continue;
    }
    let group = byId.get(id);
    if (!group) {
      // The first declaration's session is the group's, whatever later
      // members say. Recorded before any usability check, because the room
      // is named by the group and not by the declaration we end up using.
      group = { id, session: d.session?.trim() ?? '', members: [] };
      byId.set(id, group);
      order.push(id);
    }
    group.members.push(d);
  }

  for (const id of order) {
    const group = byId.get(id)!;

    // "Declarations in one group MUST name the same `session`" — checked
    // across EVERY member, including ones we cannot use. A disagreement
    // hidden behind a bad address is still a disagreement, and the author
    // is the only one who can fix it.
    for (const member of group.members) {
      const session = member.session?.trim() ?? '';
      if (session && session !== group.session) {
        warnings.push({
          slug: 'session-conflict',
          detail:
            `synchronization group "${id}" names two sessions ` +
            `("${group.session}" then "${session}"); using the first — ` +
            `fallback changes transport, never the room`,
        });
      }
    }

    // "a shell uses the first whose `type` it implements" — document order,
    // not this shell's preference. Ranking by preference would silently
    // override the author's ordering, which is the only thing a group does.
    for (const member of group.members) {
      const type = member.type?.trim();
      const address = member.address?.trim();
      const session = member.session?.trim();

      const missing = [
        type ? '' : 'type',
        address ? '' : 'address',
        session ? '' : 'session',
      ].filter(Boolean);
      if (missing.length > 0) {
        warnings.push({
          slug: 'incomplete',
          detail: `a declaration in synchronization group "${id}" has no ${missing.join(' and no ')}, so it cannot be used`,
        });
        continue;
      }
      if (!isNetworkEndpoint(address!)) {
        warnings.push({
          slug: 'not-a-network-endpoint',
          detail:
            `synchronization address ${address} in group "${id}" does not name a network ` +
            `endpoint, so that declaration is unusable`,
        });
        continue;
      }
      if (!speaks.has(type!)) continue; // not an error: we just do not speak it
      group.chosen = member;
      break;
    }

    if (!group.chosen) {
      // Said once per group, and deliberately not phrased as the document
      // being wrong — most of the time it is a shell that implements none
      // of the offered transports, which is a conforming outcome.
      warnings.push({
        slug: 'no-usable-declaration',
        detail:
          `synchronization group "${id}" has no usable declaration for this shell ` +
          `(offered: ${group.members.map((m) => m.type?.trim() || '(no type)').join(', ')}); ` +
          `entities naming it stay static`,
      });
    }
  }

  const groups = order.map((id) => byId.get(id)!);
  return { groups, warnings, groupFor: (id) => byId.get(id) };
}
