/**
 * WebXR entry for both boots: the Enter VR button, the support probe,
 * the enter handler, exit on a world change, and the per-frame VR tick.
 *
 * It lives outside `main.ts` so that published worlds, which boot through
 * self-boot, get the same VR entry: someone opening a world's link in a
 * headset browser can enter it. The VR controls follow the world
 * (`session.worldControlFlags()`, fed by the `client-hints` profile's
 * `hints:vr`), and the head's pose is exposed for what the others see.
 *
 * Babylon-free (the xr hygiene suite pins it): the shell passes plain
 * callbacks for the feet, and the code-split chunk is reached only through
 * the loader, on the first Enter press, so a flat session never pays for it.
 */
import { createEnterVrButton } from './enterVrButton';
import { isImmersiveVrSupported } from './xrSupport';
import {
  defaultXrChunkLoader,
  type ImmersiveSessionController,
  type XrChunkLoader,
  type XrHeadPose,
  type XrInputFrame,
  type XrSessionOptions,
  type XrVec3,
} from './xrTypes';

/** The face of the world session VR needs (both boots hold one). */
export interface VrWorldSession {
  state(): { loaded: boolean };
  active(): { scene: unknown };
  worldControlFlags(): ReturnType<NonNullable<XrSessionOptions['getControlFlags']>>;
  portals(): unknown;
  walkableMeshes(): unknown;
  /** The entity a controller ray hits, by id (the desktop click's candidate set). */
  pickEntityAlongRay(ray: unknown): string | null;
  /** Run an entity's on-click, as a mouse click does. */
  dispatchEntityClick(id: string): void;
}

export interface VrEntryDeps {
  doc: Document;
  /** The engine in use: WebXR presents on WebGL2 only (see xrSupport). */
  engineKind: string;
  session: VrWorldSession;
  /** The visitor's current feet (the flat-screen controller's). */
  feet(): XrVec3;
  teleportFeet(x: number, y: number, z: number): void;
  /** VR stick movement through the same grounding and collision as desktop. */
  stepFeet(dx: number, dz: number, dtS: number): XrVec3;
  navigate(href: string): void;
  onXrInput?(frame: XrInputFrame): void;
  createPointerAffordance: NonNullable<XrSessionOptions['createPointerAffordance']>;
  /** Default: the code-split chunk. */
  loader?: XrChunkLoader;
  /** Default: `navigator.xr.isSessionSupported('immersive-vr')`. */
  supported?: () => Promise<boolean>;
  /**
   * Loads the page again in WebGL2, where VR presents (vrReload.ts). Given,
   * the button is offered on any engine, and a press on another one calls
   * this instead of starting VR; absent, it is offered on WebGL2 only.
   */
  reloadForVr?: () => void;
  log: { warn(...args: unknown[]): void };
  /**
   * The messages in the headset: the lines the flat panel shows now,
   * and a factory for the panel drawn in view (made on Enter, fed each VR
   * frame, disposed when the session ends). Absent → no panel in VR.
   */
  messagesHud?: {
    lines(): string[];
    create(scene: unknown): { show(lines: readonly string[]): void; dispose(): void };
  };
}

export interface VrEntry {
  isPresenting(): boolean;
  /** The per-frame VR tick; true when it ran (the caller skips the desktop tick). */
  tick(dtMs: number): boolean;
  /** The head's pose while presenting; null otherwise. */
  headPose(): XrHeadPose | null;
  /** The world lifecycle: loaded enables the button; unloading ends any session. */
  worldLoaded(loaded: boolean): void;
  /** What the button does; exposed for the boots' tests and hooks. */
  enter(): Promise<void>;
  dispose(): void;
}

export function mountVrEntry(deps: VrEntryDeps): VrEntry {
  const loader = deps.loader ?? defaultXrChunkLoader;
  let controller: ImmersiveSessionController | undefined;
  let hud: { show(lines: readonly string[]): void; dispose(): void } | undefined;
  let enterInFlight = false;
  const dropHud = (): void => {
    hud?.dispose();
    hud = undefined;
  };
  let disposed = false;

  const button = createEnterVrButton(deps.doc, {
    onEnter: () => void enter(),
    onExit: () => void controller?.exit().catch(() => {}),
  });
  // The probe is cheap and Babylon-free; boot never waits on it.
  void (deps.supported ?? (() => isImmersiveVrSupported()))().then((supported) => {
    // On WebGL2 VR presents; on another engine only where the page can load again in WebGL2 (xrSupport.ts).
    if (!disposed) button.setAvailable(supported && (deps.reloadForVr !== undefined || deps.engineKind === 'webgl2'));
  });

  // Exit-on-nav: a session is bound to the scene it entered.
  const release = (): void => {
    dropHud();
    if (!controller) return;
    controller.dispose();
    controller = undefined;
    button.setPresenting(false);
  };

  const enter = async (): Promise<void> => {
    if (controller?.isPresenting() || enterInFlight || disposed) return;
    if (!deps.session.state().loaded) return;
    if (deps.engineKind !== 'webgl2') return deps.reloadForVr?.();
    enterInFlight = true;
    try {
      const mod = await loader();
      if (disposed || !deps.session.state().loaded) return;
      // A world swap can finish while the session is being made; never bind to
      // a torn-down scene (use-after-free guard).
      const enterScene = deps.session.active().scene;
      const made = await mod.createImmersiveSession({
        scene: enterScene,
        getFeetPosition: () => deps.feet(),
        onEntered: () => button.setPresenting(true),
        // Seamless return: the flat view resumes where the headset was.
        onExited: (exitFeet) => {
          button.setPresenting(false);
          deps.teleportFeet(exitFeet.x, exitFeet.y, exitFeet.z);
        },
        getControlFlags: () => deps.session.worldControlFlags(),
        stepLocomotion: (dx, dz, dt) => deps.stepFeet(dx, dz, dt),
        onXrInput: (frame) => deps.onXrInput?.(frame),
        getPortalCandidates: () => deps.session.portals(),
        getWalkableMeshes: () => deps.session.walkableMeshes(),
        navigateHref: (href) => deps.navigate(href),
        // A trigger on a button: the same pick and the same handler as a click.
        pickEntityAlongRay: (ray) => deps.session.pickEntityAlongRay(ray),
        clickEntity: (id) => deps.session.dispatchEntityClick(id),
        teleportFeetTo: (x, y, z) => deps.teleportFeet(x, y, z),
        createPointerAffordance: deps.createPointerAffordance,
      });
      if (disposed || !deps.session.state().loaded || deps.session.active().scene !== enterScene) {
        made.dispose();
        return;
      }
      controller = made;
      // A headset- or system-started exit: release the session for a clean re-enter.
      made.onStateChange((presenting) => {
        button.setPresenting(presenting);
        if (!presenting && controller === made) {
          dropHud();
          made.dispose();
          controller = undefined;
        }
      });
      // The messages panel in view, for this session's scene.
      hud = deps.messagesHud?.create(enterScene);
      await made.enter();
    } catch (err) {
      // No device, a rejected chunk, any enter failure: the flat view stays.
      deps.log.warn('[webverse] Enter VR failed:', err);
      release();
    } finally {
      enterInFlight = false;
    }
  };

  return {
    isPresenting: () => controller?.isPresenting() === true,
    tick(dtMs) {
      if (!controller?.isPresenting()) return false;
      controller.tick(dtMs);
      if (hud && deps.messagesHud) hud.show(deps.messagesHud.lines());
      return true;
    },
    headPose: () => (controller?.isPresenting() ? controller.headPose() : null),
    worldLoaded(loaded) {
      button.setWorldLoaded(loaded);
      if (!loaded) release();
    },
    enter,
    dispose() {
      if (disposed) return;
      disposed = true;
      release();
      button.dispose();
    },
  };
}
