/**
 * Messages: the stream. What the shell, the people in the room, and
 * the world have said, as lines a person reads.
 *
 * Sans-DOM and sans-strings: a message is posted as (channel, kind, fields)
 * and becomes text through the TEMPLATE the settings hold for that kind.
 * The stream has no words of its own — easy defaults that are always
 * customizable means every sentence a person sees is data that
 * a user, an embedder, or a page can change without a rebuild. What is kept
 * (`maxLines`), for how long (`fadeMs`) and which channels are shown are
 * settings too, read live on every call.
 *
 * The panel (`messagesPanel.ts`) draws this; an embedder that wants its own
 * UI subscribes here and draws nothing of ours.
 */
import type { ShellMessagesSettings } from '../settings/shellSettings';
import type { CapabilityReport } from '../capabilities/capabilityRegistry';

export type MessageChannel = 'shell' | 'people' | 'world';

export interface Message {
  readonly channel: MessageChannel;
  /** The template key — `joined`, `chat`, `reconnecting` … */
  readonly kind: string;
  /** Rendered text. Plain text: a field is never markup, and the panel escapes. */
  readonly text: string;
  /** When it was said, on the injected clock. */
  readonly at: number;
}

export interface MessageStreamDeps {
  settings: () => ShellMessagesSettings;
  /** The clock. Default: `Date.now`. */
  now?: () => number;
}

export interface MessageStream {
  /** Say something. Null when the kind has no template and no `text` field: nothing to say. */
  post(channel: MessageChannel, kind: string, fields: Record<string, string>): Message | null;
  /** The lines to draw now: shown channels only, unfaded, the last `maxLines`, newest last. */
  visible(): readonly Message[];
  /**
   * The recent history: the last `n` lines on shown channels, faded or
   * not, newest last. What the panel draws while the chat line is open.
   */
  history(n: number): readonly Message[];
  /** Hear each message as it is posted. Returns the unsubscribe. */
  subscribe(listener: (message: Message) => void): () => void;
}

/**
 * The SHELL channel's mapping from a world-lifecycle event to a message.
 * Pure, so the one place the shell speaks for itself is tested, not a literal
 * buried in `main.ts`. Only the two events a person cares about; the rest are
 * console detail.
 */
export function shellMessageForLifecycle(
  event: { kind: string; title?: string | null; url?: string },
): { kind: string; fields: Record<string, string> } | null {
  if (event.kind === 'world-entered') return { kind: 'entered', fields: { title: event.title ?? '' } };
  if (event.kind === 'load-failed') return { kind: 'load-failed', fields: { url: event.url ?? '' } };
  return null;
}

/**
 * A world script's `Logging.Log` reaches the WORLD channel only at the
 * DEFAULT level. A warning or an error is a developer's, and stays in the
 * console; it does not wash over a visitor's Messages panel.
 */
export function worldMessageReachesPanel(level: string): boolean {
  return level === 'default';
}

/**
 * The worldsync session says seven kinds through one `say`. Joins,
 * leaves and chat are the PEOPLE in the room; the connection story —
 * reconnecting, back, refused, ended — is the SHELL's own notice, so turning
 * the people channel off never silences "connection lost" or "refused".
 */
const SHELL_SESSION_KINDS: ReadonlySet<string> = new Set(['reconnecting', 'back', 'refused', 'ended', 'unreachable']);

export function channelForSessionMessage(kind: string): 'shell' | 'people' {
  return SHELL_SESSION_KINDS.has(kind) ? 'shell' : 'people';
}

/** The session's `say` deps callback: route each kind to its channel. Pure, so the wiring in worldSession.ts is a reference to tested code, not a literal. */
export function routeSessionMessage(
  onMessage: (channel: MessageChannel, kind: string, fields: Record<string, string>) => void,
): (kind: string, fields: Record<string, string>) => void {
  return (kind, fields) => onMessage(channelForSessionMessage(kind), kind, fields);
}

/**
 * A capability gap is a shell-channel line (the `capability` template).
 * One line per gap from the capability report: feature×count and the reason.
 */
export function capabilityMessages(report: CapabilityReport): Array<{ kind: string; fields: Record<string, string> }> {
  return report.gaps.map((gap) => ({ kind: 'capability', fields: { text: `${gap.feature}×${gap.count}: ${gap.reason}` } }));
}

/** `{name}` → fields.name; an unknown placeholder renders empty. */
export function renderTemplate(template: string, fields: Record<string, string>): string {
  return template.replace(/\{([a-zA-Z0-9_-]+)\}/g, (_, key: string) => fields[key] ?? '');
}

/** Lines kept for history, whatever `maxLines` draws. */
export const HISTORY_LIMIT = 200;

export function createMessageStream(deps: MessageStreamDeps): MessageStream {
  const now = deps.now ?? (() => Date.now());
  const kept: Message[] = [];
  const listeners = new Set<(message: Message) => void>();

  return {
    post(channel, kind, fields) {
      const template = deps.settings().templates[kind];
      const text = template === undefined ? fields['text'] : renderTemplate(template, fields);
      if (text === undefined) return null;
      const message: Message = { channel, kind, text, at: now() };
      kept.push(message);
      // Keep a history; `maxLines` bounds what is drawn, not what is
      // kept. Never fewer than `maxLines`, so an embedder asking for more
      // than HISTORY_LIMIT lines still gets them.
      const keep = Math.max(HISTORY_LIMIT, Math.floor(deps.settings().maxLines));
      if (kept.length > keep) kept.splice(0, kept.length - keep);
      for (const listener of listeners) {
        try {
          listener(message);
        } catch {
          // A listener's failure is its own; the message was said.
        }
      }
      return message;
    },

    visible() {
      const { channels, fadeMs, maxLines } = deps.settings();
      const t = now();
      const max = Math.max(0, Math.floor(maxLines));
      if (max === 0) return [];
      const lastLines = kept.filter((m) => channels[m.channel]).slice(-max);
      return lastLines.filter((m) => fadeMs <= 0 || t - m.at < fadeMs);
    },

    history(n) {
      const { channels } = deps.settings();
      const count = Math.max(0, Math.floor(n));
      if (count === 0) return [];
      return kept.filter((m) => channels[m.channel]).slice(-count);
    },

    subscribe(listener) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
  };
}
