export interface ScriptEntityApiDeps {
  scene: Scene;
  registry: EntityRegistry;
  camera: FreeCamera;
  controller: FirstPersonController;
  /** The world's own URL (with its query) — the `World.GetQueryParam` source. */
  worldUrl: string;
  /** The NavigationController seam (script nav == portal nav == hash nav). Absent → no-op. */
  navigate?: (url: string) => void;
  /**
   * The WORLD-owned environment handle (`AppliedEnvironment`),
   * the target of the WORLD-LEVEL `Environment.SetSkyTexture`/`SetSolidColorSky`
   * (drives the EXISTING sky subsystem at runtime). Absent → the Environment.*
   * bridges are safe no-ops returning `false`.
   */
  environment?: AppliedEnvironment;
  /**
   * Register a script-created `button`'s on-click call-string into
   * the SAME `entityOnClick` map the click dispatcher reads (`worldSession`
   * owns the map; a script button coexists additively with VEML buttons). Absent
   * → a script button is still pickable but its click is inert (a safe degrade).
   */
  onClickRegister?: (id: string, handler: string) => void;
  /** Drop a button's on-click record on delete-cascade (churn-clean). */
  onClickUnregister?: (id: string) => void;
  /**
   * The live DESKTOP input-state source for the `Input` polling API
   * (`GetMoveValue`/`GetLookValue`/`GetKeyValue`/`IsVR`), supplied by the page
   * (`main.ts`/`selfBootCore.ts`) over the EXISTING `desktopInput`/
   * `firstPersonController`/xr state. Absent → the polling defaults to zero/false.
   * `GetPointerRaycast` is NOT here — it reuses THIS host's `camera`+`registry`.
   */
  scriptInput?: ScriptInputStateProvider;
  /** Test/prod seams mirrored from buildWorld (the glb factory path). */
  gltfChunkLoader?: () => Promise<GltfChunkModule>;
  fetchImpl?: typeof fetch;
  engineKind?: string;
  onProgress?: WorldLoadProgressListener;
  /** The world's shadow rig: a script-built mesh casts and receives like a declared one. */
  shadows?: ShadowRig;
  /** The world's physics rig: bodies for Physical entities, loaded on first demand. */
  physics?: PhysicsRig;
}

// --- plain-data coercion (the serializable boundary already delivered plain objects) ---
function vec3(v: Vec3Like | undefined, dflt = 0): Vector3 {
  return new Vector3(
    Number.isFinite(v?.x) ? (v as Vec3Like).x : dflt,
    Number.isFinite(v?.y) ? (v as Vec3Like).y : dflt,
    Number.isFinite(v?.z) ? (v as Vec3Like).z : dflt,
  );
}
function quat(q: QuatLike | undefined): Quaternion {
  // Default = identity (0,0,0,1).
  return new Quaternion(
    Number.isFinite(q?.x) ? (q as QuatLike).x : 0,
    Number.isFinite(q?.y) ? (q as QuatLike).y : 0,
    Number.isFinite(q?.z) ? (q as QuatLike).z : 0,
    Number.isFinite(q?.w) ? (q as QuatLike).w : 1,
  );
}
function toVec3Like(v: Vector3): Vec3Like {
  return { x: v.x, y: v.y, z: v.z };
}
function toQuatLike(q: Quaternion): QuatLike {
  return { x: q.x, y: q.y, z: q.z, w: q.w };
}

const defaultGltfChunkLoader = (): Promise<GltfChunkModule> => import('../engine/gltfChunk');

/**
 * A model's material that takes a person's colour: named `tint`
 * (profiles/client-hints.md). A clone keeps the name with the mirror's id
 * after a colon, so a re-tint still finds it.
 */
function isTintMaterial(name: string | undefined): boolean {
  return name === 'tint' || (name !== undefined && name.startsWith('tint:'));
}

/** A script Color (components 0..1) as the document's hex colour. */
function colorToHex(c: { r: number; g: number; b: number; a: number }): string {
  const h = (v: number): string =>
    Math.round(Math.min(1, Math.max(0, Number.isFinite(v) ? v : 0)) * 255)
      .toString(16)
      .padStart(2, '0');
  return `#${h(c.r)}${h(c.g)}${h(c.b)}${h(c.a)}`;
}

export function createScriptEntityApi(deps: ScriptEntityApiDeps): EntityApiHost {
  const { scene, registry, camera, controller, worldUrl } = deps;
  const gltfChunkLoader = deps.gltfChunkLoader ?? defaultGltfChunkLoader;
  // Per-world highlight state (side map, GC'd with the host). Not part of the
  // core op set (position/rotation/scale/visibility/parent/delete) — a minimal
  // best-effort emissive tint on StandardMaterial meshes; tracked as a boolean.
  const highlighted = new Set<string>();
  // The per-entity INTERACTION STATE (id → 'hidden'|'static'|
  // 'physical'|'placing'). A Map (own-property-safe — a forged '__proto__' state
  // never reaches it: the setter validates via a switch first). GC'd with the
  // host (a fresh host per world).
  const interactionStates = new Map<string, string>();
  // Warn ONCE that InteractionState.Physical degrades (v4 has no physics
  // engine; characters are kinematic); the corpus still renders.
  // The per-entity TEXT record (id → { entity, texture }) for `text`
  // and `input` entities, backing SetText/GetText's live glyph content. A Map
  // (own-property-safe; a forged '__proto__' id never reaches it). Holds a
  // MUTABLE synth VemlTextEntity (SetText mutates .text) + the DynamicTexture
  // (SetText redraws via the SAME `drawTextPlane` create uses). GC'd with the
  // host; entries dropped on delete-cascade.
  const textRecords = new Map<string, { entity: VemlTextEntity; texture: DynamicTexture }>();
  /**
   * A glb entity's animation clips, by entity id, for `animateMirror`.
   * Disposed with the entity (a registry disposer); dropped here on delete.
   */
  const clipsById = new Map<string, AnimationGroup[]>();
  /** A mirror's name label (a billboard plane over the head), by entity id. */
  const labelById = new Map<string, Mesh>();

  /**
   * The name over a mirror's head. A world-space text plane from the
   * same builder VEML `<text>` uses, parented to the mirror's root so it
   * follows, billboarded so it reads from anywhere. Height is the default
   * avatar's (1.76 m) plus a hand — a capsule mirror gets the same label at
   * the same height, which is fine: the label says who, not how tall.
   */
  const attachLabel = (id: string, text: string, height?: number): void => {
    const root = rootOf(id);
    if (!root) return;
    const existing = labelById.get(id);
    if (existing) existing.dispose(false, true);
    try {
      attachLabelPlane(id, text, root, height);
    } catch (err) {
      // No canvas to draw text on (a headless engine), or anything else: the
      // person still appears, unnamed. Said once, never thrown.
      log.warn(`[webverse] net: label for ${id} could not be drawn:`, err);
    }
  };

  /**
   * Draw a mirror's avatar in its person's colour. Each material is
   * CLONED first: the default avatar's materials may be shared, and tinting
   * one person must not tint everyone. PBR and standard materials both.
   *
   * Which parts take the colour (profiles/client-hints.md, hints:people
   * tint): a material named `tint` if the model has one, and the whole model
   * otherwise. The default avatar names its body `tint`, so its eyes keep
   * their own colour.
   */
  const tintMirror = (id: string, c: { r: number; g: number; b: number }): void => {
    const root = rootOf(id);
    if (!root) return;
    const meshes = root.getChildMeshes(false).filter((m) => !m.name.startsWith('label:'));
    const named = meshes.some((m) => isTintMaterial(m.material?.name));
    for (const mesh of meshes) {
      if (named && !isTintMaterial(mesh.material?.name)) continue;
      // Structural, not Babylon's Material type: materials may only be
      // imported through a registered manifest module (check-shader-imports).
      type Tintable = {
        name: string;
        clone(name: string): Tintable | null;
        albedoColor?: { copyFromFloats(r: number, g: number, b: number): unknown };
        diffuseColor?: { copyFromFloats(r: number, g: number, b: number): unknown };
      };
      const material = mesh.material as unknown as Tintable | null;
      if (!material) continue;
      const own = material.clone(`${material.name}:${id}`);
      if (!own) continue;
      own.albedoColor?.copyFromFloats(c.r, c.g, c.b);
      own.diffuseColor?.copyFromFloats(c.r, c.g, c.b);
      mesh.material = own as unknown as typeof mesh.material;
    }
  };

  const attachLabelPlane = (id: string, text: string, root: TransformNode, height?: number): void => {
    // Sized to the name, on a dark pill, just above the head — or at the
    // height the world's `people.label-height` gives.
    const built = createNameLabelPlane(id, text, scene);
    built.mesh.parent = root;
    built.mesh.position.set(0, height ?? built.layout.centerY, 0);
    // The billboard presents the plane's BACK to the camera, so the text
    // arrives upside down. The mesh cannot be turned to fix it: Babylon
    // composes a billboard from the DECOMPOSED scale, so a negative scale
    // is read as a rotation and thrown away with the rest. The flip is made
    // in the TEXTURE instead (v' = 1 - v; the offset keeps a clamped texture
    // in range).
    built.texture.vScale = -1;
    built.texture.vOffset = 1;
    built.mesh.billboardMode = 7; // BILLBOARDMODE_ALL — face the camera on every axis
    built.mesh.isPickable = false;
    labelById.set(id, built.mesh);
  };

  // ==================== CHARACTER PHYSICS & MOTION (state) ====================
  // The per-world CHARACTER MOTION records (id → the KINEMATIC motion state). A
  // Map (own-property-safe — a forged '__proto__' id is a normal member). Created
  // on createEntity(kind:'character') (BOTH the capsule + glb paths); dropped on
  // delete-cascade; GC'd with the host (a fresh host per world → no cross-world
  // motion; a nav tears it down). Kinematic, for a character without a body: the state
  // holds the vertical velocity (Jump adds, gravity integrates) + the SURFACE/FREE
  // mode (SetPhysicalProperties.gravitational toggle). `walkables` is a FILTERED
  // WalkableSource that excludes the character's OWN meshes (a character must not
  // self-ground on its own capsule) — a reusable scratch array → allocation-free.
  interface CharacterMotionRecord {
    node: TransformNode;
    /** The collider mesh (rootNode when it is a mesh — the corpus capsule); else null (glb degrade). */
    collider: AbstractMesh | null;
    /** The character's own meshes (excluded from its ground probe). */
    ownMeshes: Set<AbstractMesh>;
    /** A stored filtered WalkableSource (reuses a scratch array — allocation-free). */
    walkables: WalkableSource;
    state: CharacterKinematicState;
    /** 'surface' = gravity + grounding active; 'free' = free-fly (SetPosition-driven). */
    mode: 'surface' | 'free';
    /** The recorded EntityPhysicalProperties (RECORDED-NOT-SIMULATED except gravitational). */
    props: PhysicalPropertiesSpec;
  }
  const characters = new Map<string, CharacterMotionRecord>();
  /** Physical properties set on entities that are not characters (the round trip for GetPhysicalProperties). */
  const bodyProps = new Map<string, PhysicalPropertiesSpec>();
  /** The five fields, finite and boolean checked, own-property only. */
  const recordProps = (props: PhysicalPropertiesSpec): PhysicalPropertiesSpec => {
    const recorded: PhysicalPropertiesSpec = {};
    if (typeof props.angularDrag === 'number' && Number.isFinite(props.angularDrag)) recorded.angularDrag = props.angularDrag;
    if (typeof props.drag === 'number' && Number.isFinite(props.drag)) recorded.drag = props.drag;
    if (typeof props.mass === 'number' && Number.isFinite(props.mass)) recorded.mass = props.mass;
    const com = props.centerOfMass;
    if (com && typeof com === 'object') {
      recorded.centerOfMass = {
        x: Number.isFinite(com.x) ? com.x : 0,
        y: Number.isFinite(com.y) ? com.y : 0,
        z: Number.isFinite(com.z) ? com.z : 0,
      };
    }
    if (typeof props.gravitational === 'boolean') recorded.gravitational = props.gravitational;
    return recorded;
  };

  // THE LOCAL-vs-MIRROR ISOLATION AUTHORITY (registry-side half). The
  // ids that are REMOTE-avatar MIRRORS (created by `createMirror` from a peer's
  // broadcast) — the ONLY ids a PEER may move/rotate/delete via the net bridge's
  // `moveMirror`/`rotateMirror`/`deleteMirror`. A LOCALLY-AUTHORED entity id is
  // NEVER in here, so a peer can never reach it. Critically, `createEntity` DROPS an
  // id from this set the moment a local author (re)registers it: if a malicious peer
  // PRE-CLAIMED an id (mirror-first) that the world then AUTHORS (local-second — the
  // registry overwrites the mirror node), the id ceases to be a mirror and the
  // peer's subsequent move/delete for it become no-ops. A `Set<string>`, so
  // a `__proto__`/`constructor` id is a plain member (pollution-immune).
  const mirrorIds = new Set<string>();

  /** Register a character's KINEMATIC motion record (default FREE —
   * SetPosition-driven, so plain positioning and camera-follow keep working; gravity opts in via
   * SetPhysicalProperties(gravitational=true), which the corpus always calls). */
  const registerCharacterMotion = (
    id: string,
    node: TransformNode,
    meshes: readonly AbstractMesh[],
  ): void => {
    const ownMeshes = new Set<AbstractMesh>(meshes);
    const scratch: AbstractMesh[] = [];
    const walkables: WalkableSource = () => {
      scratch.length = 0;
      for (const m of registry.walkableMeshes()) {
        if (!ownMeshes.has(m)) scratch.push(m);
      }
      return scratch;
    };
    characters.set(id, {
      node,
      collider: characterCollider(node),
      ownMeshes,
      walkables,
      state: { verticalVelocityMps: 0, grounded: false },
      mode: 'free',
      props: {},
    });
  };

  /** The live character record for an id, or null (guards non-character). */
  const characterOf = (id: string): CharacterMotionRecord | null => {
    const entry = registry.get(id);
    if (!entry || entry.isDisposed() || entry.type !== 'character') return null;
    const rec = characters.get(id);
    return rec ?? null;
  };

  // ==================== CAMERA & RIG FOLLOWERS (state) ========================
  // The third-person camera chain. All targets are entity ID STRINGS (handle-as-
  // id — NO live node crosses); resolved per frame in `updateFollowers`. GC'd
  // with the host (a fresh host per world → no cross-world following; a nav tears
  // it down). The Sets store strings → prototype-pollution-immune (a `__proto__`
  // id is a normal member).
  //
  // Direction A — camera-follows-entity (AttachToEntity/PlaceCameraOn): the
  // camera rides the entity's world pose + a LOCAL offset, via the controller.
  let cameraAttachTargetId: string | null = null;
  const cameraAttachOffset = { x: 0, y: 0, z: 0 };
  // Direction B — entity-follows-camera / entity-follows-rig: the follower ENTITY
  // rides the camera / the rig origin each frame.
  const cameraFollowers = new Set<string>();
  const rigFollowers = new Set<string>();
  // Scratch objects reused each frame (no per-frame allocation in the loop).
  const followScratchPos = new Vector3();
  const followScratchQuat = new Quaternion();
  const followOffsetVec = new Vector3();

  /** Turn camera-attach off + restore free-look (idempotent). */
  const detachCamera = (): void => {
    if (cameraAttachTargetId === null) return;
    cameraAttachTargetId = null;
    cameraAttachOffset.x = 0;
    cameraAttachOffset.y = 0;
    cameraAttachOffset.z = 0;
    controller.setExternalPositionControl(false);
  };

  /** Attach the camera to an entity (camera-follows-entity). `null`
   * detaches + restores free-look. A forged/foreign/stale id → false. */
  const attachCameraToEntity = (id: string | null, offset?: Vec3Like): boolean => {
    if (id === null || id === undefined) {
      detachCamera();
      return true;
    }
    const key = String(id);
    if (!registry.get(key)) return false; // deny-by-default
    cameraAttachTargetId = key;
    if (offset) {
      cameraAttachOffset.x = Number.isFinite(offset.x) ? offset.x : 0;
      cameraAttachOffset.y = Number.isFinite(offset.y) ? offset.y : 0;
      cameraAttachOffset.z = Number.isFinite(offset.z) ? offset.z : 0;
    }
    // The script API's AttachToEntity/PlaceCameraOn takes NO offset — leave the existing
    // offset (default {0,0,0}) so the corpus's follow-up Camera.SetPosition sets
    // it. The controller now rides the entity (its own motion suspended).
    controller.setExternalPositionControl(true);
    return true;
  };

  /** The live Babylon Light for a `light` entity, found by NAME
   * (`light:${tag}`). Works for BOTH script-created (rootNode carrier) AND
   * VEML-authored (NO rootNode — parented to the parent entity's node) lights,
   * because both name the Light `light:${tag}` in `createLightEntity`. */
  const lightOf = (id: string): Light | null => {
    const entry = registry.get(id);
    if (!entry || entry.isDisposed() || entry.type !== 'light') return null;
    return scene.getLightByName(`light:${entry.tag}`) ?? null;
  };

  /** The canonical class of a live Babylon light. */
  const lightClassOf = (light: Light): 'point' | 'directional' | 'spot' | 'other' => {
    if (light instanceof PointLight) return 'point';
    if (light instanceof DirectionalLight) return 'directional';
    if (light instanceof SpotLight) return 'spot';
    return 'other';
  };

  /** The entity's carrier node (all built types own a rootNode carrier). */
  const rootOf = (id: string): TransformNode | undefined => {
    const entry = registry.get(id);
    return entry && !entry.isDisposed() ? entry.rootNode : undefined;
  };

  /** Build the StandardMaterial for a primitive from a script `Color`. */
  const materialFromColor = (name: string, color: ColorLike | undefined): StandardMaterial => {
    const mat = new StandardMaterial(name, scene);
    if (color) {
      mat.diffuseColor = new Color3(
        Number.isFinite(color.r) ? color.r : 0.5,
        Number.isFinite(color.g) ? color.g : 0.5,
        Number.isFinite(color.b) ? color.b : 0.5,
      );
      if (Number.isFinite(color.a) && color.a < 1) mat.alpha = color.a;
    } else {
      mat.diffuseColor = new Color3(0.5, 0.5, 0.5);
    }
    return mat;
  };

  /** Apply the script transform (LOCAL under the parent, as SetPosition(pos, true)). */
  const applyScriptTransform = (
    node: TransformNode,
    spec: CreateEntitySpec,
    meshes: readonly AbstractMesh[],
  ): void => {
    const position = { x: spec.position?.x ?? 0, y: spec.position?.y ?? 0, z: spec.position?.z ?? 0 };
    const rotation = quat(spec.rotation);
    const scl = spec.scale ?? { x: 1, y: 1, z: 1 };
    if (spec.isSize) {
      applyVemlTransform(
        node,
        { kind: 'sizetransform', position, rotation: toQuatLike(rotation), size: scl },
        { allowScale: true, allowSize: true, originalSize: () => encapsulatedSize(meshes) },
      );
    } else {
      applyVemlTransform(
        node,
        { kind: 'scaletransform', position, rotation: toQuatLike(rotation), scale: scl },
        { allowScale: true, allowSize: false },
      );
    }
  };

  const encapsulatedSize = (meshes: readonly AbstractMesh[]): Vector3 => {
    let min: Vector3 | null = null;
    let max: Vector3 | null = null;
    for (const mesh of meshes) {
      mesh.computeWorldMatrix(true);
      const box = mesh.getBoundingInfo().boundingBox;
      min = min === null ? box.minimumWorld.clone() : Vector3.Minimize(min, box.minimumWorld);
      max = max === null ? box.maximumWorld.clone() : Vector3.Maximize(max, box.maximumWorld);
    }
    return min && max ? max.subtract(min) : new Vector3(1, 1, 1);
  };

  const resolveParent = (parentId: string | null | undefined): TransformNode | null => {
    if (!parentId) return null;
    return rootOf(parentId) ?? null;
  };

  const mintId = (id: string | null | undefined): string =>
    typeof id === 'string' && id.length > 0 ? id : crypto.randomUUID();

  // A script UI element's proportional placement within its parent
  // canvas frame's unit rect, built from the `positionPercent`/`sizePercent`
  // Vector2s (mapped DIRECTLY onto a `VemlCanvasTransform` — the SAME shape
  // `placeUiChild` consumes for VEML UI). Absent → undefined (placeUiChild
  // default-fills). Percents finite-guarded, size defaults to 1.
  const uiChildTransform = (spec: CreateEntitySpec): VemlCanvasTransform | undefined => {
    if (!spec.positionPercent && !spec.sizePercent) return undefined;
    const pp = spec.positionPercent;
    const sp = spec.sizePercent;
    return {
      kind: 'canvastransform',
      positionPercent: {
        x: Number.isFinite(pp?.x) ? (pp as Vec3Like).x : 0.5,
        y: Number.isFinite(pp?.y) ? (pp as Vec3Like).y : 0.5,
      },
      sizePercent: {
        x: Number.isFinite(sp?.x) ? (sp as Vec3Like).x : 1,
        y: Number.isFinite(sp?.y) ? (sp as Vec3Like).y : 1,
      },
    };
  };

  // The sibling index of a NEW child under `parentId` (for the
  // per-child z-step that avoids coplanar z-fighting between UI planes). The
  // new plane is not parented yet, so `children().length` is the correct index.
  const siblingIndexOf = (parentId: string | null | undefined): number =>
    parentId ? registry.children(parentId).length : 0;

  // The SHARED async glb load path (so BOTH `mesh` and
  // `character`-with-a-model register through the SAME code — registry-identical,
  // hollow-handle, spawn-hidden, onLoaded on success / onError on failure). The
  // registered `type` distinguishes them; everything else is identical.
  /**
   * Glb loads IN FLIGHT, id → a generation. A glb entity is not in the
   * registry until its bytes have loaded, so a delete in that window finds
   * nothing there; without this, the load would then register a ghost that
   * every later create for the id is refused against (a peer who leaves a
   * second after its first pose). A delete, or a new create for the same id,
   * bumps the generation; a load that comes back to find it is not the
   * current one disposes what it loaded and registers nothing.
   */
  const loading = new Map<string, number>();
  /** Generations come from ONE counter, so a stale load can never match a later load's number by coincidence. */
  let loadSeq = 0;
  /** Abandon whatever load is in flight for `id`; true when there was one. The map holds only CURRENT loads. */
  const abandonLoad = (id: string): boolean => loading.delete(id);

  const loadGlbEntity = (
    id: string,
    tag: string,
    type: string,
    url: string,
    spec: CreateEntitySpec,
    parentNode: TransformNode | null,
    onLoaded?: () => void,
    onError?: (message: string) => void,
  ): void => {
    const gen = (loadSeq += 1);
    loading.set(id, gen);
    const current = (): boolean => loading.get(id) === gen;
    const settle = (): void => {
      if (current()) loading.delete(id);
    };
    void (async (): Promise<void> => {
      try {
        const bytes = await fetchAssetBytes(url, deps.onProgress, deps.fetchImpl);
        if (scene.isDisposed) return; // world torn down mid-stream — drop silently
        const chunk = await gltfChunkLoader();
        if (scene.isDisposed) return;
        const container = await chunk.loadGlbContainer(bytes, scene, `${tag}.glb`, deps.engineKind, { baseUrl: url });
        if (scene.isDisposed) return;
        // ONE generation check, here, after everything that can be awaited:
        // the id was deleted or reclaimed while the bytes were on their way,
        // so what loaded is nobody's. (Checks after the earlier awaits would
        // save some parsing, but would also mask a missing check here — so
        // there is exactly one.)
        if (!current()) {
          container.dispose();
          return;
        }
        settle();
        container.addAllToScene();
        const root = new TransformNode(`${type}:${tag}`, scene);
        for (const n of container.rootNodes) n.parent = root;
        for (const m of container.meshes) m.checkCollisions = true;
        deps.shadows?.track(container.meshes);
        applyScriptTransform(root, spec, container.meshes);
        root.parent = parentNode;
        root.setEnabled(false); // SPAWN HIDDEN
        // The clips ride with the entity. A MIRROR starts silent (its
        // session decides idle/walk); a script's own glb keeps Babylon's
        // default of playing what it loaded.
        const clips = [...container.animationGroups];
        const skeletons = [...container.skeletons];
        if (mirrorIds.has(id)) for (const g of clips) g.stop();
        clipsById.set(id, clips);
        registry.register({
          id,
          tag,
          type,
          assetUrl: url,
          rootNode: root,
          meshes: [...container.meshes],
          materials: [...container.materials],
          textures: [...container.textures],
          disposers: [
            () => {
              for (const g of clips) g.dispose();
              for (const s of skeletons) s.dispose();
            },
          ],
        });
        // A glb character gets a KINEMATIC motion record too (the root
        // is a TransformNode, not a mesh → collider null → position-move + ground-
        // probe degrade, no wall collision; the corpus's third-person avatar is the
        // no-mesh capsule path with full collision).
        if (type === 'character') registerCharacterMotion(id, root, container.meshes);
        if (onLoaded) onLoaded(); // SUCCESS
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err);
        log.warn(`[webverse] script ${type} '${tag}' failed to load ${url}: ${message}`);
        if (scene.isDisposed || !current()) return; // world torn down, or the id gone, mid-load — settle nothing
        settle();
        registry.registerErrored({ id, tag, type, assetUrl: url, message });
        // The ASYNC-failure channel (onError → the promise rejects; absent →
        // onLoaded fires on failure too, as legacy scripts expect).
        if (onError) onError(message);
        else if (onLoaded) onLoaded();
      }
    })();
  };

  return {
    createEntity(
      spec: CreateEntitySpec,
      onLoaded?: () => void,
      onError?: (message: string) => void,
    ): string {
      const id = mintId(spec.id);
      // A LOCAL author (re)claims this id: it is no longer a peer
      // mirror. This closes the PRE-CLAIM isolation hole — if a peer pre-claimed
      // this id as a mirror, the mirror node is overwritten below and the id drops
      // out of the mirror-authority set, so a peer can no longer move/delete it.
      // (createMirror re-adds the id AFTER this, for the genuine-mirror path.)
      mirrorIds.delete(id);
      abandonLoad(id); // an older glb still loading for this id is nobody's now
      const tag = typeof spec.tag === 'string' && spec.tag.length > 0 ? spec.tag : id;
      const kind = spec.kind;
      const parentNode = resolveParent(spec.parentId);

      // --- primitive (the 11) ---
      if (PRIMITIVE_SET.has(kind)) {
        const mesh = createPrimitiveMesh(kind as VemlPrimitiveType, `${kind}:${tag}`, scene);
        const material = materialFromColor(`${kind}:${tag}:mat`, spec.color);
        mesh.material = material;
        mesh.checkCollisions = true;
        deps.shadows?.track([mesh]);
        applyScriptTransform(mesh, spec, [mesh]);
        mesh.parent = parentNode;
        mesh.setEnabled(false); // SPAWN HIDDEN until SetVisibility(true)
        registry.register({ id, tag, type: kind, rootNode: mesh, meshes: [mesh], materials: [material] });
        if (onLoaded) onLoaded();
        return id;
      }

      // --- container ---
      if (kind === 'container') {
        const node = new TransformNode(`container:${tag}`, scene);
        applyScriptTransform(node, spec, []);
        node.parent = parentNode;
        node.setEnabled(false);
        registry.register({ id, tag, type: 'container', rootNode: node });
        if (onLoaded) onLoaded();
        return id;
      }

      // --- light ---
      if (kind === 'light') {
        const root = new TransformNode(`light:${tag}`, scene);
        applyScriptTransform(root, spec, []);
        root.parent = parentNode;
        // The light sits at the carrier's origin (identity transform) and rides
        // under it — moving/hiding the carrier moves/hides the light uniformly.
        const synth = { tag, castShadows: false } as unknown as VemlLightEntity;
        const light = createLightEntity(synth, scene, root);
        root.setEnabled(false);
        registry.register({ id, tag, type: 'light', rootNode: root, disposers: [() => light.dispose()] });
        if (onLoaded) onLoaded();
        return id;
      }

      // --- mesh (glb via meshResources[0]) — async; hollow handle until onLoaded ---
      if (kind === 'mesh') {
        const url = spec.meshResources?.[0] ?? spec.meshObject ?? '';
        if (url.length === 0) {
          log.warn(`[webverse] script mesh '${tag}': no mesh-resource — nothing to load`);
          if (onLoaded) onLoaded();
          return id;
        }
        loadGlbEntity(id, tag, 'mesh', url, spec, parentNode, onLoaded, onError);
        return id;
      }

      // --- character (KINEMATIC) — registry-identical to a mesh ---
      // No-mesh (the corpus's `CharacterEntity.Create(null, pos, …)`) → a default
      // CAPSULE body (the visible kinematic avatar, the default-capsule
      // character the script API promises). Mesh form → the SAME async glb path.
      // Motion (Move/Jump/SetPhysicalProperties) runs on the kinematic record below.
      // meshOffset/meshRotation/labelOffset are RECORDED-NOT-APPLIED (the
      // character model transform + label are not implemented).
      if (kind === 'character') {
        const url = spec.meshResources?.[0] ?? spec.meshObject ?? '';
        if (url.length > 0) {
          loadGlbEntity(id, tag, 'character', url, spec, parentNode, onLoaded, onError);
          return id;
        }
        const body = createPrimitiveMesh('capsulemesh', `character:${tag}`, scene);
        body.material = materialFromColor(`character:${tag}:mat`, spec.color);
        body.checkCollisions = true;
        deps.shadows?.track([body]);
        applyScriptTransform(body, spec, [body]);
        body.parent = parentNode;
        body.setEnabled(false); // SPAWN HIDDEN until SetVisibility(true)
        registry.register({
          id,
          tag,
          type: 'character',
          rootNode: body,
          meshes: [body],
          materials: [body.material as StandardMaterial],
        });
        // The KINEMATIC motion record (the corpus capsule → full
        // moveWithCollisions wall+floor collision; default FREE mode).
        registerCharacterMotion(id, body, [body]);
        if (onLoaded) onLoaded();
        return id;
      }

      // --- world-space UI — wrap the uiEntity builders so a
      // script-created UI element is REGISTRY-IDENTICAL to a VEML-parsed one
      // (same registry/pick/dispose paths; honors SetVisibility/SetInteractionState/
      // Delete-cascade). The canvas FRAME registers as a mesh-less carrier; the
      // text/image/button/input planes register with { rootNode, materials, textures }.
      if (kind === 'canvas') {
        const frame = createCanvasFrame(tag, scene);
        applyScriptTransform(frame, spec, []);
        frame.parent = parentNode;
        frame.setEnabled(false); // SPAWN HIDDEN
        registry.register({ id, tag, type: 'canvas', rootNode: frame });
        if (onLoaded) onLoaded();
        return id;
      }

      if (kind === 'text' || kind === 'input') {
        // InputEntity DEGRADES to a text-field-shaped text plane (v4 has no live
        // world-space keyboard-capture widget). Both use
        // the VEML text builder; SetText/GetText drive the DynamicTexture.
        const synth: VemlTextEntity = {
          type: 'text',
          tag,
          text: typeof spec.text === 'string' ? spec.text : '',
          fontSize: Number.isFinite(spec.fontSize) ? spec.fontSize : undefined,
          children: [],
          placementSockets: [],
        };
        const build = createTextPlane(synth, scene);
        placeUiChild(build.mesh, uiChildTransform(spec), siblingIndexOf(spec.parentId));
        build.mesh.parent = parentNode;
        build.mesh.setEnabled(false); // SPAWN HIDDEN
        registry.register({
          id,
          tag,
          type: kind,
          rootNode: build.mesh,
          materials: [build.material],
          textures: build.texture ? [build.texture] : undefined,
        });
        if (build.texture) {
          textRecords.set(id, { entity: synth, texture: build.texture as DynamicTexture });
        }
        if (onLoaded) onLoaded();
        return id;
      }

      if (kind === 'image') {
        // Resolve the image path against the world URL (relative to the world);
        // a malformed URL falls back to the raw string.
        const raw = typeof spec.imageFile === 'string' ? spec.imageFile : '';
        let resolved = raw;
        if (raw.length > 0) {
          try {
            resolved = new URL(raw, worldUrl).href;
          } catch {
            resolved = raw;
          }
        }
        const synth: VemlImageEntity = {
          type: 'image',
          tag,
          imageFile: raw.length > 0 ? { raw, resolved } : undefined,
          children: [],
          placementSockets: [],
        };
        const build = createImagePlane(synth, scene);
        placeUiChild(build.mesh, uiChildTransform(spec), siblingIndexOf(spec.parentId));
        build.mesh.parent = parentNode;
        build.mesh.setEnabled(false); // SPAWN HIDDEN
        registry.register({
          id,
          tag,
          type: 'image',
          rootNode: build.mesh,
          materials: [build.material],
          textures: build.texture ? [build.texture] : undefined,
        });
        if (onLoaded) onLoaded();
        return id;
      }

      if (kind === 'button') {
        const onClick = typeof spec.onClick === 'string' ? spec.onClick : undefined;
        const synth: VemlButtonEntity = {
          type: 'button',
          tag,
          onClickEvent: onClick,
          children: [],
          placementSockets: [],
        };
        const build = createButtonPlane(synth, scene);
        placeUiChild(build.mesh, uiChildTransform(spec), siblingIndexOf(spec.parentId));
        build.mesh.parent = parentNode;
        build.mesh.setEnabled(false); // SPAWN HIDDEN
        registry.register({
          id,
          tag,
          type: 'button',
          rootNode: build.mesh,
          materials: [build.material],
        });
        // Register the on-click into the SAME entityOnClick map the click
        // dispatcher reads (a script button's click EXECUTES its handler).
        if (onClick && onClick.length > 0) deps.onClickRegister?.(id, onClick);
        if (onLoaded) onLoaded();
        return id;
      }

      log.warn(`[webverse] script: unknown entity kind '${kind}' — nothing created`);
      if (onLoaded) onLoaded();
      return id;
    },

    // Create a remote-avatar MIRROR for an inbound peer entity, via
    // the SAME `createEntity` factory (registry-identical, handle-as-id, the
    // peer's exact id honored by `mintId`). Spawn-then-visible: `createEntity`
    // spawns HIDDEN, so `onLoaded → setVisibility(true)` reveals the inbound
    // mirror. A remote character is the kinematic `CharacterEntity` in default
    // FREE mode (no gravity — driven purely by inbound broadcasts, never by
    // local physics). DEDUP/COLLISION guard: if the id already names a LIVE
    // local entity (a mirror already created, OR a locally-authored entity) → false,
    // NO overwrite (the local-vs-mirror isolation's create half). Only the corpus
    // set (character/mesh/container) is supported; any other → false+warn.
    createMirror(spec: NetMirrorSpec): boolean {
      const type = spec?.type;
      if (type !== 'character' && type !== 'mesh' && type !== 'container') {
        log.warn(`[webverse] net: unsupported mirror entity type '${String(type)}' — skipped (deferred full-parity).`);
        return false;
      }
      const id = typeof spec.id === 'string' ? spec.id : '';
      if (!id) return false;
      // COLLISION/DEDUP — never overwrite a live local entity (authored or mirror).
      if (registry.get(id)) {
        log.warn(`[webverse] net: mirror create for existing id '${id}' — deduped (no overwrite).`);
        return false;
      }
      const tag = typeof spec.tag === 'string' && spec.tag.length > 0 ? spec.tag : id;
      const url = typeof spec.url === 'string' && spec.url.length > 0 ? spec.url : undefined;
      const label = typeof spec.label === 'string' && spec.label.length > 0 ? spec.label : undefined;
      const tint = spec.tint;
      const labelHeight = typeof spec.labelHeight === 'number' && Number.isFinite(spec.labelHeight) ? spec.labelHeight : undefined;
      const fallbackUrl = typeof spec.fallbackUrl === 'string' && spec.fallbackUrl.length > 0 ? spec.fallbackUrl : undefined;
      const createSpec: CreateEntitySpec = {
        kind: type,
        id,
        tag,
        position: spec.position,
        rotation: spec.rotation,
        // An avatar: the same glb path a script's CharacterEntity.Create(mesh, …) takes.
        ...(url !== undefined ? { meshResources: [url] } : {}),
      };
      // A `container` has no visual but is registry-identical; a `mesh` mirror with
      // no resource is a hollow node (the corpus mirrors CHARACTERS — the capsule
      // path — so this is the hot path). Spawn-then-visible on load; the label
      // goes on once there is a root to hang it from.
      const reveal = (): void => {
        this.setVisibility(id, true);
        if (label !== undefined) attachLabel(id, label, labelHeight);
        if (tint !== undefined) tintMirror(id, tint);
      };
      // A world's avatar that will not load: the shell's own instead
      // (profiles/client-hints.md, `veml:client-hints:avatar-unloadable`).
      const failed = (): void => {
        if (fallbackUrl === undefined || !mirrorIds.has(id)) {
          reveal();
          return;
        }
        log.warn(`[webverse] veml:client-hints:avatar-unloadable ${url ?? ''} — drawing the next avatar`);
        this.deleteMirror(id);
        const { fallbackUrl: _dropped, fallbackUrls: later = [], ...rest } = spec;
        const [next, ...after] = later;
        this.createMirror({
          ...rest,
          url: fallbackUrl,
          ...(next === undefined ? {} : { fallbackUrl: next }),
          ...(after.length ? { fallbackUrls: after } : {}),
        });
      };
      // MARK it a mirror BEFORE the load resolves, so the async glb path can
      // tell a mirror (clips start silent) from a script's own entity — and
      // AFTER createEntity's synchronous start, which clears the id first.
      this.createEntity(createSpec, reveal, failed);
      mirrorIds.add(id);
      return true;
    },

    // THE PEER-FACING mirror mutators (the local-vs-mirror isolation's
    // move/delete half). Applied ONLY when the id is a genuine mirror (`mirrorIds`);
    // a locally-authored id — including one that OVERWROTE a pre-claimed mirror — is
    // NOT a mirror, so a peer's move/rotate/delete is refused. Distinct from
    // the script-facing `setPosition`/`setRotation`/`delete` (those are unrestricted
    // — a local script owns its scene; a PEER does not).
    moveMirror(id: string, position: Vec3Like): boolean {
      if (!mirrorIds.has(id)) return false;
      return this.setPosition(id, position, false);
    },
    rotateMirror(id: string, rotation: QuatLike): boolean {
      if (!mirrorIds.has(id)) return false;
      return this.setRotation(id, rotation, false);
    },
    deleteMirror(id: string): boolean {
      if (!mirrorIds.has(id)) return false;
      mirrorIds.delete(id);
      return this.delete(id);
    },
    isMirror(id: string): boolean {
      return mirrorIds.has(id);
    },
    animateMirror(id: string, clip: string): boolean {
      // The isolation rule again: a peer animates only what a peer created.
      if (!mirrorIds.has(id)) return false;
      const clips = clipsById.get(id);
      const wanted = clips?.find((g) => g.name === clip);
      if (!clips || !wanted) return false;
      for (const g of clips) if (g !== wanted && g.isPlaying) g.stop();
      if (!wanted.isPlaying) wanted.play(true);
      return true;
    },

    get(id: string): string | null {
      return registry.get(id) ? id : null;
    },
    getByTag(tag: string): string | null {
      return registry.findByTag(tag)?.id ?? null;
    },
    getAll(): string[] {
      return registry.all().map((e) => e.id);
    },
    getTag(id: string): string | null {
      return registry.get(id)?.tag ?? null;
    },
    getType(id: string): string | null {
      // The registered entity kind (character/mesh/container/…), for
      // the outbound sync create-topic mapping. Null if gone.
      return registry.get(id)?.type ?? null;
    },

    getPosition(id: string, local: boolean): Vec3Like | null {
      const node = rootOf(id);
      if (!node) return null;
      node.computeWorldMatrix(true);
      return toVec3Like(local ? node.position : node.getAbsolutePosition());
    },
    setPosition(id: string, pos: Vec3Like, local: boolean): boolean {
      const node = rootOf(id);
      if (!node) return false;
      const v = vec3(pos);
      if (local || !node.parent) node.position.copyFrom(v);
      else node.setAbsolutePosition(v);
      node.computeWorldMatrix(true);
      return true;
    },
    getRotation(id: string, local: boolean): QuatLike | null {
      const node = rootOf(id);
      if (!node) return null;
      node.computeWorldMatrix(true);
      if (local) {
        return toQuatLike(node.rotationQuaternion ?? Quaternion.FromEulerVector(node.rotation));
      }
      return toQuatLike(node.absoluteRotationQuaternion);
    },
    setRotation(id: string, rot: QuatLike, local: boolean): boolean {
      const node = rootOf(id);
      if (!node) return false;
      const q = quat(rot);
      if (local || !node.parent) {
        node.rotationQuaternion = q;
      } else {
        // World rotation on a parented node: local = parentWorld^-1 * world.
        const parent = node.parent as TransformNode;
        parent.computeWorldMatrix(true);
        const parentInv = Quaternion.Inverse(parent.absoluteRotationQuaternion);
        node.rotationQuaternion = parentInv.multiply(q);
      }
      node.computeWorldMatrix(true);
      return true;
    },
    getScale(id: string): Vec3Like | null {
      const node = rootOf(id);
      return node ? toVec3Like(node.scaling) : null;
    },
    setScale(id: string, scale: Vec3Like): boolean {
      const node = rootOf(id);
      if (!node) return false;
      node.scaling.copyFrom(vec3(scale, 1));
      return true;
    },

    // ==================== TRANSFORM COMPLETION ====================

    // GetTransform — a plain-data snapshot derived on demand (handle-as-id — NO
    // live node crosses). position/rotation ABSOLUTE (world); scale LOCAL (the
    // script API's GetTransform reports local scale). forward/right/up in the LH
    // Y-up convention via Babylon's OWN axes rotated by the world quaternion — do
    // NOT hand-roll a sign-guessed cross-product (its handedness is easy to get
    // wrong). `up` is a v4 ADDITION (the legacy Transform exposes only forward/right).
    getTransform(id: string): TransformSnapshot | null {
      const node = rootOf(id);
      if (!node) return null;
      node.computeWorldMatrix(true);
      const rot = node.absoluteRotationQuaternion;
      const fwd = new Vector3(0, 0, 1);
      fwd.rotateByQuaternionToRef(rot, fwd);
      const rgt = new Vector3(1, 0, 0);
      rgt.rotateByQuaternionToRef(rot, rgt);
      const up = new Vector3(0, 1, 0);
      up.rotateByQuaternionToRef(rot, up);
      return {
        position: toVec3Like(node.getAbsolutePosition()),
        rotation: toQuatLike(rot),
        scale: toVec3Like(node.scaling),
        forward: toVec3Like(fwd),
        right: toVec3Like(rgt),
        up: toVec3Like(up),
      };
    },

    // GetSize — the entity's encapsulated WORLD-BOUNDS size (original mesh
    // size · mesh scaling; the rendered bounding dimensions), REAL-
    // WORLD dimensions distinct from getScale's raw multiplier. Carrier-less /
    // mesh-less entity (container/light) has no bounds → degrade to scale.
    getSize(id: string): Vec3Like | null {
      const entry = registry.get(id);
      if (!entry || entry.isDisposed() || !entry.rootNode) return null;
      const meshes = entry.ownedMeshes();
      if (meshes.length > 0) return toVec3Like(encapsulatedSize(meshes));
      return toVec3Like(entry.rootNode.scaling); // size==scale degrade
    },
    // SetSize — drive the node scaling so the entity's world-bounds become `size`
    // via the EXISTING vemlTransform `computeSizeScale` (the sizetransform factor
    // math). originalSize (unscaled) = worldBounds / currentScaling per-axis
    // (SIZE_EPSILON_M-guarded). Carrier-less → degrade to raw scale.
    setSize(id: string, size: Vec3Like): boolean {
      const entry = registry.get(id);
      if (!entry || entry.isDisposed() || !entry.rootNode) return false;
      const node = entry.rootNode;
      const target = vec3(size, 1);
      const meshes = entry.ownedMeshes();
      if (meshes.length === 0) {
        node.scaling.copyFrom(target); // size==scale degrade (no bounds)
        return true;
      }
      const bounds = encapsulatedSize(meshes);
      const scl = node.scaling;
      const original = new Vector3(
        Math.abs(scl.x) < SIZE_EPSILON_M ? bounds.x : bounds.x / scl.x,
        Math.abs(scl.y) < SIZE_EPSILON_M ? bounds.y : bounds.y / scl.y,
        Math.abs(scl.z) < SIZE_EPSILON_M ? bounds.z : bounds.z / scl.z,
      );
      node.scaling = computeSizeScale({ x: target.x, y: target.y, z: target.z }, original);
      node.computeWorldMatrix(true);
      return true;
    },

    // GetEulerRotation — DEGREES, read back from the quaternion with Babylon's
    // own toEulerAngles (the inverse of the FromEulerAngles used by setter → a
    // guaranteed round-trip). local → local quaternion; world → absolute.
    getEulerRotation(id: string, local: boolean): Vec3Like | null {
      const node = rootOf(id);
      if (!node) return null;
      node.computeWorldMatrix(true);
      const q = local
        ? node.rotationQuaternion ?? Quaternion.FromEulerVector(node.rotation)
        : node.absoluteRotationQuaternion;
      const e = q.toEulerAngles();
      return { x: e.x * RAD_TO_DEG, y: e.y * RAD_TO_DEG, z: e.z * RAD_TO_DEG };
    },
    // SetEulerRotation — DEGREES → radians → Babylon's own FromEulerAngles. World
    // on a parented node uses parentAbsRotInv · q (the SAME setRotation-world
    // math — do NOT improvise handedness).
    setEulerRotation(id: string, euler: Vec3Like, local: boolean): boolean {
      const node = rootOf(id);
      if (!node) return false;
      const e = vec3(euler, 0);
      const q = Quaternion.FromEulerAngles(e.x * DEG_TO_RAD, e.y * DEG_TO_RAD, e.z * DEG_TO_RAD);
      if (local || !node.parent) {
        node.rotationQuaternion = q;
      } else {
        const parent = node.parent as TransformNode;
        parent.computeWorldMatrix(true);
        const parentInv = Quaternion.Inverse(parent.absoluteRotationQuaternion);
        node.rotationQuaternion = parentInv.multiply(q);
      }
      node.computeWorldMatrix(true);
      return true;
    },

    getParent(id: string): string | null {
      const node = rootOf(id);
      if (!node) return null;
      const parent = registry.findByRootNode(node.parent as TransformNode | null);
      return parent?.id ?? null;
    },
    setParent(id: string, parentId: string | null): boolean {
      const node = rootOf(id);
      if (!node) return false;
      if (parentId === null) {
        node.setParent(null); // detach to scene root (world transform preserved)
      } else {
        const parent = resolveParent(parentId);
        if (!parent) return false;
        // DENY a cycle (self-parent, or reparenting under our own descendant):
        // Babylon `setParent` would set the parent pointer BEFORE it crashes in
        // `_syncParentEnabledState`, corrupting the live scene graph — every later
        // computeWorldMatrix/isEnabled/teardown then recurses to a stack overflow
        // (a cheap untrusted-script DoS). Walk the proposed parent's ancestor
        // chain; if it already contains `node`, the reparent would close a loop.
        for (let a: TransformNode | null = parent; a; a = a.parent as TransformNode | null) {
          if (a === node) {
            log.warn(`[webverse] script SetParent: refused (would create a parent cycle) on entity ${id}`);
            return false;
          }
        }
        node.setParent(parent); // preserves WORLD transform
      }
      registry.invalidateCaches();
      return true;
    },
    getChildren(id: string): string[] {
      return registry.children(id).map((e) => e.id);
    },
    getVisibility(id: string): boolean {
      const node = rootOf(id);
      return node ? node.isEnabled(false) : false;
    },
    setVisibility(id: string, visible: boolean): boolean {
      const node = rootOf(id);
      if (!node) return false;
      node.setEnabled(!!visible);
      registry.invalidateCaches(); // a hidden→shown mesh becomes walkable next tick
      return true;
    },
    getHighlight(id: string): boolean {
      return highlighted.has(id);
    },
    setHighlight(id: string, highlight: boolean): boolean {
      const entry = registry.get(id);
      if (!entry) return false;
      const on = !!highlight;
      if (on) highlighted.add(id);
      else highlighted.delete(id);
      // Best-effort emissive tint on StandardMaterial meshes (minimal — not part
      // of the core op set; a marker that highlight state round-trips).
      for (const mesh of entry.ownedMeshes()) {
        const mat = mesh.material as StandardMaterial | null;
        if (mat && mat.emissiveColor) {
          mat.emissiveColor = on ? new Color3(0.3, 0.3, 0.3) : new Color3(0, 0, 0);
        }
      }
      return true;
    },
    delete(id: string): boolean {
      const entry = registry.get(id);
      if (!entry) {
        // Nothing registered yet, but a glb may be on its way: abandon
        // it, and forget the marks a create put down before the load.
        if (!abandonLoad(id)) return false;
        mirrorIds.delete(id);
        return true;
      }
      // CASCADE to the descendant subtree (disposing only the parent NODE —
      // Babylon recursively disposes child nodes — would LEAVE child ENTITIES as
      // stale registry entries). Collect the
      // full descendant set via the entity-tree-on-demand (registry.children,
      // DERIVED from the one-way scene graph — NO synced second tree) FIRST,
      // before any disposal nulls the live parent pointers `children` reads;
      // then dispose post-order (children before parent). Each dispose() is
      // idempotent + removes its own registry entry (a later parent node dispose
      // re-hits already-disposed child nodes harmlessly).
      const ordered: RegisteredEntity[] = [];
      const seen = new Set<string>();
      const collect = (eid: string): void => {
        if (seen.has(eid)) return; // guard a corrupt cycle (setParent already denies these)
        seen.add(eid);
        for (const child of registry.children(eid)) collect(child.id);
        const e = registry.get(eid);
        if (e) ordered.push(e); // post-order: descendants precede this entity
      };
      collect(id);
      for (const e of ordered) {
        highlighted.delete(e.id);
        mirrorIds.delete(e.id); // drop the mirror-authority marker
        clipsById.delete(e.id); // the groups themselves go with the registry disposer
        labelById.get(e.id)?.dispose(false, true); // the name plane, its material and texture
        labelById.delete(e.id);
        interactionStates.delete(e.id); // drop the interaction-state record
        bodyProps.delete(e.id);
        deps.physics?.remove(e.id); // and its body
        textRecords.delete(e.id); // drop the text/input glyph record
        characters.delete(e.id); // drop the character motion record (a mid-arc Jump dies cleanly)
        deps.onClickUnregister?.(e.id); // drop the button on-click record
        e.dispose(); // removes from the registry + disposes the node + invalidates caches
      }
      return true;
    },
    compare(idA: string, idB: string): boolean {
      // Two handles are equal iff they name the same live entity.
      return idA === idB && registry.get(idA) !== undefined;
    },

    worldGetQueryParam(key: string): string | null {
      if (typeof key !== 'string' || isReservedParamName(key)) return null; // shell-reserved params are never exposed to scripts
      return worldQueryParams(worldUrl).get(key);
    },
    worldLoadWorld(url: string): void {
      if (typeof url === 'string' && url.length > 0) deps.navigate?.(url);
    },
    worldLoadWebPage(url: string): void {
      if (typeof url === 'string' && url.length > 0) deps.navigate?.(url);
    },
    worldGetLoadState(): string {
      // Scripts run only after the world has entered — the active state.
      return 'loadedworld';
    },

    cameraGetPosition(_local: boolean): Vec3Like | null {
      return toVec3Like(camera.position);
    },
    cameraSetPosition(pos: Vec3Like, _local: boolean): boolean {
      const v = vec3(pos);
      // WHILE camera-attached, `Camera.SetPosition(offset, local)`
      // sets the third-person LOCAL OFFSET (the corpus `Camera.SetPosition(0,1,
      // -2, true)` immediately after `PlaceCameraOn`), NOT a feet teleport (the
      // controller is under external-position-control; a teleport would be
      // overwritten by the follow loop next frame anyway). The follow loop
      // applies the offset in the entity's frame.
      if (cameraAttachTargetId !== null) {
        cameraAttachOffset.x = v.x;
        cameraAttachOffset.y = v.y;
        cameraAttachOffset.z = v.z;
        return true;
      }
      // The Camera "position" is the EYE (= feet + EYE_HEIGHT_M); teleport the
      // FEET so the camera lands at `pos` (the controller's teleport idiom).
      controller.teleportFeet(new Vector3(v.x, v.y - EYE_HEIGHT_M, v.z));
      return true;
    },
    cameraGetRotation(_local: boolean): QuatLike | null {
      // Camera orientation from the controller's yaw/pitch (Babylon FreeCamera
      // rotation = (pitch, yaw, roll)).
      return toQuatLike(
        Quaternion.RotationYawPitchRoll(camera.rotation.y, camera.rotation.x, camera.rotation.z),
      );
    },
    cameraSetRotation(rot: QuatLike, _local: boolean): boolean {
      const q = quat(rot);
      // Feed yaw/pitch back into the controller (a direct camera.rotation write
      // is reverted by syncCamera). LH Y-up: forward = quat·(0,0,1); yaw =
      // atan2(fwd.x, fwd.z), pitch = asin(-fwd.y). Do NOT improvise handedness.
      const fwd = new Vector3(0, 0, 1);
      fwd.rotateByQuaternionToRef(q, fwd);
      const yaw = Math.atan2(fwd.x, fwd.z);
      const clampedY = Math.max(-1, Math.min(1, -fwd.y));
      const pitch = Math.asin(clampedY);
      controller.setOrientation(yaw, pitch);
      return true;
    },

    // ==================== CAMERA & RIG FOLLOWERS ====================
    // See the state block above + sandboxTypes `EntityApiHost` doc. Handle-as-id:
    // every target is an entity ID string, resolved per frame in updateFollowers.

    // Direction A — camera-follows-entity. `id === null` detaches + restores
    // free-look. A forged/absent id → false.
    cameraAttachToEntity(id: string | null, offset?: Vec3Like): boolean {
      return attachCameraToEntity(id, offset);
    },
    // `CharacterEntity.PlaceCameraOn()` == `AttachToEntity(entity)` with no offset.
    entityPlaceCameraOn(id: string): boolean {
      return attachCameraToEntity(String(id));
    },
    // Direction B — entity-follows-camera. The follower ENTITY rides the camera.
    cameraAddFollower(id: string): boolean {
      const key = String(id);
      if (!registry.get(key)) return false;
      cameraFollowers.add(key);
      return true;
    },
    cameraRemoveFollower(id: string): boolean {
      return cameraFollowers.delete(String(id));
    },
    // Direction B — entity-follows-rig. The follower ENTITY rides the rig origin
    // (= controller feet + yaw). The recorded externalPositionControl seam — a
    // no-op suppress in v4 (the character is kinematic).
    inputAddRigFollower(id: string): boolean {
      const key = String(id);
      if (!registry.get(key)) return false;
      rigFollowers.add(key);
      return true;
    },
    inputRemoveRigFollower(id: string): boolean {
      return rigFollowers.delete(String(id));
    },
    // The per-frame follow loop (worldSession.updateFollowers → here), AFTER
    // tickScripts + controller/xr tick. Re-resolves every id (disposed-guard).
    updateFollowers(isPresenting: boolean): void {
      // --- Direction A: camera-follows-entity ---
      if (cameraAttachTargetId !== null) {
        const node = rootOf(cameraAttachTargetId);
        if (!node) {
          // Target Deleted (delete cascade) / disposed → detach + restore free-look.
          detachCamera();
        } else if (!isPresenting) {
          // VR-vs-attach precedence: while presenting, the WebXRCamera owns the
          // view — SKIP the camera drive (do NOT fight it). The controller stays
          // externally-controlled (its desktop tick is suspended in VR anyway).
          node.computeWorldMatrix(true);
          // Reuse a scratch vec for the local offset → NO per-frame allocation.
          followOffsetVec.set(cameraAttachOffset.x, cameraAttachOffset.y, cameraAttachOffset.z);
          Vector3.TransformCoordinatesToRef(followOffsetVec, node.getWorldMatrix(), followScratchPos);
          // Camera rotation rides the entity's world rotation (the offset already
          // rotated with it; this keeps the view aligned to the character facing).
          // NIT (top-level/quaternion-mode only, which the corpus always uses): the
          // quaternion branch reads the WORLD rotation (absoluteRotationQuaternion);
          // the euler fallback reads node.rotation (LOCAL) — equal for a top-level
          // entity, which is the corpus case (a script character is never parented).
          const rot = node.rotationQuaternion
            ? node.absoluteRotationQuaternion
            : Quaternion.FromEulerVectorToRef(node.rotation, followScratchQuat);
          controller.applyExternalCamera(followScratchPos, rot);
        }
      }
      // --- Direction B: entity-follows-camera ---
      if (cameraFollowers.size > 0) {
        // The FP camera is never parented (the controller owns it) → camera.
        // position IS its world position (no world-matrix recompute needed).
        for (const fid of cameraFollowers) {
          const node = rootOf(fid);
          if (!node) {
            cameraFollowers.delete(fid); // Deleted target → drop
            continue;
          }
          followScratchPos.copyFrom(camera.position);
          if (node.parent) node.setAbsolutePosition(followScratchPos);
          else node.position.copyFrom(followScratchPos);
          // Write the yaw/pitch/roll quat INTO the node's existing rotationQuaternion
          // (allocated once when a node first becomes a follower) → NO per-frame
          // allocation. NIT (top-level only, the corpus case): this writes the
          // camera's WORLD rotation into the node's rotationQuaternion, which is the
          // node's LOCAL slot — equal for a top-level follower (never parented here).
          if (!node.rotationQuaternion) node.rotationQuaternion = new Quaternion();
          Quaternion.RotationYawPitchRollToRef(
            camera.rotation.y,
            camera.rotation.x,
            camera.rotation.z,
            node.rotationQuaternion,
          );
          node.computeWorldMatrix(true);
        }
      }
      // --- Direction B: entity-follows-rig (rig origin = feet + yaw) ---
      if (rigFollowers.size > 0) {
        const feet = controller.feetPosition();
        // The rig heading = the camera yaw (LH Y-up: rotation.y is yaw).
        for (const fid of rigFollowers) {
          const node = rootOf(fid);
          if (!node) {
            rigFollowers.delete(fid);
            continue;
          }
          followScratchPos.copyFrom(feet);
          if (node.parent) node.setAbsolutePosition(followScratchPos);
          else node.position.copyFrom(followScratchPos);
          // Allocation-free yaw-only rotation into the node's existing quaternion
          // (see the camera-follower NIT above re: top-level/local-slot).
          if (!node.rotationQuaternion) node.rotationQuaternion = new Quaternion();
          Quaternion.RotationYawPitchRollToRef(camera.rotation.y, 0, 0, node.rotationQuaternion);
          node.computeWorldMatrix(true);
        }
      }
    },

    // ==================== CHARACTER PHYSICS & MOTION ====================
    // Kinematic without a body, a body otherwise: Move = collision-resolved world
    // displacement + ground-snap (SAME moveWithCollisions + groundProbe primitives
    // as the player); Jump = grounded-gated vertical impulse → a deterministic arc
    // integrated by updateCharacters; SetPhysicalProperties records the props +
    // toggles SURFACE↔FREE via gravitational. Handle-as-id: a {x,y,z} / a props
    // object crosses as plain data; the host guards the id names a character.

    characterMove(id: string, v: Vec3Like): boolean {
      const rec = characterOf(id);
      if (!rec) return false;
      const d = vec3(v);
      // SURFACE mode glues to the floor (grounded walking); FREE mode is free-fly.
      moveCharacter(rec.node, rec.collider, rec.walkables, d.x, d.y, d.z, rec.mode === 'surface', rec.state);
      return true;
    },
    characterJump(id: string, amount: number, discardIfFalling: boolean): boolean {
      const rec = characterOf(id);
      if (!rec) return false;
      if (!Number.isFinite(amount)) return false;
      // A Physical character jumps through its body: the engine owns the arc.
      if (deps.physics?.isSimulated(id)) {
        if (!deps.physics.resting(id) && discardIfFalling) return false;
        return deps.physics.launch(id, amount);
      }
      // Grounded-gate: jump only if on a surface or !discardIfFalling. Mid-air with
      // discardIfFalling (default true) is a no-op → false.
      const onSurface = isOnSurface(rec.collider, rec.node, rec.walkables);
      if (!onSurface && discardIfFalling) return false;
      rec.state.verticalVelocityMps += amount;
      rec.state.grounded = false;
      return true;
    },
    characterSetPhysicalProperties(id: string, props: PhysicalPropertiesSpec): boolean {
      if (!props || typeof props !== 'object') return false;
      const rec = characterOf(id);
      if (!rec) {
        // Not a character: the properties drive the entity's body, if it has
        // one or comes to have one, and are kept for the round trip.
        const entry = registry.get(id);
        if (!entry || entry.isDisposed()) return false;
        const recorded = recordProps(props);
        bodyProps.set(id, recorded);
        deps.physics?.setProperties(id, recorded);
        return true;
      }
      // Recorded for the round trip (own-property-guarded; a hostile props
      // object never pollutes). Without a body, `gravitational` alone moves
      // the character: SURFACE (gravity + grounding) or FREE. With a body, the
      // rig takes all five.
      const recorded = recordProps(props);
      if (recorded.gravitational !== undefined) {
        rec.mode = recorded.gravitational ? 'surface' : 'free';
        if (!recorded.gravitational) rec.state.verticalVelocityMps = 0; // free-fly: no residual fall
      }
      rec.props = recorded;
      deps.physics?.setProperties(id, recorded);
      return true;
    },
    characterGetPhysicalProperties(id: string): PhysicalPropertiesSpec | null {
      const rec = characterOf(id);
      const p = rec ? rec.props : bodyProps.get(id);
      if (!p) return null;
      // A guaranteed round-trip against the recorded props (plain data — no node).
      const out: PhysicalPropertiesSpec = {};
      if (p.angularDrag !== undefined) out.angularDrag = p.angularDrag;
      if (p.drag !== undefined) out.drag = p.drag;
      if (p.mass !== undefined) out.mass = p.mass;
      if (p.gravitational !== undefined) out.gravitational = p.gravitational;
      if (p.centerOfMass) out.centerOfMass = { ...p.centerOfMass };
      return out;
    },
    // The per-frame vertical integrator (a fixed-update analogue). SURFACE
    // mode only; FREE + grounded-idle characters early-out (allocation-free steady
    // state). Disposed-guard: a Deleted target is dropped from the map.
    updateCharacters(deltaMs: number): void {
      if (characters.size === 0) return;
      const dtS = (Number.isFinite(deltaMs) ? deltaMs : 0) / 1000;
      if (dtS <= 0) return;
      let dead: string[] | null = null;
      for (const [cid, rec] of characters) {
        const entry = registry.get(cid);
        if (!entry || entry.isDisposed()) {
          (dead ??= []).push(cid);
          continue;
        }
        if (rec.mode !== 'surface') continue; // FREE: no ambient gravity
        if (deps.physics?.isSimulated(cid)) continue; // the engine owns a Physical character's fall
        stepCharacterGravity(rec.node, rec.collider, rec.walkables, dtS, rec.state);
      }
      if (dead) for (const cid of dead) characters.delete(cid);
    },

    // ==================== GROWTH-TIER surface ====================

    // --- Environment (WORLD-level: drives the EXISTING sky subsystem) ---
    environmentSetSolidColorSky(color: ColorLike): boolean {
      const env = deps.environment;
      if (!env || typeof env.setSolidColorSky !== 'function') return false;
      env.setSolidColorSky({
        r: Number.isFinite(color?.r) ? color.r : 0.5,
        g: Number.isFinite(color?.g) ? color.g : 0.5,
        b: Number.isFinite(color?.b) ? color.b : 0.5,
        a: Number.isFinite(color?.a) ? color.a : 1,
      });
      return true;
    },
    environmentSetSky(options: SkyOptionsSpec): boolean {
      const env = deps.environment;
      if (!env || typeof env.setBackground !== 'function') return false;
      // The sky profile's attributes, spelled as the document spells them:
      // colours as hex, numbers clamped to the profile's ranges, non-finite
      // numbers dropped so the default applies.
      const sky: VemlLiteProceduralSky = {};
      const hex = (c: ColorLike | undefined): string | undefined => (c ? colorToHex(c) : undefined);
      const num = (v: number | undefined, lo: number, hi: number): number | undefined =>
        typeof v === 'number' && Number.isFinite(v) ? Math.min(hi, Math.max(lo, v)) : undefined;
      const put = (key: string, value: string | number | boolean | undefined): void => {
        if (value !== undefined) sky[key] = value;
      };
      put('daySkyColor', hex(options.zenith));
      put('dayHorizonColor', hex(options.horizon));
      put('horizonSkyBlend', num(options.blend, 0.1, 2));
      put('groundEnabled', typeof options.groundEnabled === 'boolean' ? options.groundEnabled : undefined);
      put('groundColor', hex(options.groundColor));
      put('groundHeight', num(options.groundHeight, -1, 1));
      put('groundFadeAmount', num(options.groundFade, 0, 1));
      put('sunEnabled', typeof options.sunEnabled === 'boolean' ? options.sunEnabled : undefined);
      put('sunDiameter', num(options.sunDiameter, 0, Number.MAX_SAFE_INTEGER));
      put('sunZenithColor', hex(options.sunColor));
      put('sunElevation', num(options.sunElevation, -90, 90));
      put('sunAzimuth', num(options.sunAzimuth, 0, 360));
      void env.setBackground({ kind: 'lite-procedural-sky', sky });
      return true;
    },
    environmentSetEnvironmentMap(src: string, options: EnvironmentMapOptionsSpec): boolean {
      const env = deps.environment;
      if (!env || typeof env.setBackground !== 'function') return false;
      if (typeof src !== 'string' || src.length === 0) return false;
      let resolved = src;
      try {
        resolved = new URL(src, worldUrl).href;
      } catch {
        resolved = src;
      }
      // The backdrop stays what it is (the current clear colour); the
      // environment profile's map rides on it, as a declared one does.
      const c = env.info.clearColor;
      const environmentMap: VemlEnvironmentMap = { raw: src, resolved };
      // The environment profile's ranges, as the parser holds a document to
      // them: a strength below zero or not finite is ignored and the default
      // applies; glazing-f0 is 0..1, above 1 clamped to 1.
      for (const k of ['intensity', 'diffuse', 'specular', 'glazingBoost'] as const) {
        const v = options[k];
        if (typeof v === 'number' && Number.isFinite(v) && v >= 0) environmentMap[k] = v;
      }
      const f0 = options.glazingF0;
      if (typeof f0 === 'number' && Number.isFinite(f0) && f0 >= 0) environmentMap.glazingF0 = Math.min(1, f0);
      if (options.punctualLights) environmentMap.punctualLights = options.punctualLights;
      void env.setBackground({ kind: 'color', color: colorToHex({ r: c.r, g: c.g, b: c.b, a: c.a }), environmentMap });
      return true;
    },
    environmentSetSkyTexture(url: string): boolean {
      const env = deps.environment;
      if (!env || typeof env.setSkyTexture !== 'function') return false;
      if (typeof url !== 'string' || url.length === 0) return false;
      // Resolve the script-supplied path against the world URL (a relative
      // path is relative to the world); a malformed URL falls back to the raw string.
      let resolved = url;
      try {
        resolved = new URL(url, worldUrl).href;
      } catch {
        resolved = url;
      }
      env.setSkyTexture(resolved); // FIRE-AND-FORGET (the script API's SetSkyTexture returns nothing)
      return true;
    },

    // --- LightEntity (entity-keyed; reuse lightEntity.ts; find light by name) ---
    lightSetType(id: string, type: string): boolean {
      const entry = registry.get(id);
      if (!entry || entry.isDisposed() || entry.type !== 'light') {
        log.warn(`[webverse] script SetLightType: entity ${id} is not a light`);
        return false;
      }
      // Own-property-safe enum resolution (NEVER index an object with the
      // untrusted string — prototype pollution). Unknown/forged → false.
      let target: 'point' | 'directional' | 'spot';
      switch (typeof type === 'string' ? type.trim().toLowerCase() : '') {
        case 'point':
          target = 'point';
          break;
        case 'directional':
          target = 'directional';
          break;
        case 'spot':
          target = 'spot';
          break;
        default:
          log.warn(`[webverse] script SetLightType: unknown light type '${String(type)}'`);
          return false;
      }
      const old = scene.getLightByName(`light:${entry.tag}`) ?? null;
      if (!old) return false;
      if (lightClassOf(old) === target) return true; // already that class — no-op

      // Capture the old light's observable state, then swap the class (a Babylon
      // light's type IS its class). The stale registry disposer disposes the old
      // (already-disposed) light idempotently; scene.dispose() at teardown
      // reclaims the new light — exactly one live light per entity, no leak.
      const diffuse = old.diffuse.clone();
      const intensity = old.intensity;
      const parent = old.parent;
      const oldPos = (old as unknown as { position?: Vector3 }).position;
      const oldDir = (old as unknown as { direction?: Vector3 }).direction;
      const oldRange = (old as unknown as { range?: number }).range;
      const position = oldPos ? oldPos.clone() : new Vector3(0, 0, 0);
      const direction = oldDir ? oldDir.clone() : new Vector3(0, 0, 1);
      const name = old.name;
      old.dispose();

      let next: Light;
      switch (target) {
        case 'point': {
          const p = new PointLight(name, position, scene);
          if (typeof oldRange === 'number' && Number.isFinite(oldRange)) p.range = oldRange;
          next = p;
          break;
        }
        case 'directional': {
          const d = new DirectionalLight(name, direction, scene);
          d.position = position;
          next = d;
          break;
        }
        case 'spot': {
          const s = new SpotLight(
            name,
            position,
            direction,
            DEFAULT_SPOT_ANGLE_DEG * DEG_TO_RAD,
            1,
            scene,
          );
          if (typeof oldRange === 'number' && Number.isFinite(oldRange)) s.range = oldRange;
          next = s;
          break;
        }
      }
      next.diffuse = diffuse;
      next.intensity = intensity;
      if (parent) next.parent = parent;
      return true;
    },
    lightSetProperties(id: string, props: LightPropertiesSpec): boolean {
      const light = lightOf(id);
      if (!light) {
        log.warn(`[webverse] script SetLightProperties: entity ${id} is not a light`);
        return false;
      }
      if (!props || typeof props !== 'object') return false;
      // Colour and temperature compose the same way as on a VEML light:
      // the authored colour scaled by the temperature's tint. Each call
      // recomposes from the parts it has, so setting only the temperature
      // re-tints the authored colour rather than the already tinted one.
      const source = lightColorSourceOf(light);
      const color = props.color;
      if (color && typeof color === 'object') {
        source.base = {
          r: Number.isFinite(color.r) ? color.r : source.base.r,
          g: Number.isFinite(color.g) ? color.g : source.base.g,
          b: Number.isFinite(color.b) ? color.b : source.base.b,
        };
      }
      if (typeof props.temperature === 'number' && Number.isFinite(props.temperature) && props.temperature > 0) {
        source.temperature = props.temperature;
      }
      applyLightColor(light, source);
      if (typeof props.intensity === 'number' && Number.isFinite(props.intensity)) {
        light.intensity = props.intensity;
      }
      if (typeof props.range === 'number' && Number.isFinite(props.range)) {
        const ranged = light as unknown as { range?: number };
        if ('range' in light) ranged.range = props.range;
      }
      // The spot angles are full cone angles in degrees, like `spot-angle`;
      // a light that is not a spot has no cone, so they are ignored for it.
      if (light instanceof SpotLight) {
        if (typeof props.outerSpotAngle === 'number' && Number.isFinite(props.outerSpotAngle) && props.outerSpotAngle > 0) {
          light.angle = (props.outerSpotAngle * Math.PI) / 180;
        }
        if (typeof props.innerSpotAngle === 'number' && Number.isFinite(props.innerSpotAngle) && props.innerSpotAngle >= 0) {
          light.innerAngle = (props.innerSpotAngle * Math.PI) / 180;
        }
      }
      return true;
    },

    // --- BaseEntity interaction state (tolerant; no-physics degrade) ---
    entitySetInteractionState(id: string, state: string): boolean {
      const entry = registry.get(id);
      if (!entry || entry.isDisposed()) return false;
      const node = entry.rootNode; // undefined for a VEML light (no carrier)
      let normalized: string;
      switch (typeof state === 'string' ? state.trim().toLowerCase() : '') {
        case 'hidden':
          normalized = 'hidden';
          if (node) node.setEnabled(false);
          break;
        case 'static':
          normalized = 'static';
          if (node) node.setEnabled(true);
          break;
        case 'physical':
          // A dynamic body from the physics rig (the engine loads on the first ask).
          normalized = 'physical';
          if (node) node.setEnabled(true);
          break;
        case 'placing':
          // A kinematic body: moved by its node, pushing what it meets.
          normalized = 'placing';
          if (node) node.setEnabled(true);
          break;
        default:
          log.warn(`[webverse] script SetInteractionState: unknown state '${String(state)}'`);
          return false;
      }
      interactionStates.set(id, normalized);
      if (node && deps.physics) {
        // A character's body stands on its feet; any other entity's turns freely.
        deps.physics.setInteraction(id, node, entry.ownedMeshes(), normalized as 'hidden' | 'static' | 'physical' | 'placing', {
          upright: characters.has(id),
        });
      }
      registry.invalidateCaches(); // a hidden↔shown node changes walkable membership
      return true;
    },
    entityGetInteractionState(id: string): string | null {
      const entry = registry.get(id);
      if (!entry || entry.isDisposed()) return null;
      const recorded = interactionStates.get(id);
      if (recorded !== undefined) return recorded;
      // Unrecorded → derive from the live node's visibility (a carrier-less
      // entity — e.g. a VEML light — reports Static, the visible-marker default).
      const node = entry.rootNode;
      if (!node) return 'static';
      return node.isEnabled(false) ? 'static' : 'hidden';
    },

    // ==================== REMAINING ENTITY FACTORIES ====================

    // SetText/GetText — live DynamicTexture glyph content of a `text`/`input`
    // entity (keyed by id → the host-side textRecords map → the real texture).
    // SetText mutates the stored spec + REDRAWS via the SAME `drawTextPlane`
    // create uses (single-source). A non-text/input id → false/null (a forged
    // id, a mesh, etc.). The corpus reads GetText() back after SetText() — a
    // guaranteed round-trip against the stored spec.
    entitySetText(id: string, text: string): boolean {
      const record = textRecords.get(id);
      if (!record) return false;
      record.entity.text = typeof text === 'string' ? text : String(text ?? '');
      drawTextPlane(record.texture, record.entity);
      return true;
    },
    entityGetText(id: string): string | null {
      const record = textRecords.get(id);
      if (!record) return null;
      return record.entity.text ?? '';
    },

    // MakeScreenCanvas — the v4 WORLD-SPACE degrade:
    // v4 renders every canvas world-space by design, so a screen-canvas request
    // SUCCEEDS (true — the corpus's FinishLoadingControlsCanvas chain must not
    // break) but does NOT change the render mode, does NOT reposition the canvas
    // in front of the camera, does NOT create a DOM/HUD overlay. True screen-space
    // overlay UI would be a new capability; it is not implemented.
    canvasMakeScreenCanvas(id: string): boolean {
      const entry = registry.get(id);
      if (!entry || entry.isDisposed() || entry.type !== 'canvas') return false;
      return true; // world-space no-op-that-succeeds
    },
    canvasMakeWorldCanvas(id: string): boolean {
      const entry = registry.get(id);
      if (!entry || entry.isDisposed() || entry.type !== 'canvas') return false;
      return true; // already world-space (the native mode)
    },
    canvasIsScreenCanvas(id: string): boolean {
      // Always world-space in v4 — a canvas is never a screen canvas.
      return false;
    },

    // ==================== INPUT POLLING ====================

    // GetMoveValue/GetLookValue/GetKeyValue/IsVR source from the page-supplied
    // ScriptInputStateProvider (the EXISTING desktopInput/firstPersonController/xr
    // state); absent → sane zero/false. Plain-data across the boundary (a {x,y}/
    // bool — NEVER a live node/event; toHostSafe is the backstop).
    inputGetMoveValue(): Vec2Like {
      const v = deps.scriptInput?.getMoveValue();
      return {
        x: Number.isFinite(v?.x) ? (v as Vec2Like).x : 0,
        y: Number.isFinite(v?.y) ? (v as Vec2Like).y : 0,
      };
    },
    inputGetLookValue(): Vec2Like {
      const v = deps.scriptInput?.getLookValue();
      return {
        x: Number.isFinite(v?.x) ? (v as Vec2Like).x : 0,
        y: Number.isFinite(v?.y) ? (v as Vec2Like).y : 0,
      };
    },
    inputGetKeyValue(key: string): boolean {
      return deps.scriptInput?.isKeyDown(String(key)) === true;
    },
    inputIsVR(): boolean {
      return deps.scriptInput?.isVR() === true;
    },
    // GetPointerRaycast — the CROSSHAIR ray (camera forward; v4 has ONE pointer —
    // the script API's direction/pointerIndex args are accepted-but-ignored)
    // + the REUSED pickEntity over the SAME candidate set
    // pickScriptEntityAt builds (all loaded, non-disposed entities with pickable
    // meshes). Returns the entity's registry ID (handle-as-id — the prelude
    // re-wraps it; NO live node crosses) + the world-space hit point/normal/origin
    // (computed from the ray like pickGroundPoint). null on no hit.
    inputGetPointerRaycast(): PointerRaycastHit | null {
      // Crosshair ray = camera centre along forward (the locked-pointer
      // idiom, buildScriptAimRay). No computeWorldMatrix — globalPosition/
      // getDirection read the camera's live world state.
      const origin = camera.globalPosition.clone();
      const dir = camera.getDirection(Vector3.Forward()).normalize();
      const ray = new Ray(origin, dir, PORTAL_MAX_REACH_M);
      const candidates: { id: string; meshes: readonly AbstractMesh[] }[] = [];
      for (const entry of registry.all()) {
        if (entry.isDisposed() || entry.status !== 'loaded') continue;
        const meshes: AbstractMesh[] = [...entry.ownedMeshes()];
        // A pickable rootNode mesh (UI buttons register their plane as rootNode,
        // not in `meshes`) is a valid hit — mirror pickScriptEntityAt.
        if (
          meshes.length === 0 &&
          entry.rootNode instanceof AbstractMesh &&
          entry.rootNode.isPickable
        ) {
          meshes.push(entry.rootNode);
        }
        if (meshes.length > 0) candidates.push({ id: entry.id, meshes });
      }
      const pick = pickEntity(ray, candidates);
      if (!pick) return null;
      // World hit point from the ray (Ray.intersectsMesh populates distance, not
      // always pickedPoint — the pickGroundPoint idiom). Normal best-effort from
      // the winning mesh's PickingInfo (falls back to the up vector).
      const point = origin.add(dir.scale(pick.distance));
      let nx = 0;
      let ny = 1;
      let nz = 0;
      try {
        const info = ray.intersectsMesh(pick.mesh);
        const normal = info.hit ? info.getNormal(true, true) : null;
        if (normal) {
          nx = normal.x;
          ny = normal.y;
          nz = normal.z;
        }
      } catch {
        /* best-effort normal — the hit point + entity are the load-bearing data */
      }
      if (!Number.isFinite(point.x) || !Number.isFinite(point.y) || !Number.isFinite(point.z)) {
        return null; // a degenerate ray never yields a valid hit
      }
      return {
        entity: pick.id,
        hitPoint: { x: point.x, y: point.y, z: point.z },
        hitPointNormal: { x: nx, y: ny, z: nz },
        origin: { x: origin.x, y: origin.y, z: origin.z },
      };
    },
  };
}
