/**
 * The shadow rig: one per world, owning which lights cast shadows and which
 * meshes cast and receive them.
 *
 * A light asks to cast shadows (`cast-shadows` on a VEML light) and the rig
 * decides:
 * - a directional light gets the world's one cascaded generator (the plain
 *   generator where the engine has no cascade support); a second directional
 *   light is declined with a diagnostic, since a second full-scene shadow map
 *   would double the cost for a light that rarely reads as the key;
 * - a spot light gets its own generator, bounded by its cone;
 * - a point light is declined: six-face maps cost more than they show.
 *
 * Every mesh the world builds for a `primitive` or an `asset` entity casts
 * into every generator and receives shadows, whether it was built before or
 * after the light; a disposed mesh leaves the render lists. The map size is
 * the client's setting, capped at `SHADOW_MAP_SIZE_MAX`; zero turns shadows
 * off for the visitor.
 *
 * The generators and their shaders live in the code-split shadow chunk,
 * loaded on the first attach, so a world whose lights cast no shadows pays
 * nothing for them.
 */
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import type { Light } from '@babylonjs/core/Lights/light';
import type { DirectionalLight } from '@babylonjs/core/Lights/directionalLight';
import type { Node } from '@babylonjs/core/node';
import type { IShadowLight } from '@babylonjs/core/Lights/shadowLight';
import type { ShadowGenerator } from '@babylonjs/core/Lights/Shadows/shadowGenerator';
import type { Scene } from '@babylonjs/core/scene';
import type { Observer } from '@babylonjs/core/Misc/observable';
import type { ShadowChunkModule } from './shadowChunk';
import { log } from '../logging/runtimeLog';

/** The default shadow-map edge, in texels. */
export const DEFAULT_SHADOW_MAP_SIZE = 1024;
/** The ceiling a setting cannot raise. */
export const SHADOW_MAP_SIZE_MAX = 2048;
/** Beyond this distance from the camera the cascades stop; the budget for a walkable world. */
export const SHADOW_MAX_DISTANCE_M = 150;
const CASCADES = 3;

export type ShadowGeneratorKind = 'cascaded' | 'directional' | 'spot';

export interface ShadowReport {
  mapSize: number;
  generators: Array<{ tag: string; kind: ShadowGeneratorKind; casters: number }>;
  declined: Array<{ tag: string; reason: string }>;
}

export interface ShadowRig {
  /** A light that declared cast-shadows: give it a generator, or decline and say why. */
  attach(light: Light, tag: string): Promise<void>;
  /** Meshes the world built: they cast into every generator and receive shadows. */
  track(meshes: readonly AbstractMesh[]): void;
  report(): ShadowReport;
  dispose(): void;
}

/** A setting's value into a usable size: non-finite → the default, below zero → off, above the ceiling → the ceiling. */
export function clampShadowMapSize(value: number): number {
  if (!Number.isFinite(value)) return DEFAULT_SHADOW_MAP_SIZE;
  if (value <= 0) return 0;
  return Math.min(SHADOW_MAP_SIZE_MAX, Math.floor(value));
}

export const emptyShadowReport = (mapSize = DEFAULT_SHADOW_MAP_SIZE): ShadowReport => ({
  mapSize,
  generators: [],
  declined: [],
});

const defaultLoader = (): Promise<ShadowChunkModule> => import('./shadowChunk');

export function createShadowRig(
  scene: Scene,
  options: { mapSize: number; loader?: () => Promise<ShadowChunkModule>; engineKind?: string },
): ShadowRig {
  const mapSize = clampShadowMapSize(options.mapSize);
  const loader = options.loader ?? defaultLoader;
  let chunk: Promise<ShadowChunkModule> | undefined;
  const generators: Array<{ tag: string; kind: ShadowGeneratorKind; generator: ShadowGenerator }> = [];
  const declined: Array<{ tag: string; reason: string }> = [];
  const casters = new Set<AbstractMesh>();
  const disposeObservers = new Map<AbstractMesh, Observer<Node>>();
  let disposed = false;
  // The directional slot is claimed before the chunk is awaited, not when the
  // generator exists: two glbs loading together, each with a sun, both reach
  // this point before either has a generator, and only one may have it.
  let directionalTag: string | undefined;

  const loadChunk = (): Promise<ShadowChunkModule> => {
    if (!chunk) {
      chunk = loader().then(async (m) => {
        if (options.engineKind === 'webgpu') await m.loadWebGPUShadowShaders();
        return m;
      });
    }
    return chunk;
  };

  const decline = (tag: string, reason: string): void => {
    declined.push({ tag, reason });
    log.warn(`[webverse] light '${tag}': cast-shadows declined — ${reason}`);
  };

  const forget = (mesh: AbstractMesh): void => {
    if (!casters.delete(mesh)) return;
    const observer = disposeObservers.get(mesh);
    if (observer) {
      mesh.onDisposeObservable.remove(observer);
      disposeObservers.delete(mesh);
    }
    for (const { generator } of generators) generator.removeShadowCaster(mesh, false);
  };

  return {
    async attach(light, tag) {
      if (disposed) return;
      if (mapSize === 0) {
        decline(tag, 'shadows are off in this client (shadow-map size 0)');
        return;
      }
      const className = light.getClassName();
      if (className === 'PointLight') {
        decline(tag, 'point lights cast no shadows (a six-face map costs more than it shows)');
        return;
      }
      if (className !== 'DirectionalLight' && className !== 'SpotLight') {
        decline(tag, `a ${className} cannot cast shadows`);
        return;
      }
      if (className === 'DirectionalLight') {
        if (directionalTag !== undefined) {
          decline(tag, `one cascaded generator per world — shadows come from the directional light '${directionalTag}'`);
          return;
        }
        directionalTag = tag;
      }
      let m: ShadowChunkModule;
      try {
        m = await loadChunk();
      } catch (err) {
        if (directionalTag === tag) directionalTag = undefined;
        log.warn(`[webverse] light '${tag}': the shadow chunk failed to load — no shadows`, err);
        return;
      }
      if (disposed || light.isDisposed()) {
        if (directionalTag === tag) directionalTag = undefined;
        return;
      }
      const shadowLight = light as unknown as IShadowLight;
      let generator: ShadowGenerator;
      let kind: ShadowGeneratorKind;
      if (className === 'DirectionalLight' && m.CascadedShadowGenerator.IsSupported) {
        const cascaded = new m.CascadedShadowGenerator(mapSize, light as DirectionalLight);
        cascaded.numCascades = CASCADES;
        cascaded.lambda = 0.9;
        cascaded.stabilizeCascades = true;
        cascaded.shadowMaxZ = SHADOW_MAX_DISTANCE_M;
        generator = cascaded;
        kind = 'cascaded';
      } else {
        generator = new m.ShadowGenerator(mapSize, shadowLight);
        kind = className === 'DirectionalLight' ? 'directional' : 'spot';
      }
      generator.usePercentageCloserFiltering = true;
      generator.filteringQuality = m.ShadowGenerator.QUALITY_MEDIUM;
      generator.bias = 0.002;
      generator.normalBias = 0.02;
      const held = { tag, kind, generator };
      generators.push(held);
      for (const mesh of casters) generator.addShadowCaster(mesh, false);
      // A light that is removed gives its generator up, and a sun the world's
      // one cascaded slot with it, so the light that takes its place can cast.
      light.onDisposeObservable.addOnce(() => {
        const at = generators.indexOf(held);
        if (at < 0) return;
        generators.splice(at, 1);
        generator.dispose();
        if (className === 'DirectionalLight' && directionalTag === tag) directionalTag = undefined;
      });
    },
    track(meshes) {
      if (disposed) return;
      for (const mesh of meshes) {
        if (casters.has(mesh) || mesh.isDisposed()) continue;
        casters.add(mesh);
        mesh.receiveShadows = true;
        const observer = mesh.onDisposeObservable.addOnce(() => forget(mesh));
        if (observer) disposeObservers.set(mesh, observer);
        for (const { generator } of generators) generator.addShadowCaster(mesh, false);
      }
    },
    report() {
      return {
        mapSize,
        generators: generators.map((g) => ({ tag: g.tag, kind: g.kind, casters: casters.size })),
        declined: declined.map((d) => ({ ...d })),
      };
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      for (const mesh of [...casters]) forget(mesh);
      for (const { generator } of generators.splice(0)) generator.dispose();
      declined.length = 0;
      directionalTag = undefined;
    },
  };
}
