/**
 * Portal interaction.
 *
 * The page-level orchestrator that turns a VEML 3.1 `link` into an interactive
 * in-world hyperlink. Each frame it picks the focused portal from the LIVE
 * active world (re-targeting whatever world is loaded), applies the affordance
 * (mesh emissive highlight + the DOM label/reticle overlay), and on activation
 * calls the SAME `NavigationController.navigate` seam as hash/browser navigation
 * — so browser history records the hop and native Back returns.
 *
 * THE AIMING MODEL (pointer lock has NO cursor, so desktop-under-lock is
 * crosshair-RAYCAST, not hover):
 * - DESKTOP pointer-locked → a camera-CENTRE ray (the crosshair).
 * - DESKTOP unlocked → a ray unprojected through the cursor (DOM hover).
 * - TOUCH → tap-to-pick: a `pointerup` casts a ray through the tapped point and
 *   activates on hit (continuous per-frame aim on touch is deferred — it would
 *   fight the dual-stick locomotion).
 * The ray SOURCE is the only thing that differs; the geometric pick is the pure,
 * VR-reusable `pickPortal` (portalPicker.ts). VR supplies a controller
 * ray to the same picker.
 *
 * FAILURE: activation is a plain `navigate(resolvedHref)`. If the target
 * is unreachable, worldSession's load-then-swap keeps the CURRENT world alive
 * and the feedback surface's error card paints over it — nothing to do here but not throw.
 *
 * href resolution: `link.resolvedHref` is already the WHATWG resolve against the
 * world document URL (parser.ts / uriResolve.ts, A.9) — a relative `../world-b`
 * from world A is already absolute here. Navigate straight to it.
 *
 * Babylon: `Ray` from the class-only `Culling/ray.core`; `Vector3`/`Matrix`
 * from math.vector; `Color3` from math.color; emissive is a property on the
 * already-bundled StandardMaterial/PBRMaterial (NO new shader/material import —
 * the shader-import manifest stays byte-untouched). Main-bundle.
 */
import { Ray } from '@babylonjs/core/Culling/ray.core';
import { Vector3, Matrix } from '@babylonjs/core/Maths/math.vector';
import { Color3 } from '@babylonjs/core/Maths/math.color';
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import type { NavigationController } from '../navigation/navigationController';
import type { PortalEntry } from '../scene/entityRegistry';
import { pickPortal, PORTAL_MAX_REACH_M, type PortalRaySource } from './portalPicker';
import type { PortalOverlay, PortalPoint } from './portalOverlay';

/** The minimal camera shape the interaction reads (a Babylon FreeCamera fits). */
export interface PortalCamera {
  readonly globalPosition: Vector3;
  getDirection(localAxis: Vector3): Vector3;
  getViewMatrix(): Matrix;
  getProjectionMatrix(): Matrix;
  getScene(): { getEngine(): { getRenderWidth(): number; getRenderHeight(): number } };
}

/** The active-world view the interaction re-targets each frame. */
export interface PortalActiveView {
  camera: PortalCamera;
}

/** The input-state slice the aiming model needs. */
export interface PortalInput {
  isPointerLocked(): boolean;
}

/** Minimal canvas surface (listeners + client size for cursor→render mapping). */
export interface PortalCanvas {
  addEventListener(type: string, listener: (ev: Event) => void): void;
  removeEventListener(type: string, listener: (ev: Event) => void): void;
  readonly clientWidth: number;
  readonly clientHeight: number;
}

export interface PortalInteractionOptions {
  getActive: () => PortalActiveView;
  getPortals: () => readonly PortalEntry[];
  navigation: Pick<NavigationController, 'navigate'>;
  input: PortalInput;
  doc: Document;
  canvas: PortalCanvas;
  /** Test seam: inject the overlay (defaults to the real DOM overlay). */
  overlay?: PortalOverlay;
  /** The clock, in ms. Default: `performance.now`. */
  now?: () => number;
}

/**
 * How long a door's card has to have been up before a click with the
 * pointer free goes through the door. A click meant for the world (the
 * first one takes the pointer) can land where a door happens to be; going
 * through a door is a choice, made after reading where it leads.
 */
const HOVER_BEFORE_CLICK_MS = 300;

/** A focused portal descriptor for observability (window.__webverse). */
export interface FocusedPortal {
  tag: string;
  label: string;
  href: string;
}

export interface PortalInteraction {
  /** Per-frame: re-pick from the live world, update highlight + overlay. */
  update(): void;
  /** The currently focused portal (or null) — the e2e's focus read. */
  focusedPortal(): FocusedPortal | null;
  /** Activate the focused portal (navigate) — the e2e's deterministic path. */
  activateFocused(): void;
  dispose(): void;
}

/** Emissive boost applied to a focused portal mesh (restored on unfocus). */
const HIGHLIGHT_EMISSIVE = new Color3(0.35, 0.5, 0.9);

/** A material that carries an emissiveColor (StandardMaterial / PBRMaterial). */
interface EmissiveMaterial {
  emissiveColor?: Color3;
}

/** The display label for a link: its author text, or the raw href when unlabeled. */
function linkLabel(link: PortalEntry['link']): string {
  return link.label !== '' ? link.label : link.href;
}

export function createPortalInteraction(options: PortalInteractionOptions): PortalInteraction {
  const { getActive, getPortals, navigation, input, doc, canvas } = options;
  let disposed = false;
  // The door card and the aiming dot are not part of the first paint: their
  // code is asked for the first time there is something of theirs to show.
  let overlay: PortalOverlay | null = options.overlay ?? null;
  let asked = overlay !== null;
  const wantOverlay = (): void => {
    if (asked) return;
    asked = true;
    void import('./portalOverlay').then(
      (mod) => {
        if (disposed) return;
        overlay = mod.createPortalOverlay(doc);
        showFocused();
      },
      () => {
        asked = false;
      },
    );
  };

  // Last cursor position over the canvas (render-space is derived at ray build).
  let cursorX: number | null = null;
  let cursorY: number | null = null;

  // The focused portal + the mesh's saved emissive (restored on unfocus). Held
  // by identity so a world teardown (candidate gone) clears it next frame.
  const now = options.now ?? (() => performance.now());
  let focusedAt = 0;
  let focused: {
    entry: PortalEntry;
    mesh: AbstractMesh;
    savedEmissive: Color3 | null;
  } | null = null;

  const emissiveOf = (mesh: AbstractMesh): EmissiveMaterial | null => {
    const mat = mesh.material as unknown as EmissiveMaterial | null;
    return mat && mat.emissiveColor instanceof Color3 ? mat : null;
  };

  const applyHighlight = (mesh: AbstractMesh): Color3 | null => {
    const mat = emissiveOf(mesh);
    if (!mat || !mat.emissiveColor) return null;
    const saved = mat.emissiveColor.clone();
    mat.emissiveColor = HIGHLIGHT_EMISSIVE.clone();
    return saved;
  };

  const restoreHighlight = (): void => {
    if (!focused || focused.savedEmissive === null) return;
    // Guard a disposed mesh/material (world torn down mid-focus).
    if (focused.mesh.isDisposed()) return;
    const mat = emissiveOf(focused.mesh);
    if (mat) mat.emissiveColor = focused.savedEmissive;
  };

  const clearFocus = (): void => {
    if (!focused) return;
    restoreHighlight();
    focused = null;
    overlay?.hideFocus();
  };

  // Where the door card sits: at the pointer while it is free, in the middle
  // (null) once the world holds it.
  const cardAt = (): PortalPoint | null =>
    input.isPointerLocked() || cursorX === null || cursorY === null ? null : { x: cursorX, y: cursorY };
  // The card says the door's name and the site it leads to. The site is
  // worked out from the address this client resolved, never from the name.
  const showFocused = (): void => {
    if (focused) overlay?.showFocus(linkLabel(focused.entry.link), focused.entry.link.resolvedHref, cardAt());
  };

  // Build the aim ray for the current modality (null = no aim this frame).
  const buildRay: PortalRaySource = () => {
    const { camera } = getActive();
    if (input.isPointerLocked()) {
      // Crosshair: from the camera centre along its forward axis.
      const origin = camera.globalPosition.clone();
      const dir = camera.getDirection(Vector3.Forward());
      return new Ray(origin, dir.normalize(), PORTAL_MAX_REACH_M);
    }
    if (cursorX === null || cursorY === null) return null; // no cursor yet
    return unprojectRay(camera, cursorX, cursorY);
  };

  // A ray from the camera through a canvas cursor/tap point (CSS px → render px).
  const unprojectRay = (camera: PortalCamera, cx: number, cy: number): Ray => {
    const engine = camera.getScene().getEngine();
    const rw = engine.getRenderWidth();
    const rh = engine.getRenderHeight();
    const cw = canvas.clientWidth || rw;
    const ch = canvas.clientHeight || rh;
    const px = (cx / cw) * rw;
    const py = (cy / ch) * rh;
    const view = camera.getViewMatrix();
    const proj = camera.getProjectionMatrix();
    const id = Matrix.Identity();
    const near = Vector3.Unproject(new Vector3(px, py, 0), rw, rh, id, view, proj);
    const far = Vector3.Unproject(new Vector3(px, py, 1), rw, rh, id, view, proj);
    const dir = far.subtract(near).normalize();
    return new Ray(near, dir, PORTAL_MAX_REACH_M);
  };

  const setFocus = (entry: PortalEntry, mesh: AbstractMesh): void => {
    if (focused && focused.entry === entry && focused.mesh === mesh) return; // unchanged
    clearFocus();
    focused = { entry, mesh, savedEmissive: applyHighlight(mesh) };
    focusedAt = now();
    showFocused();
  };

  const activate = (link: PortalEntry['link']): void => {
    // The SAME seam as hash/Back (F.7): writes the hash (history entry) + loads.
    // A build-fatal rejection is already surfaced via load-failed — never let it
    // escape as an unhandled rejection.
    void navigation.navigate(link.resolvedHref).catch(() => {});
  };

  // --- listeners -----------------------------------------------------------
  const onMouseMove = (ev: Event): void => {
    const m = ev as MouseEvent;
    cursorX = m.offsetX;
    cursorY = m.offsetY;
  };

  // Desktop primary click (locked crosshair OR unlocked hover) → activate the
  // focused portal. desktopInput's own click handler (pointer-lock request)
  // co-exists: when unlocked it also requests lock, harmlessly — activation wins.
  const onClick = (): void => {
    if (!focused) return;
    if (!input.isPointerLocked() && now() - focusedAt < HOVER_BEFORE_CLICK_MS) return;
    activate(focused.entry.link);
  };

  // Touch tap-to-pick: a touch pointerup casts a one-shot ray through the tapped
  // point and activates on hit (guarded to touch so desktop uses `click` only,
  // avoiding a double-activate — navigate is idempotent anyway).
  const onPointerUp = (ev: Event): void => {
    const p = ev as PointerEvent;
    if (p.pointerType !== 'touch') return;
    const { camera } = getActive();
    const ray = unprojectRay(camera, p.offsetX, p.offsetY);
    const pick = pickPortal(ray, getPortals());
    if (pick) activate(pick.candidate.link);
  };

  canvas.addEventListener('mousemove', onMouseMove);
  canvas.addEventListener('click', onClick);
  canvas.addEventListener('pointerup', onPointerUp);

  return {
    update(): void {
      if (disposed) return;
      const locked = input.isPointerLocked();
      if (locked || getPortals().length > 0) wantOverlay();
      overlay?.setReticleVisible(locked);
      const ray = buildRay();
      const pick = ray ? pickPortal(ray, getPortals()) : null;
      if (pick) {
        setFocus(pick.candidate, pick.mesh);
        overlay?.placeFocus(cardAt());
      } else clearFocus();
    },
    focusedPortal(): FocusedPortal | null {
      if (!focused) return null;
      return {
        tag: focused.entry.entity.tag,
        label: linkLabel(focused.entry.link),
        href: focused.entry.link.resolvedHref,
      };
    },
    activateFocused(): void {
      if (focused) activate(focused.entry.link);
    },
    dispose(): void {
      if (disposed) return;
      disposed = true;
      clearFocus();
      canvas.removeEventListener('mousemove', onMouseMove);
      canvas.removeEventListener('click', onClick);
      canvas.removeEventListener('pointerup', onPointerUp);
      overlay?.dispose();
    },
  };
}
