/**
 * What a world's script saves, kept apart by the world's source.
 *
 * A page keeps what every world saved in one store, because a page has one
 * store. A world may read and change only what worlds from its own source
 * saved: the origin its document came from. So every key is kept under that
 * origin: `webverse:ls:<origin>|<the script's key>`. An origin has no `|`
 * in it, so no key a script chooses reaches another source's values.
 *
 * A world made from a file on the visitor's computer has no source: its
 * files are served from the page's own store, under one folder, whoever made
 * the file. Such worlds would all share one space, so what their scripts
 * save is kept for the visit only and written nowhere.
 */
import type { LocalStorageBackend } from '../sandbox/sandboxTypes';

/** What the sandbox puts before every key a script names, so a script reaches none of the page's own. */
const MARK = 'webverse:ls:';

/** `backend` as the world whose document is at `worldUrl` has it: its own source's values and no other's. */
export function sourceStorage(backend: LocalStorageBackend | undefined, worldUrl: string): LocalStorageBackend | undefined {
  if (!backend) return undefined;
  let store = backend;
  let source = 'null';
  try {
    const world = new URL(worldUrl);
    source = world.origin;
    // The folder a world made from a file is served from: kept for the visit, in memory.
    if (world.pathname.includes('/__import/')) {
      const visit = new Map<string, string>();
      store = { getItem: (key) => visit.get(key) ?? null, setItem: (key, value) => void visit.set(key, value), removeItem: (key) => void visit.delete(key) };
    }
  } catch {
    // Not an address: it shares with nothing that has one.
  }
  // The source goes after the sandbox's own mark, which is at the start of every key it hands over.
  const at = (key: string): string => `${MARK}${source}|${key.replace(MARK, '')}`;
  return {
    getItem: (key) => store.getItem(at(key)),
    setItem: (key, value) => store.setItem(at(key), value),
    removeItem: (key) => store.removeItem(at(key)),
  };
}
