/**
 * Quality tiers: one dial for how much a device draws, so a world runs on a
 * small phone and looks its best on a strong desktop. A tier sets how far a
 * planet's blocks reach, how much detail its far terrain asks for, how many
 * of its tiles are kept, the shadows' sharpness, the render scale, the
 * temporal anti-aliasing and upscaling, and the contact shadows. The
 * visitor picks a tier, or `auto`, which starts from what the browser says
 * about the device (memory, cores, graphics card, touch).
 *
 * Zero imports, DOM-free, main-bundle.
 */

export type QualityTier = 'low' | 'medium' | 'high' | 'ultra';
export const QUALITY_TIERS: readonly QualityTier[] = ['low', 'medium', 'high', 'ultra'];

export interface Temporal {
  antialias: boolean;
  /** 0.5 to 1; under 1 only with `antialias`, which rebuilds the detail. */
  upscale: number;
}

/** The visitor's choice: the tier's (`auto`), none, smoothed at the screen's size, or smoothed and upscaled. */
export type TemporalChoice = 'auto' | 'off' | 'antialias' | 'upscale';
export const TEMPORAL_CHOICES: readonly TemporalChoice[] = ['auto', 'off', 'antialias', 'upscale'];
/** The share of the screen's width and height an upscaled scene is drawn at. */
export const UPSCALE_SHARE = 0.67;

/** What the visitor's choice makes of the tier's temporal anti-aliasing; anything unknown is `auto`. */
export function temporalOf(choice: TemporalChoice | undefined, tier: Temporal): Temporal {
  if (choice === 'off') return { antialias: false, upscale: 1 };
  if (choice === 'antialias') return { antialias: true, upscale: 1 };
  if (choice === 'upscale') return { antialias: true, upscale: UPSCALE_SHARE };
  return tier;
}

/** Motion blur on a planet, the visitor's comfort choice: off unless they turn it on, and never in VR. */
export type MotionBlurChoice = 'off' | 'on';

/** Depth of field on a planet, the visitor's choice: `auto` follows the world's `planet.focus`, `off` never draws it, `on` draws it wherever the tier can. */
export type FocusChoice = 'auto' | 'off' | 'on';

/** A planet's terrain style, the visitor's choice: `auto` follows the world's `planet.terrain-style`, else smoothed or whole blocks. */
export type TerrainStyleChoice = 'auto' | 'smooth' | 'blocks';

/** The blocks' relief on a planet, the visitor's choice: `auto` follows the world's `planet.block-relief`, `off` draws them flat, `on` with relief even where the world asks for none. */
export type ReliefChoice = 'auto' | 'off' | 'on';

/** The things that move on a planet, the visitor's choice: `auto` follows the world's `planet.things`, else shown or hidden whatever it asks. */
export type ThingsChoice = 'auto' | 'shown' | 'hidden';

export interface QualityProfile {
  tier: QualityTier;
  /** The most a light's shadow map may be, in texels; 0 draws no shadows. */
  shadowMapSize: number;
  /** Pixels drawn per screen pixel, 0 to 1. */
  renderScale: number;
  /** On a planet: edges smoothed over frames (temporal anti-aliasing), and the share of the screen's width and height the scene is drawn at, the detail rebuilt from the frames before (1 draws it whole). */
  temporal: Temporal;
  planet: {
    /** Chunk columns out from the visitor whose blocks are drawn. */
    chunkRadius: number;
    /** On-screen error, in pixels, a far tile may show before it is refined. */
    maxScreenError: number;
    /** The same, with the eye high over the planet (farDetail.ts): finer, so the planet is drawn in detail from space. */
    farScreenError: number;
    /** Far tiles kept loaded beyond those shown, for coming back. */
    keepTiles: number;
    /** The far terrain wears the game's textures; without, its colours. */
    textures: boolean;
    /** The sky's samples of the air (along each view ray, and each ray to the sun), the layers of noise in the clouds, whether the brightest things bloom, and whether the clouds are marched as volumes, with how many steps along the eye's line and toward the sun, and at what share of the screen's width and height (the march's cost goes as its square). */
    sky: { steps: number; lightSteps: number; cloudOctaves: number; bloom: boolean; cloudVolume: boolean; cloudSteps: number; cloudLightSteps: number; cloudScale: number };
    /** The planet's water mirrors its sky and the sun. */
    waterReflections: boolean;
    /** The planet's water measures how deep it is from what lies behind it (a depth map of the scene), so its bed fades as it deepens. */
    waterDepth: boolean;
    /** Foam on the planet's shores, where the water's depth is measured. */
    waterFoam: boolean;
    /** The sun's caustics on the planet's shallow beds: seen through the water where its depth is measured, and on the ground about an eye under it. */
    caustics: boolean;
    /** The planet's water mirrors the shore, trees and cliffs over it, traced across the picture drawn where its depth is measured: 0 not at all, 1 at full detail, 0.5 with half the steps along each ray. */
    waterMirror: number;
    /** The planet's plants and leaves sway in its wind. */
    sway: boolean;
    /** The eye adapts to the planet's light, brightening in shade and at night and darkening in the sun: a pass over the view. */
    eyeAdaptation: boolean;
    /** The sun's beams through clouds and trees: three passes, two of them at a quarter of the view's size. */
    sunbeams: boolean;
    /** The planet's blocks are drawn in the light their chunks carry: shaded in their corners, and glowing about their light sources at night. */
    blockLight: boolean;
    /** The thin dark line where a block, a plant or a person meets the ground in sun, which the sun's shadow map is too coarse to draw: a pass over the view's depth. */
    /** Absent is off. */
    contactShadows?: boolean;
  };
}

const PROFILES: Record<QualityTier, QualityProfile> = {
  // For a small phone: blocks only close by, coarse far terrain in colours, fewer pixels, no shadows.
  low: { tier: 'low', shadowMapSize: 0, renderScale: 0.6, temporal: { antialias: false, upscale: 1 }, planet: { chunkRadius: 2, maxScreenError: 32, farScreenError: 32, keepTiles: 16, textures: false, sky: { steps: 6, lightSteps: 2, cloudOctaves: 2, bloom: false, cloudVolume: false, cloudSteps: 0, cloudLightSteps: 0, cloudScale: 1 }, waterReflections: false, waterDepth: false, waterFoam: false, caustics: false, waterMirror: 0, sway: false, blockLight: false, eyeAdaptation: false, sunbeams: false } },
  medium: { tier: 'medium', shadowMapSize: 512, renderScale: 1, temporal: { antialias: false, upscale: 1 }, planet: { chunkRadius: 5, maxScreenError: 16, farScreenError: 6, keepTiles: 48, textures: true, sky: { steps: 10, lightSteps: 3, cloudOctaves: 3, bloom: false, cloudVolume: false, cloudSteps: 0, cloudLightSteps: 0, cloudScale: 1 }, waterReflections: true, waterDepth: false, waterFoam: false, caustics: false, waterMirror: 0, sway: true, blockLight: true, eyeAdaptation: true, sunbeams: false } },
  high: { tier: 'high', shadowMapSize: 1024, renderScale: 1, temporal: { antialias: true, upscale: UPSCALE_SHARE }, planet: { chunkRadius: 8, maxScreenError: 12, farScreenError: 2, keepTiles: 96, textures: true, sky: { steps: 16, lightSteps: 4, cloudOctaves: 5, bloom: true, cloudVolume: true, cloudSteps: 32, cloudLightSteps: 4, cloudScale: 0.5 }, waterReflections: true, waterDepth: true, waterFoam: true, caustics: true, waterMirror: 0.5, sway: true, blockLight: true, eyeAdaptation: true, sunbeams: false, contactShadows: true } },
  ultra: { tier: 'ultra', shadowMapSize: 2048, renderScale: 1, temporal: { antialias: true, upscale: 1 }, planet: { chunkRadius: 10, maxScreenError: 8, farScreenError: 1.5, keepTiles: 160, textures: true, sky: { steps: 24, lightSteps: 6, cloudOctaves: 6, bloom: true, cloudVolume: true, cloudSteps: 56, cloudLightSteps: 6, cloudScale: 0.5 }, waterReflections: true, waterDepth: true, waterFoam: true, caustics: true, waterMirror: 1, sway: true, blockLight: true, eyeAdaptation: true, sunbeams: true, contactShadows: true } },
};

export function qualityProfile(tier: QualityTier): QualityProfile {
  return PROFILES[tier];
}

/** What a browser says about the device, each part when it says it. */
export interface DeviceFacts {
  /** `navigator.deviceMemory`: gigabytes, rounded down and capped at 8 by the browser. */
  memoryGB?: number;
  /** `navigator.hardwareConcurrency`. */
  cores?: number;
  /** The graphics card's name, as WebGL's renderer string gives it. */
  renderer?: string;
  /** A touch screen: a phone or a tablet, by its likeliest. */
  touch: boolean;
}

/** The facts from a window's navigator, and the renderer string when the engine knows it. */
export function readDeviceFacts(win: { navigator: { deviceMemory?: number; hardwareConcurrency?: number; maxTouchPoints?: number } }, renderer?: string): DeviceFacts {
  const n = win.navigator;
  return {
    ...(typeof n.deviceMemory === 'number' ? { memoryGB: n.deviceMemory } : {}),
    ...(typeof n.hardwareConcurrency === 'number' ? { cores: n.hardwareConcurrency } : {}),
    ...(renderer ? { renderer } : {}),
    touch: (n.maxTouchPoints ?? 0) > 0,
  };
}

/** A renderer drawing in software: every frame costs the processor. */
const SOFTWARE = /swiftshader|llvmpipe|software|basic render/i;
/** A discrete graphics card's name. */
const DISCRETE = /geforce|rtx|nvidia|radeon rx|radeon pro|arc a\d/i;

/** The tier a device starts on. With nothing said about it, high. */
export function autoTier(d: DeviceFacts): QualityTier {
  if (d.renderer && SOFTWARE.test(d.renderer)) return 'low';
  const small = (d.memoryGB !== undefined && d.memoryGB <= 4) || (d.cores !== undefined && d.cores <= 4);
  if (d.touch) return (d.memoryGB !== undefined && d.memoryGB <= 3) || (d.cores !== undefined && d.cores <= 4) ? 'low' : 'medium';
  if (small) return 'medium';
  if (d.renderer && DISCRETE.test(d.renderer) && (d.memoryGB ?? 0) >= 8 && (d.cores ?? 0) >= 8) return 'ultra';
  return 'high';
}

/** The tier in force: the visitor's, or the device's for `auto`. */
export function resolveTier(chosen: QualityTier | 'auto', d: DeviceFacts): QualityTier {
  return chosen === 'auto' ? autoTier(d) : chosen;
}
