/**
 * The `client-hints` profile's vocabulary (specs/veml/profiles/client-hints.md):
 * every hint's name, allowed values and shell default, and the one validator
 * the parser (parse40) and a script's `ClientHints.Set` both use — "validated
 * exactly as the attribute is". Pure data and one function, here in src/veml
 * because it is VEML vocabulary; the runtime is src/hints/clientHints.ts.
 */

import { parseColor } from '@fivesqd/veml-parse';

type Spec =
  | { kind: 'enum'; values: readonly string[] }
  | { kind: 'number'; min: number; max: number; words?: readonly string[] }
  | { kind: 'list'; values: readonly string[] }
  | { kind: 'uri' }
  | { kind: 'text' }
  | { kind: 'color'; words: readonly string[] }
  | { kind: 'layers'; of: { kind: 'number'; min: number; max: number } | { kind: 'color' }; words: readonly string[] };

/** The most layers a `layers` hint carries. */
export const MAX_HINT_LAYERS = 4;
const layers = (of: { kind: 'number'; min: number; max: number } | { kind: 'color' }, words: readonly string[] = ['auto']) => ({ kind: 'layers', of, words }) as const;

const BOOL = { kind: 'enum', values: ['true', 'false'] } as const;
const SHOW = { kind: 'enum', values: ['show', 'hide'] } as const;
const POINTER = { kind: 'enum', values: ['none', 'ui', 'teleport'] } as const;

