export const isHintName = (name: string): name is HintName => Object.prototype.hasOwnProperty.call(HINT_SPECS, name);

/** The look settings `hints:view` carries for any world, each also an attribute of `hints:planet`. */
export const VIEW_LOOK_HINTS = ['exposure', 'adaptation-speed', 'exposure-min', 'exposure-max', 'bloom', 'sun-flare', 'grade'] as const;

/**
 * A hint as a planet reads it: its own `planet.*` look attribute where the
 * world set it, and the world's `view.*` where the planet's is left at
 * `auto`. The view's `adapt` is a planet's own `auto`, which adapts.
 */
export function lookHint(get: (name: string) => string | null | undefined, name: string): string | null | undefined {
  const own = get(name);
  if (own !== 'auto' || !name.startsWith('planet.') || !(VIEW_LOOK_HINTS as readonly string[]).includes(name.slice(7))) return own;
  const world = get(`view.${name.slice(7)}`);
  return world === 'adapt' ? 'auto' : (world ?? own);
}

export type HintReason = 'unknown-value' | 'out-of-range' | 'unknown-attribute';
export type HintCheck = { ok: true; value: string; reason?: HintReason } | { ok: false; reason: HintReason };

/**
 * Validate one hint as its attribute is (profiles/client-hints.md,
 * Degradation 3): a number out of range is clamped and kept, with a reason
 * to warn; an unknown enumerated value is refused; an unknown list token is
 * dropped with a reason to warn.
 */
export function validateHint(name: string, raw: string): HintCheck {
  if (!isHintName(name)) return { ok: false, reason: 'unknown-attribute' };
  const spec: Spec = HINT_SPECS[name];
  const value = raw.trim();
  switch (spec.kind) {
    case 'enum':
      return spec.values.includes(value) ? { ok: true, value } : { ok: false, reason: 'unknown-value' };
    case 'number': {
      if (spec.words?.includes(value)) return { ok: true, value };
      const n = Number(value);
      // Where words stand beside numbers, anything else is an unknown value, not a number out of range.
      if (value === '' || !Number.isFinite(n)) return { ok: false, reason: spec.words ? 'unknown-value' : 'out-of-range' };
      if (n < spec.min || n > spec.max) {
        return { ok: true, value: String(Math.min(spec.max, Math.max(spec.min, n))), reason: 'out-of-range' };
      }
      return { ok: true, value };
    }
    case 'list': {
      const tokens = value.split(/\s+/).filter((t) => t.length > 0);
      if (tokens.length === 1 && tokens[0] === 'none') return { ok: true, value: 'none' };
      const kept = tokens.filter((t) => spec.values.includes(t));
      const out = kept.length > 0 ? kept.join(' ') : 'none';
      return kept.length === tokens.length ? { ok: true, value: out } : { ok: true, value: out, reason: 'unknown-value' };
    }
    case 'uri':
    case 'text':
      return { ok: true, value };
    case 'color':
      // As core VEML writes colours (§4.5): hex, color(r g b a) or a CSS name.
      if (spec.words.includes(value)) return { ok: true, value };
      return value !== '' && parseColor(value).color.form !== 'neutral' ? { ok: true, value } : { ok: false, reason: 'unknown-value' };
    case 'layers': {
      if (spec.words.includes(value)) return { ok: true, value };
      let entries = layerEntries(value);
      if (entries.length === 0) return { ok: false, reason: 'unknown-value' };
      let reason: HintReason | undefined;
      if (entries.length > MAX_HINT_LAYERS) {
        entries = entries.slice(0, MAX_HINT_LAYERS);
        reason = 'out-of-range';
      }
      let taken = 0;
      const out = entries.map((e) => {
        const one = layerEntry(spec.of, e);
        if (one === null) {
          reason = 'unknown-value';
          return 'auto';
        }
        if (one.clamped) reason ??= 'out-of-range';
        if (e !== 'auto') taken++;
        return one.value;
      });
      // Not one entry the attribute takes: refused, so its default stands.
      if (taken === 0 && out.every((e) => e === 'auto') && entries.some((e) => e !== 'auto')) return { ok: false, reason: 'unknown-value' };
      return reason ? { ok: true, value: out.join(' '), reason } : { ok: true, value: out.join(' ') };
    }
  }
}

/** A layered value's entries, split at spaces outside parentheses, so `color(…)` stays one entry. */
function layerEntries(value: string): string[] {
  const out: string[] = [];
  let depth = 0;
  let current = '';
  for (const ch of value) {
    if (ch === '(') depth++;
    if (ch === ')') depth = Math.max(0, depth - 1);
    if (/\s/.test(ch) && depth === 0) {
      if (current) out.push(current);
      current = '';
    } else current += ch;
  }
  if (current) out.push(current);
  return out;
}

/** One entry of a layered value: `auto`, or as its attribute takes it (a number clamped to its range); null when it is neither. */
function layerEntry(of: { kind: 'number'; min: number; max: number } | { kind: 'color' }, e: string): { value: string; clamped: boolean } | null {
  if (e === 'auto') return { value: 'auto', clamped: false };
  if (of.kind === 'color') return parseColor(e).color.form !== 'neutral' ? { value: e, clamped: false } : null;
  const n = Number(e);
  if (!Number.isFinite(n)) return null;
  const c = Math.min(of.max, Math.max(of.min, n));
  return c === n ? { value: e, clamped: false } : { value: String(c), clamped: true };
}
