/**
 * The `html` entity — VEML 4.0 §4.6, the whole of VEML's 2D UI story.
 *
 * An embedded web surface: a sandboxed browsing context on a quad in the
 * entity's local XY plane, facing +Z, sized by the transform. A browser cannot
 * paint a live iframe into a WebGL texture, so the realization is in two
 * halves that move together:
 *
 *  - the QUAD, a plane mesh in the scene (what the world sees: it occludes,
 *    it is where the panel is, it carries the transform), and
 *  - the IFRAME, a DOM element over the canvas that follows the quad's
 *    projection every frame — hidden when the quad is behind the viewer or
 *    off the canvas. The page is drawn by the browser at full fidelity and is
 *    usable with the pointer. What this cannot do is sit behind a wall: a quad
 *    occluded by scene geometry still shows its page (recorded in deviations).
 *
 * The iframe is the capability boundary §4.6 names: `sandbox` without
 * `allow-same-origin`, so the page is a null origin with standard web
 * sandboxing and none of the world's capabilities; a world script cannot reach
 * into it, nor it into the sandbox. Its only way to speak is `postMessage`,
 * which the session turns into the entity's `on-message` action.
 *
 * Pointer events: the page's while the pointer is free, the canvas's while it
 * is locked (so mouse-look over a panel keeps working).
 */
import { CreatePlane } from '@babylonjs/core/Meshes/Builders/planeBuilder';
import { Vector3, Matrix } from '@babylonjs/core/Maths/math.vector';
import { Color3 } from '@babylonjs/core/Maths/math.color';
import { Viewport } from '@babylonjs/core/Maths/math.viewport';
import type { Camera } from '@babylonjs/core/Cameras/camera';
import type { Mesh } from '@babylonjs/core/Meshes/mesh';
import type { Scene } from '@babylonjs/core/scene';
import type { VemlHtmlEntity } from '../veml/documentModel';
import { StandardMaterial } from '../engine/shaderImports';

/** The `sandbox` flags: scripts and forms, never the embedder's origin. */
export const HTML_SANDBOX = 'allow-scripts allow-forms';
/** A private marker so a page's tooling can find the surfaces (not an API). */
export const HTML_SURFACE_ATTR = 'data-webverse-html-surface';

export interface HtmlHost {
  document: Document;
}

export interface HtmlQuad {
  mesh: Mesh;
  material: StandardMaterial;
}

export interface HtmlSurface extends HtmlQuad {
  readonly tag: string;
  readonly iframe: HTMLIFrameElement;
  /** The action the entity's `on-message` names, if any. */
  readonly onMessage?: string;
  /**
   * Place the iframe over the quad's projection onto a canvas of `width`×`height`
   * CSS pixels whose top-left is at (`offsetX`, `offsetY`) in the page. Hides it
   * when the quad is behind the camera or entirely off the canvas.
   */
  project(camera: Camera, width: number, height: number, offsetX?: number, offsetY?: number): void;
  /** Whether the page receives pointer events (false while the pointer is locked). */
  setInteractive(interactive: boolean): void;
  /** True when `source` is this surface's browsing context (a `message` event's source). */
  isFrom(source: unknown): boolean;
  dispose(): void;
}

/** The quad alone — what a DOM-less embedder still gets. */
export function createHtmlQuad(entity: VemlHtmlEntity, scene: Scene): HtmlQuad {
  const tag = entity.tag ?? 'html';
  const mesh = CreatePlane(`html:${tag}`, { size: 1 }, scene);
  const material = new StandardMaterial(`html:${tag}:mat`, scene);
  // A dark, slightly translucent slab: visible where the panel is from any
  // angle, and unobtrusive under the page the iframe draws over it.
  material.emissiveColor = new Color3(0.08, 0.09, 0.11);
  material.disableLighting = true;
  material.backFaceCulling = false;
  material.alpha = 0.85;
  mesh.material = material;
  mesh.isPickable = false;
  return { mesh, material };
}

const CORNERS = [
  new Vector3(-0.5, -0.5, 0),
  new Vector3(0.5, -0.5, 0),
  new Vector3(0.5, 0.5, 0),
  new Vector3(-0.5, 0.5, 0),
];

export function createHtmlSurface(entity: VemlHtmlEntity, scene: Scene, host: HtmlHost): HtmlSurface {
  const quad = createHtmlQuad(entity, scene);
  const tag = entity.tag ?? 'html';
  const doc = host.document;

  const iframe = doc.createElement('iframe');
  iframe.setAttribute('sandbox', HTML_SANDBOX);
  iframe.setAttribute('referrerpolicy', 'no-referrer');
  iframe.setAttribute(HTML_SURFACE_ATTR, tag);
  iframe.setAttribute('title', tag);
  if (entity.url?.resolved) iframe.setAttribute('src', entity.url.resolved);
  const s = iframe.style;
  s.position = 'fixed';
  s.left = '0px';
  s.top = '0px';
  s.width = '0px';
  s.height = '0px';
  s.border = '0';
  s.margin = '0';
  s.padding = '0';
  s.background = 'transparent';
  s.display = 'none';
  s.pointerEvents = 'auto';
  s.zIndex = '5';
  doc.body.appendChild(iframe);

  let disposed = false;
  const dispose = (): void => {
    if (disposed) return;
    disposed = true;
    iframe.remove();
    if (!quad.mesh.isDisposed()) quad.mesh.dispose(false, true);
  };
  // Registry disposal goes through the mesh; the iframe must go with it.
  quad.mesh.onDisposeObservable.add(() => {
    if (!disposed) {
      disposed = true;
      iframe.remove();
    }
  });

  const world = new Vector3();
  const view = new Vector3();
  const screen = new Vector3();
  const identity = Matrix.Identity();

  return {
    ...quad,
    tag,
    iframe,
    onMessage: entity.onMessage,
    project(camera, width, height, offsetX = 0, offsetY = 0) {
      if (disposed) return;
      const worldMatrix = quad.mesh.computeWorldMatrix(true);
      const viewMatrix = camera.getViewMatrix();
      const transform = scene.getTransformMatrix();
      const viewport = new Viewport(0, 0, width, height);
      let minX = Infinity;
      let minY = Infinity;
      let maxX = -Infinity;
      let maxY = -Infinity;
      for (const corner of CORNERS) {
        Vector3.TransformCoordinatesToRef(corner, worldMatrix, world);
        // Left-handed view space looks down +z: a corner at or behind the eye
        // has no projection — hide rather than draw a mirrored rectangle.
        Vector3.TransformCoordinatesToRef(world, viewMatrix, view);
        if (view.z <= camera.minZ) {
          s.display = 'none';
          return;
        }
        Vector3.ProjectToRef(world, identity, transform, viewport, screen);
        if (screen.x < minX) minX = screen.x;
        if (screen.y < minY) minY = screen.y;
        if (screen.x > maxX) maxX = screen.x;
        if (screen.y > maxY) maxY = screen.y;
      }
      // Clip to the canvas; hide when nothing is left.
      const left = Math.max(0, minX);
      const top = Math.max(0, minY);
      const right = Math.min(width, maxX);
      const bottom = Math.min(height, maxY);
      if (right - left < 1 || bottom - top < 1) {
        s.display = 'none';
        return;
      }
      s.display = 'block';
      s.left = `${offsetX + left}px`;
      s.top = `${offsetY + top}px`;
      s.width = `${right - left}px`;
      s.height = `${bottom - top}px`;
    },
    setInteractive(interactive) {
      s.pointerEvents = interactive ? 'auto' : 'none';
    },
    isFrom(source) {
      return source !== null && source !== undefined && source === iframe.contentWindow;
    },
    dispose,
  };
}
