/**
 * The physics rig: rigid bodies for the entities a script makes `Physical`,
 * on demand.
 *
 * The engine (Havok, through Babylon's plugin) lives in a code-split chunk
 * and loads the first time a world asks for a body. Until it lands, and in a
 * world that never asks, nothing here touches the simulation: the visitor's
 * own locomotion stays kinematic (proven, VR-safe), entities stay where the
 * document put them, and the fast path carries no engine.
 *
 * What a state means (the World API's `InteractionState`):
 * - `Physical`: a dynamic body, with a collider from the entity's mesh (a
 *   convex hull for a single mesh, a box from the hierarchy's bounds for a
 *   glb), driven by gravity and contact. Its mesh stops colliding with the
 *   visitor's capsule through the mesh collision system, so walking into it
 *   pushes it instead of being stopped by it.
 * - `Static`: a static body, when the engine is up: a wall a crate can rest
 *   against. Without the engine, nothing.
 * - `Placing`: a kinematic body: moved by its node, pushing dynamic bodies,
 *   never pushed.
 * - `Hidden`: no body.
 *
 * When the engine is up, every walkable mesh of the world gets a static body
 * too (a mesh collider), so a crate rests on the floor the visitor walks on.
 * The visitor is a kinematic capsule that follows the feet each frame; a
 * kinematic body is infinitely heavy to the engine, so the visitor shoves
 * what they walk into.
 */
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import { Mesh } from '@babylonjs/core/Meshes/mesh';
import { TransformNode } from '@babylonjs/core/Meshes/transformNode';
import { Vector3 } from '@babylonjs/core/Maths/math.vector';
import type { Scene } from '@babylonjs/core/scene';
import type { WalkableSource } from '../../controller/groundProbe';
import { CAPSULE_RADIUS_M, EYE_HEIGHT_M } from '../../controller/firstPersonController';
import { log } from '../../logging/runtimeLog';
import type { PhysicalPropertiesSpec } from '../../sandbox/sandboxTypes';
import type { PhysicsBodyHandle, PhysicsBodySpec, PhysicsChunkModule, PhysicsMotion, PhysicsWorld } from './physicsChunk';

export type { PhysicsChunkModule } from './physicsChunk';
export type PhysicsChunkLoader = () => Promise<PhysicsChunkModule>;
export type PhysicsInteraction = 'static' | 'physical' | 'placing' | 'hidden';

export interface PhysicsReport {
  /** `none` until a world asks for a body; then loading, ready, or failed (the world stays kinematic). */
  engine: 'none' | 'loading' | 'ready' | 'failed';
  dynamic: number;
  static: number;
  animated: number;
}

export interface PhysicsRig {
  /**
   * The entity's interaction state changed; give it, change, or take away its body.
   * `upright`: the body never turns (a character, which stands on its feet).
   */
  setInteraction(id: string, node: TransformNode, meshes: readonly AbstractMesh[], state: PhysicsInteraction, options?: { upright?: boolean }): void;
  /** Mass, drag, angular drag and centre of mass drive the body; `gravitational: false` makes it kinematic. */
  setProperties(id: string, props: PhysicalPropertiesSpec): void;
  /** True while the entity has a dynamic body: the engine owns its motion. */
  isSimulated(id: string): boolean;
  /** Set the body's vertical speed (a jump). False when the entity has no dynamic body. */
  launch(id: string, upMps: number): boolean;
  /** True when the body is not moving vertically (on something). */
  resting(id: string): boolean;
  remove(id: string): void;
  /** Per frame: the visitor's capsule follows the feet; new walkable meshes get static bodies. */
  tick(dtS: number, feet: Vector3): void;
  /** Advance the simulation (tests). The client's render step does this on its own. */
  step(dtS: number): void;
  /** Resolves once the engine decision is made (ready or failed), or at once when nothing asked for it. */
  ready(): Promise<void>;
  report(): PhysicsReport;
  dispose(): void;
}

export interface CreatePhysicsRigOptions {
  loader?: PhysicsChunkLoader;
  /** Hands the chunk the engine instance (tests read the wasm from disk). */
  instantiate?: () => Promise<unknown>;
  walkables: WalkableSource;
  /** Positive magnitude, m/s²; the world's locomotion hint where it has one. */
  gravityMps2?: number;
}

export function emptyPhysicsReport(): PhysicsReport {
  return { engine: 'none', dynamic: 0, static: 0, animated: 0 };
}

const defaultLoader: PhysicsChunkLoader = () => import('./physicsChunk');
const DEFAULT_GRAVITY_MPS2 = 9.81;
const DEFAULT_MASS_KG = 1;
/** A body at rest: vertical speed under this. */
const RESTING_MPS = 0.05;

interface Entity {
  node: TransformNode;
  meshes: readonly AbstractMesh[];
  state: PhysicsInteraction;
  props: PhysicalPropertiesSpec;
  body: PhysicsBodyHandle | null;
  /** The mesh collision flags the body replaced, restored when it goes. */
  collisionFlags: Map<AbstractMesh, boolean>;
  /** Its body never turns (a character). */
  upright?: boolean;
}

function motionFor(state: PhysicsInteraction, props: PhysicalPropertiesSpec): PhysicsMotion | null {
  switch (state) {
    case 'physical':
      return props.gravitational === false ? 'animated' : 'dynamic';
    case 'placing':
      return 'animated';
    case 'static':
      return 'static';
    default:
      return null;
  }
}

/** The collider an entity's geometry gives: a hull for one mesh, a box for a hierarchy. */
function shapeFor(node: TransformNode, meshes: readonly AbstractMesh[]): Pick<PhysicsBodySpec, 'shape' | 'mesh' | 'extents' | 'center'> {
  if (node instanceof Mesh && node.getTotalVertices() > 0) return { shape: 'convex', mesh: node };
  const single = meshes.length === 1 && meshes[0] instanceof Mesh ? (meshes[0] as Mesh) : null;
  if (single && single.getTotalVertices() > 0 && single.parent === node) return { shape: 'convex', mesh: single };
  node.computeWorldMatrix(true);
  const { min, max } = node.getHierarchyBoundingVectors(true);
  const extents = max.subtract(min);
  const worldCenter = min.add(max).scale(0.5);
  const center = Vector3.TransformCoordinates(worldCenter, node.getWorldMatrix().clone().invert());
  return {
    shape: 'box',
    extents: new Vector3(Math.max(extents.x, 0.01), Math.max(extents.y, 0.01), Math.max(extents.z, 0.01)),
    center,
  };
}

export function createPhysicsRig(scene: Scene, options: CreatePhysicsRigOptions): PhysicsRig {
  const loader = options.loader ?? defaultLoader;
  const gravity = new Vector3(0, -(options.gravityMps2 ?? DEFAULT_GRAVITY_MPS2), 0);
  const entities = new Map<string, Entity>();
  const grounds = new Map<AbstractMesh, PhysicsBodyHandle>();
  let world: PhysicsWorld | null = null;
  let engine: PhysicsReport['engine'] = 'none';
  let loading: Promise<void> | null = null;
  let disposed = false;
  let visitor: { node: TransformNode; body: PhysicsBodyHandle } | null = null;
  let lastWalkables: readonly AbstractMesh[] | null = null;

  const ensureEngine = (): Promise<void> => {
    if (loading) return loading;
    engine = 'loading';
    loading = loader()
      .then((chunk) => chunk.createPhysicsWorld(scene, { gravity, instantiate: options.instantiate }))
      .then((w) => {
        if (disposed) {
          w.dispose();
          return;
        }
        world = w;
        engine = 'ready';
        for (const [id, e] of entities) realise(id, e);
        syncGrounds(true);
      })
      .catch((err: unknown) => {
        if (disposed) return;
        engine = 'failed';
        log.warn(`[webverse] physics: the engine could not load; the world stays kinematic — ${String(err)}`);
      });
    return loading;
  };

  const makeVisitor = (w: PhysicsWorld, feet: Vector3): { node: TransformNode; body: PhysicsBodyHandle } => {
    const node = new TransformNode('physics:visitor', scene);
    node.position.copyFrom(feet);
    node.computeWorldMatrix(true);
    const body = w.body(node, { motion: 'animated', shape: 'capsule', mass: 0, radius: CAPSULE_RADIUS_M, height: EYE_HEIGHT_M });
    return { node, body };
  };

  const dropBody = (e: Entity): void => {
    e.body?.dispose();
    e.body = null;
    for (const [m, flag] of e.collisionFlags) m.checkCollisions = flag;
    e.collisionFlags.clear();
  };

  /** Give the entity the body its state and properties call for, replacing what it has. */
  const realise = (id: string, e: Entity): void => {
    if (!world) return;
    const motion = motionFor(e.state, e.props);
    if (motion === null) {
      dropBody(e);
      return;
    }
    if (e.body) {
      e.body.setMotion(motion);
      applyProps(e);
      return;
    }
    const ground = grounds.get(e.node as AbstractMesh);
    if (ground) {
      // The entity's own body replaces the one it had as plain ground.
      ground.dispose();
      grounds.delete(e.node as AbstractMesh);
    }
    try {
      e.body = world.body(e.node, {
        ...shapeFor(e.node, e.meshes),
        motion,
        mass: e.props.mass ?? DEFAULT_MASS_KG,
        ...(e.upright ? { upright: true } : {}),
      });
    } catch (err) {
      log.warn(`[webverse] physics: no body for '${id}' — ${String(err)}`);
      return;
    }
    applyProps(e);
    if (motion === 'dynamic') {
      // The engine resolves contact with the visitor now; the capsule's own
      // mesh collision would only stop at the crate's face.
      for (const m of e.meshes) {
        e.collisionFlags.set(m, m.checkCollisions);
        m.checkCollisions = false;
      }
    }
  };

  const applyProps = (e: Entity): void => {
    if (!e.body) return;
    const p = e.props;
    if (p.mass !== undefined || p.centerOfMass) {
      e.body.setMass(p.mass ?? DEFAULT_MASS_KG, p.centerOfMass ? new Vector3(p.centerOfMass.x, p.centerOfMass.y, p.centerOfMass.z) : undefined);
    }
    if (p.drag != null || p.angularDrag != null) e.body.setDamping(p.drag ?? undefined, p.angularDrag ?? undefined);
  };

  /** Every walkable mesh without an entity body of its own is static ground. */
  const syncGrounds = (force: boolean): void => {
    if (!world) return;
    const current = options.walkables();
    if (!force && current === lastWalkables) return;
    lastWalkables = current;
    const owned = new Set<AbstractMesh>();
    for (const e of entities.values()) if (e.body) for (const m of e.meshes) owned.add(m);
    const wanted = new Set<AbstractMesh>();
    for (const m of current) {
      if (owned.has(m) || m.isDisposed() || !(m instanceof Mesh) || m.getTotalVertices() === 0) continue;
      wanted.add(m);
      if (!grounds.has(m)) {
        try {
          grounds.set(m, world.body(m, { motion: 'static', shape: 'mesh', mass: 0, mesh: m }));
        } catch (err) {
          log.warn(`[webverse] physics: no ground body for '${m.name}' — ${String(err)}`);
        }
      }
    }
    for (const [m, body] of grounds) {
      if (!wanted.has(m)) {
        body.dispose();
        grounds.delete(m);
      }
    }
  };

  const count = (motion: PhysicsMotion): number => {
    let n = 0;
    for (const e of entities.values()) if (e.body && e.body.motion() === motion) n += 1;
    if (motion === 'static') n += grounds.size;
    if (motion === 'animated' && visitor) n += 1;
    return n;
  };

  return {
    setInteraction(id, node, meshes, state, options): void {
      if (disposed) return;
      let e = entities.get(id);
      if (!e) {
        e = { node, meshes, state, props: {}, body: null, collisionFlags: new Map() };
        entities.set(id, e);
      } else {
        e.node = node;
        e.meshes = meshes;
        e.state = state;
      }
      if (options?.upright) e.upright = true;
      if (state === 'physical' || state === 'placing') void ensureEngine();
      if (state === 'hidden') {
        dropBody(e);
        if (world) syncGrounds(true);
        return;
      }
      realise(id, e);
    },
    setProperties(id, props): void {
      if (disposed) return;
      let e = entities.get(id);
      if (!e) {
        // Properties ahead of a state: kept for when the body comes.
        e = { node: new TransformNode(`physics:pending:${id}`, scene), meshes: [], state: 'hidden', props: {}, body: null, collisionFlags: new Map() };
        e.node.dispose();
        entities.set(id, e);
      }
      e.props = { ...e.props, ...props };
      if (e.body) realise(id, e);
    },
    isSimulated(id): boolean {
      const e = entities.get(id);
      return e?.body?.motion() === 'dynamic';
    },
    launch(id, upMps): boolean {
      const e = entities.get(id);
      if (!e?.body || e.body.motion() !== 'dynamic' || !Number.isFinite(upMps)) return false;
      const v = e.body.linearVelocity();
      e.body.setLinearVelocity(new Vector3(v.x, upMps, v.z));
      return true;
    },
    resting(id): boolean {
      const e = entities.get(id);
      if (!e?.body) return true;
      return Math.abs(e.body.linearVelocity().y) < RESTING_MPS;
    },
    remove(id): void {
      const e = entities.get(id);
      if (!e) return;
      dropBody(e);
      entities.delete(id);
    },
    tick(_dtS, feet): void {
      if (disposed || !world) return;
      // The visitor's capsule is made where the feet first are, never at the
      // origin: a crate dropped there would land on an invisible visitor.
      visitor ??= makeVisitor(world, feet);
      visitor.node.position.set(feet.x, feet.y, feet.z);
      visitor.node.computeWorldMatrix(true);
      syncGrounds(false);
    },
    step(dtS): void {
      world?.step(dtS);
    },
    ready(): Promise<void> {
      return loading ?? Promise.resolve();
    },
    report(): PhysicsReport {
      return { engine, dynamic: count('dynamic'), static: count('static'), animated: count('animated') };
    },
    dispose(): void {
      if (disposed) return;
      disposed = true;
      for (const e of entities.values()) dropBody(e);
      entities.clear();
      for (const b of grounds.values()) b.dispose();
      grounds.clear();
      visitor?.body.dispose();
      visitor?.node.dispose();
      visitor = null;
      world?.dispose();
      world = null;
    },
  };
}
