/**
 * VR pointer affordance — the IN-WORLD visual surface.
 *
 *
 * The Babylon-touching half of the VR pointer affordance: the portal focus
 * HIGHLIGHT (the same emissive boost desktop puts on the hit portal mesh), a
 * world-space LABEL (a DynamicTexture plane — the SAME idiom as `uiEntity.ts`'s
 * `text`), a teleport RETICLE (a small emissive disc at the ground hit point),
 * and an optional aim LASER (a thin box along the controller ray). A DOM overlay
 * (the desktop `portalOverlay`) is invisible in-headset, so the VR affordance MUST
 * be in-world — this is that in-world surface.
 *
 * Imported ONLY by the code-split `xrChunk.ts` (+ tests), so it rides the split
 * chunk (a non-VR world never fetches it). Babylon Materials/DynamicTexture come
 * from `../engine/shaderImports` (the manifest's SINGLE legal Materials site —
 * already in first-paint, so importing it into this chunk-only module adds NO
 * new Materials import SITE and pulls NO new shader into first paint: the shader
 * manifest stays byte-UNCHANGED). `xrChunk.ts` itself stays Materials-free.
 *
 * TESTING REALITY (honest): headless has NO headset — these in-world visuals
 * are NOT observable in e2e; they are MANUAL-verified in-headset. The pointer
 * LOGIC (pick / ground-filter / routing / navigate / teleport) is unit-proven
 * in `vrPointer.ts`; this module is the cosmetic surface it drives.
 */
import { CreatePlane } from '@babylonjs/core/Meshes/Builders/planeBuilder';
import { CreateDisc } from '@babylonjs/core/Meshes/Builders/discBuilder';
import { CreateBox } from '@babylonjs/core/Meshes/Builders/boxBuilder';
import { Color3 } from '@babylonjs/core/Maths/math.color';
import { Vector3 } from '@babylonjs/core/Maths/math.vector';
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import type { Mesh } from '@babylonjs/core/Meshes/mesh';
import type { Scene } from '@babylonjs/core/scene';
import { StandardMaterial, DynamicTexture } from '../engine/shaderImports';
import type { VrPointerAffordanceLike, VrPointerHand, VrVec3 } from './vrPointer';

/** Emissive boost applied to a focused portal mesh (the desktop portal highlight). */
const HIGHLIGHT_EMISSIVE = new Color3(0.35, 0.5, 0.9);
/** Reticle tint when the teleport target is valid (green). */
const RETICLE_VALID = new Color3(0.3, 0.85, 0.4);
/** Babylon `BILLBOARDMODE_ALL` (face the camera on all axes) — literal, documented. */
const BILLBOARDMODE_ALL = 7;
/** Label plane DynamicTexture resolution (modest — a short link label). */
const LABEL_W = 512;
const LABEL_H = 128;

/** A material carrying an emissiveColor (StandardMaterial / PBRMaterial). */
interface EmissiveMaterial {
  emissiveColor?: Color3;
}

/** Per-hand affordance meshes (lazily built, reused, LIFO-disposed). */
interface HandVisuals {
  ray?: Mesh;
  reticle?: Mesh;
  label?: Mesh;
  labelTex?: DynamicTexture;
  highlighted?: AbstractMesh;
  savedEmissive?: Color3 | null;
  lastLabel?: string;
}

export interface VrPointerAffordance extends VrPointerAffordanceLike {
  dispose(): void;
}

const emissiveOf = (mesh: AbstractMesh): EmissiveMaterial | null => {
  const mat = mesh.material as unknown as EmissiveMaterial | null;
  return mat && mat.emissiveColor instanceof Color3 ? mat : null;
};

/**
 * Build the in-world VR pointer affordance for a scene. All meshes are
 * `isPickable=false` (they are never portals/walkable themselves) and disposed
 * on `dispose()`.
 */
export function createVrPointerAffordance(scene: Scene): VrPointerAffordance {
  const hands: Record<VrPointerHand, HandVisuals> = { left: {}, right: {} };
  let disposed = false;

  const applyHighlight = (mesh: AbstractMesh): Color3 | null => {
    const mat = emissiveOf(mesh);
    if (!mat || !mat.emissiveColor) return null;
    const saved = mat.emissiveColor.clone();
    mat.emissiveColor = HIGHLIGHT_EMISSIVE.clone();
    return saved;
  };

  const restoreHighlight = (v: HandVisuals): void => {
    if (!v.highlighted || v.savedEmissive == null) return;
    if (v.highlighted.isDisposed()) return;
    const mat = emissiveOf(v.highlighted);
    if (mat) mat.emissiveColor = v.savedEmissive;
  };

  const ensureLabel = (v: HandVisuals, hand: VrPointerHand): void => {
    if (v.label && !v.label.isDisposed()) return;
    const tex = new DynamicTexture(`vrptr:${hand}:label:tex`, { width: LABEL_W, height: LABEL_H }, scene, false);
    const mat = new StandardMaterial(`vrptr:${hand}:label:mat`, scene);
    mat.emissiveTexture = tex;
    mat.disableLighting = true;
    mat.backFaceCulling = false;
    const plane = CreatePlane(`vrptr:${hand}:label`, { width: 0.5, height: 0.125 }, scene);
    plane.material = mat;
    plane.isPickable = false;
    plane.billboardMode = BILLBOARDMODE_ALL;
    plane.setEnabled(false);
    v.label = plane;
    v.labelTex = tex;
    v.lastLabel = undefined;
  };

  const drawLabel = (v: HandVisuals, text: string): void => {
    if (!v.labelTex || v.lastLabel === text) return;
    const ctx = v.labelTex.getContext() as unknown as {
      clearRect(x: number, y: number, w: number, h: number): void;
    };
    ctx.clearRect(0, 0, LABEL_W, LABEL_H);
    // Background + text via the DynamicTexture canvas-2D helper (uiEntity idiom).
    v.labelTex.drawText(text, null, 82, 'bold 44px sans-serif', '#dfe3ea', '#101014cc', true, true);
    v.lastLabel = text;
  };

  return {
    showRay(hand: VrPointerHand, origin: VrVec3, direction: VrVec3, length: number): void {
      if (disposed) return;
      const v = hands[hand];
      if (!v.ray || v.ray.isDisposed()) {
        const box = CreateBox(`vrptr:${hand}:ray`, { width: 0.006, height: 0.006, depth: 1 }, scene);
        const mat = new StandardMaterial(`vrptr:${hand}:ray:mat`, scene);
        mat.emissiveColor = new Color3(0.6, 0.7, 0.95);
        mat.disableLighting = true;
        box.material = mat;
        box.isPickable = false;
        v.ray = box;
      }
      const o = new Vector3(origin.x, origin.y, origin.z);
      const d = new Vector3(direction.x, direction.y, direction.z).normalize();
      const len = Number.isFinite(length) && length > 0 ? length : 1;
      // Orient the box along the ray (local +Z), then place its midpoint.
      v.ray.setEnabled(true);
      v.ray.scaling.z = len;
      v.ray.position.copyFrom(o.add(d.scale(len / 2)));
      v.ray.lookAt(o.add(d));
    },
    hideRay(hand: VrPointerHand): void {
      if (disposed) return;
      hands[hand].ray?.setEnabled(false);
    },
    showPortalFocus(hand: VrPointerHand, mesh: unknown, label: string): void {
      if (disposed) return;
      const v = hands[hand];
      const m = mesh as AbstractMesh;
      if (v.highlighted !== m) {
        restoreHighlight(v);
        v.highlighted = m;
        v.savedEmissive = applyHighlight(m);
      }
      ensureLabel(v, hand);
      drawLabel(v, label);
      if (v.label) {
        // Float the label above the portal mesh centre (billboarded to camera).
        const c = m.getBoundingInfo().boundingBox.centerWorld;
        v.label.position.set(c.x, c.y + 0.6, c.z);
        v.label.setEnabled(true);
      }
    },
    clearPortalFocus(hand: VrPointerHand): void {
      if (disposed) return;
      const v = hands[hand];
      restoreHighlight(v);
      v.highlighted = undefined;
      v.savedEmissive = null;
      v.label?.setEnabled(false);
    },
    showTeleportTarget(hand: VrPointerHand, point: VrVec3, valid: boolean): void {
      if (disposed) return;
      const v = hands[hand];
      if (!v.reticle || v.reticle.isDisposed()) {
        const disc = CreateDisc(`vrptr:${hand}:reticle`, { radius: 0.25, tessellation: 24 }, scene);
        const mat = new StandardMaterial(`vrptr:${hand}:reticle:mat`, scene);
        mat.emissiveColor = RETICLE_VALID.clone();
        mat.disableLighting = true;
        mat.backFaceCulling = false;
        disc.material = mat;
        disc.isPickable = false;
        disc.rotation.x = Math.PI / 2; // lay flat on the ground
        v.reticle = disc;
      }
      const mat = v.reticle.material as unknown as EmissiveMaterial | null;
      if (mat && mat.emissiveColor) mat.emissiveColor = (valid ? RETICLE_VALID : new Color3(0.85, 0.3, 0.3)).clone();
      v.reticle.position.set(point.x, point.y + 0.02, point.z);
      v.reticle.setEnabled(valid);
    },
    hideTeleportTarget(hand: VrPointerHand): void {
      if (disposed) return;
      hands[hand].reticle?.setEnabled(false);
    },
    dispose(): void {
      if (disposed) return;
      disposed = true;
      for (const hand of ['left', 'right'] as VrPointerHand[]) {
        const v = hands[hand];
        restoreHighlight(v);
        v.ray?.material?.dispose();
        v.ray?.dispose();
        v.reticle?.material?.dispose();
        v.reticle?.dispose();
        v.label?.material?.dispose();
        v.labelTex?.dispose();
        v.label?.dispose();
      }
    },
  };
}
