/**
 * Runtime feedback surface.
 *
 * The default, themeable, DOM-based user-facing surface for the self-boot
 * path (no app chrome): adopts the inline SPLASH container baked into
 * index.html (`#webverse-feedback` — critical CSS paints before this chunk
 * arrives), then renders the LOADING OVERLAY (world title + per-asset
 * progress with bytes where available, auto-dismissed on world-enter), the
 * hard-failure ERROR CARD (non-technical reason + actionable hint + reload),
 * and the non-blocking capability-gap TOAST (dismissible; never a blocking
 * error).
 *
 * OPT-OUT: this module is wired only by main.ts (the default page). An
 * embedder consuming `createWorldSession` directly gets NO default surface
 * and drives its own via the same seams this one uses — the session's
 * `onProgress` (load progress events) + `onLifecycle` (lifecycle events). The
 * surface only REACTS to those events; it never wraps or intercepts the load
 * path, so `__webverse.loadWorld`-driven flows (the e2e) are untouched.
 *
 * Naming note: the `data-webverse-feedback-*` attributes
 * and `--webverse-feedback-*` custom properties are implementation
 * identifiers of THIS runtime's private, swappable default surface (the same
 * allowance as the `[webverse]` log prefix); user-facing copy is unbranded.
 *
 * Main-bundle, DOM-only, ZERO Babylon imports. Churn-safe: one container +
 * one toast node reused across loads; per-asset rows update IN PLACE and are
 * cleared per load (no accumulation across the 25-cycle churn harness).
 * Accessibility: overlay `role=status aria-live=polite`, error card
 * `role=alert`; reload/dismiss are real <button>s (keyboard-reachable); the
 * containers are pointer-events:none — only buttons re-enable, so canvas
 * input is never eaten.
 */
import type { WorldLifecycleEvent, WorldLoadFailure } from '../scene/worldSession';
import type { WorldLoadProgressEvent } from '../scene/loadProgress';
import type { CapabilityReport } from '../capabilities/capabilityRegistry';
import type { ConsentAnswer, ConsentRequest } from '../capabilities/consent';
import { log } from '../logging/runtimeLog';

export interface FeedbackSurfaceOptions {
  /**
   * Reload affordance callback: called with the failed world URL (retry it),
   * or null for a boot-fatal (the page itself should reload).
   */
  onReload?: (failedUrl: string | null) => void;
}

export interface FeedbackSurface {
  onLifecycle(event: WorldLifecycleEvent): void;
  onProgress(event: WorldLoadProgressEvent): void;
  /** Show the non-blocking degradation toast when the report has gaps. */
  notifyCapabilities(report: CapabilityReport): void;
  /**
   * Ask the visitor about a world's capabilities (VEML 4.0 §9): a card
   * naming the world's origin, one row per capability with Allow and Block.
   * Resolves once every row is answered; a row still open when the card goes
   * (a new load, a newer request, dispose) is answered denied.
   */
  requestConsent(req: ConsentRequest): Promise<Record<string, ConsentAnswer>>;
  /** Boot finished with no world requested — dismiss the splash. */
  bootCompleted(): void;
  /** Boot (or another fatal path) failed — convert to the error card. */
  showFatal(err: unknown): void;
  dispose(): void;
}

export type FeedbackState = 'splash' | 'loading' | 'error' | 'hidden';

/** Container id — must match the inline splash markup in index.html. */
export const FEEDBACK_CONTAINER_ID = 'webverse-feedback';

/** Max per-asset rows rendered; the rest collapse into a "+N more" line. */
export const MAX_ASSET_ROWS = 8;

/**
 * The network-phase hint must be HONEST: browsers make
 * CORS failures indistinguishable from offline/DNS/connection-refused (all
 * opaque TypeErrors), but the TARGET URL is still known — a SAME-ORIGIN
 * target can never fail on CORS, so it gets plain unreachable copy; a known
 * cross-origin target names CORS (still hedged with offline); an
 * undeterminable target gets the fully hedged copy.
 */
function networkPhaseHint(targetUrl: string | undefined, pageHref: string | undefined): string {
  let crossOrigin: boolean | null = null;
  if (targetUrl !== undefined && pageHref !== undefined) {
    try {
      const page = new URL(pageHref);
      crossOrigin = new URL(targetUrl, page.href).origin !== page.origin;
    } catch {
      crossOrigin = null;
    }
  }
  if (crossOrigin === false) {
    return "The world's server didn't respond. Check the address and your connection, then try again.";
  }
  if (crossOrigin === true) {
    return "The world's host needs to allow cross-origin access (CORS). It may also be offline.";
  }
  return (
    "If the world lives on another site, the world's host needs to allow " +
    'cross-origin access (CORS). It may also be offline.'
  );
}

/**
 * Non-technical error copy, keyed structurally — never message-sniffed.
 * `pageHref` (when known) origin-gates the network-phase CORS wording — see
 * `networkPhaseHint`.
 */
export function failureCopy(
  failure: WorldLoadFailure | undefined,
  pageHref?: string,
): {
  reason: string;
  hint: string;
} {
  // A local path pasted into a web app. Predictable, and it has a specific
  // answer; the generic network wording would send the user hunting for
  // CORS, and the page's own rule about sites would tell them nothing: a
  // file is no site. Checked before the phase split: the browser refuses the
  // scheme before any response exists, so it arrives as `network`, or the
  // page declines it before asking, and it arrives as `refused`.
  if (failure && (failure.kind === 'fetch' || failure.kind === 'refused') && failure.url?.startsWith('file:')) {
    return {
      reason: "That's a file on your computer, not a web address.",
      hint: 'A web page can\'t open local files. Serve the folder over http (any static server), or open it with the desktop build.',
    };
  }
  if (failure && failure.kind === 'fetch') {
    if (failure.phase === 'network') {
      return {
        reason: "This world couldn't be reached.",
        hint: networkPhaseHint(failure.url, pageHref),
      };
    }
    // A world its owner restricted answers 401 to nobody and 403 to the
    // wrong person. Neither is a broken link: one wants a sign-in, the
    // other the owner's permission.
    if (/\bHTTP 401\b/.test(failure.message ?? '')) {
      return {
        reason: 'This world asks you to sign in.',
        hint: failure.url
          ? `Only people its owner allows can view it. Open ${failure.url} in your browser and sign in there, then come back.`
          : 'Only people its owner allows can view it. Open its address in your browser and sign in there, then come back.',
      };
    }
    if (/\bHTTP 403\b/.test(failure.message ?? '')) {
      return {
        reason: "This world's owner has not allowed you in.",
        hint: 'You are signed in, but this account is not on the list of people who may view it. Ask the owner to add you.',
      };
    }
    return {
      reason: "This world couldn't be found.",
      // Name what was asked for. For a bare model URL that is the whole
      // interface, and "the link may be broken" without the link is a black
      // screen with better manners.
      hint: failure.url
        ? `The link may be broken or the file moved (HTTP error): ${failure.url}`
        : 'The link may be broken or the file moved (HTTP error).',
    };
  }
  switch (failure?.kind) {
    case 'malformed-xml':
      return {
        reason: "This world's file is damaged.",
        hint: "The document isn't valid XML — re-export or fix the world file.",
      };
    case 'served-html':
      // Distinct from `not-veml`, which means the document WAS fetched
      // and is not a world. This means nothing is there at all: the address
      // answered with a web page, which is what a dev server or an
      // SPA-fallback host sends for a file it does not have.
      return {
        reason: 'There is no world at this address.',
        hint: failure.url
          ? `That address served a web page, not a world — check the path: ${failure.url}`
          : 'That address served a web page, not a world — check the path.',
      };
    case 'not-veml':
      return {
        reason: "This isn't a world document.",
        hint: "The link doesn't point to a VEML world.",
      };
    case 'unsupported-namespace':
      return {
        reason: 'This world needs a newer browser.',
        hint: "The world declares a VEML version this browser doesn't support.",
      };
    case 'refused':
      // Nothing is wrong with the world or the network: the page itself only
      // opens worlds from the sites it lists. The message names the address
      // and those sites.
      return { reason: "This page doesn't open worlds from that site.", hint: failure.message };
    default:
      return {
        reason: 'Something went wrong loading this world.',
        hint: 'Reloading may fix it. Details are in the browser console.',
      };
  }
}

/**
 * "412 KB" / "1.2 MB"; with a known total: "412 KB / 1.2 MB". Units are
 * coordinated with the rounding: a KB value that rounds
 * to 1000 promotes to "1.0 MB" (never "1000 KB"), and sub-kilobyte values
 * render as real bytes (never "0 KB").
 */
export function formatByteProgress(loadedBytes: number, totalBytes: number | null): string {
  const one = (bytes: number): string => {
    const kb = Math.round(bytes / 1_000);
    if (kb >= 1_000) return `${(bytes / 1_000_000).toFixed(1)} MB`;
    if (kb >= 1) return `${kb} KB`;
    return `${Math.max(0, Math.round(bytes))} B`;
  };
  return totalBytes === null ? one(loadedBytes) : `${one(loadedBytes)} / ${one(totalBytes)}`;
}

/** Toast text: "…: terrain×2, water×1" (the HUD capability-line join). */
export function capabilityToastText(report: CapabilityReport): string {
  const total = report.gaps.reduce((n, g) => n + g.count, 0);
  const list = report.gaps.map((g) => `${g.feature}×${g.count}`).join(', ');
  return (
    `This world uses ${total} feature${total === 1 ? '' : 's'} ` +
    `this browser doesn't support yet: ${list}`
  );
}

function basename(url: string): string {
  try {
    const path = new URL(url, 'http://placeholder.invalid/').pathname;
    const last = path.split('/').filter(Boolean).pop();
    // Root-path URLs have no basename — fall back to the URL WITHOUT its
    // query/hash (never leak `?param=...` into the overlay title).
    return last ?? url.split(/[?#]/)[0] ?? url;
  } catch {
    return url;
  }
}

export function createFeedbackSurface(
  doc: Document,
  options: FeedbackSurfaceOptions = {},
): FeedbackSurface {
  // Adopt the inline splash container when present (the runtime takes
  // over the SAME node); create one for embedder pages without the markup.
  const adopted = doc.getElementById(FEEDBACK_CONTAINER_ID);
  const createdContainer = adopted === null;
  const container: HTMLElement = adopted ?? doc.createElement('div');
  if (createdContainer) {
    container.id = FEEDBACK_CONTAINER_ID;
    container.setAttribute('role', 'status');
    container.setAttribute('aria-live', 'polite');
    // Minimal inline styling for the no-markup path (index.html carries the
    // real critical CSS; a bare embedder page still gets a legible overlay).
    container.style.cssText =
      'position:fixed;inset:0;z-index:10;display:flex;flex-direction:column;' +
      'align-items:center;justify-content:center;gap:12px;background:#101014;' +
      'color:#dfe3ea;font:14px/1.5 system-ui,sans-serif;text-align:center;' +
      'pointer-events:none;';
    doc.body.appendChild(container);
  }

  let state: FeedbackState = 'splash';
  let failedUrl: string | null = null;
  let disposed = false;
  // Per-asset rows for the CURRENT load, keyed by asset URL; rows update in
  // place (no per-event node creation — churn-safe).
  const assetRows = new Map<string, HTMLElement>();
  let overflowRow: HTMLElement | undefined;
  let toast: HTMLElement | undefined;

  const setState = (next: FeedbackState): void => {
    state = next;
    container.setAttribute('data-webverse-feedback-state', next);
    // The loading overlay is a polite status region; the error card must
    // interrupt — swap the role AND the explicit aria-live (an explicit
    // `polite` would otherwise override role=alert's implicit assertiveness).
    container.setAttribute('role', next === 'error' ? 'alert' : 'status');
    container.setAttribute('aria-live', next === 'error' ? 'assertive' : 'polite');
    if (createdContainer) {
      // The created (embedder) path has no index.html stylesheet, so the
      // hidden-state rule must be applied inline — without this the created
      // container is a permanent opaque full-screen div.
      container.style.display = next === 'hidden' ? 'none' : 'flex';
    }
  };
  // Reflect the adopted splash into the surface's own state tracking; a
  // created (embedder) container starts hidden — nothing to show yet.
  setState(createdContainer ? 'hidden' : 'splash');

  // Keyboard flows (Enter on Reload / toast dismiss) must not strand focus on
  // <body> when the focused button is removed — locomotion keydown listeners
  // live on the canvas (index.html tabindex=0).
  const restoreFocus = (root: HTMLElement | undefined): void => {
    if (!root) return;
    const active = doc.activeElement;
    if (active !== null && root.contains(active)) {
      doc.getElementById('renderCanvas')?.focus();
    }
  };

  const clearChildren = (): void => {
    restoreFocus(container);
    while (container.firstChild) container.removeChild(container.firstChild);
    assetRows.clear();
    overflowRow = undefined;
  };

  const el = (tag: string, attrs?: Record<string, string>, text?: string): HTMLElement => {
    const node = doc.createElement(tag);
    if (attrs) for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, v);
    if (text !== undefined) node.textContent = text;
    return node;
  };

  const spinner = (): HTMLElement =>
    el('div', { class: 'webverse-feedback-spinner', 'aria-hidden': 'true' });

  // --- loading overlay -----------------------------------------------------
  let titleEl: HTMLElement | undefined;
  let assetListEl: HTMLElement | undefined;

  const showLoading = (url: string): void => {
    clearChildren();
    container.appendChild(spinner());
    titleEl = el('p', { 'data-webverse-feedback-title': '' }, `Loading ${basename(url)}…`);
    container.appendChild(titleEl);
    assetListEl = el('div', { 'data-webverse-feedback-assets': '' });
    assetListEl.style.cssText = 'font-size:12px;opacity:0.8;max-width:80vw;overflow:hidden;';
    container.appendChild(assetListEl);
    setState('loading');
  };

  const assetRow = (url: string): HTMLElement | null => {
    if (!assetListEl) return null;
    const existing = assetRows.get(url);
    if (existing) return existing;
    if (assetRows.size >= MAX_ASSET_ROWS) {
      // Collapse the overflow into one counter row (a 100-asset world must
      // not build a huge DOM).
      if (!overflowRow) {
        overflowRow = el('div', { 'data-webverse-feedback-asset-overflow': '' });
        assetListEl.appendChild(overflowRow);
      }
      overflowRow.textContent = `+${assetRows.size - MAX_ASSET_ROWS + 1} more…`;
      assetRows.set(url, overflowRow);
      return null; // overflow rows don't render per-asset text
    }
    const row = el('div', { 'data-webverse-feedback-asset': url }, `${basename(url)}…`);
    assetRows.set(url, row);
    assetListEl.appendChild(row);
    return row;
  };

  // --- error card ----------------------------------------------------------
  const showError = (failure: WorldLoadFailure | undefined, retryUrl: string | null): void => {
    clearChildren();
    removeToast(); // a stale capability toast must not float over the card
    failedUrl = retryUrl;
    // The page href origin-gates the network-phase CORS hint (see failureCopy).
    const copy = failureCopy(failure, doc.defaultView?.location?.href);
    const reason = el('p', { 'data-webverse-feedback-error-reason': '' }, copy.reason);
    // Themeable error accent (--webverse-feedback-error, per the story's
    // theming set); inline so the created (embedder) path is covered too.
    reason.style.color = 'var(--webverse-feedback-error, #ffb4ab)';
    container.appendChild(reason);
    container.appendChild(el('p', { 'data-webverse-feedback-error-hint': '' }, copy.hint));
    const reload = el('button', { type: 'button', 'data-webverse-feedback-reload': '' }, 'Reload');
    reload.addEventListener('click', () => {
      try {
        options.onReload?.(failedUrl);
      } catch (err) {
        log.warn('[webverse] feedback reload callback threw:', err);
      }
    });
    container.appendChild(reload);
    setState('error');
  };

  // --- toast ---------------------------------------------------------------
  // Each toast asked for, so one whose code arrives after it was cleared or replaced is not drawn.
  let toastTurn = 0;
  const removeToast = (): void => {
    toastTurn += 1;
    restoreFocus(toast);
    toast?.remove();
    toast = undefined;
  };

  // The toast's code (feedbackToast.ts) is fetched the first time a world has something to tell.
  const showToast = (text: string): void => {
    removeToast();
    const mine = toastTurn;
    void import('./feedbackToast').then(
      ({ buildToast }) => {
        if (mine !== toastTurn || disposed) return;
        toast = buildToast(doc, text, () => removeToast());
        doc.body.appendChild(toast);
      },
      () => undefined,
    );
  };

  // --- consent card (§9) ----------------------------------------------------
  let consentCard: HTMLElement | undefined;
  let consentOpen:
    | { answers: Record<string, ConsentAnswer>; remaining: Set<string>; resolve: (a: Record<string, ConsentAnswer>) => void }
    | undefined;

  /** Answer every open row `answer` and take the card down. */
  const settleConsent = (answer: ConsentAnswer): void => {
    const open = consentOpen;
    consentOpen = undefined;
    restoreFocus(consentCard);
    consentCard?.remove();
    consentCard = undefined;
    if (!open) return;
    for (const cap of open.remaining) open.answers[cap] = answer;
    open.resolve(open.answers);
  };

  const showConsent = (req: ConsentRequest): Promise<Record<string, ConsentAnswer>> => {
    settleConsent('denied'); // a newer question replaces an older one
    return new Promise((resolve) => {
      const remaining = new Set(req.capabilities);
      const answers: Record<string, ConsentAnswer> = {};
      consentOpen = { answers, remaining, resolve };
      if (remaining.size === 0) {
        settleConsent('denied');
        return;
      }
      // The card's code is fetched now, the first time a world asks. A question settled meanwhile (a newer one,
      // a new load, the surface gone) is not drawn; one whose code cannot be fetched is answered as denied.
      const mine = consentOpen;
      void import('./consentCard').then(
        ({ buildConsentCard }) => {
          if (consentOpen !== mine || disposed) return;
          consentCard = buildConsentCard(doc, req, (cap, answer, row) => {
            const open = consentOpen;
            if (open !== mine || !open.remaining.has(cap)) return;
            open.answers[cap] = answer;
            open.remaining.delete(cap);
            restoreFocus(row);
            row.remove();
            if (open.remaining.size === 0) settleConsent('denied');
          });
          doc.body.appendChild(consentCard);
        },
        () => {
          if (consentOpen === mine) settleConsent('denied');
        },
      );
    });
  };

  // --- the surface ----------------------------------------------------------
  const guarded =
    <T = void>(fn: (arg: T) => void) =>
    (arg?: T): void => {
      if (disposed) return;
      try {
        fn(arg as T);
      } catch (err) {
        // Observability, not control flow: a DOM failure must never break a
        // world load (the emitProgress posture).
        log.warn('[webverse] feedback surface error:', err);
      }
    };

  return {
    onLifecycle: guarded((event: WorldLifecycleEvent) => {
      switch (event.kind) {
        case 'load-started':
          removeToast();
          settleConsent('denied'); // the question was about the world being left
          showLoading(event.url);
          break;
        case 'document-parsed':
          if (titleEl && event.title) titleEl.textContent = `Loading ${event.title}…`;
          break;
        case 'world-entered':
          clearChildren();
          setState('hidden');
          break;
        case 'load-failed':
          showError(event.errors[0], event.url);
          break;
        case 'unloaded':
          removeToast();
          // An unload can CANCEL an in-flight load (the session emits
          // `unloaded` for that too) — never leave the overlay spinning for
          // an abandoned load.
          if (state === 'loading') {
            clearChildren();
            setState('hidden');
          }
          break;
      }
    }),
    onProgress: guarded((event: WorldLoadProgressEvent) => {
      if (state !== 'loading') return;
      const row = assetRow(event.url);
      if (!row || row === overflowRow) return;
      const name = basename(event.url);
      switch (event.kind) {
        case 'asset-started':
          break; // row created with its "name…" placeholder
        case 'asset-progress':
          row.textContent = `${name} — ${formatByteProgress(event.loadedBytes, event.totalBytes)}`;
          break;
        case 'asset-completed':
          row.textContent = `${name} — done`;
          break;
        case 'asset-failed':
          row.textContent = `${name} — failed`;
          row.setAttribute('data-webverse-feedback-asset-failed', '');
          break;
      }
    }),
    notifyCapabilities: guarded((report: CapabilityReport) => {
      if (!report || report.gaps.length === 0) return;
      showToast(capabilityToastText(report));
    }),
    requestConsent(req: ConsentRequest): Promise<Record<string, ConsentAnswer>> {
      if (disposed) return Promise.resolve(Object.fromEntries(req.capabilities.map((c) => [c, 'denied' as const])));
      try {
        return showConsent(req);
      } catch (err) {
        log.warn('[webverse] feedback surface error:', err);
        return Promise.resolve(Object.fromEntries(req.capabilities.map((c) => [c, 'denied' as const])));
      }
    },
    bootCompleted: guarded(() => {
      // Only from splash — never clobber an in-flight load or an error card.
      if (state === 'splash') {
        clearChildren();
        setState('hidden');
      }
    }),
    showFatal: guarded((err: unknown) => {
      log.error('[webverse] fatal:', err);
      showError(undefined, null);
    }),
    dispose(): void {
      if (disposed) return;
      disposed = true;
      removeToast();
      settleConsent('denied');
      if (createdContainer) {
        container.remove();
      } else {
        // Leave the adopted splash container in the page (it belongs to the
        // bootstrap HTML), parked hidden.
        clearChildren();
        container.setAttribute('data-webverse-feedback-state', 'hidden');
      }
    },
  };
}
