/**
 * VEML color-value parser. The FIDELITY CORE.
 *
 * Parses a VEML `background/color` value into raw RGBA floats, conforming to
 * how existing VEML worlds are rendered in practice rather than to the XSD
 * alone. This is DISTINCT from `src/scene/primitives.ts` `parseVemlColor`
 * (the clamped-diffuse parser with a broad HTML palette + 3/4-digit hex):
 * a background color needs HDR (values > 1) and the `color(...)` form, and it
 * has its own fixed named set + hex-length policy. The two are deliberately
 * NOT unified.
 *
 * Grammar:
 *  - 9 named colors, case-insensitive; otherwise `color(` → the color-value
 *    form, else hex.
 *  - `color(r g b a)`: 3 or 4 numeric tokens taken as raw floats, so a value
 *    of 1 == full channel (== hex FF) and > 1 == HDR intensity.
 *  - `#rrggbb` / `#rrggbbaa`: 6 or 8 hex digits ONLY, /255 per channel.
 *  - Anything malformed → gray (0.5,0.5,0.5,0.5).
 *
 * PURE: no Babylon, no DOM — unit-tests under plain node. Never throws
 * (malformed/absent → the gray fallback + a console.warn).
 */

import { log } from '../../logging/runtimeLog';

/** Raw RGBA — HDR-capable (r/g/b may exceed 1 for `color(...)` intensities). */
export interface RgbaColor {
  r: number;
  g: number;
  b: number;
  a: number;
}

/** The ONLY 9 conformant names for a background named color (`grey` is an
 * alias of `gray`). NOTE these differ from HTML/CSS and from primitives'
 * broader palette: `green` is (0,1,0) not HTML (0,0.5,0), and `yellow` is
 * (1,0.921569,0.015686). */
const UNITY_NAMED: Record<string, RgbaColor> = {
  white: { r: 1, g: 1, b: 1, a: 1 },
  black: { r: 0, g: 0, b: 0, a: 1 },
  gray: { r: 0.5, g: 0.5, b: 0.5, a: 1 },
  grey: { r: 0.5, g: 0.5, b: 0.5, a: 1 },
  red: { r: 1, g: 0, b: 0, a: 1 },
  yellow: { r: 1, g: 0.921569, b: 0.015686, a: 1 },
  blue: { r: 0, g: 0, b: 1, a: 1 },
  cyan: { r: 0, g: 1, b: 1, a: 1 },
  magenta: { r: 1, g: 0, b: 1, a: 1 },
  green: { r: 0, g: 1, b: 0, a: 1 },
};

/** The malformed/unknown fallback: (0.5,0.5,0.5,0.5) (gray, half-alpha).
 * The background applier opaquifies this for the clear color (a sky is opaque);
 * the parser itself returns the fallback unchanged. */
const FALLBACK: Readonly<RgbaColor> = { r: 0.5, g: 0.5, b: 0.5, a: 0.5 };

function warn(value: string): RgbaColor {
  log.warn(`[webverse] invalid VEML background color '${value}' — using gray fallback`);
  return { ...FALLBACK };
}

/** `color(r g b a)` / `color(r,g,b,a)`. Leniently accepts comma OR space
 * separators AND float components, not only space-separated integers. The
 * `1 == FF, > 1 == HDR` semantics are preserved (raw numbers returned). */
function fromColorValue(raw: string): RgbaColor {
  const inner = raw
    .toLowerCase()
    .replace('color(', '')
    .replace(')', '')
    .replace(/,/g, ' ') // leniency: comma OR space
    .trim();
  const tokens = inner.split(/\s+/).filter((t) => t.length > 0);
  if (tokens.length !== 3 && tokens.length !== 4) return warn(raw);
  const nums = tokens.map((t) => Number(t));
  if (nums.some((n) => !Number.isFinite(n))) return warn(raw);
  return {
    r: nums[0]!,
    g: nums[1]!,
    b: nums[2]!,
    a: tokens.length === 4 ? nums[3]! : 1, // 3-token alpha defaults to 1
  };
}

/** `#rrggbb` / `#rrggbbaa` — 6 or 8 digits ONLY (no 3/4 short
 * form — that is a primitives-only leniency). */
function fromHex(raw: string): RgbaColor {
  const hex = raw.replace('#', '');
  if (!/^[0-9a-fA-F]+$/.test(hex)) return warn(raw);
  const byte = (i: number): number => parseInt(hex.slice(i, i + 2), 16) / 255;
  if (hex.length === 6) {
    return { r: byte(0), g: byte(2), b: byte(4), a: 1 };
  }
  if (hex.length === 8) {
    return { r: byte(0), g: byte(2), b: byte(4), a: byte(6) };
  }
  return warn(raw);
}

/**
 * Parse a VEML background color value:
 * 9 named (case-insensitive) → hex/`color(...)` dispatch → gray fallback.
 * Absent/malformed never throws.
 */
export function parseVemlColorValue(value: string | undefined): RgbaColor {
  if (value === undefined) return { ...FALLBACK };
  const raw = value.trim();
  if (raw.length === 0) return warn(value);

  // Own-property guard: a plain-object lookup would resolve inherited keys like
  // `constructor` / `__proto__` to Object.prototype members (truthy) and spread
  // them to a malformed `{}` — this keeps unknown names on the gray-fallback path.
  const key = raw.toLowerCase();
  if (Object.prototype.hasOwnProperty.call(UNITY_NAMED, key)) return { ...UNITY_NAMED[key]! };

  if (raw.toLowerCase().startsWith('color(')) return fromColorValue(raw);
  if (raw.startsWith('#')) return fromHex(raw);

  // Bare token that is neither a known name nor a recognized form: malformed,
  // so warn and fall back to gray.
  return warn(value);
}
