export const VEML_4_0_NAMESPACE = "http://www.fivesqd.com/schemas/veml/4.0";
/** A root `veml` in the 4.0 namespace — or namespace-less but carrying
 *  `version` (the shell inserts the namespace before schema processing) —
 *  is a VEML 4.0 document. Anything else (a wrong namespace, or a
 *  namespace-less root without `version`, the prototype-era wire form) is
 *  not, and is not processed as one. */
export function classifyRoot(namespaceURI, hasVersion) {
    if (namespaceURI === VEML_4_0_NAMESPACE)
        return { is40: true };
    if (namespaceURI === null && hasVersion)
        return { is40: true };
    return {
        is40: false,
        diagnostic: { id: "veml:1.4:wrong-namespace", detail: namespaceURI ?? "no namespace, no version" },
    };
}
const SCHEME_RE = /^[A-Za-z][A-Za-z0-9+.-]*:/;
/** C0 controls and DEL. A URL parser strips them, so a scheme hidden behind
 *  one would read as a relative reference here and as itself to the fetcher
 *  (`java\tscript:`); the value is refused before any scheme is read. */
const CONTROL_RE = /[\u0000-\u001f\u007f]/;
/** §1.4 scheme allowlist: any URI-bearing attribute (`href`, `src`, `url`,
 *  …) must be `http(s)` if absolute; a document-relative reference inherits
 *  the document's base scheme and is always allowed here (base-URI
 *  resolution is a loader concern). A value with a control character in it
 *  is refused as `control-character`. Returns the offending scheme, or `null`
 *  when the value is acceptable. */
export function badScheme(value) {
    if (CONTROL_RE.test(value))
        return "control-character";
    const m = SCHEME_RE.exec(value);
    if (!m)
        return null;
    const scheme = m[0].slice(0, -1).toLowerCase();
    return scheme === "http" || scheme === "https" ? null : scheme;
}
