/**
 * Where a viewer-owned file (the default avatar) is fetched from.
 *
 * The viewer's files and the page can live in different places: a world
 * published at a host's /w/<id> loads the viewer from /webverse/.
 * Resolving the avatar against the page would ask for /w/avatars/default.glb,
 * a 404, and the other people in a room would never be drawn. So the viewer's own base
 * wins, and the page's base is the fallback for the app served from its own
 * folder, where the two are the same.
 */
export function viewerAssetUrl(
  path: string,
  viewerBase: string | undefined,
  pageBase: string | undefined,
): string | undefined {
  const base = viewerBase ?? pageBase;
  return base === undefined ? undefined : new URL(path, base).href;
}
