/**
 * The composition policy for `include` (VEML 4.0 §6.2), kept apart from the
 * scene so it can be reasoned about without one.
 *
 * A document may place other documents under its entities. The client fetches
 * the included documents in parallel, once per URL, and composes each one's
 * entities under the entity that named it. What bounds the work: only the
 * first `INCLUDE_ELIGIBLE_PER_DOCUMENT` subsidiary references of a document
 * are eligible, nesting stops at `INCLUDE_MAX_DEPTH`, the whole tree fetches
 * at most `INCLUDE_TREE_FETCH_CAP` documents, and a document that names one of
 * its own ancestors is omitted rather than followed. Any one failure omits
 * that include alone; the rest of the world, and the root above all, stands.
 *
 * The caller supplies the fetch, the build, where warnings go and whether the
 * load it serves is still the current one. Everything here is sequencing.
 */
import type { VemlDocument } from './documentModel';
import type { VemlParseResult } from './parser';

/** §6.2: the first sixteen subsidiary references of a document are eligible. */
export const INCLUDE_ELIGIBLE_PER_DOCUMENT = 16;
/** §6.2: a client supports nesting at least eight deep; this one stops there. */
export const INCLUDE_MAX_DEPTH = 8;
/** §6.2: the whole tree fetches at most sixty-four documents. */
export const INCLUDE_TREE_FETCH_CAP = 64;

/** One `include` as it sits in a built document: the entity that carries it and the resolved target. */
export interface IncludeSite {
  /** The registry id of the entity carrying the include (`''` when that entity did not build). */
  entityId: string;
  /** The reference as authored. */
  href: string;
  /** The reference resolved against the document that authored it. */
  url: string;
  /** §6.2: a hash the included document must match. */
  integrity?: string;
  /** The carrier's tag, for a carrier that has no registry entry yet (a glb still waiting to load). */
  carrierTag?: string;
  /**
   * Where the include stands in the include tree, depth first: its index among
   * the root's includes, then among its parent's, and so on. Compared in that
   * order, an include comes before the ones it brings in, and those before the
   * includes after it. Absent where the include's place in the tree is unknown.
   */
  order?: readonly number[];
}

export type IncludeOmissionReason =
  | 'ineligible'
  | 'cycle'
  | 'depth'
  | 'cap'
  | 'fetch'
  | 'integrity'
  | 'parse'
  | 'cancelled';

/**
 * What became of one include: composed under its entity, omitted and why, or
 * deferred — its carrier declared bounds (§4.8) and the visitor has not come
 * near enough to see them yet.
 */
export interface IncludeOutcome {
  url: string;
  entityId: string;
  /** 1 for the root's own includes, 2 for theirs, and so on. */
  depth: number;
  status: 'composed' | 'omitted' | 'deferred';
  /** Present when omitted. */
  reason?: IncludeOmissionReason;
  message?: string;
}

export interface ComposeDeps {
  /**
   * Fetch and parse one document; never rejects, failures come back in the
   * result. `integrity`, when the site pins one, is the hash the bytes must
   * match (a mismatch is a `fetch` error with phase `integrity`).
   */
  fetchDocument(url: string, integrity?: string): Promise<VemlParseResult>;
  /**
   * Compose a parsed child under its site and report the includes the child
   * itself carries (with their entity ids as built). A rejection omits the
   * include with reason `parse`.
   */
  build(site: IncludeSite, child: VemlDocument, depth: number): Promise<{ sites: IncludeSite[] }>;
  warn(message: string): void;
  /** True once the load this composition serves is no longer the current one. */
  isCancelled(): boolean;
}

export interface ComposeRoot {
  document: VemlDocument;
  url: string;
  /** The root's includes, in document order, with their entity ids as built. */
  sites: IncludeSite[];
}

/**
 * The subsidiary-fetch budget of one load (§6.2): every document fetched by
 * URL — included documents and prototype definitions alike — keyed by URL so a
 * second reference to the same URL shares the first fetch, and sized against
 * `INCLUDE_TREE_FETCH_CAP`.
 */
export type FetchBudget = Map<string, Promise<unknown>>;

interface TreeState {
  /** Fetches started, by URL: the dedup table and the cap's counter. */
  fetches: FetchBudget;
  outcomes: IncludeOutcome[];
}

/**
 * Compose every eligible include under `root`, recursively, and report what
 * happened to each one. Resolves once the whole tree has settled; never
 * rejects. `budget` is shared with whatever else the load fetches by URL.
 */
export async function composeIncludes(
  root: ComposeRoot,
  deps: ComposeDeps,
  budget: FetchBudget = new Map(),
): Promise<IncludeOutcome[]> {
  const tree: TreeState = { fetches: budget, outcomes: [] };
  await composeLevel(root.document, root.sites, [root.url], 1, tree, deps);
  return tree.outcomes;
}

async function composeLevel(
  parent: VemlDocument,
  sites: IncludeSite[],
  ancestors: string[],
  depth: number,
  tree: TreeState,
  deps: ComposeDeps,
): Promise<void> {
  // Eligibility is by position among the parent's subsidiary references, not
  // among its includes: prototypes count too (§6.2). A parent that recorded
  // none (a 3.x document, or a test double) is judged by site order.
  const refs = parent.metadata.subsidiaryRefs ?? sites.map((s) => s.url);
  const eligible = new Set(refs.slice(0, INCLUDE_ELIGIBLE_PER_DOCUMENT));
  const parentUrl = ancestors[ancestors.length - 1]!;

  const work: Array<Promise<void>> = [];
  for (const site of sites) {
    const omit = (reason: IncludeOmissionReason, message: string): void => {
      tree.outcomes.push({ url: site.url, entityId: site.entityId, depth, status: 'omitted', reason, message });
      deps.warn(`[webverse] include ${site.url} (from ${parentUrl}): ${message}`);
    };
    if (!eligible.has(site.url)) {
      omit('ineligible', `ineligible — only the first ${INCLUDE_ELIGIBLE_PER_DOCUMENT} subsidiary references of a document are composed (§6.2)`);
      continue;
    }
    if (ancestors.includes(site.url)) {
      omit('cycle', 'cycle — the document is already an ancestor of this include (§6.2)');
      continue;
    }
    if (depth > INCLUDE_MAX_DEPTH) {
      omit('depth', `nesting deeper than ${INCLUDE_MAX_DEPTH} (§6.2)`);
      continue;
    }
    // One fetch per URL (§6.2) — per URL and pin when a site pins a hash, so a
    // document fetched under one pin is never trusted under another.
    const key = site.integrity === undefined ? site.url : `${site.url}\n${site.integrity}`;
    let fetching = tree.fetches.get(key) as Promise<VemlParseResult> | undefined;
    if (fetching === undefined) {
      if (tree.fetches.size >= INCLUDE_TREE_FETCH_CAP) {
        omit('cap', `the tree already fetched ${INCLUDE_TREE_FETCH_CAP} documents (§6.2)`);
        continue;
      }
      fetching = deps.fetchDocument(site.url, site.integrity);
      tree.fetches.set(key, fetching);
    }
    // Every sibling's fetch has started by the time any is awaited.
    work.push(composeOne(site, fetching, ancestors, depth, tree, deps, omit));
  }
  await Promise.all(work);
}

async function composeOne(
  site: IncludeSite,
  fetching: Promise<VemlParseResult>,
  ancestors: string[],
  depth: number,
  tree: TreeState,
  deps: ComposeDeps,
  omit: (reason: IncludeOmissionReason, message: string) => void,
): Promise<void> {
  const result = await fetching;
  if (deps.isCancelled()) {
    tree.outcomes.push({ url: site.url, entityId: site.entityId, depth, status: 'omitted', reason: 'cancelled' });
    return;
  }
  if (!result.ok) {
    const first = result.report.errors[0];
    const transport = first?.kind === 'fetch' || first?.kind === 'served-html';
    const reason = first?.kind === 'fetch' && first.phase === 'integrity' ? 'integrity' : transport ? 'fetch' : 'parse';
    omit(reason, first?.message ?? 'the document could not be read');
    return;
  }
  let built: { sites: IncludeSite[] };
  try {
    built = await deps.build(site, result.document, depth);
  } catch (err) {
    omit('parse', `could not be composed: ${err instanceof Error ? err.message : String(err)}`);
    return;
  }
  if (deps.isCancelled()) {
    tree.outcomes.push({ url: site.url, entityId: site.entityId, depth, status: 'omitted', reason: 'cancelled' });
    return;
  }
  tree.outcomes.push({ url: site.url, entityId: site.entityId, depth, status: 'composed' });
  if (built.sites.length > 0) {
    await composeLevel(result.document, built.sites, [...ancestors, site.url], depth + 1, tree, deps);
  }
}
