/**
 * The `planet` profile (specs/veml/profiles/planet.md): `planet:planet`,
 * `planet:entry` and `planet:site` in a 4.0 document's `environment`. The
 * world is a planet only with a valid `planet:planet`. Every invalid part is
 * dropped with its named warning and never fails the world, and the
 * profile's own elements are never reported unknown (the spec's MUST NOT).
 */

import type { VemlPlanet, VemlPlanetEntry } from './documentModel';
import type { VemlParseWarning } from './parser';
import { geographic, planetList, planetNumber, readSite } from './planetValues';
import { resolveWorldUri } from './uriResolve';

/** An element the core parser kept as unknown: its local name and attributes. */
export interface PlanetNode {
  tag: string;
  attributes: Record<string, string>;
}

export function readPlanetProfile(
  profiles: readonly string[],
  unknown: readonly PlanetNode[],
  warnings: VemlParseWarning[],
  worldDocUrl: string,
): VemlPlanet | undefined {
  if (!profiles.includes('planet')) return undefined;
  const mine = new Set(['planet', 'entry', 'site']);
  for (let i = warnings.length - 1; i >= 0; i -= 1) {
    const w = warnings[i]!;
    if (w.name === 'veml:2:unknown-element' && typeof w.path === 'string' && mine.has(w.path.replace(/^<|>$/g, ''))) warnings.splice(i, 1);
  }
  const warn = (slug: string, path: string): void => {
    warnings.push({ kind: 'diagnostic', name: `veml:planet:${slug}`, path });
  };
  const nodes = (tag: string) => unknown.filter((n) => n.tag === tag);

  const [first, ...rest] = nodes('planet');
  if (rest.length > 0) warn('duplicate', `${rest.length} further <planet:planet> ignored`);
  let planet: VemlPlanet | undefined;
  if (first) {
    const a = first.attributes;
    const radius = planetNumber(a['radius']);
    const src = a['src'];
    if (!src || radius === undefined || radius <= 0) {
      warn('invalid', '<planet:planet> needs a src and a radius above 0');
    } else {
      let reach = radius;
      if (a['reach'] !== undefined) {
        const r = planetNumber(a['reach']);
        if (r === undefined || r < 0) warn('invalid', `reach="${a['reach']}" read as the radius`);
        else reach = r;
      }
      let spawn: [number, number] = [0, 0];
      if (a['spawn'] !== undefined) {
        const s = geographic(a['spawn'], false);
        if (!s) warn('invalid', `spawn="${a['spawn']}" read as 0,0`);
        else spawn = [s[0]!, s[1]!];
      }
      planet = { src: { raw: src, resolved: resolveWorldUri(src, worldDocUrl) }, radius, reach, spawn, entries: [], sites: [] };
      // The planet's day: each kept only when valid, and otherwise left to its default with a warning.
      const day = [
        ['day-length', 'dayLength', (n: number) => n >= 0],
        ['time', 'time', (n: number) => n >= 0 && n < 24],
        ['sun-latitude', 'sunLatitude', (n: number) => n >= -90 && n <= 90],
        ['tide-period', 'tidePeriod', (n: number) => n > 0],
      ] as const;
      for (const [attr, key, ok] of day) {
        if (a[attr] === undefined) continue;
        const n = planetNumber(a[attr]);
        if (n === undefined || !ok(n)) warn('invalid', `${attr}="${a[attr]}" read as its default`);
        else planet[key] = n;
      }
    }
  }

  const entries = nodes('entry');
  const sites = nodes('site');
  if (!planet) {
    if (entries.length + sites.length > 0) warn('not-a-planet', 'planet:entry and planet:site need a planet:planet');
    return undefined;
  }
  for (const e of entries) {
    const id = e.attributes['id'];
    const at = geographic(e.attributes['at'], false);
    const look = e.attributes['look'] === undefined ? [0, 0] : planetList(e.attributes['look'], 2);
    if (!id || !at || !look || look[1]! < -90 || look[1]! > 90) {
      warn('invalid-entry', `<planet:entry id="${id ?? ''}">`);
      continue;
    }
    if (planet.entries.some((x) => x.id === id)) {
      warn('duplicate-entry', `a second planet:entry "${id}" ignored`);
      continue;
    }
    const entry: VemlPlanetEntry = { id, at: [at[0]!, at[1]!], look: [look[0]!, look[1]!] };
    planet.entries.push(entry);
  }
  for (const s of sites) {
    const site = readSite(s.attributes, worldDocUrl);
    if (site) planet.sites.push(site);
    else warn('invalid-site', `<planet:site href="${s.attributes['href'] ?? ''}">`);
  }
  return planet;
}
