/**
 * A glb's own sound: the KHR_audio_emitter draft extension (glTF).
 *
 * VEML 4.0 keeps audio in the asset layer (glTF and its extensions), so the
 * shell reads it from the loaded glb rather than from the document. The
 * reader is pure; the builder hands each emitter to the SAME sound factory
 * and gesture gate the declared audio entities use, placed at the
 * node that carries it.
 *
 * Scope: node (positional) emitters whose audio is a `uri` beside the
 * glb, with their cone when `shapeType` is "cone". Global emitters and audio
 * embedded in a bufferView are not read. A uri with any scheme other than
 * http(s) is refused: the world's sounds come from files, never from script
 * or data URLs.
 */
import { Vector3 } from '@babylonjs/core/Maths/math.vector';
import type { Scene } from '@babylonjs/core/scene';
import type { TransformNode } from '@babylonjs/core/Meshes/transformNode';
import type { AudioGestureGate } from './audioGesture';
import type { SoundFactory, SpatialSound } from './audioEntity';

export const KHR_AUDIO_EMITTER = 'KHR_audio_emitter';

export interface GltfAudioEmitter {
  /** glTF node index carrying the emitter. */
  node: number;
  /** The node's name (the ingest writes `audio:<speaker>`). */
  name: string;
  /** Absolute URL, resolved against the glb's URL. */
  url: string;
  loop: boolean;
  autoPlay: boolean;
  /** Emitter gain × source gain. */
  volume: number;
  refDistance: number;
  maxDistance: number;
  rolloffFactor: number;
  distanceModel: 'linear' | 'inverse' | 'exponential';
  /** A directional emitter's cone: full angles in radians, linear outer gain.
   * It faces the node's local -Z. Absent for an omnidirectional emitter. */
  cone?: { innerAngle: number; outerAngle: number; outerGain: number };
}

const FULL_TURN = 2 * Math.PI;
const clamp = (v: number, lo: number, hi: number): number => Math.min(hi, Math.max(lo, v));

type Obj = Record<string, unknown>;
const isObj = (v: unknown): v is Obj => typeof v === 'object' && v !== null && !Array.isArray(v);
const num = (v: unknown, d: number): number => (typeof v === 'number' && Number.isFinite(v) ? v : d);
const bool = (v: unknown, d: boolean): boolean => (typeof v === 'boolean' ? v : d);
const at = (list: unknown, i: unknown): Obj | undefined =>
  Array.isArray(list) && typeof i === 'number' && Number.isInteger(i) && isObj(list[i]) ? (list[i] as Obj) : undefined;

/** Resolve a uri against the glb; only http(s) results are allowed. */
function resolveAudioUrl(uri: unknown, glbUrl: string): string | undefined {
  if (typeof uri !== 'string' || uri.trim() === '') return undefined;
  try {
    // Resolved first, then judged by the RESULT's protocol: a relative path
    // inherits the glb's http(s); javascript:, data:, file: and the rest keep
    // their own and are refused.
    const url = new URL(uri, glbUrl);
    return url.protocol === 'http:' || url.protocol === 'https:' ? url.href : undefined;
  } catch {
    return undefined;
  }
}

/** The node emitters a parsed glTF declares, one spec per source. Never throws. */
export function readAudioEmitters(gltf: unknown, glbUrl: string): GltfAudioEmitter[] {
  if (!isObj(gltf)) return [];
  const ext = isObj(gltf.extensions) ? gltf.extensions[KHR_AUDIO_EMITTER] : undefined;
  if (!isObj(ext)) return [];
  const out: GltfAudioEmitter[] = [];
  const nodes = Array.isArray(gltf.nodes) ? gltf.nodes : [];
  nodes.forEach((node, index) => {
    if (!isObj(node) || !isObj(node.extensions)) return;
    const ref = node.extensions[KHR_AUDIO_EMITTER];
    if (!isObj(ref)) return;
    const emitter = at(ext.emitters, ref.emitter);
    if (!emitter || emitter.type !== 'positional' || !Array.isArray(emitter.sources)) return;
    const positional = isObj(emitter.positional) ? emitter.positional : {};
    const model = positional.distanceModel;
    let cone: GltfAudioEmitter['cone'];
    if (positional.shapeType === 'cone') {
      const innerAngle = clamp(num(positional.coneInnerAngle, FULL_TURN), 0, FULL_TURN);
      // An outer cone narrower than the inner one has no meaning; it is widened to match.
      const outerAngle = Math.max(innerAngle, clamp(num(positional.coneOuterAngle, FULL_TURN), 0, FULL_TURN));
      cone = { innerAngle, outerAngle, outerGain: clamp(num(positional.coneOuterGain, 0), 0, 1) };
    }
    for (const sourceIndex of emitter.sources) {
      const source = at(ext.sources, sourceIndex);
      const audio = source ? at(ext.audio, source.audio) : undefined;
      const url = audio ? resolveAudioUrl(audio.uri, glbUrl) : undefined;
      if (!source || url === undefined) continue;
      out.push({
        node: index,
        name: typeof node.name === 'string' ? node.name : `audio:node${index}`,
        url,
        loop: bool(source.loop, false),
        autoPlay: bool(source.autoPlay, false),
        volume: num(emitter.gain, 1) * num(source.gain, 1),
        refDistance: num(positional.refDistance, 1),
        maxDistance: num(positional.maxDistance, 10000),
        rolloffFactor: num(positional.rolloffFactor, 1),
        distanceModel: model === 'linear' || model === 'exponential' ? model : 'inverse',
        ...(cone ? { cone: { ...cone } } : {}),
      });
    }
  });
  return out;
}

/** The Babylon node a glTF node index became (the loader records `/nodes/<i>`). */
export function nodeForGltfIndex(nodes: readonly TransformNode[], index: number): TransformNode | undefined {
  const pointer = `/nodes/${index}`;
  return nodes.find((n) => {
    const meta = (n as unknown as { _internalMetadata?: { gltf?: { pointers?: string[] } } })._internalMetadata;
    return meta?.gltf?.pointers?.includes(pointer) === true;
  });
}

export interface BuiltGltfSound {
  emitter: GltfAudioEmitter;
  sound: SpatialSound;
  position: { x: number; y: number; z: number };
  /** World direction the cone faces; absent for an omnidirectional emitter. */
  direction?: { x: number; y: number; z: number };
  /** LIFO: the gate callback is removed before the sound is disposed. */
  disposers: Array<() => void>;
}

/**
 * Build each emitter's sound at its node (after the entity's transform is
 * applied, so the absolute position is final), autoplay through the gate.
 * An emitter whose node cannot be found is skipped.
 */
export function buildGltfAudio(
  emitters: readonly GltfAudioEmitter[],
  nodes: readonly TransformNode[],
  scene: Scene,
  gate: AudioGestureGate,
  factory: SoundFactory,
): BuiltGltfSound[] {
  const built: BuiltGltfSound[] = [];
  for (const emitter of emitters) {
    const node = nodeForGltfIndex(nodes, emitter.node);
    if (!node) continue;
    node.computeWorldMatrix(true);
    const at = node.getAbsolutePosition();
    // The cone faces the node's local -Z. Through the world matrix, so the
    // loader's handedness root and every parent's turn are included.
    let direction: { x: number; y: number; z: number } | undefined;
    if (emitter.cone) {
      const d = Vector3.TransformNormal(new Vector3(0, 0, -1), node.getWorldMatrix()).normalize();
      direction = { x: d.x, y: d.y, z: d.z };
    }
    const sound = factory(emitter.name, emitter.url, scene, {
      loop: emitter.loop,
      volume: emitter.volume,
      spatialSound: true,
      refDistance: emitter.refDistance,
      maxDistance: emitter.maxDistance,
      rolloffFactor: emitter.rolloffFactor,
      distanceModel: emitter.distanceModel,
      ...(emitter.cone && direction ? { cone: { ...emitter.cone, direction } } : {}),
    });
    sound.setPosition(at.clone());
    let disposed = false;
    const disposers: Array<() => void> = [
      () => {
        disposed = true;
        sound.dispose();
      },
    ];
    if (emitter.autoPlay) {
      disposers.push(
        gate.onGesture(() => {
          if (disposed || scene.isDisposed) return;
          sound.play();
        }),
      );
    }
    built.push({ emitter, sound, position: { x: at.x, y: at.y, z: at.z }, ...(direction ? { direction } : {}), disposers });
  }
  return built;
}
