/**
 * Hardcoded scratch/test scene.
 * Nothing here builds world-loading machinery. A lit ground + primitives
 * proves "a lit scene renders", and the raised spawn platform + in-path box
 * make gravity-rest and collision behavior provable in e2e. The grounding
 * fixtures live in the CODE-SPLIT `groundingFixtures.ts` (loaded only for
 * `?test-grounding=1` — test-scene-only, zero main-bundle cost); this
 * default scene is what users get when no world is loaded.
 *
 * Walkability is EXPLICIT designation: the scene keeps a set of
 * meshes the ground probe may accept and exposes it as a `WalkableSource`.
 * A loaded world uses an EntityRegistry-backed provider instead — the
 * controller only ever sees the function type.
 */
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import type { AbstractEngine } from '@babylonjs/core/Engines/abstractEngine';
import { Scene } from '@babylonjs/core/scene';
import { Vector3 } from '@babylonjs/core/Maths/math.vector';
import { Color3, Color4 } from '@babylonjs/core/Maths/math.color';
import { FreeCamera } from '@babylonjs/core/Cameras/freeCamera';
import { HemisphericLight } from '@babylonjs/core/Lights/hemisphericLight';
import { DirectionalLight } from '@babylonjs/core/Lights/directionalLight';
import { CreateGround } from '@babylonjs/core/Meshes/Builders/groundBuilder';
import { CreateBox } from '@babylonjs/core/Meshes/Builders/boxBuilder';
import { CreateSphere } from '@babylonjs/core/Meshes/Builders/sphereBuilder';
import { StandardMaterial } from '../engine/shaderImports';
import type { WalkableSource } from '../controller/groundProbe';

/** Platform top surface height — the ledge the player spawns on. */
export const PLATFORM_TOP_Y = 1.5;

export interface TestSceneResult {
  scene: Scene;
  camera: FreeCamera;
  /** Player spawn (FEET position). */
  spawnFeet: Vector3;
  /** The explicit walkable designation for the ground probe. */
  walkables: WalkableSource;
  /** Releases scene-owned timers (fixture scenes only). Idempotent. */
  dispose(): void;
}

export function createTestScene(engine: AbstractEngine): TestSceneResult {
  const scene = new Scene(engine);
  scene.clearColor = new Color4(0.05, 0.06, 0.09, 1);
  scene.collisionsEnabled = true;

  // The first-person controller owns this camera's position and rotation
  // every tick; the initial values here are placeholders only.
  const camera = new FreeCamera('camera', new Vector3(0, 1.75, -6), scene);

  // Lit scene: hemispheric ambient + a directional key light.
  const hemi = new HemisphericLight('hemi', new Vector3(0, 1, 0), scene);
  hemi.intensity = 0.6;
  const sun = new DirectionalLight('sun', new Vector3(-0.4, -1, 0.6), scene);
  sun.intensity = 0.9;

  // Explicit walkable designation: only meshes added here may
  // ever be ground for the probe — membership, not isPickable/name/collision
  // heuristics.
  const walkableSet = new Set<AbstractMesh>();

  const makeMat = (name: string, r: number, g: number, b: number): StandardMaterial => {
    const mat = new StandardMaterial(name, scene);
    mat.diffuseColor = new Color3(r, g, b);
    return mat;
  };

  const ground = CreateGround('ground', { width: 24, height: 24 }, scene);
  ground.material = makeMat('groundMat', 0.32, 0.4, 0.3);
  ground.checkCollisions = true;
  walkableSet.add(ground);

  // Collision obstacle directly in the spawn walk path (1.2 AC 2).
  const box = CreateBox('box', { size: 1 }, scene);
  box.position = new Vector3(0, 0.5, 0);
  box.material = makeMat('boxMat', 0.75, 0.3, 0.25);
  box.checkCollisions = true;
  walkableSet.add(box);

  const sphere = CreateSphere('sphere', { diameter: 1.2, segments: 24 }, scene);
  sphere.position = new Vector3(1.5, 0.6, 0);
  sphere.material = makeMat('sphereMat', 0.25, 0.45, 0.8);
  sphere.checkCollisions = true;
  walkableSet.add(sphere);

  // Raised spawn platform (ledge): walking forward (+Z) drops the player
  // onto the ground below — 1.2 AC 3.
  const platform = CreateBox(
    'platform',
    { width: 4, depth: 4, height: PLATFORM_TOP_Y },
    scene,
  );
  platform.position = new Vector3(0, PLATFORM_TOP_Y / 2, -6);
  platform.material = makeMat('platformMat', 0.45, 0.42, 0.5);
  platform.checkCollisions = true;
  walkableSet.add(platform);

  return {
    scene,
    camera,
    // Spawn a hair above the platform top so the first ticks settle onto it.
    spawnFeet: new Vector3(0, PLATFORM_TOP_Y + 0.02, -6),
    walkables: () => [...walkableSet],
    dispose: () => undefined,
  };
}
