/**
 * Capabilities and consent (VEML 4.0 §9), apart from any scene or page.
 *
 * A document declares what it requests; the client is the visitor's agent and
 * asks them; the default is nothing. This module knows the vocabulary, which
 * names the client can actually gate, how a decision is remembered per
 * origin, and how a declaration list becomes a plan: what to ask about, what
 * is already answered, what is denied without a question.
 */
import type { LocalStorageBackend } from '../sandbox/sandboxTypes';

/** The §9 names, as spelt. */
export type CapabilityKind = 'microphone' | 'camera' | 'persistent-storage' | 'position-reporting' | 'network';

export type ClassifiedCapability =
  | { recognized: true; kind: Exclude<CapabilityKind, 'network'> }
  | { recognized: true; kind: 'network'; origin: string }
  | { recognized: false };

/** What the visitor decided, or why nobody was asked. */
export type ConsentDecision = 'granted' | 'denied' | 'pending' | 'unsupported' | 'unknown';
export type ConsentAnswer = 'granted' | 'denied';

export interface ConsentPlanEntry {
  capability: string;
  recognized: boolean;
  decision: ConsentDecision;
}

/** What the client asks the visitor: the world's origin, which world, and the gated capabilities still undecided. */
export interface ConsentRequest {
  origin: string;
  worldUrl: string;
  title: string | null;
  capabilities: string[];
}

/** Whoever puts the question to the visitor (the feedback surface in a page; a fake in tests). */
export interface ConsentHost {
  request(req: ConsentRequest): Promise<Record<string, ConsentAnswer>>;
}

/** The capabilities a feature of this client is gated on; the rest are denied by construction. */
export const GATED_CAPABILITIES: ReadonlySet<string> = new Set(['persistent-storage', 'position-reporting']);

export const CONSENT_STORE_PREFIX = 'webverse:consent:';

/**
 * RFC 6454 ASCII origin: `scheme://host[:port]`, lowercase scheme, no path,
 * no trailing slash, no wildcard, no non-ASCII. `network:` takes nothing
 * looser (§9).
 */
const ORIGIN_RE = /^[a-z][a-z0-9+.-]*:\/\/[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)*(:\d{1,5})?$/;

export function classifyCapability(name: string): ClassifiedCapability {
  switch (name) {
    case 'microphone':
    case 'camera':
    case 'persistent-storage':
    case 'position-reporting':
      return { recognized: true, kind: name };
    default:
      break;
  }
  if (name.startsWith('network:')) {
    const origin = name.slice('network:'.length);
    if (ORIGIN_RE.test(origin)) return { recognized: true, kind: 'network', origin };
  }
  return { recognized: false };
}

/** What a gated capability lets the world do, in the visitor's words. */
export function describeCapability(capability: string): string {
  switch (capability) {
    case 'persistent-storage':
      return 'remember things about you between visits';
    case 'position-reporting':
      return 'know where you are standing in the world';
    default:
      return capability;
  }
}

export interface ConsentLedger {
  decision(origin: string, capability: string): ConsentAnswer | undefined;
  remember(origin: string, capability: string, answer: ConsentAnswer): void;
  /** Forget every remembered decision for `origin`. */
  forget(origin: string): void;
}

/**
 * Remembered decisions, one per (origin, capability), in the client's own
 * storage under `CONSENT_STORE_PREFIX`; in memory for the session when the
 * client has none. A value that is not an answer is ignored.
 */
export function createConsentLedger(store: LocalStorageBackend | undefined): ConsentLedger {
  const memory = new Map<string, ConsentAnswer>();
  const key = (origin: string, capability: string): string => `${CONSENT_STORE_PREFIX}${origin}|${capability}`;
  const asAnswer = (v: string | null | undefined): ConsentAnswer | undefined =>
    v === 'granted' || v === 'denied' ? v : undefined;
  return {
    decision(origin, capability) {
      if (!store) return memory.get(key(origin, capability));
      try {
        return asAnswer(store.getItem(key(origin, capability)));
      } catch {
        return undefined;
      }
    },
    remember(origin, capability, answer) {
      memory.set(key(origin, capability), answer);
      try {
        store?.setItem(key(origin, capability), answer);
      } catch {
        /* a full or blocked store loses the memory, never the answer */
      }
    },
    forget(origin) {
      const prefix = `${CONSENT_STORE_PREFIX}${origin}|`;
      for (const k of [...memory.keys()]) if (k.startsWith(prefix)) memory.delete(k);
      if (!store) return;
      // The backend has no key listing; the browser's does, and the stub in
      // tests does too, so enumerate when we can and fall back to the names
      // we know otherwise.
      const keys = enumerateKeys(store);
      for (const k of keys ?? [...GATED_CAPABILITIES].map((c) => `${prefix}${c}`)) {
        if (k.startsWith(prefix)) {
          try {
            store.removeItem(k);
          } catch {
            /* same posture as remember */
          }
        }
      }
    },
  };
}

function enumerateKeys(store: LocalStorageBackend): string[] | undefined {
  const s = store as LocalStorageBackend & { length?: number; key?: (i: number) => string | null; map?: Map<string, string> };
  if (s.map instanceof Map) return [...s.map.keys()];
  if (typeof s.length === 'number' && typeof s.key === 'function') {
    const out: string[] = [];
    for (let i = 0; i < s.length; i += 1) {
      const k = s.key(i);
      if (k !== null) out.push(k);
    }
    return out;
  }
  return undefined;
}

/**
 * One entry per distinct declared name: a gated capability is `granted` or
 * `denied` if remembered, else `pending` (to be asked); a recognised one the
 * client has no feature for is `unsupported`; anything else is `unknown`.
 * Both of the last two are denied in effect, and nobody is asked about them.
 */
export function planConsent(declared: readonly string[], origin: string, ledger: ConsentLedger): ConsentPlanEntry[] {
  const seen = new Set<string>();
  const plan: ConsentPlanEntry[] = [];
  for (const capability of declared) {
    if (seen.has(capability)) continue;
    seen.add(capability);
    const classified = classifyCapability(capability);
    if (!classified.recognized) {
      plan.push({ capability, recognized: false, decision: 'unknown' });
      continue;
    }
    if (!GATED_CAPABILITIES.has(capability)) {
      plan.push({ capability, recognized: true, decision: 'unsupported' });
      continue;
    }
    plan.push({ capability, recognized: true, decision: ledger.decision(origin, capability) ?? 'pending' });
  }
  return plan;
}
