/**
 * The nearest mesh a ray meets, found mesh by mesh with the ray core the
 * shell already carries. Babylon's own scene picking lives in a module that
 * brings the camera class with it; code that loads after first paint casts
 * through this instead, so its chunk shares nothing new with the entry.
 */
import type { Scene } from '@babylonjs/core/scene';
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import type { PickingInfo } from '@babylonjs/core/Collisions/pickingInfo';
import type { Vector3 } from '@babylonjs/core/Maths/math.vector';
import { Ray } from '@babylonjs/core/Culling/ray.core';

/** The closest hit within `reach` among the scene's meshes that `pick` admits, or null. */
export function castNearest(
  scene: Scene,
  origin: Vector3,
  dir: Vector3,
  reach: number,
  pick: (mesh: AbstractMesh) => boolean,
): PickingInfo | null {
  const ray = new Ray(origin, dir, reach);
  let best: PickingInfo | null = null;
  for (const m of scene.meshes) {
    if (!pick(m)) continue;
    const info = ray.intersectsMesh(m, false);
    if (info.hit && (!best || info.distance < best.distance)) best = info;
  }
  return best;
}
