/**
 * Enter-VR button — the DOM shell control.
 *
 *
 * A neutral-named, themeable, DOM-only shell control (ZERO Babylon imports) —
 * a SIBLING of `#webverse-feedback` appended to `document.body`, NOT a child
 * of the feedback surface (so the feedback surface is unaffected by VR).
 * Mirrors the feedbackSurface conventions: a real
 * `<button>` (keyboard-reachable), `pointer-events:auto` on the button only
 * (canvas input is never eaten), themeable via `--webverse-xr-*` custom
 * properties, `data-webverse-xr-*` attributes for e2e queries, and
 * focus-restore to `#renderCanvas` when the button hides/disables (keyboard
 * focus belongs to the canvas, never stranded on <body>).
 *
 * Naming note: the user-facing LABEL "Enter VR"/"Exit VR" is
 * fine; the `data-webverse-xr-*`/`--webverse-xr-*` identifiers are this
 * runtime's private, swappable surface (the same allowance as the `[webverse]`
 * log prefix and the feedback/portal DOM attributes).
 *
 * GATING (nothing else changes when VR is unavailable):
 * - `available === false` (no WebXR, or the engine is WebGPU — see xrSupport) →
 *   button HIDDEN. A no-WebXR desktop session is byte-identical to today.
 * - `available === true` + no world loaded → button SHOWN, DISABLED.
 * - `available === true` + world loaded → button ENABLED (press = enter);
 *   while presenting, the label flips to "Exit VR" (press = exit).
 */
import { log } from '../logging/runtimeLog';

export interface EnterVrButtonOptions {
  /** Fired when the (enabled, not-presenting) button is pressed — start VR. */
  onEnter: () => void;
  /** Fired when the button is pressed while presenting — exit VR. */
  onExit: () => void;
}

export interface EnterVrButton {
  /** WebXR is usable this session (supported AND WebGL2 engine). Hidden when false. */
  setAvailable(available: boolean): void;
  /** A real world is loaded (entry target exists). Disabled when false. */
  setWorldLoaded(loaded: boolean): void;
  /** An immersive-vr session is presenting — flip the label to "Exit VR". */
  setPresenting(presenting: boolean): void;
  dispose(): void;
}

/** The button's id / query hook (must be stable for the e2e). */
export const ENTER_VR_BUTTON_ID = 'webverse-xr-enter';

export function createEnterVrButton(
  doc: Document,
  options: EnterVrButtonOptions,
): EnterVrButton {
  let available = false;
  let worldLoaded = false;
  let presenting = false;
  let disposed = false;

  const button = doc.createElement('button');
  button.id = ENTER_VR_BUTTON_ID;
  button.type = 'button';
  button.setAttribute('data-webverse-xr-button', '');
  // Minimal inline styling (self-contained — no index.html critical CSS needed
  // for this control); themeable via --webverse-xr-* custom properties.
  button.style.cssText =
    'position:fixed;right:12px;top:12px;z-index:11;padding:8px 14px;border-radius:6px;' +
    'font:13px/1.2 system-ui,sans-serif;cursor:pointer;pointer-events:auto;' +
    'color:var(--webverse-xr-fg,#dfe3ea);background:var(--webverse-xr-bg,#1b1b22);' +
    'border:1px solid var(--webverse-xr-border,rgba(223,227,234,0.35));';

  const restoreFocus = (): void => {
    // Never strand keyboard focus on the button when it hides/disables —
    // hand it back to the canvas (locomotion keydown lives there).
    if (doc.activeElement === button) {
      doc.getElementById('renderCanvas')?.focus();
    }
  };

  const render = (): void => {
    // HIDDEN unless WebXR is available this session (nothing else changes).
    const visible = available;
    button.style.display = visible ? 'inline-block' : 'none';
    button.setAttribute(
      'data-webverse-xr-state',
      !visible ? 'hidden' : presenting ? 'presenting' : worldLoaded ? 'ready' : 'disabled',
    );
    // Enabled only when available AND a real world is loaded (an entry target).
    const enabled = available && worldLoaded;
    button.disabled = !enabled;
    button.setAttribute('aria-disabled', enabled ? 'false' : 'true');
    button.textContent = presenting ? 'Exit VR' : 'Enter VR';
    button.setAttribute('aria-label', presenting ? 'Exit VR' : 'Enter VR');
    if (!visible || !enabled) restoreFocus();
  };

  const onClick = (): void => {
    if (disposed || button.disabled) return;
    try {
      if (presenting) options.onExit();
      else options.onEnter();
    } catch (err) {
      // Observability, not control flow — a handler throw must never break the
      // shell (the feedbackSurface posture).
      log.warn('[webverse] Enter-VR button handler error:', err);
    }
  };

  button.addEventListener('click', onClick);
  doc.body.appendChild(button);
  render();

  return {
    setAvailable(next: boolean): void {
      if (disposed) return;
      available = next;
      render();
    },
    setWorldLoaded(next: boolean): void {
      if (disposed) return;
      worldLoaded = next;
      render();
    },
    setPresenting(next: boolean): void {
      if (disposed) return;
      presenting = next;
      render();
    },
    dispose(): void {
      if (disposed) return;
      disposed = true;
      button.removeEventListener('click', onClick);
      restoreFocus();
      button.remove();
    },
  };
}
