/**
 * The name over a person's head, readable.
 *
 * A fixed-size texture and plane clip long names, and thin white text with
 * no backing is lost against bright surfaces. So the texture and the plane
 * are sized from the name, the text sits on a dark see-through pill, and the
 * pill sits just above the default avatar's head.
 *
 * Pure: layout numbers and a paint over a 2D context shape, no Babylon, so
 * both are tested without an engine. The plane itself is built in
 * uiEntity.ts, beside the other text planes.
 */

export const NAME_LABEL = {
  fontPx: 56,
  font: 'bold 56px system-ui, sans-serif',
  padXPx: 26,
  padYPx: 14,
  /** Metres per texture pixel: a 84 px tall pill is 0.2 m. */
  metresPerPx: 0.2 / 84,
  /** The default avatar is 1.76 m; the pill's bottom clears the head by this. */
  headTopM: 1.76,
  gapM: 0.1,
  backing: 'rgba(0, 0, 0, 0.6)',
  text: '#ffffff',
} as const;

export interface NameLabelLayout {
  texW: number;
  texH: number;
  planeW: number;
  planeH: number;
  /** The plane's centre above the person's feet. */
  centerY: number;
}

/**
 * The width a name takes when there is no canvas to measure it with (a
 * headless engine, a unit test): a bold sans glyph averages ~0.6 em.
 */
export function estimateTextWidthPx(text: string): number {
  return Math.ceil(text.length * NAME_LABEL.fontPx * 0.6);
}

export function nameLabelLayout(textWidthPx: number): NameLabelLayout {
  const texW = Math.ceil(Math.max(0, textWidthPx) + 2 * NAME_LABEL.padXPx);
  const texH = NAME_LABEL.fontPx + 2 * NAME_LABEL.padYPx;
  const planeW = texW * NAME_LABEL.metresPerPx;
  const planeH = texH * NAME_LABEL.metresPerPx;
  return { texW, texH, planeW, planeH, centerY: NAME_LABEL.headTopM + NAME_LABEL.gapM + planeH / 2 };
}

/** The parts of a 2D context the paint uses (a CanvasRenderingContext2D fits). */
export interface LabelContext {
  fillStyle: unknown;
  font: string;
  textAlign: unknown;
  textBaseline: unknown;
  clearRect(x: number, y: number, w: number, h: number): void;
  beginPath(): void;
  moveTo(x: number, y: number): void;
  lineTo(x: number, y: number): void;
  arcTo(x1: number, y1: number, x2: number, y2: number, r: number): void;
  closePath(): void;
  fill(): void;
  fillText(text: string, x: number, y: number): void;
}

/** A dark, rounded, see-through pill, then the name in white on it. */
export function paintNameLabel(ctx: LabelContext, text: string, layout: NameLabelLayout): void {
  const { texW: w, texH: h } = layout;
  const r = h / 2;
  ctx.clearRect(0, 0, w, h);
  ctx.beginPath();
  ctx.moveTo(r, 0);
  ctx.lineTo(w - r, 0);
  ctx.arcTo(w, 0, w, r, r);
  ctx.arcTo(w, h, w - r, h, r);
  ctx.lineTo(r, h);
  ctx.arcTo(0, h, 0, r, r);
  ctx.arcTo(0, 0, r, 0, r);
  ctx.closePath();
  ctx.fillStyle = NAME_LABEL.backing;
  ctx.fill();
  ctx.font = NAME_LABEL.font;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = NAME_LABEL.text;
  ctx.fillText(text, w / 2, h / 2 + 2);
}
