/**
 * World-load progress events.
 *
 * THE CONTRACT the loading panel consumes — keep shapes stable.
 * Main-bundle code, zero Babylon imports: byte progress and download-failure
 * semantics are owned HERE (the shell fetches asset bytes itself and hands
 * buffers to the code-split loader), so failure and progress behavior never
 * depends on loader internals.
 *
 * Event order per asset URL: `asset-started` → zero or more `asset-progress`
 * → exactly one of `asset-completed` | `asset-failed`. `totalBytes` is the
 * server-provided Content-Length when present and parseable, else null
 * (byte progress only where the server provides lengths — loadedBytes is
 * always known once chunks stream; totalBytes may not be). A compressed
 * response (Content-Encoding other than identity) has no known total: the
 * header is the length on the wire and the bytes read are decoded. A host
 * that compresses without letting another origin see the coding shows it
 * only by the bytes running past the header; the total is null from then
 * on, so `loadedBytes` never exceeds a `totalBytes` that is given.
 */

import { log } from '../logging/runtimeLog';

export type WorldLoadProgressEvent =
  | { kind: 'asset-started'; url: string }
  | { kind: 'asset-progress'; url: string; loadedBytes: number; totalBytes: number | null }
  | { kind: 'asset-completed'; url: string }
  | { kind: 'asset-failed'; url: string; message: string };

export type WorldLoadProgressListener = (event: WorldLoadProgressEvent) => void;

/**
 * Deliver an event to an (optional) listener. A throwing listener must never
 * break world loading — progress is observability, not control flow (same
 * never-throws posture as loadWorld's report contract).
 */
export function emitProgress(
  listener: WorldLoadProgressListener | undefined,
  event: WorldLoadProgressEvent,
): void {
  if (!listener) return;
  try {
    listener(event);
  } catch (err) {
    log.warn('[webverse] progress listener threw:', err);
  }
}

/** Parse a Content-Length header value into a positive byte count, or null. */
function parseContentLength(value: string | null): number | null {
  if (value === null) return null;
  const n = Number(value);
  return Number.isFinite(n) && n > 0 ? n : null;
}

/**
 * Fetch an asset's bytes with progress events and clean failure
 * semantics: emits `asset-started` first; streams the body when the
 * platform provides a reader (emitting `asset-progress` per chunk, with
 * `totalBytes` from Content-Length when the server sent one); emits
 * `asset-completed` on success. ANY failure (network, CORS, HTTP status)
 * emits `asset-failed` with the asset URL and rethrows — the caller decides
 * what an errored asset means (world building registers the entity errored
 * and keeps loading the world).
 */
export async function fetchAssetBytes(
  url: string,
  onProgress?: WorldLoadProgressListener,
  fetchImpl: typeof fetch = fetch,
): Promise<ArrayBuffer> {
  emitProgress(onProgress, { kind: 'asset-started', url });
  try {
    const response = await fetchImpl(url);
    if (!response.ok) {
      throw new Error(`HTTP ${response.status} ${response.statusText}`);
    }
    const coding = (response.headers.get('content-encoding') ?? 'identity').trim().toLowerCase();
    let totalBytes = coding === 'identity' || coding === '' ? parseContentLength(response.headers.get('content-length')) : null;
    let buffer: ArrayBuffer;
    const body = response.body;
    if (body && typeof body.getReader === 'function') {
      const reader = body.getReader();
      const chunks: Uint8Array[] = [];
      let loadedBytes = 0;
      for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        if (value) {
          chunks.push(value);
          loadedBytes += value.byteLength;
          if (totalBytes !== null && loadedBytes > totalBytes) totalBytes = null;
          emitProgress(onProgress, { kind: 'asset-progress', url, loadedBytes, totalBytes });
        }
      }
      const assembled = new Uint8Array(loadedBytes);
      let offset = 0;
      for (const chunk of chunks) {
        assembled.set(chunk, offset);
        offset += chunk.byteLength;
      }
      buffer = assembled.buffer;
    } else {
      // No streaming body on this platform/mock — still a valid load, just
      // without incremental progress.
      buffer = await response.arrayBuffer();
    }
    emitProgress(onProgress, { kind: 'asset-completed', url });
    return buffer;
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    emitProgress(onProgress, { kind: 'asset-failed', url, message });
    throw err instanceof Error ? err : new Error(message);
  }
}
