const PRIMITIVE_TYPE_SET: ReadonlySet<string> = new Set(VEML_PRIMITIVE_TYPES);

/** The world-space UI tier ("parsed, minimal render"). */
const UI_TYPE_SET: ReadonlySet<string> = new Set(['canvas', 'text', 'image', 'button']);
/** Loaded content may exceed its declared bounds (§4.8) by this factor before the client says so. */
const DECLARED_BOUNDS_TOLERANCE = 1.25;

export interface BuildWorldOptions {
  /** Asset progress listener (the loading-panel contract — see loadProgress.ts). */
  onProgress?: WorldLoadProgressListener;
  fetchImpl?: typeof fetch;
  /**
   * The code-split glTF chunk loader. Defaults to the real dynamic import;
   * injectable so unit tests can count invocations and simulate rejection.
   */
  gltfChunkLoader?: () => Promise<GltfChunkModule>;
  /** Engine kind ('webgpu' gates the WGSL PBR shader load in the chunk). */
  engineKind?: string;
  /**
   * Autoplay gesture gate (session-scoped, persistent gesture
   * state). Defaults to a fresh gate (used only if the world has audio).
   */
  audioGate?: AudioGestureGate;
  /**
   * Sound factory seam. When provided (unit tests inject a fake),
   * audio builds SYNCHRONOUSLY and the code-split audioChunk is never loaded.
   * When absent (production), the real Sound comes from the code-split chunk.
   */
  soundFactory?: SoundFactory;
  /** Code-split audio chunk loader seam (dynamic import by default). */
  audioChunkLoader?: () => Promise<AudioChunkModule>;
  /** Observability hook: one call per built audio entity. */
  onAudioBuilt?: (info: AudioBuiltInfo) => void;
  /**
   * Capability degradation registry. Every KNOWN-but-web-unsupported
   * entity (the 8 degrade-tier types) and every genuinely-unknown xsi:type is
   * registered here as a capability gap instead of being silently dropped.
   * Defaults to a fresh throwaway registry when the caller does
   * not supply one (like `audioGate`); the session injects its own so the
   * report reaches the world state.
   */
  capabilityRegistry?: CapabilityRegistry;
  /**
   * The world declared the VEML 4.0 `lighting` profile: glb
   * KHR_lights_punctual lights are honored (kept + added to the scene) instead
   * of stripped (the core default).
   */
  honorEmbeddedLights?: boolean;
  /**
   * Called once per glb that delivered honored embedded lights,
   * with the count. The session sums these to decide the default-lighting
   * stand-down (applyDefaultLightingAfterEntities). Never called when
   * `honorEmbeddedLights` is off (the strip leaves zero).
   */
  onAssetLights?: (count: number) => void;
  /**
   * The DOM that hosts an `html` entity's embedded page (§4.6). Absent — a
   * headless embedder — the quad still builds and the entity reports a
   * degraded gap with `HTML_NO_DOM_REASON`.
   */
  htmlHost?: HtmlHost;
  /**
   * Where a 3.x `water` or `waterblocker` entity goes: the water profile's
   * body or blocker it maps onto (profiles/water.md, Migration), in world
   * coordinates. The session collects them beside the document's own.
   */
  water?: { body(body: VemlWaterBody): void; blocker(blocker: VemlWaterBlocker): void };
  /** One call per built html surface; the session tracks them for projection and messages. */
  onHtmlBuilt?: (surface: HtmlSurface) => void;
  /**
   * Build these entities instead of the document's own — an included
   * document's (§6.2), composed into a world that is already standing.
   */
  rootEntities?: readonly VemlEntity[];
  /** The node the top-level entities hang from; null (the default) is the scene root. */
  rootParent?: TransformNode | null;
  /**
   * Where the viewer stands, for choosing each `lod`'s first level (§4.10).
   * Absent, a lod shows its first non-empty level — the draft's fallback for
   * a client that has not evaluated distance.
   */
  viewerPosition?: { x: number; y: number; z: number };
  /** One call per `lod` built, with what the session needs to switch and build its levels later. */
  onLodBuilt?: (lod: LodHandle) => void;
  /**
   * The visitor's quality level, and where a model that has lighter files
   * (VEML §4.4) is handed over to be loaded again when the level changes.
   * Absent, every model loads its own file.
   */
  assetLevels?: AssetLevelSink;
  /**
   * Deferral by declared bounds (§4.8). Present, a glb entity that declares
   * bounds is not fetched here but handed over with its world box, and a lod
   * that declares bounds builds no level yet (`LodHandle.deferredBox`); every
   * declared box is reported so the caller can defer an include behind it and
   * frame a spawn before geometry exists. Absent, everything loads now.
   */
  deferral?: {
    asset(item: DeferredAsset): void;
    declared(entityId: string, tag: string, box: WorldBox): void;
  };
  /**
   * The world's shadow rig: a light with cast-shadows is handed to it, and
   * every primitive and glb mesh is tracked as a caster and receiver. Absent,
   * nothing casts.
   */
  shadows?: ShadowRig;
}

/** A glb whose fetch waits on its declared box: `start` loads it the way the eager path would have. */
export interface DeferredAsset {
  /** The declared id, else the tag (the registry id does not exist until it loads). */
  entityId: string;
  tag: string;
  box: WorldBox;
  start(): Promise<void>;
}

/** One level of a built `lod`: its node, its content, and whether that content is built yet. */
export interface LodLevelHandle {
  range: number;
  entities: VemlEntity[];
  pendingInstances?: VemlLodLevel['pendingInstances'];
  node: TransformNode;
  /** The registry id the level's node is registered under, so instances can name it as their host. */
  hostId: string;
  built: boolean;
}

/** A built `lod` (§4.10): the session chooses `active` by distance and builds levels on first need. */
export interface LodHandle {
  entityId: string;
  node: TransformNode;
  /** The document that declared it — whose prototypes its levels' instances name. */
  document: VemlDocument;
  levels: LodLevelHandle[];
  active: number;
  /** Set when the lod declared bounds (§4.8): no level is built until the visitor sees this box. */
  deferredBox?: WorldBox;
}

/** A node's world matrix with its whole ancestry recomputed — nothing has rendered yet at build time. */
export function freshWorldMatrix(node: TransformNode | null): Matrix {
  if (node === null) return Matrix.Identity();
  const chain: TransformNode[] = [];
  for (let n: TransformNode | null = node; n; n = n.parent as TransformNode | null) chain.unshift(n);
  for (const n of chain) n.computeWorldMatrix(true);
  return node.getWorldMatrix();
}

/** A node's world position with its whole ancestry recomputed — nothing has rendered yet at build time. */
export function freshAbsolutePosition(node: TransformNode): Vector3 {
  freshWorldMatrix(node);
  return node.getAbsolutePosition();
}

/** Snapshot descriptor for a built audio entity (worldState.audio). */
export interface AudioBuiltInfo {
  tag: string;
  autoPlay: boolean;
  spatial: boolean;
  position: { x: number; y: number; z: number };
  /** World direction a directional sound's cone faces (a glb emitter with a cone). */
  direction?: { x: number; y: number; z: number };
  /** Live sound handle for reading `isPlaying` (undefined if no audio-file). */
  sound?: { readonly isPlaying: boolean };
}

const defaultGltfChunkLoader = (): Promise<GltfChunkModule> =>
  import('../engine/gltfChunk');

// Dynamic import → code-split chunk (audioChunk-*.js). The real Babylon Sound +
// WebAudio engine load ONLY when a world contains an audio entity.
const defaultAudioChunkLoader = (): Promise<AudioChunkModule> =>
  import('./audioChunk').then((m) => ({ createSound: m.createSound }));

/** Local-space encapsulated bounds size of a primitive mesh (pre-transform). */
function primitiveLocalSize(mesh: AbstractMesh): Vector3 {
  const box = mesh.getBoundingInfo().boundingBox;
  return box.maximum.subtract(box.minimum);
}

/**
 * Entity-local encapsulated bounds of a glb's own meshes, measured with the
 * (unparented, identity) entity root — the original size a sizetransform
 * scales against, measured across the whole hierarchy.
 */
function containerMeshesSize(meshes: readonly AbstractMesh[]): Vector3 {
  let min: Vector3 | null = null;
  let max: Vector3 | null = null;
  for (const mesh of meshes) {
    mesh.computeWorldMatrix(true);
    const box = mesh.getBoundingInfo().boundingBox;
    min = min === null ? box.minimumWorld.clone() : Vector3.Minimize(min, box.minimumWorld);
    max = max === null ? box.maximumWorld.clone() : Vector3.Maximize(max, box.maximumWorld);
  }
  if (min === null || max === null) return new Vector3(1, 1, 1);
  return max.subtract(min);
}

export async function buildWorld(
  document: VemlDocument,
  scene: Scene,
  registry: EntityRegistry,
  options: BuildWorldOptions = {},
): Promise<void> {
  const { onProgress, fetchImpl, engineKind } = options;
  const chunkLoader = options.gltfChunkLoader ?? defaultGltfChunkLoader;
  const audioGate = options.audioGate ?? createAudioGestureGate();
  const audioChunkLoader = options.audioChunkLoader ?? defaultAudioChunkLoader;
  const capabilities = options.capabilityRegistry ?? createCapabilityRegistry();

  // The chunk is fetched at most once per build, and ONLY when a glb entity
  // actually exists (pure-primitive worlds never pay for the loader).
  let chunkPromise: Promise<GltfChunkModule> | undefined;
  const loadChunk = (): Promise<GltfChunkModule> => {
    chunkPromise ??= chunkLoader();
    return chunkPromise;
  };

  // The audio chunk (real Babylon Sound + WebAudio engine) is code-split and
  // fetched at most once per build, ONLY when an audio entity is present
  // (silent worlds never pay for WebAudio). When a soundFactory is
  // injected (tests), audio builds synchronously and this never loads.
  let audioChunkPromise: Promise<AudioChunkModule> | undefined;
  const loadAudioChunk = (): Promise<AudioChunkModule> => {
    audioChunkPromise ??= audioChunkLoader();
    return audioChunkPromise;
  };

  const pendingAssets: Array<Promise<void>> = [];

  // Iterative walk: pathologically deep nesting must not overflow the stack,
  // so never recurse the document tree.
  interface WalkItem {
    entity: VemlEntity;
    parentNode: TransformNode | null;
    /** Position among its siblings — used to z-separate coplanar UI planes. */
    siblingIndex: number;
  }
  const stack: WalkItem[] = [];
  const rootEntities = options.rootEntities ?? document.environment.entities;
  const rootParent = options.rootParent ?? null;
  for (let i = rootEntities.length - 1; i >= 0; i--) {
    stack.push({ entity: rootEntities[i]!, parentNode: rootParent, siblingIndex: i });
  }

  const pushChildren = (entity: VemlEntity, parentNode: TransformNode | null): void => {
    for (let i = entity.children.length - 1; i >= 0; i--) {
      stack.push({ entity: entity.children[i]!, parentNode, siblingIndex: i });
    }
  };

  while (stack.length > 0) {
    const { entity, parentNode, siblingIndex } = stack.pop()!;
    const type = entity.type;

    const isPrimitive = PRIMITIVE_TYPE_SET.has(type);
    const isBuildable =
      isPrimitive ||
      type === 'container' ||
      type === 'mesh' ||
      type === 'light' ||
      type === 'audio' ||
      type === 'html' ||
      UI_TYPE_SET.has(type); // canvas/text/image/button
    if (!isBuildable) {
      // Classify the non-built entity for the capability report. The entity
      // and its subtree are still skipped (no pushChildren); this only ADDS
      // reporting so nothing is dropped silently.
      //   The tag reported: `tag` when present, else `id`, else '(untagged)' —
      // degrade-tier entities are reported regardless of tag (unlike buildable
      // types, which require one).
      const reportTag = entity.tag ?? entity.id ?? '(untagged)';
      if (type === 'water' || type === 'waterblocker') {
        // Not a gap: the 3.x water kinds are the water profile's body and
        // blocker, placed where the entity resolved to in the world.
        mapLegacyWater(entity, parentNode, scene, options.water);
        continue;
      }
      if (Object.prototype.hasOwnProperty.call(DEGRADE_TIER_REASONS, type)) {
        // (a) KNOWN-but-web-unsupported: parsed into a full typed shape, no
        // parse warning — the web capability profile is why it is skipped.
        const reason = DEGRADE_TIER_REASONS[type]!;
        capabilities.register({ feature: type, kind: 'degraded', tag: reportTag, reason });
        log.warn(
          `[webverse] capability gap: '${type}' entity (tag '${reportTag}') ${reason} — parsed, skipped`,
        );
      } else if ('known' in entity && entity.known === false) {
        // (b) genuinely-UNKNOWN xsi:type (not one of the 28 subtypes). The
        // parser already emitted an `unknown-entity-type` warning; this
        // re-surfaces it at the capability level (kind:'unknown').
        const feature = type || '(missing xsi:type)';
        capabilities.register({
          feature,
          kind: 'unknown',
          tag: reportTag,
          reason: UNKNOWN_TYPE_REASON,
        });
        log.warn(
          `[webverse] capability gap: unknown entity type '${feature}' (tag '${reportTag}') — parsed, skipped`,
        );
      }
      // else: a KNOWN type that is neither degrade-tier nor UI-tier and has no
      // builder yet — silently skipped (the final safety net). The UI tier
      // (text/image/canvas/button) is BUILT above (isBuildable), so it never
      // reaches here.
      continue;
    }

    // tag is required for every buildable type; subtree skipped.
    if (!entity.tag) {
      log.warn(
        `[webverse] VEML ${type} entity missing required field: tag — skipping entity (and its children)`,
      );
      continue;
    }
    const tag = entity.tag;

    if (type === 'container') {
      // Containers validate the transform BEFORE creation: anything
      // but a scaletransform (or, leniently, no transform) skips the entity.
      if (entity.transform !== undefined && entity.transform.kind !== 'scaletransform') {
        log.warn(
          `[webverse] container '${tag}': ${
            entity.transform.kind === 'sizetransform' ? 'Size' : 'Canvas'
          } Transform not allowed — skipping entity (and its children)`,
        );
        continue;
      }
      const node = new TransformNode(`container:${tag}`, scene);
      applyVemlTransform(node, entity.transform, { allowScale: true, allowSize: false });
      node.parent = parentNode;
      const registered = registry.register({ id: entity.id, tag, type, rootNode: node });
      pushChildren(entity, node);
      // §4.8: the declared box, in world space, for whoever defers behind it.
      const declared =
        entity.bounds !== undefined && options.deferral !== undefined
          ? declaredWorldBox(entity.bounds, undefined, freshWorldMatrix(node))
          : undefined;
      if (declared !== undefined) options.deferral!.declared(registered.id, tag, declared);
      if (entity.lodLevels !== undefined && entity.lodLevels.length > 0) {
        // §4.10: one node per level, shown one at a time. Only the level for
        // where the viewer stands is built now; the session builds the rest
        // the first time each is needed.
        const levels: LodLevelHandle[] = entity.lodLevels.map((level, i) => {
          const levelNode = new TransformNode(`lod-level:${tag}:${i}`, scene);
          levelNode.parent = node;
          const host = registry.register({
            id: `${registered.id}:level:${i}`,
            tag: `${tag}:level:${i}`,
            type: 'container',
            rootNode: levelNode,
          });
          return {
            range: level.range,
            entities: level.entities,
            ...(level.pendingInstances !== undefined ? { pendingInstances: level.pendingInstances } : {}),
            node: levelNode,
            hostId: host.id,
            built: false,
          };
        });
        const viewer = options.viewerPosition;
        const active =
          viewer !== undefined
            ? selectLodLevel(
                levels.map((l) => l.range),
                Vector3.Distance(freshAbsolutePosition(node), new Vector3(viewer.x, viewer.y, viewer.z)),
              )
            : firstNonEmptyLevel(levels.map((l) => l.entities.length + (l.pendingInstances?.length ?? 0)));
        levels.forEach((l, i) => l.node.setEnabled(i === active));
        if (declared !== undefined) {
          // Even the active level waits until the declared box is seen (§4.10 with §4.8).
          options.onLodBuilt?.({ entityId: registered.id, node, document, levels, active, deferredBox: declared });
          continue;
        }
        const first = levels[active]!;
        first.built = true;
        for (let i = first.entities.length - 1; i >= 0; i--) {
          stack.push({ entity: first.entities[i]!, parentNode: first.node, siblingIndex: i });
        }
        options.onLodBuilt?.({ entityId: registered.id, node, document, levels, active });
      }
      continue;
    }

    if (type === 'light' || type === 'audio') {
      // Light + audio accept a scaletransform ONLY (size/canvas → skip): they
      // have no bounds for a size to scale against.
      // A transform-less light/audio builds at identity (lenient).
      if (entity.transform !== undefined && entity.transform.kind !== 'scaletransform') {
        log.warn(
          `[webverse] ${type} '${tag}': ${
            entity.transform.kind === 'sizetransform' ? 'Size' : 'Canvas'
          } Transform not allowed — skipping entity (and its children)`,
        );
        continue;
      }
      if (type === 'light') {
        // Lights carry no meshes → never enter walkableMeshes(). A Light is a
        // Node disposed via the entity's `disposers` (not a mesh/material).
        const light = createLightEntity(entity as VemlLightEntity, scene, parentNode);
        registry.register({
          id: entity.id,
          tag,
          type,
          disposers: [() => light.dispose()],
        });
        if ((entity as VemlLightEntity).castShadows && options.shadows) {
          await options.shadows.attach(light, tag);
        }
      } else {
        const buildAudioNow = (factory: SoundFactory): void => {
          const built = createAudioEntity(
            entity as VemlAudioEntity,
            scene,
            audioGate,
            factory,
          );
          registry.register({ id: entity.id, tag, type, disposers: built.disposers });
          options.onAudioBuilt?.({
            tag,
            autoPlay: built.autoPlay,
            spatial: built.spatial,
            position: built.position,
            sound: built.sound,
          });
        };
        if (options.soundFactory !== undefined) {
          // Injected fake (unit tier): build synchronously, no chunk load.
          buildAudioNow(options.soundFactory);
        } else {
          // Production: fetch the code-split audio chunk (once), then build.
          // Autoplay is gesture-gated, so the chunk-load latency is hidden.
          pendingAssets.push(loadAudioChunk().then((m) => buildAudioNow(m.createSound)));
        }
      }
      // Light/audio create no hierarchy node; their (rare) children parent
      // under the same parent, positioned in the parent's space.
      pushChildren(entity, parentNode);
      continue;
    }

    if (type === 'canvas') {
      // The canvas FRAME, rendered WORLD-SPACE (VEML carries no signal for
      // screen-space; see uiEntity.ts). A canvas rejects a canvastransform,
      // accepts scale/size (like a container's transform gate).
      if (entity.transform !== undefined && entity.transform.kind === 'canvastransform') {
        log.warn(
          `[webverse] canvas '${tag}': Canvas Transform not allowed — skipping entity (and its children)`,
        );
        continue;
      }
      const frame = createCanvasFrame(tag, scene);
      const applied = applyVemlTransform(frame, entity.transform, {
        allowScale: true,
        allowSize: true,
        originalSize: () => new Vector3(1, 1, 1),
      });
      if (!applied.ok) {
        log.warn(`[webverse] canvas '${tag}': ${applied.reason} — keeping default transform`);
      }
      frame.parent = parentNode;
      // No meshes → not walkable (signage is not ground). rootNode disposes it.
      registry.register({ id: entity.id, tag, type, rootNode: frame });
      pushChildren(entity, frame);
      continue;
    }

    if (type === 'text' || type === 'image' || type === 'button') {
      // World-space UI plane. A `canvastransform` places it
      // proportionally within the parent canvas frame's unit rect; a
      // scale/size transform (or none) 3D-places it in the parent's space
      // (lenient — a UI element is not skipped for lacking a canvastransform).
      let build: UiPlaneBuild;
      if (type === 'text') build = createTextPlane(entity as VemlTextEntity, scene);
      else if (type === 'image') build = createImagePlane(entity as VemlImageEntity, scene);
      else build = createButtonPlane(entity as VemlButtonEntity, scene);

      if (entity.transform !== undefined && entity.transform.kind === 'canvastransform') {
        placeUiChild(build.mesh, entity.transform, siblingIndex);
      } else {
        const applied = applyVemlTransform(build.mesh, entity.transform, {
          allowScale: true,
          allowSize: true,
          originalSize: () => new Vector3(1, 1, 1),
        });
        if (!applied.ok) {
          log.warn(`[webverse] ${type} '${tag}': ${applied.reason} — keeping default transform`);
        }
      }
      build.mesh.parent = parentNode;
      // NO `meshes` → excluded from walkableMeshes(); NO checkCollisions.
      // rootNode (the plane) + materials + textures own disposal.
      registry.register({
        id: entity.id,
        tag,
        type,
        rootNode: build.mesh,
        materials: [build.material],
        textures: build.texture ? [build.texture] : undefined,
      });
      pushChildren(entity, build.mesh);
      continue;
    }

    if (type === 'html') {
      // The 4.0 embedded web surface (§4.6): a quad in the entity's local XY
      // plane sized by its transform, plus — given a DOM — the sandboxed iframe
      // that follows the quad's projection (htmlEntity.ts). Without a DOM the
      // quad still stands and the gap is reported with its own reason.
      const htmlEntity = entity as VemlHtmlEntity;
      // A frame is navigated with its site's cookies whatever its sandbox, so
      // a world from another site could show this page's own signed-in pages
      // on a surface. It may not name them; the rest of the world stands.
      if (htmlEntity.url && worldAccessOf(scene).refuses(htmlEntity.url.resolved)) {
        log.warn(`[webverse] html '${tag}': ${htmlEntity.url.resolved} ${OWN_ORIGIN_REFUSED}`);
        continue;
      }
      const built = options.htmlHost
        ? createHtmlSurface(htmlEntity, scene, options.htmlHost)
        : createHtmlQuad(htmlEntity, scene);
      const applied = applyVemlTransform(built.mesh, entity.transform, {
        allowScale: true,
        allowSize: true,
        originalSize: () => new Vector3(1, 1, 1),
      });
      if (!applied.ok) {
        log.warn(`[webverse] html '${tag}': ${applied.reason} — keeping default transform`);
      }
      built.mesh.parent = parentNode;
      // NO `meshes` → not walkable; the quad + material own disposal (the
      // surface removes its iframe when the quad disposes).
      registry.register({ id: entity.id, tag, type, rootNode: built.mesh, materials: [built.material] });
      if (options.htmlHost) {
        options.onHtmlBuilt?.(built as HtmlSurface);
      } else {
        capabilities.register({ feature: type, kind: 'degraded', tag, reason: HTML_NO_DOM_REASON });
        log.warn(`[webverse] capability gap: 'html' entity (tag '${tag}') ${HTML_NO_DOM_REASON} — quad only`);
      }
      pushChildren(entity, built.mesh);
      continue;
    }

    if (isPrimitive) {
      const mesh = createPrimitiveMesh(type as VemlPrimitiveType, `${type}:${tag}`, scene);
      const material = createPrimitiveMaterial(
        `${type}:${tag}:mat`,
        'color' in entity ? entity.color : undefined,
        scene,
      );
      mesh.material = material;
      mesh.checkCollisions = true; // walkable ⊆ collidable
      options.shadows?.track([mesh]);
      // Mesh/primitive transforms apply with the result IGNORED:
      // invalid → warn, keep defaults, keep the entity.
      const applied = applyVemlTransform(mesh, entity.transform, {
        allowScale: true,
        allowSize: true,
        originalSize: () => primitiveLocalSize(mesh),
      });
      if (!applied.ok) {
        log.warn(`[webverse] ${type} '${tag}': ${applied.reason} — keeping default transform`);
      }
      mesh.parent = parentNode;
      registry.register({
        id: entity.id,
        tag,
        type,
        rootNode: mesh,
        meshes: [mesh],
        materials: [material],
        // A VEML 3.1 `link` makes this primitive a portal (the
        // ingest tool's --link cubemesh slab; §8.5). Undefined otherwise.
        link: entity.link,
      });
      pushChildren(entity, mesh);
      continue;
    }

    // type === 'mesh' — glb via mesh-resource.
    const meshResources = 'meshResources' in entity ? entity.meshResources : [];
    if (meshResources.length === 0) {
      log.warn(
        `[webverse] mesh entity '${tag}' missing required field: mesh-resource — skipping entity (and its children)`,
      );
      continue;
    }
    if (meshResources.length > 1) {
      log.warn(
        `[webverse] mesh entity '${tag}': ${meshResources.length} mesh-resource entries — only the first (glb) is loaded (multi-file glTF deferred)`,
      );
    }
    const ownUrl = meshResources[0]!.resolved;
    // §4.4: lighter files for the same model. A level loads the one with the
    // lowest quality not below it, else the model's own. Only a model that
    // has some is watched for a change of level.
    const alternatives = 'meshAlternatives' in entity ? (entity.meshAlternatives ?? []) : [];
    const levels = alternatives.length > 0 ? options.assetLevels : undefined;
    const urlAt = (level: VemlQualityLevel): string => {
      const at = VEML_QUALITY_LEVELS.indexOf(level);
      return alternatives.find((a) => VEML_QUALITY_LEVELS.indexOf(a.quality) >= at)?.resource.resolved ?? ownUrl;
    };

    // The entity root exists synchronously so children parent correctly
    // while the glb streams; the transform applies after load, once the
    // bounds a sizetransform needs exist.
    const rootNode = new TransformNode(`mesh:${tag}`, scene);
    pushChildren(entity, rootNode);

    // A watched model is found again by its id, so it has one from the start.
    const entityId = entity.id ?? (levels ? crypto.randomUUID() : undefined);
    const transform = entity.transform;
    const link = entity.link; // captured for the async register below
    const declaredBounds = entity.bounds;
    // §4.8: with declared bounds and a caller that defers, the glb waits for
    // the visitor to see the box; the node and children stand meanwhile.
    const declared =
      declaredBounds !== undefined && options.deferral !== undefined
        ? declaredWorldBox(declaredBounds, transform, freshWorldMatrix(parentNode))
        : undefined;
    if (declared !== undefined) {
      rootNode.parent = parentNode; // placed now; the transform applies with the load
      options.deferral!.declared(entityId ?? tag, tag, declared);
    }
    // Fetches one file and stands what it holds under the entity's node, placed
    // by the entity's transform. `first` is the entity's first file: a file
    // brought in place of another does not count its lights again.
    let afterAdopt: (() => Promise<void>) | undefined;
    const bring = async (assetUrl: string, first: boolean): Promise<EntityContent> => {
          const bytes = await fetchAssetBytes(assetUrl, onProgress, fetchImpl);
          const chunk = await loadChunk();
          // The glb's own sounds (KHR_audio_emitter) are read from its JSON.
          let gltfJson: unknown;
          const container = await chunk.loadGlbContainer(bytes, scene, `${tag}.glb`, engineKind, {
            ...(options.honorEmbeddedLights ? { honorEmbeddedLights: true } : {}),
            // What the glb names by a relative address is beside the glb, not beside the page.
            baseUrl: assetUrl,
            onGltfJson: (json) => {
              gltfJson = json;
            },
          });
          container.addAllToScene();
          // Honored KHR_lights_punctual lights: report the count for the
          // default-lighting stand-down and own their disposal with the entity
          // (a script-deleted entity must not leave orphan lights in the scene).
          const assetLights = [...container.lights];
          if (assetLights.length > 0) {
            if (first) options.onAssetLights?.(assetLights.length);
            // A glb light carries no shadow flag (glTF has none), so the
            // world's sun is taken as the author saw it: a directional light
            // from the asset casts shadows, and the rig keeps it to one per
            // world. Spot and point lights from a glb cast none — a cost the
            // author cannot bound from Blender.
            if (options.shadows) {
              const rig = options.shadows;
              const offer = async (): Promise<void> => {
                for (const light of assetLights) {
                  if (light.getClassName() !== 'DirectionalLight' || light.isDisposed()) continue;
                  await rig.attach(light, light.name.length > 0 ? light.name : tag);
                }
              };
              // A file taking another's place asks once the old sun is gone: until then the old sun holds the world's one generator.
              if (first) await offer();
              else afterAdopt = offer;
            }
          }
          for (const node of container.rootNodes) {
            node.parent = rootNode;
          }
          for (const mesh of container.meshes) {
            mesh.checkCollisions = true; // walkable ⊆ collidable
          }
          options.shadows?.track(container.meshes);
          // Bounds measured entity-local (root unparented at identity),
          // container meshes only — THEN transform, THEN world parenting.
          rootNode.parent = null;
          const naturalSize = containerMeshesSize(container.meshes);
          const applied = applyVemlTransform(rootNode, transform, {
            allowScale: true,
            allowSize: true,
            originalSize: () => naturalSize,
          });
          if (!applied.ok) {
            log.warn(`[webverse] mesh '${tag}': ${applied.reason} — keeping default transform`);
          }
          rootNode.parent = parentNode;
          // §4.8: a declaration governs deferral only, never what renders; a
          // glb that outgrows its declared box is shown whole and said. The
          // comparison is in the entity's own frame, where both sizes live:
          // a scale transform scales loaded and declared alike, so it cancels;
          // a size transform fits the content to the target by construction,
          // so nothing can diverge and there is nothing to say.
          if (declaredBounds !== undefined && transform?.kind !== 'sizetransform') {
            const d = declaredBounds.size;
            const grew = (loaded: number, said: number): boolean => loaded > said * DECLARED_BOUNDS_TOLERANCE && loaded - said > 1e-3;
            if (grew(naturalSize.x, d.x) || grew(naturalSize.y, d.y) || grew(naturalSize.z, d.z)) {
              log.warn(
                `[webverse] mesh '${tag}': loaded content (${naturalSize.x.toFixed(2)}×${naturalSize.y.toFixed(2)}×${naturalSize.z.toFixed(2)} m) is larger than its declared bounds (${d.x}×${d.y}×${d.z} m) — rendered whole; the declaration only delayed its loading`,
              );
            }
          }
          // Sounds at their nodes, now that the transform is final. The
          // audio chunk loads only for a glb that has them.
          const emitters = readAudioEmitters(gltfJson, assetUrl);
          const soundDisposers: Array<() => void> = [];
          if (emitters.length > 0) {
            const factory = options.soundFactory ?? (await loadAudioChunk()).createSound;
            const nodes = [...container.transformNodes, ...container.meshes];
            for (const built of buildGltfAudio(emitters, nodes, scene, audioGate, factory)) {
              soundDisposers.push(...built.disposers);
              options.onAudioBuilt?.({
                tag: built.emitter.name,
                autoPlay: built.emitter.autoPlay,
                spatial: true,
                position: built.position,
                ...(built.direction ? { direction: built.direction } : {}),
                sound: built.sound,
              });
            }
          }
          const entityDisposers: Array<() => void> = [
            ...(assetLights.length > 0 ? [(): void => assetLights.forEach((l) => l.dispose())] : []),
            ...soundDisposers,
          ];
          return {
            meshes: [...container.meshes],
            materials: [...container.materials],
            textures: [...container.textures],
            // Honored glb lights die with their entity (disposers run
            // FIRST in the registry's teardown order),
            // and so do its sounds (gate callbacks popped before the sounds).
            disposers: entityDisposers,
            assetUrl,
          };
    };
    const reasonOf = (err: unknown): string => (err instanceof Error ? err.message : String(err));
    /** The address of the file the entity holds; empty until one has loaded. */
    let loadedUrl = '';
    const loadGlb = async (): Promise<void> => {
        let assetUrl = levels ? urlAt(levels.level()) : ownUrl;
        try {
          let content: EntityContent;
          try {
            content = await bring(assetUrl, true);
          } catch (err) {
            if (assetUrl === ownUrl) throw err;
            // §4.4: a lighter file that fails gives way to the model's own.
            log.warn(`[webverse] mesh '${tag}': ${assetUrl} failed (${reasonOf(err)}) — loading ${ownUrl}`);
            assetUrl = ownUrl;
            content = await bring(ownUrl, true);
          }
          registry.register({
            id: entityId,
            tag,
            type: 'mesh',
            rootNode,
            meshes: content.meshes,
            materials: content.materials,
            textures: content.textures,
            disposers: content.disposers && content.disposers.length > 0 ? content.disposers : undefined,
            // A VEML 3.1 `link` makes this glb entity a portal.
            link,
            assetUrl,
          });
          loadedUrl = assetUrl;
        } catch (err) {
          // The world still loads; the entity registers errored with
          // the asset URL. (fetchAssetBytes already emitted asset-failed for
          // download failures; a chunk/parse failure reports through the
          // registry entry — and the node must not leak.)
          const message = reasonOf(err);
          log.warn(`[webverse] mesh '${tag}' failed to load ${assetUrl}: ${message}`);
          rootNode.parent = parentNode; // children (if any) stay placed
          registry.registerErrored({
            id: entityId,
            tag,
            type: 'mesh',
            assetUrl,
            message,
            rootNode, // still owned: disposed with the entity (no node leak)
          });
        }
        // Watched from here on: when the level changes, another file may take this one's place.
        levels?.track({
          tag,
          choose: urlAt,
          loaded: () => loadedUrl,
          gone: () => registry.get(entityId!)?.isDisposed() !== false,
          bring: (url) => bring(url, false),
          adopt: (content, url) => {
            registry.get(entityId!)?.replaceContent(content);
            loadedUrl = url;
            const offer = afterAdopt;
            afterAdopt = undefined;
            void offer?.();
          },
        });
    };
    if (declared !== undefined) {
      options.deferral!.asset({ entityId: entityId ?? tag, tag, box: declared, start: loadGlb });
    } else {
      pendingAssets.push(loadGlb());
    }
  }

  await Promise.all(pendingAssets);
}

/** The water profile's defaults, for a 3.x water entity that omits a field. */
const LEGACY_WATER_DEFAULTS = { color: '#2a6f97ff', deepColor: '#0b2a3aff', clarity: 4, waves: 0.1 } as const;

/**
 * A 3.x `water` or `waterblocker` entity → the water profile's body or
 * blocker (profiles/water.md, Migration): `shallow-color` is `color`,
 * `deep-end` is `clarity`, the wave amplitude is `waves` (metres, clamped to
 * 0..1), the rest described one shader and are dropped. The box is the
 * entity's transform resolved through its parents into the world frame.
 */
function mapLegacyWater(
  entity: VemlEntity,
  parentNode: TransformNode | null,
  scene: Scene,
  sink: BuildWorldOptions['water'],
): void {
  const probe = new TransformNode(`${entity.type}:probe`, scene);
  const applied = applyVemlTransform(probe, entity.transform, { allowScale: true, allowSize: false });
  probe.parent = parentNode;
  probe.computeWorldMatrix(true);
  const position = probe.getAbsolutePosition().clone();
  const extent = probe.absoluteScaling.clone();
  const rotation = probe.absoluteRotationQuaternion.clone();
  probe.dispose();
  if (!applied.ok) {
    log.warn(`[webverse] ${entity.type} '${entity.tag ?? '(untagged)'}': ${applied.reason} — ignored`);
    return;
  }
  if (!sink) return;
  const vec = (v: Vector3): { x: number; y: number; z: number } => ({ x: v.x, y: v.y, z: v.z });
  if (entity.type === 'waterblocker') {
    sink.blocker({ position: vec(position), rotation: { x: rotation.x, y: rotation.y, z: rotation.z, w: rotation.w }, extent: vec(extent) });
    return;
  }
  const water = entity as VemlWaterEntity;
  const rgba = (raw: string | undefined, fallback: string): { r: number; g: number; b: number; a: number } => {
    const parsed = parseVemlColor(raw ?? fallback);
    return { r: parsed.color.r, g: parsed.color.g, b: parsed.color.b, a: parsed.alpha };
  };
  const clarity = typeof water.deepEnd === 'number' && Number.isFinite(water.deepEnd) ? Math.max(0, water.deepEnd) : LEGACY_WATER_DEFAULTS.clarity;
  const waves =
    typeof water.waveAmplitude === 'number' && Number.isFinite(water.waveAmplitude)
      ? Math.min(1, Math.max(0, water.waveAmplitude))
      : LEGACY_WATER_DEFAULTS.waves;
  sink.body({
    position: vec(position),
    extent: vec(extent),
    color: rgba(water.shallowColor, LEGACY_WATER_DEFAULTS.color),
    deepColor: rgba(water.deepColor, LEGACY_WATER_DEFAULTS.deepColor),
    clarity,
    waves,
  });
}
