/**
 * Input bindings — VEML 4.0 §8.2.
 *
 * The core input vocabulary is four names: `move` and `look` (two axes each),
 * `interact` (primary activation) and `use` (secondary). A document binds an
 * input to an action; the defaults are PER INPUT, so declaring one binding
 * never forfeits the others, and a binding-free world is walkable. `use` has
 * no default: unbound, it fires nothing on the bus. A document suppresses a
 * default by binding that input to an action nothing handles.
 *
 * An input name outside the vocabulary would be a client extension this
 * client does not have; §2 says warn and ignore. Bindings are read from the
 * ROOT document only (an included document's are inert) — the composition
 * layer enforces that; this module only resolves what it is given.
 */
import { BUILT_IN_ACTIONS, isValidActionName } from './actionBus';

export const CORE_INPUTS = ['move', 'look', 'interact', 'use'] as const;
export type CoreInput = (typeof CORE_INPUTS)[number];

export const DEFAULT_BINDINGS: Readonly<Partial<Record<CoreInput, string>>> = Object.freeze({
  move: 'veml.character.move',
  look: 'veml.character.look',
  interact: 'veml.interact',
});

export function isCoreInput(name: string): name is CoreInput {
  return (CORE_INPUTS as ReadonlyArray<string>).includes(name);
}

export function isBuiltInAction(action: string): boolean {
  return BUILT_IN_ACTIONS.includes(action);
}

export interface DeclaredBinding {
  input: string;
  action: string;
}

/**
 * The effective input → action map: the defaults, overlaid by the document's
 * declarations. Later declarations win, with a warning.
 */
export function resolveInputBindings(
  declared: ReadonlyArray<DeclaredBinding>,
  warn: (message: string) => void = (m) => console.warn(m),
): Map<CoreInput, string> {
  const bindings = new Map<CoreInput, string>();
  for (const input of CORE_INPUTS) {
    const action = DEFAULT_BINDINGS[input];
    if (action !== undefined) bindings.set(input, action);
  }
  const declaredInputs = new Set<CoreInput>();
  for (const b of declared) {
    const input = typeof b.input === 'string' ? b.input.toLowerCase() : '';
    if (!isCoreInput(input)) {
      warn(`[webverse] input-binding: '${b.input}' is not a core input (move, look, interact, use) — ignored`);
      continue;
    }
    if (!isValidActionName(b.action)) {
      warn(`[webverse] input-binding: '${input}' names an invalid action ${JSON.stringify(b.action)} — ignored`);
      continue;
    }
    if (declaredInputs.has(input)) {
      warn(`[webverse] input-binding: '${input}' is bound more than once — the last declaration wins`);
    }
    declaredInputs.add(input);
    bindings.set(input, b.action);
  }
  return bindings;
}
