/**
 * Detection for the VEML HTML authoring dialect (conformance G.1): whether a
 * fetched document, or the page itself, is an HTML world.
 *
 * These checks stay in the main bundle so every load can route a document.
 * The dialect's parser (htmlDialect.ts) is code-split and loaded only once a
 * document turns out to be HTML, which a typical, XML world never is.
 */

/** Does the URL's pathname (query/hash excluded) end in `.html` or `.htm`? */
export function isHtmlWorldUrl(url: string, base?: string): boolean {
  try {
    const p = new URL(url, base).pathname.toLowerCase();
    return p.endsWith('.html') || p.endsWith('.htm');
  } catch {
    return false;
  }
}

/** Is a Content-Type header's MIME (params stripped) exactly `text/html`? */
export function mimeIsHtml(contentType: string | null | undefined): boolean {
  if (!contentType) return false;
  const mime = contentType.split(';', 1)[0] ?? '';
  return mime.trim().toLowerCase() === 'text/html';
}

/** Does the parsed document contain ≥1 `veml-*` element (any localName prefix)? */
export function containsVemlElement(doc: Document): boolean {
  for (const el of Array.from(doc.getElementsByTagName('*'))) {
    if (el.localName.startsWith('veml-')) return true;
  }
  return false;
}

/**
 * The world a page POINTS AT, as the self-boot script reads it: a
 * `<veml-world src="…">`, else any element's `data-world`, else nothing.
 * One rule for both readers of a page, the boot script on the page itself
 * and a load of the page's address from elsewhere, so a published world's
 * page means the same world whichever way it is reached.
 */
export function worldPointerOf(doc: Document): string | null {
  const worldEl = doc.getElementsByTagName('veml-world')[0];
  const worldSrc = worldEl?.getAttribute('src')?.trim();
  if (worldSrc) return worldSrc;
  for (const el of Array.from(doc.querySelectorAll('[data-world]'))) {
    const url = el.getAttribute('data-world')?.trim();
    if (url) return url;
  }
  return null;
}

/** `worldPointerOf` over HTML text, parsed inertly (no script runs). */
export function worldPointerInHtml(htmlText: string): string | null {
  return worldPointerOf(new DOMParser().parseFromString(htmlText, 'text/html'));
}
