/**
 * The people messages, mountable on any page.
 *
 * Both the full app (`main.ts`) and the self-boot path, which every published
 * world boots through, mount chat and "X joined" lines through this one
 * mount. It feeds the session's messages into a stream,
 * draws the panel, and opens the chat line on the chat key. `/name …` typed
 * there chooses the name the others see.
 */
import { createMessageStream, type MessageChannel } from './messageStream';
import { createMessagesPanel, type MessagesPanel } from './messagesPanel';
import type { ShellSettings } from '../settings/shellSettings';
import { chooseVisitorName, type NameStore } from '../net/visitorIdentity';
import { touchButtonCss } from '../input/touchButtons';
import type { ClientHints } from '../hints/clientHints';

/** What the mount needs from a world session. */
export interface PeopleSession {
  chat(text: string): boolean;
  messagesMembers(): Array<{ name: string; self: boolean }>;
}

export interface PeopleMessages {
  /** The world session's `onMessage`: what the room and the world say. */
  onMessage(channel: MessageChannel, kind: string, fields: Record<string, string>): void;
  /**
   * Draw the panel and bind the chat key on `canvas`; on a touch page, also
   * the chat button. Returns the unmount.
   */
  mount(session: PeopleSession, canvas: HTMLElement, options?: { touch?: boolean; hints?: ClientHints }): () => void;
  /** Redraw from the settings (e.g. the menu moved chat). */
  refresh(): void;
  /** The lines the panel shows now (none while hidden): the headset panel's text. */
  shownLines(): string[];
}

/**
 * A phone has no hardware keyboard, so the chat key can never open the line. On touch, this button does
 * what the chat key does; the phone's own keyboard then sends the line. Any
 * panel with `openInput` takes it, so the full app mounts the same button.
 */
export function mountTouchChat(
  doc: Document,
  panel: { openInput(): void; closeInput(): void; inputOpen(): boolean },
): () => void {
  const button = doc.createElement('div');
  button.setAttribute('data-webverse-touch-button', 'chat');
  button.setAttribute('role', 'button');
  button.setAttribute('aria-label', 'Chat');
  button.textContent = 'Chat';
  button.style.cssText = touchButtonCss('left');
  // pointerup, not click: a tap that opens the line must also be the gesture
  // that focuses it, or a phone will not raise its keyboard. The button
  // toggles: a second tap closes the line.
  const open = (ev: Event): void => {
    ev.preventDefault();
    if (panel.inputOpen()) panel.closeInput();
    else panel.openInput();
  };
  const stop = (ev: Event): void => ev.preventDefault();
  button.addEventListener('pointerup', open);
  button.addEventListener('touchstart', stop, { passive: false });
  doc.body.appendChild(button);
  return () => {
    button.removeEventListener('pointerup', open);
    button.removeEventListener('touchstart', stop);
    button.remove();
  };
}

const NAME_COMMAND = /^\/name\s+(.+)$/i;

/**
 * Chat follows the world's hints (profiles/client-hints.md, hints:chat
 * and controls.touch-buttons), for any panel: the published-world mount and
 * the full app share it. `chat.panel=hide` sets the starting state of each
 * world (the visitor's own toggle wins after); the touch chat button comes
 * and goes with `controls.touch-buttons` and `chat.enabled`; chat turned off
 * closes an open line. Returns the unmount.
 */
export function followChatHints(
  doc: Document,
  panel: { openInput(): void; closeInput(): void; inputOpen(): boolean; toggle(): void },
  options: { touch: boolean; hints?: ClientHints },
): () => void {
  const { hints } = options;
  let hiddenByHint = false;
  const applyPanel = (): void => {
    const hide = hints?.shown('chat.panel') === false;
    if (hide && !hiddenByHint) panel.toggle();
    hiddenByHint = hide;
  };
  let unmountButton: (() => void) | undefined;
  const syncButton = (): void => {
    const want = options.touch && (hints ? hints.touchButtons().includes('chat') : true);
    if (want && !unmountButton) unmountButton = mountTouchChat(doc, panel);
    if (!want && unmountButton) {
      unmountButton();
      unmountButton = undefined;
      panel.closeInput();
    }
  };
  applyPanel();
  syncButton();
  const unsubscribe = hints?.subscribe((name) => {
    if (name === 'chat.panel') applyPanel();
    if (name === 'chat.enabled' || name === 'controls.touch-buttons') syncButton();
    if (name === 'chat.enabled' && hints.flag('chat.enabled') === false) panel.closeInput();
  });
  return () => {
    unsubscribe?.();
    unmountButton?.();
  };
}

export function createPeopleMessages(
  doc: Document,
  settings: () => ShellSettings,
  store?: NameStore,
): PeopleMessages {
  const stream = createMessageStream({ settings: () => settings().messages });
  let panel: MessagesPanel | undefined;

  const note = (text: string): void => {
    stream.post('shell', 'capability', { text });
    panel?.refresh();
  };

  return {
    onMessage(channel, kind, fields) {
      stream.post(channel, kind, fields);
      panel?.refresh();
    },
    refresh() {
      panel?.applySettings();
    },
    shownLines: () => panel?.shownLines() ?? [],
    mount(session, canvas, options = {}) {
      // The world's say (profiles/client-hints.md, hints:chat): chat
      // off takes the line, the key and the button away; read live.
      const hints = options.hints;
      const chatOn = (): boolean => hints?.flag('chat.enabled') ?? true;
      const mounted = createMessagesPanel(doc, {
        stream,
        settings: () => settings().messages,
        members: () => session.messagesMembers(),
        send: (text) => {
          const named = NAME_COMMAND.exec(text.trim());
          if (named) {
            const chosen = chooseVisitorName(store, named[1]!);
            // The name travels with the hello, so the room sees it from the
            // next time this page joins one.
            note(chosen === null ? 'a name cannot be blank' : `you are ${chosen} from your next visit`);
            return true;
          }
          return chatOn() ? session.chat(text) : false;
        },
      });
      panel = mounted;
      // The chat key, on the canvas (it holds focus under pointer lock). Not
      // while the line is open: there the input owns Enter and Escape.
      const onKey = (ev: KeyboardEvent): void => {
        if (ev.ctrlKey || ev.altKey || ev.metaKey || mounted.inputOpen()) return;
        const bindings = settings().bindings;
        if (bindings.chat.includes(ev.code)) {
          if (!chatOn()) return;
          ev.preventDefault();
          mounted.openInput();
        } else if (bindings.messagesToggle.includes(ev.code)) {
          ev.preventDefault();
          mounted.toggle();
        }
      };
      canvas.addEventListener('keydown', onKey);
      const unmountTouch = followChatHints(doc, mounted, { touch: options.touch === true, ...(hints ? { hints } : {}) });
      // Who is here follows the room by itself: drawing only on a message
      // is not enough, because nobody posts one for a person joining a room
      // already in use, so a newcomer would see nobody.
      const follow = setInterval(() => mounted.refresh(), 1_000);
      return () => {
        clearInterval(follow);
        unmountTouch();
        canvas.removeEventListener('keydown', onKey);
        mounted.dispose();
        if (panel === mounted) panel = undefined;
      };
    },
  };
}
