/**
 * `lod` level selection (VEML 4.0 §4.10), kept apart from the scene.
 *
 * A level is active from its range up to the next level's range; a viewer
 * nearer than the first range sees the first. A viewer walking across a
 * boundary must clear a band around it before the level changes, in either
 * direction, so standing on a boundary never flickers between two levels.
 * With no distance at all, the first non-empty level renders: `lod`
 * degrades to its best representation, never to nothing.
 */

/** The band is this fraction of the boundary's range… */
export const LOD_BAND_FRACTION = 0.1;
/** …and never narrower than this, in metres. */
export const LOD_BAND_MIN_M = 1;

/** The half-width of the band around a boundary at `range` metres. */
export function lodBand(range: number): number {
  return Math.max(LOD_BAND_MIN_M, range * LOD_BAND_FRACTION);
}

/** The level whose span holds `distance`, with no band. */
function levelAt(ranges: readonly number[], distance: number): number {
  let level = 0;
  for (let i = 1; i < ranges.length; i += 1) if (distance >= ranges[i]!) level = i;
  return level;
}

/**
 * The level to show at `distance` metres. `current` is the level showing
 * now, if any; leaving it for a farther level needs the boundary plus its
 * band, and for a nearer one the boundary minus its band. `ranges` is
 * ascending, as the parser leaves it.
 */
export function selectLodLevel(ranges: readonly number[], distance: number, current?: number): number {
  if (ranges.length === 0) return 0;
  const plain = levelAt(ranges, distance);
  if (current === undefined || plain === current) return plain;
  if (plain > current) {
    // Walking out: the farthest level whose boundary is cleared by its band.
    let level = current;
    for (let i = current + 1; i < ranges.length; i += 1) {
      if (distance >= ranges[i]! + lodBand(ranges[i]!)) level = i;
    }
    return level;
  }
  // Walking in: stay on a level until the viewer is inside its boundary by the band.
  let level = 0;
  for (let i = 1; i <= current; i += 1) {
    if (distance >= ranges[i]! - lodBand(ranges[i]!)) level = i;
  }
  return level;
}

/** §4.10's fallback when no distance is evaluated: the first level with content, else the first. */
export function firstNonEmptyLevel(entityCounts: readonly number[]): number {
  const i = entityCounts.findIndex((n) => n > 0);
  return i === -1 ? 0 : i;
}
